"use client";

/** agenda-view — chronological event list grouped by day (grouping in `lib/agenda`). */

import type React from "react";
import { memo, useCallback, useMemo, useRef, useState } from "react";
import { type AgendaEntry, groupAgenda } from "../lib/agenda";
import {
  formatRange,
  type KloqView,
  type PlacedEvent,
  type TimeFormatOptions,
  type ViewDescriptor,
} from "../lib/calendar-types";
import { formatDate } from "../lib/date-format";
import { EVENT_COLORS } from "../lib/event-palette";
import { eventTitle, fullDate, plural } from "../lib/event-text";
import { formatViewTitle } from "../lib/navigation";
import { rovingTab } from "../lib/roving";
import { cn } from "../lib/utils";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import { ContextMenu, ContextMenuTrigger } from "../ui/context-menu";
import { FOCUS_RING_INSET } from "./cell-classes";
import { type CalendarMenuTarget, EventContextMenu, GridContextMenu } from "./event-context-menu";
import { useKloqSettings } from "./settings-context";

/** Where a "New event here" from an agenda row lands. */
const AGENDA_NEW_EVENT_MIN = 9 * 60;

interface AgendaViewProps {
  view: ViewDescriptor;
  events: PlacedEvent[];
  selectedId: string | null;
  registerNode: (id: string, node: HTMLElement | null) => void;
  onSelect: (id: string | null, opts?: { isNew?: boolean }) => void;
  onOpenDay: (date: Date) => void;
  viewSetting: KloqView;
  onSwitchView: (view: KloqView) => void;
  /** The one event carrying `tabIndex={0}` — see `lib/roving.ts`. */
  rovingId?: string | null;
}

export function AgendaView({
  view,
  events,
  selectedId,
  registerNode,
  onSelect,
  onOpenDay,
  viewSetting,
  onSwitchView,
  rovingId,
}: AgendaViewProps) {
  const g = useKloqSettings();
  const hostRef = useRef<HTMLDivElement>(null);
  const agenda = useMemo(() => groupAgenda(events, view), [events, view]);

  const [target, setTarget] = useState<CalendarMenuTarget | null>(null);
  const pending = useRef<CalendarMenuTarget | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);

  const onContextMenuCapture = useCallback(
    (e: React.MouseEvent) => {
      pending.current = null;
      const el = e.target as HTMLElement | null;
      const row = el?.closest?.("[data-cal-event]") as HTMLElement | null;
      const id = row?.dataset.calEvent;
      if (id) {
        const event = events.find((ev) => ev.id === id);
        if (event) pending.current = { kind: "event", event };
        return;
      }
      const group = el?.closest?.("[data-agenda-day]") as HTMLElement | null;
      const col = Number(group?.dataset.agendaDay);
      if (!Number.isFinite(col)) return;
      pending.current = {
        kind: "slot",
        col,
        // clamped into the configured day range
        startMin: g.clampMinutes(AGENDA_NEW_EVENT_MIN),
        allDay: false,
      };
    },
    [events, g],
  );

  const onOpenChange = (next: boolean) => {
    if (next && !pending.current) return;
    if (next) setTarget(pending.current);
    setMenuOpen(next);
  };

  // one day heading is in the tab order; ↑/↓ move it
  const [leadDay, setLeadDay] = useState<number | null>(null);
  const headingDay =
    agenda.days.find((d) => d.dayIndex === leadDay)?.dayIndex ??
    agenda.days.find((d) => d.isToday)?.dayIndex ??
    agenda.days[0]?.dayIndex;
  const onKeyDown = useCallback((e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
    if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
    const from = e.target as HTMLElement | null;
    if (from?.dataset?.agendaOpen === undefined) return;
    // `preventDefault()` also tells the document-level keyboard layer to yield
    e.preventDefault();
    const all = Array.from(e.currentTarget.querySelectorAll<HTMLElement>("[data-agenda-open]"));
    all[all.indexOf(from) + (e.key === "ArrowDown" ? 1 : -1)]?.focus();
  }, []);

  return (
    <ContextMenu open={menuOpen} onOpenChange={onOpenChange}>
      <ContextMenuTrigger
        onContextMenuCapture={onContextMenuCapture}
        render={
          <div
            ref={hostRef}
            className="min-h-0 flex-1 overflow-y-auto overscroll-contain"
            onKeyDown={onKeyDown}
          />
        }
      >
        {agenda.days.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center gap-1 px-6 py-10 text-center">
            <p className="text-sm font-medium">Nothing scheduled</p>
            <p className="text-sm text-muted-foreground">
              {formatViewTitle(view, g.locale)} is clear.
            </p>
          </div>
        ) : (
          <div role="list" aria-label="Schedule" className="@container mx-auto w-full max-w-3xl">
            {agenda.days.map((day) => {
              const dateLabel = fullDate(day.date, g.locale);
              return (
                <section
                  key={day.dayIndex}
                  data-agenda-day={day.dayIndex}
                  role="listitem"
                  aria-label={`${dateLabel}, ${plural(day.entries.length, "event")}`}
                  className="border-b last:border-b-0"
                >
                  <h2 className="sticky top-0 z-10 flex items-center gap-2 border-b bg-background px-4 py-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      data-agenda-open={day.dayIndex}
                      tabIndex={day.dayIndex === headingDay ? 0 : -1}
                      onFocus={() => setLeadDay(day.dayIndex)}
                      onClick={() => onOpenDay(day.date)}
                      aria-label={`Open ${dateLabel}`}
                      className="-mx-2.5"
                    >
                      {formatDate(day.date, g.locale, HEADING_DATE)}
                    </Button>
                    {day.isToday ? <Badge size="sm">Today</Badge> : null}
                  </h2>

                  <ul className="flex flex-col py-1">
                    {day.entries.map((entry) => (
                      <li key={`${entry.event.id}:${day.dayIndex}`}>
                        <AgendaRow
                          entry={entry}
                          dateLabel={dateLabel}
                          selected={entry.event.id === selectedId}
                          // only the first day of a multi-day event registers its node
                          registerNode={entry.repeat ? undefined : registerNode}
                          // continuation rows share the id; one tab stop per event
                          tabIndex={entry.repeat ? -1 : rovingTab(rovingId, entry.event.id)}
                          onSelect={onSelect}
                        />
                      </li>
                    ))}
                  </ul>
                </section>
              );
            })}

            {agenda.emptyDays > 0 ? (
              <p className="px-4 py-3 text-center text-2xs text-muted-foreground">
                {agenda.emptyDays} empty {agenda.emptyDays === 1 ? "day" : "days"} hidden
              </p>
            ) : null}
          </div>
        )}
      </ContextMenuTrigger>

      {target?.kind === "event" ? (
        <EventContextMenu
          event={target.event}
          selected={target.event.id === selectedId}
          host={hostRef}
          days={view.days}
          onSelect={onSelect}
          close={() => setMenuOpen(false)}
        />
      ) : target ? (
        <GridContextMenu
          slot={target}
          host={hostRef}
          days={view.days}
          todayIndex={-1}
          viewSetting={viewSetting}
          onSwitchView={onSwitchView}
          onSelect={onSelect}
          close={() => setMenuOpen(false)}
        />
      ) : null}
    </ContextMenu>
  );
}

const HEADING_DATE: Intl.DateTimeFormatOptions = {
  weekday: "long",
  month: "long",
  day: "numeric",
};

interface AgendaRowProps {
  entry: AgendaEntry;
  dateLabel: string;
  selected: boolean;
  tabIndex?: number;
  registerNode?: (id: string, node: HTMLElement | null) => void;
  onSelect: (id: string | null, opts?: { isNew?: boolean }) => void;
}

/** The time column: a range for a timed event, "All day" otherwise. */
function agendaTimeLabel(entry: AgendaEntry, opts?: TimeFormatOptions): string {
  const { event, continuesBefore } = entry;
  if (continuesBefore) return "Continues";
  if (event.allDay) return "All day";
  return formatRange(event.startMin, event.endMin, opts);
}

const AgendaRow = memo(function AgendaRow({
  entry,
  dateLabel,
  selected,
  tabIndex,
  registerNode,
  onSelect,
}: AgendaRowProps) {
  const g = useKloqSettings();
  const { event } = entry;
  const c = EVENT_COLORS[event.color];
  const time = agendaTimeLabel(entry, g.timeFormat);

  return (
    <button
      type="button"
      data-cal-event={event.id}
      ref={registerNode ? (node) => registerNode(event.id, node) : undefined}
      onClick={() => onSelect(event.id)}
      aria-pressed={selected}
      tabIndex={tabIndex}
      aria-label={rowLabel(event, dateLabel, time, entry.continuesAfter)}
      className={cn(
        "flex w-full cursor-pointer items-center gap-3 px-4 py-1.5 text-left transition-[background-color,box-shadow] duration-150 hover:bg-accent",
        FOCUS_RING_INSET,
        selected && cn("bg-accent ring-2 ring-inset", c.ring),
      )}
    >
      <span className="w-36 shrink-0 whitespace-nowrap text-xs tabular-nums text-muted-foreground">
        {time}
      </span>{" "}
      <span aria-hidden className={cn("size-2 shrink-0 rounded-full", c.bar)} />
      <span className="min-w-0 flex-1 truncate text-sm font-medium">{eventTitle(event)}</span>{" "}
      {event.location ? (
        <span className="hidden shrink-0 truncate text-xs text-muted-foreground @xl:block">
          {event.location}
        </span>
      ) : null}
    </button>
  );
});

function rowLabel(
  event: PlacedEvent,
  dateLabel: string,
  time: string,
  continuesAfter: boolean,
): string {
  const title = eventTitle(event);
  const tail = continuesAfter ? ", continues" : "";
  const where = event.location ? `, ${event.location}` : "";
  // time then title then location, the order the row renders them: the visible
  // text has to be part of the accessible name (label-content-name-mismatch)
  return `${time}, ${title}${where}, ${dateLabel}${tail}`;
}

"use client";

import type React from "react";
import { memo } from "react";
import { formatDaySpan, type PlacedEvent } from "../lib/calendar-types";
import { EVENT_COLORS, EVENT_TEXT_CSS } from "../lib/event-palette";
import { eventTitle } from "../lib/event-text";
import { cn } from "../lib/utils";
import { FOCUS_RING } from "./cell-classes";
import { samePlacement } from "./event-block";

export interface AllDayChipProps {
  event: PlacedEvent;
  /** visible column count from the view descriptor */
  dayCount: number;
  /** short day name per visible column (`view.namesShort`) */
  dayNamesShort: string[];
  /** stacking row within the lane */
  row: number;
  rowHeight: number;
  selected: boolean;
  /** roving tabindex from the owning lane; defaults to `selected ? 0 : -1` */
  tabIndex?: number;
  /** drag-engine contract: a custom chip must register its root and forward pointerdown */
  registerNode: (id: string, node: HTMLElement | null) => void;
  onPointerDown: (e: React.PointerEvent<HTMLElement>, event: PlacedEvent) => void;
  /** keyboard/AT activation — Enter, Space, synthesised clicks; never pointer gestures */
  onActivate?: (event: PlacedEvent) => void;
}

export const AllDayChip = memo(
  function AllDayChip({
    event,
    dayCount,
    dayNamesShort,
    row,
    rowHeight,
    selected,
    tabIndex,
    registerNode,
    onPointerDown,
    onActivate,
  }: AllDayChipProps) {
    const c = EVENT_COLORS[event.color];
    const startDay = event.dayIndex;
    const endDay = event.endDayIndex;
    const title = eventTitle(event);
    const label = `${title}, ${formatDaySpan(startDay, endDay, dayNamesShort)}, all day`;
    return (
      <div
        data-cal-event={event.id}
        data-day={startDay}
        data-end-day={endDay}
        data-selected={selected || undefined}
        role="button"
        // aria-pressed: role="button" doesn't support aria-selected
        aria-pressed={selected}
        aria-label={label}
        tabIndex={tabIndex ?? (selected ? 0 : -1)}
        ref={(node) => registerNode(event.id, node)}
        onPointerDown={(e) => onPointerDown(e, event)}
        // `detail === 0` marks a click no pointer produced (AT activation)
        onClick={(e) => {
          if (e.detail === 0) onActivate?.(event);
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onActivate?.(event);
          }
        }}
        className={cn(
          "group absolute flex h-5.5 cursor-grab items-center overflow-hidden rounded-md pl-2.5 pr-2 transition-[background-color,box-shadow] duration-150",
          // the list wrapper is `pointer-events-none`
          "pointer-events-auto",
          "focus-visible:z-20",
          FOCUS_RING,
          c.tint,
          c.ink,
          selected && cn("z-20 shadow-(--shadow-md) ring-2", c.ring),
        )}
        style={{
          top: row * rowHeight + 3,
          left: `calc(${(startDay / dayCount) * 100}% + 2px)`,
          width: `calc(${((endDay - startDay + 1) / dayCount) * 100}% - 5px)`,
          color: EVENT_TEXT_CSS,
        }}
      >
        <span aria-hidden className={cn("absolute inset-y-1 left-1 w-0.75 rounded-full", c.bar)} />
        <span className="truncate text-xs font-medium leading-none">{title}</span>

        <div
          aria-hidden
          data-lane-edge="left"
          className="absolute -left-1 top-0 bottom-0 flex w-2 cursor-ew-resize items-center justify-center pointer-coarse:-left-3 pointer-coarse:w-6"
        >
          <span
            className={cn(
              "h-3 w-0.75 rounded-full opacity-0 transition-opacity duration-150 group-hover:opacity-60",
              c.bar,
            )}
          />
        </div>
        <div
          aria-hidden
          data-lane-edge="right"
          className="absolute -right-1 top-0 bottom-0 flex w-2 cursor-ew-resize items-center justify-center pointer-coarse:-right-3 pointer-coarse:w-6"
        >
          <span
            className={cn(
              "h-3 w-0.75 rounded-full opacity-0 transition-opacity duration-150 group-hover:opacity-60",
              c.bar,
            )}
          />
        </div>
      </div>
    );
  },
  (a, b) =>
    samePlacement(a.event, b.event) &&
    a.dayCount === b.dayCount &&
    a.dayNamesShort === b.dayNamesShort &&
    a.row === b.row &&
    a.rowHeight === b.rowHeight &&
    a.selected === b.selected &&
    a.tabIndex === b.tabIndex &&
    a.registerNode === b.registerNode &&
    a.onPointerDown === b.onPointerDown &&
    a.onActivate === b.onActivate,
);

"use client";

/** all-day-lane — the banner strip between the day headers and the scrollable grid. */

import type React from "react";
import { useCallback, useMemo } from "react";
import type { PlacedEvent } from "../lib/calendar-types";
import { disabledAllDayColumns } from "../lib/constraints";
import { plural } from "../lib/event-text";
import { rovingTab } from "../lib/roving";
import { useLatest } from "../lib/use-latest";
import { ContextMenu, ContextMenuTrigger } from "../ui/context-menu";
import { useConstraints } from "./constraints-context";
import {
  EventContextMenu,
  fallbackDays,
  GridContextMenu,
  useCalendarContextMenu,
} from "./event-context-menu";
import { EventOverflow } from "./event-overflow";
import { useSlots } from "./slots";
import { useCoarsePointer } from "./use-responsive";

const ROW_H = 24; // chip height (22) + 2px gap
const ROW_H_TOUCH = 26; // the 24px touch minimum + the same gap
const MAX_ROWS = 3;
const MORE_H = 18;

/** Greedy row assignment — first row whose last chip ends before this one starts. */
function layoutRows(events: PlacedEvent[]): Map<string, number> {
  const rows: number[] = []; // last occupied day per row
  const out = new Map<string, number>();
  const sorted = [...events].sort(
    (a, b) => a.dayIndex - b.dayIndex || b.endDayIndex - a.endDayIndex,
  );
  for (const e of sorted) {
    let row = rows.findIndex((last) => last < e.dayIndex);
    if (row === -1) {
      row = rows.length;
      rows.push(e.endDayIndex);
    } else {
      rows[row] = e.endDayIndex;
    }
    out.set(e.id, row);
  }
  return out;
}

const LANE_LABEL =
  "flex w-(--kloq-gutter-width,4rem) shrink-0 items-center justify-end pr-2.5 text-2xs text-muted-foreground select-none";

/** The lane before the calendar knows its date: the strip at its resting height, no columns. */
export function AllDayLaneFrame() {
  return (
    <div className="flex shrink-0 border-b">
      <div className={LANE_LABEL}>All day</div>
      <div className="h-7.5 min-w-0 flex-1 pointer-coarse:h-8" />
    </div>
  );
}

interface AllDayLaneProps {
  events: PlacedEvent[];
  /** visible column count from the view descriptor */
  dayCount: number;
  /** short day name per visible column (`view.namesShort`) — accessible names */
  dayNamesShort: string[];
  laneRef: React.RefObject<HTMLDivElement | null>;
  laneDraftRef: React.RefObject<HTMLDivElement | null>;
  selectedId: string | null;
  registerNode: (id: string, node: HTMLElement | null) => void;
  onLanePointerDown: (e: React.PointerEvent<HTMLDivElement>) => void;
  onEventPointerDown: (e: React.PointerEvent<HTMLElement>, event: PlacedEvent) => void;
  /** real date per visible column (`view.days`); see `fallbackDays` */
  days?: Date[];
  /** Select an event / a freshly created chip; this is what opens the panel. */
  onSelect?: (id: string | null, opts?: { isNew?: boolean }) => void;
  /** roving tabindex shared with the grid — see `lib/roving.ts` */
  rovingId?: string | null;
  /** columns under ~64px: chips show a title only */
  cramped?: boolean;
}

/** A `listitem` that adds semantics and no box. */
const CONTENTS: React.CSSProperties = { display: "contents" };

export function AllDayLane({
  events,
  dayCount,
  dayNamesShort,
  laneRef,
  laneDraftRef,
  selectedId,
  registerNode,
  onLanePointerDown,
  onEventPointerDown,
  days,
  onSelect,
  rovingId,
  cramped = false,
}: AllDayLaneProps) {
  const C = useSlots();
  const rowH = useCoarsePointer() ? ROW_H_TOUCH : ROW_H;
  const onSelectRef = useLatest(onSelect);
  const onChipActivate = useCallback((ev: PlacedEvent) => onSelectRef.current?.(ev.id), []);
  const { allDay, rows, rowCount, hidden, visible } = useMemo(() => {
    const allDay = events.filter((e) => e.allDay);
    const rows = layoutRows(allDay);
    const usedRows = rows.size ? Math.max(...rows.values()) + 1 : 1;
    const rowCount = Math.max(1, Math.min(MAX_ROWS, usedRows));
    const hidden = allDay.filter((e) => (rows.get(e.id) ?? 0) >= MAX_ROWS);
    const visible = allDay.filter((e) => (rows.get(e.id) ?? 0) < MAX_ROWS);
    return { allDay, rows, rowCount, hidden, visible };
  }, [events]);

  const columns = days ?? fallbackDays(dayCount, -1);
  const { constraints } = useConstraints();
  const blockedCols = useMemo(
    () => disabledAllDayColumns({ days: columns }, constraints),
    [columns, constraints],
  );
  const menu = useCalendarContextMenu({
    hostRef: laneRef,
    events: allDay,
    dayCount,
    allDay: true,
  });

  return (
    <div className="flex shrink-0 border-b">
      {/* gutter width grows with `timeZones`, hence the custom property */}
      <div className={LANE_LABEL}>All day</div>
      <ContextMenu open={menu.open} onOpenChange={menu.onOpenChange}>
        <ContextMenuTrigger
          onContextMenuCapture={menu.onContextMenuCapture}
          render={
            <div
              ref={laneRef}
              data-cal-lane
              data-cramped={cramped || undefined}
              data-craft="allday-promote"
              onPointerDown={onLanePointerDown}
              className="relative min-w-0 flex-1 touch-none select-none"
              style={{
                height: rowCount * rowH + 6 + (hidden.length > 0 ? rowH - ROW_H + MORE_H : 0),
              }}
            />
          }
        >
          {Array.from({ length: dayCount }, (_, i) => (
            <div
              key={i}
              aria-hidden
              className="pointer-events-none absolute inset-y-0 border-l border-border/70"
              style={{ left: `${(i / dayCount) * 100}%` }}
            />
          ))}

          {blockedCols.map((col) => (
            <div
              key={col}
              aria-hidden
              className="cal-blocked inset-y-0"
              style={{ left: `${(col / dayCount) * 100}%`, width: `${100 / dayCount}%` }}
            />
          ))}

          {/* one list for the lane; `pointer-events-none` keeps drag-create working between chips */}
          <div
            role="list"
            aria-label={`All-day events, ${allDay.length === 1 ? "1 event" : `${allDay.length} events`}`}
            className="pointer-events-none absolute inset-0"
          >
            {visible.map((event) => (
              <div key={event.id} role="listitem" style={CONTENTS}>
                <C.AllDayChip
                  event={event}
                  dayCount={dayCount}
                  dayNamesShort={dayNamesShort}
                  row={rows.get(event.id) ?? 0}
                  rowHeight={rowH}
                  selected={event.id === selectedId}
                  tabIndex={rovingTab(rovingId, event.id)}
                  registerNode={registerNode}
                  onPointerDown={onEventPointerDown}
                  onActivate={onChipActivate}
                />
              </div>
            ))}
          </div>

          <EventOverflow
            count={hidden.length}
            events={hidden}
            label={`Show ${plural(hidden.length, "more all-day event")}`}
            heading="All day"
            onSelect={onChipActivate}
            align="end"
            className="absolute right-1 bottom-0.5"
          />

          <div ref={laneDraftRef} hidden data-cal-lane-draft className="absolute z-30">
            <span data-slot="draft-label" />
          </div>
        </ContextMenuTrigger>

        {menu.target?.kind === "event" ? (
          <EventContextMenu
            event={menu.target.event}
            selected={menu.target.event.id === selectedId}
            host={laneRef}
            days={columns}
            onSelect={onSelect}
            close={menu.close}
          />
        ) : menu.target ? (
          <GridContextMenu
            slot={menu.target}
            host={laneRef}
            days={columns}
            todayIndex={-1}
            onSelect={onSelect}
            close={menu.close}
          />
        ) : null}
      </ContextMenu>
    </div>
  );
}

import { Asterisk, X } from "lucide-react";
import type { ReactElement } from "react";
import {
  attendeeLabel,
  attendeeStatus,
  avatarHue,
  initialsFor,
  STATUS_LABEL,
} from "../lib/attendees";
import type { Attendee, AttendeeStatus } from "../lib/event-types";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { Tooltip, TooltipPopup, TooltipTrigger } from "../ui/tooltip";

const STATUS_DOT: Record<AttendeeStatus, string> = {
  accepted: "bg-success",
  declined: "bg-destructive",
  tentative: "bg-warning",
  pending: "bg-muted-foreground/40",
};

function Action({ tip, children }: { tip: string; children: ReactElement }) {
  return (
    <Tooltip>
      <TooltipTrigger render={children} />
      <TooltipPopup>{tip}</TooltipPopup>
    </Tooltip>
  );
}

export function AttendeeChip({
  attendee,
  readOnly,
  organizer,
  you,
  onRemove,
  onCycle,
  onToggleOptional,
}: {
  attendee: Attendee;
  readOnly: boolean;
  /** RFC 5545 ORGANIZER */
  organizer: boolean;
  you: boolean;
  onRemove: () => void;
  onCycle: () => void;
  onToggleOptional: () => void;
}) {
  const hue = avatarHue(attendee.email);
  const status = attendeeStatus(attendee);
  const label = attendeeLabel(attendee);
  return (
    <li className="group/att flex items-center gap-2 rounded-md py-0.5 ps-2.5 pe-1 transition-colors hover:bg-accent/60">
      <span className="relative shrink-0">
        <span
          aria-hidden
          className={cn(
            "grid size-6 place-items-center rounded-full font-medium text-3xs tabular-nums",
            status === "declined" && "opacity-56",
          )}
          style={{
            backgroundColor: `color-mix(in oklab, hsl(${hue} 68% 50%) 18%, transparent)`,
            color: `color-mix(in oklab, hsl(${hue} 68% 46%) 28%, var(--foreground))`,
          }}
        >
          {initialsFor(attendee)}
        </span>
        <span
          aria-hidden
          className={cn(
            "absolute -right-px -bottom-px size-2 rounded-full ring-2 ring-card",
            STATUS_DOT[status],
          )}
        />
      </span>

      <span className="min-w-0 flex-1 leading-tight">
        <span
          className={cn(
            "block truncate text-xs text-foreground",
            status === "declined" && "line-through opacity-64",
          )}
        >
          {attendee.name ? (
            <Tooltip>
              <TooltipTrigger render={<span />}>{label}</TooltipTrigger>
              <TooltipPopup>{attendee.email}</TooltipPopup>
            </Tooltip>
          ) : (
            label
          )}
          {you ? <span className="ml-1 text-3xs text-muted-foreground">you</span> : null}
        </span>
        <span className="block truncate text-3xs text-muted-foreground">
          {STATUS_LABEL[status]}
          {organizer ? " · Organizer" : ""}
          {attendee.optional ? " · Optional" : ""}
        </span>
      </span>

      {readOnly ? null : (
        <span className="flex items-center opacity-0 transition-opacity group-hover/att:opacity-100 focus-within:opacity-100 pointer-coarse:opacity-100">
          <Action tip={attendee.optional ? "Mark as required" : "Mark as optional"}>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label={
                attendee.optional ? `Mark ${label} as required` : `Mark ${label} as optional`
              }
              aria-pressed={attendee.optional === true}
              className={cn("text-muted-foreground", attendee.optional && "text-foreground")}
              onClick={onToggleOptional}
            >
              <Asterisk />
            </Button>
          </Action>
          <Action tip={`${STATUS_LABEL[status]} — change`}>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label={`Set RSVP for ${label} — currently ${STATUS_LABEL[status]}`}
              className="text-muted-foreground"
              onClick={onCycle}
            >
              <span aria-hidden className={cn("size-2.5 rounded-full", STATUS_DOT[status])} />
            </Button>
          </Action>
          <Action tip="Remove guest">
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label={`Remove ${label}`}
              className="text-muted-foreground hover:text-destructive-foreground"
              onClick={onRemove}
            >
              <X />
            </Button>
          </Action>
        </span>
      )}
    </li>
  );
}

