/** A callback with a fixed identity that always runs the latest closure. */
function useStable<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  const latest = useLatest(fn);
  return useCallback((...args: A) => latest.current(...args), [latest]);
}

const durationMs = (value: string, fallback: number) => {
  const n = parseFloat(value);
  if (!Number.isFinite(n)) return fallback;
  return value.trim().endsWith("ms") ? n : n * 1000;
};

/**
 * Lets the event panel leave: when its child unmounts, a static copy fades out over the shared
 * overlay exit tokens. The copy is inert, and skipped entirely under reduced motion.
 */
function ExitPresence({ children }: { children: ReactNode }) {
  const id = useId();
  const present = children !== null && children !== undefined && children !== false;
  const [was, setWas] = useState(present);
  const [ghost, setGhost] = useState<HTMLElement | null>(null);
  if (was !== present) {
    setWas(present);
    // render phase, on purpose: the panel is still in the document here and gone by the next effect
    const live =
      present || prefersReducedMotion() ? null : document.getElementById(id)?.firstElementChild;
    if (live) {
      const copy = live.cloneNode(true) as HTMLElement;
      const fields = live.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>(
        "input, textarea",
      );
      copy
        .querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input, textarea")
        .forEach((field, i) => {
          field.value = fields[i]?.value ?? "";
        });
      setGhost(copy);
    } else setGhost(null);
  }

  useLayoutEffect(() => {
    if (!ghost) return;
    const host = document.getElementById(id);
    if (!host) return;
    ghost.setAttribute("inert", "");
    ghost.setAttribute("aria-hidden", "true");
    ghost.removeAttribute("role");
    ghost.removeAttribute("aria-label");
    ghost.setAttribute("data-exiting", "");
    host.appendChild(ghost);
    const tokens = getComputedStyle(host);
    const card = ghost.querySelector<HTMLElement>('[data-slot="card"]') ?? ghost;
    const exit = card.animate(
      [
        { opacity: 1, transform: "none" },
        {
          opacity: 0,
          transform: ghost.hasAttribute("data-sheet") ? "translateY(1rem)" : "scale(0.98)",
        },
      ],
      {
        duration: durationMs(tokens.getPropertyValue("--overlay-exit"), 100),
        easing: tokens.getPropertyValue("--overlay-ease").trim() || EASE_OUT,
        fill: "forwards",
      },
    );
    let live = true;
    void exit.finished.then(
      () => live && setGhost(null),
      () => {},
    );
    return () => {
      live = false;
      exit.cancel();
      ghost.remove();
    };
  }, [ghost, id]);

  return (
    <div id={id} className="contents">
      {children}
    </div>
  );
}

const CRAMPED_COLUMN = 64;

/** Stable empty density for every view that is not a year. */
const EMPTY_DENSITY: ReadonlyMap<string, DayLoad> = new Map();

/** Stable identity so a host that never passes `lanes` doesn't rebuild the timeline projection every render. */
const EMPTY_LANES: readonly Lane[] = [];
const DEFAULT_LANE_ADAPTER: LaneAdapter = byResourceId();

function CalendarAppInner({
  weekStartsOn,
  theme,
  scheme,
  view: viewProp,
  defaultView,
  onViewChange,
  date: dateProp,
  defaultDate,
  onDateChange,
  onRangeChange,
  rangePadding = 0,
  constraints,
  events: eventsProp,
  onEventsChange,
  defaultEvents,
  persistence,
  onCommit,
  designMode,
  commandPalette,
  workingHours,
  onEventClick,
  onEventDoubleClick,
  onSlotClick,
  onSelectionChange,
  globalShortcuts,
  responsive,
  currentUserEmail,
  showWeekNumbers = false,
  showDeclinedEvents = true,
  navigationKeys = "range",
  onTimeZonesClick,
  ssr = false,
  keymap,
  onCustomizeKeybinds,
  onUndo,
  onRedo,
  children,
  className,
  lanes,
  laneAdapter,
  timelineWindow,
}: InnerProps) {
  const C = useSlots();
  const g = useKloqSettings();
  // only stamp an authoring zone when the host asked for a display zone; else it's a machine-dependent claim
  const authoredZone = g.hasDisplayZone ? ({ timeZone: g.timeZone } as const) : undefined;
  const dmEnabled = designMode !== false;
  const dmHint = dmEnabled && (designMode === true || designMode.hint !== false);
  // the most recent drag-created event — the panel autofocuses its title only for this one
  const {
    store: calendarStore,
    events,
    controlled,
  } = useEventStore({
    events: eventsProp,
    onEventsChange,
    defaultEvents,
    persistence,
    onCommit,
    onReverted: (ids) => handleReverted(ids),
  });
  const [newId, setNewId] = useState<string | null>(null);
  // the panel is not the selection: it shows only while `panelId` is also the selection lead
  const [panelId, setPanelId] = useState<string | null>(null);

  const rootRef = useRef<HTMLDivElement>(null);
  // hosts with no scheme convention at all (no `dark`/`light` on <html>) follow the OS, scoped to the calendar
  const portalEl = usePortalContainer();
  useLayoutEffect(() => {
    const els = [rootRef.current, portalEl].filter((el): el is HTMLElement => !!el);
    const mq = matchMedia("(prefers-color-scheme: dark)");
    const html = document.documentElement;
    const apply = () => {
      if (scheme) return; // a pinned `scheme` owns the class
      const bare = !html.classList.contains("dark") && !html.classList.contains("light");
      const on = bare && getScheme() === "system" && mq.matches;
      for (const el of els) el.classList.toggle("dark", on);
    };
    apply();
    mq.addEventListener("change", apply);
    const mo = new MutationObserver(apply);
    mo.observe(html, { attributes: true, attributeFilter: ["class"] });
    return () => {
      mq.removeEventListener("change", apply);
      mo.disconnect();
    };
  }, [portalEl, scheme]);
  const nav = useViewNavigation({
    viewProp,
    defaultView,
    onViewChange,
    dateProp,
    defaultDate,
    onDateChange,
    responsive,
    weekStartsOn,
    rangePadding,
    onRangeChange,
    rootRef,
    // invoked at event time, after everything below is initialised
    onNavigate: () => {
      selection.clear();
      setNewId(null);
    },
    onViewSwitched: () => requestAnimationFrame(() => focusEvent(null)),
    announce: (m) => announce(m),
  });
  const {
    viewSetting,
    effectiveView,
    responsiveView,
    anchorDate,
    view,
    lastStep,
    switchView,
    jumpToDay,
    openMonth,
    step,
    stepDay,
    goToday,
    applyDate,
    range,
    rangeLabel,
    pending,
    ready,
  } = nav;
  const pendingMorph = pending.morph;
  const caps = capabilitiesOf(view.kind);
  // columns too narrow for a bar, a time and a title: blocks drop to the title alone
  const cramped =
    responsiveView.width > 0 &&
    (responsiveView.width - GUTTER_WIDTH) / view.dayCount < CRAMPED_COLUMN;
  const isTimeGrid = caps.timeGrid;
  const resolvedTimelineWindow = useMemo(
    () => resolveWindow(timelineWindow, anchorDate),
    [timelineWindow, anchorDate],
  );

  // a second zone reads ONE day's offsets — today's if visible, else the first (DST can differ by day)
  const gutterDate = gutterDateFor(view.days, view.todayIndex);
  const gutterWidth = useMemo(
    () =>
      g.timeZones.length === 0
        ? GUTTER_WIDTH
        : multiZoneGutterWidth(g.timeZones, g.fromDisplay(atNoon(gutterDate)), g.timeZone),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [g, gutterDate?.getTime()],
  );

  // the event layer waits one render: placement depends on today + localStorage, unknowable on the server
  const isClient = useIsClient();
  const { accounts, sources } = useCalendarSources();
  // both filters return their input untouched when nothing is hidden, so nothing downstream re-projects
  const visibleEvents = useMemo(() => {
    const onVisibleCalendars = filterVisibleEvents(events, sources);
    if (showDeclinedEvents || !currentUserEmail) return onVisibleCalendars;
    const kept = onVisibleCalendars.filter((e) => !hasDeclined(e, currentUserEmail));
    return kept.length === onVisibleCalendars.length ? onVisibleCalendars : kept;
  }, [events, sources, showDeclinedEvents, currentUserEmail]);
  /** Where a newly created event lands — the default ACCOUNT's calendar. */
  const newEventCalendar = useMemo(
    () => resolveDefaultCalendar(accounts, sources)?.id,
    [accounts, sources],
  );
  // spread into create paths; an explicit `undefined` key would persist as null
  const onDefaultCalendar = useMemo(
    () => (newEventCalendar ? ({ calendarId: newEventCalendar } as const) : undefined),
    [newEventCalendar],
  );
  // calendar colour is folded onto a derived copy so an inheriting event never stores a colour
  const coloured = useMemo(
    () =>
      sources.length === 0
        ? visibleEvents
        : visibleEvents.map((e) => {
            const color = resolveEventColor(e, sources);
            return color === e.color ? e : { ...e, color };
          }),
    [visibleEvents, sources],
  );
  // a year view is not projected (365 columns for one integer per day); it aggregates off the store
  const isYear = caps.projects === "range";
  const projected = useMemo(
    () =>
      (ssr || isClient) && ready && !isYear
        ? projectEvents(coloured, view, {
            dayStartMin: g.dayStartMin,
            dayEndMin: g.dayEndMin,
            timeZone: g.displayZone,
          })
        : EMPTY_PROJECTION,
    [coloured, view, ssr, isClient, ready, isYear, g.dayStartMin, g.dayEndMin, g.displayZone],
  );
  // a timeline's bars are lane placements over its own window, not day columns
  const timelineStart = resolvedTimelineWindow.start.getTime();
  const timelineEnd = resolvedTimelineWindow.end.getTime();
  const timelinePlaced = useMemo(
    () =>
      view.kind !== "timeline"
        ? null
        : (ssr || isClient) && ready
          ? projectTimeline(
              coloured,
              lanes ?? EMPTY_LANES,
              resolvedTimelineWindow,
              laneAdapter ?? DEFAULT_LANE_ADAPTER,
            ).all
          : EMPTY_PROJECTION.all,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      view.kind,
      ssr,
      isClient,
      ready,
      coloured,
      lanes,
      laneAdapter,
      timelineStart,
      timelineEnd,
      resolvedTimelineWindow.slotMinutes,
    ],
  );
  const placed = timelinePlaced ?? projected.all;

  // everything below the app bar — the element a range step slides
  const surfaceRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLDivElement>(null);
  const draftRef = useRef<HTMLDivElement>(null);
  const laneRef = useRef<HTMLDivElement>(null);
  const laneDraftRef = useRef<HTMLDivElement>(null);
  const registry = useRef(new Map<string, HTMLElement>()).current;

  const selection = useSelectionController({
    store: calendarStore,
    view,
    projected: placed,
    registry,
  });
  const selectionSeen = useRef<readonly string[] | null>(null);
  useEffect(() => {
    if (selectionSeen.current === selection.ids) return;
    const first = selectionSeen.current === null;
    selectionSeen.current = selection.ids;
    if (first && selection.ids.length === 0) return;
    const seen = new Set<string>();
    const events: CalEvent[] = [];
    for (const id of selection.ids) {
      const ev = calendarStore.get(masterIdOf(id));
      if (ev && !seen.has(ev.id)) {
        seen.add(ev.id);
        events.push(ev);
      }
    }
    onSelectionChange?.(events);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.ids]);
  const selectedId = selection.lead;

  // announcements happen on commit, never per frame
  const { announce, politeRef, assertiveRef } = useAnnouncer();

  /** How an event's time reads out loud, from a placement or a patch. */
  const whenOf = useCallback(
    (p: {
      dayIndex: number;
      endDayIndex?: number;
      startMin?: number;
      endMin?: number;
      allDay?: boolean;
    }): WhenRef =>
      p.allDay
        ? {
            day:
              p.endDayIndex !== undefined && p.endDayIndex !== p.dayIndex
                ? `${view.namesLong[p.dayIndex] ?? ""} to ${view.namesLong[p.endDayIndex] ?? ""}`
                : view.namesLong[p.dayIndex],
            allDay: true,
          }
        : {
            day: view.namesLong[p.dayIndex],
            time:
              p.startMin !== undefined && p.endMin !== undefined
                ? g.formatRange(p.startMin, p.endMin)
                : undefined,
          },
    [view, g],
  );

  /** The store event behind a placement id, for its title. */
  const eventOf = useCallback(
    (id: string) => calendarStore.get(masterIdOf(id)) ?? { title: undefined },
    [calendarStore],
  );

  // roving tabindex: one event carries `tabIndex={0}`, the selection lead — see `lib/roving.ts`
  const order = useMemo(() => selectionOrder(placed), [placed]);
  const rovingId = rovingTarget(order, selectedId);

  const focusEvent = useFocusFollow({
    rootRef,
    surfaceRef,
    registry,
    rovingId,
    selectedId,
    count: selection.count,
    announce,
  });

  const handleReverted = useRevertAnimation({ registry, announce, eventOf });

  useViewTransitions({ rootRef, surfaceRef, pending, view, projected });

  const density = useMemo(
    () =>
      (ssr || isClient) && ready && isYear
        ? densityByDay(coloured, {
            start: range.start,
            end: range.end,
            timeZone: g.displayZone,
          })
        : EMPTY_DENSITY,
    [ssr, isClient, ready, isYear, coloured, range, g.displayZone],
  );

  const registerNode = useCallback(
    (id: string, node: HTMLElement | null) => {
      if (node) registry.set(id, node);
      else registry.delete(id);
    },
    [registry],
  );

  // engine reads events per-frame through a ref — no engine re-wiring on render
  const projectedRef = useRef(projected);
  projectedRef.current = projected;

  const resolvedConstraints = useMemo(() => createConstraints(constraints), [constraints]);
  const constraintScope = useMemo(
    () => ({ constraints: resolvedConstraints, days: view.days }),
    [resolvedConstraints, view.days],
  );

  const askScope = useRecurrenceScope();
  const {
    commitPlacement,
    commitCreate,
    commitMove,
    commitResize,
    commitSpan,
    commitDuplicate,
    toggleAllDay,
    moveByDays,
    keyboardPatch,
  } = usePlacementCommits({
    store: calendarStore,
    view,
    projectedRef,
    askScope,
    constraints: resolvedConstraints,
    announce,
    whenOf,
    eventOf,
    onDefaultCalendar,
    authoredZone,
    snapshot: (masterId) => {
      pendingMorph.current = captureSnapshot(rootRef.current, true, masterId);
    },
    onPlanSelected: (from, to) => {
      selection.setLead(to);
      setPanelId((cur) => (cur === from ? to : cur));
    },
    onCreated: setNewId,
  });

  const { onCanvasPointerDown, onEventPointerDown, onLanePointerDown, flashEdges } = useDragEngine({
    view,
    settings: g,
    scrollRef,
    canvasRef,
    draftRef,
    laneRef,
    laneDraftRef,
    openEditor: (id) => {
      setNewId((cur) => (cur === id ? cur : null));
      selection.setLead(id);
      setPanelId(id);
      // the engine only reaches here on a true click, never a drag
      const ev = calendarStore.get(masterIdOf(id));
      if (ev) onEventClick?.(ev, id);
    },
    onCanvasClick: (e) => {
      setNewId(null);
      selection.clear();
      if (onSlotClick && e) {
        const slot = slotAtPointer(e);
        if (slot && slotAllowed(resolvedConstraints, slot)) onSlotClick(slot);
      }
    },
    commitCreate,
    commitMove,
    commitResize,
    commitSpan,
    commitDuplicate,
    getTimedEvents: () => projectedRef.current.timed,
    constraints: resolvedConstraints,
    announce,
  });

  const history = useHistory(calendarStore, registry);
  // announce, then re-focus the lead if it survived, else the surface
  const withHistory = (run: () => void, say: string) => () => {
    run();
    announce(say);
    requestAnimationFrame(() => focusEvent(selectedId));
  };
  const undo = withHistory(controlled ? (onUndo ?? (() => {})) : history.undo, announceUndo());
  const redo = withHistory(controlled ? (onRedo ?? (() => {})) : history.redo, announceRedo());

  // announcement + post-delete focus wrapped around the selection handle once, not at each call site
  const speakingSelection = useMemo<KloqSelectionHandle>(
    () => ({
      ...selection,
      remove: (ids) => {
        const requested = ids ? [...ids] : [...selection.ids];

        // a single recurring instance asks which occurrences; `masterIdOf` here would delete the whole series
        if (requested.length === 1) {
          const placed = projectedRef.current.all.find((e) => e.id === requested[0]);
          const occurrence = placed?.occurrence;
          const master = placed?.source;
          if (occurrence && master && !master.readOnly && askScope) {
            // computed before the delete, while the reading order still contains it
            const next = focusAfterRemoval(order, [requested[0]]);
            void askScope({
              action: "delete",
              event: master,
              occurrence,
            }).then((scope) => {
              if (!scope) return;
              applyPlan(calendarStore, deleteOccurrence(master, occurrence, scope));
              selection.clear();
              announce(announceDeleted([master]));
              requestAnimationFrame(() => focusEvent(next));
            });
            return;
          }
        }

        // `withoutSegment` (a split lead is `${id}@0`), NOT `masterIdOf` — that would delete a whole series
        const targets = requested
          .map((id) => calendarStore.get(id) ?? calendarStore.get(withoutSegment(id)))
          .filter((e): e is CalEvent => e !== undefined && !e.readOnly);
        if (targets.length === 0) return;
        // next focus target, computed before the delete in placement ids
        const removedIds = new Set(targets.map((e) => e.id));
        const next = focusAfterRemoval(
          order,
          requested.filter((id) => removedIds.has(withoutSegment(id))),
        );
        selection.remove(ids);
        announce(announceDeleted(targets));
        requestAnimationFrame(() => focusEvent(next));
      },
      recolor: (color) => {
        selection.recolor(color);
        announce(announceColor(selection.selectedEvents(), color));
      },
      duplicate: () => {
        const events = selection.selectedEvents();
        selection.duplicate();
        if (events.length === 1) announce(announceDuplicated(events[0], {}));
        else if (events.length > 1) announce(`${events.length} events duplicated`);
      },
    }),
    [selection, order, calendarStore, announce, focusEvent, askScope],
  );

  const [commandOpen, setCommandOpen] = useState(false);
  const paletteOn = commandPalette !== false;
  const paletteCommands = typeof commandPalette === "object" ? commandPalette.commands : undefined;
  const [shortcutsOpen, setShortcutsOpen] = useState(false);

  /** Create a snap-sized event, pop it in, select it, reveal it. */
  const { quickCreate, slotAtPointer, onCanvasDoubleClick } = useQuickCreate({
    store: calendarStore,
    view,
    registry,
    canvasRef,
    onDefaultCalendar,
    authoredZone,
    constraints: resolvedConstraints,
    announce,
    whenOf,
    onCreated: (id) => {
      setNewId(id);
      selection.setLead(id);
      setPanelId(id);
    },
  });

  useCalendarKeys({
    rootRef,
    globalShortcuts,
    keymap,
    flashEdges,
    projected: placed,
    view,
    selectedId,
    registry,
    select: (id) => {
      setNewId(null);
      selection.setLead(id);
      setPanelId((cur) => (cur !== null ? id : null));
    },
    panelOpen: panelId !== null && panelId === selectedId,
    openPanel: (id) => setPanelId(id),
    clearSelection: () => {
      setNewId(null);
      setPanelId(null);
      selection.clear();
    },
    updateEvent: keyboardPatch,
    quickCreate: () => quickCreate(),
    undo,
    redo,
    openCommand: () => setCommandOpen((v) => !v),
    commandPalette: paletteOn,
    openShortcuts: () => setShortcutsOpen(true),
    stepRange: step,
    stepDay,
    navigationKeys,
    goToday,
    switchView,
    selection: speakingSelection,
  });

  useEffect(() => watchSystemScheme(), []);
  const { initialScrollTop } = useGridMount({ rootRef, scrollRef, canvasRef, laneRef, isTimeGrid });

  // A rule edit can rename the occurrence under the panel (`id` → `id#instant`
  // when an event starts repeating) or drop it entirely (weekly → monthly).
  // Stay on the same series instead of losing the panel mid-edit.
  const selectedEvent = selectedId ? (placed.find((e) => e.id === selectedId) ?? null) : null;
  // the panel reads day-column placements; a timeline bar is re-expressed as one
  const timelinePanel =
    timelinePlaced && selectedEvent ? panelPlacement(selectedEvent, g.displayZone, g.locale) : null;

  // the selection follows its series through a rule edit (see use-selection);
  // the panel follows the selection, render-phase so it never unmounts in between
  if (
    panelId !== null &&
    selectedId !== null &&
    panelId !== selectedId &&
    masterIdOf(panelId) === masterIdOf(selectedId)
  ) {
    setPanelId(selectedId);
  }

  const panelOpen = panelId !== null && panelId === selectedId;

  // pointer and Enter selection: opens the panel unless told not to
  const select = useStable((id: string | null, opts?: { isNew?: boolean; open?: boolean }) => {
    setNewId(opts?.isNew ? id : null);
    selection.setLead(id);
    setPanelId(opts?.open === false ? null : id);
  });
  const onMoveByDays = useStable(moveByDays);
  const resetAll = useStable(() => {
    selection.clear();
    calendarStore.reset();
  });
  const openShortcuts = useStable(() => setShortcutsOpen(true));
  const paletteQuickCreate = useStable(() => quickCreate());
  const paletteSelectEvent = useStable((e: CalEvent) => {
    pendingMorph.current = captureSnapshot(rootRef.current);
    setNewId(null);
    applyDate(new Date(parseInstant(e.start)));
    selection.setLead(e.id);
    setPanelId(e.id);
    requestAnimationFrame(() =>
      requestAnimationFrame(() =>
        registry.get(e.id)?.scrollIntoView({ block: "center", behavior: "smooth" }),
      ),
    );
  });
  const closePanel = useStable(() => {
    setNewId(null);
    setPanelId(null);
  });
  // the panel's discard path: a just-created event is thrown away, anything else just closes
  const discardPanel = useStable(() => {
    if (newId !== null && selectedEvent && eventKeyOf(selectedEvent) === newId) {
      calendarStore.remove(newId);
      selection.clear();
    }
    setNewId(null);
    setPanelId(null);
  });

  // what the chrome parts and `useKloq()` see; memoised so unrelated state doesn't re-render consumers
  const chrome: KloqChrome = useMemo(
    () => ({
      view,
      viewSetting: effectiveView,
      collapsed: responsiveView.collapsed,
      narrow: responsiveView.width > 0 ? responsiveView.narrow : undefined,
      ready,
      timeline: lanes !== undefined,
      fits: (v: KloqView) =>
        !resolveEffectiveView(responsiveView.width, v, responsiveView.config).collapsed,
      date: anchorDate,
      atToday: view.todayIndex >= 0,
      lastStep,
      step,
      goToday,
      switchView,
      jumpToDay,
      goToDate: applyDate,
      reset: () => {
        selection.clear();
        calendarStore.reset();
      },
      openCommand: paletteOn ? () => setCommandOpen((v) => !v) : () => {},
      openShortcuts: () => setShortcutsOpen(true),
      keymap,
    }),
    [
      view,
      effectiveView,
      viewSetting,
      responsiveView.collapsed,
      responsiveView.narrow,
      responsiveView.width,
      responsiveView.config,
      anchorDate,
      lastStep,
      step,
      goToday,
      switchView,
      jumpToDay,
      applyDate,
      selection,
      calendarStore,
      keymap,
      paletteOn,
      lanes,
      ready,
    ],
  );

  return (
    <DesignModeProvider scopeRef={rootRef} globalToggle={globalShortcuts}>
      <AnnounceProvider value={announce}>
        <StoreProvider value={calendarStore}>
          <SelectionProvider value={speakingSelection}>
            <ChromeProvider value={chrome}>
              <ConstraintsProvider value={constraintScope}>
                {/* `h-full`, never `h-dvh`: the component fills whatever box the host gives it */}
                <div
                  ref={rootRef}
                  data-kloq-root
                  data-kloq-theme={theme && theme !== "coss" ? theme : undefined}
                  onDoubleClick={(e) => {
                    if (!onEventDoubleClick) return;
                    const el = (e.target as Element).closest<HTMLElement>("[data-cal-event]");
                    const id = el?.dataset.calEvent;
                    if (!id) return;
                    const ev = calendarStore.get(masterIdOf(id));
                    if (ev) onEventDoubleClick(ev, id);
                  }}
                  className={cn("flex h-full flex-col overflow-hidden", scheme, className)}
                  style={
                    {
                      "--kloq-hour-height": `${g.hourHeight}px`,
                      "--kloq-gutter-width": `${gutterWidth}px`,
                    } as React.CSSProperties
                  }
                >
                  {children}

                  <LiveRegions politeRef={politeRef} assertiveRef={assertiveRef} />

                  {/* the focus target of last resort; `tabIndex={-1}` so it is not an extra tab stop */}
                  <div
                    ref={surfaceRef}
                    role="region"
                    tabIndex={-1}
                    aria-label={
                      ready ? `${viewLabel(viewSetting)}, ${rangeLabel}` : viewLabel(viewSetting)
                    }
                    /* no focus ring: a landing pad, never tabbed to */
                    className="relative isolate flex min-h-0 flex-1 flex-col outline-none"
                  >
                    {/* not ready = no date to print yet: the structure at its final size, nothing that names a day */}
                    {!ready && !isTimeGrid ? null : view.kind === "year" ? (
                      <YearView
                        view={view}
                        weekStartsOn={weekStartsOn}
                        density={density}
                        onOpenDay={jumpToDay}
                        onOpenMonth={openMonth}
                      />
                    ) : view.kind === "month" ? (
                      <MonthView
                        view={view}
                        compact={responsiveView.narrow}
                        events={projected.all}
                        selectedId={selectedId}
                        registerNode={registerNode}
                        onSelect={select}
                        onOpenDay={jumpToDay}
                        viewSetting={effectiveView}
                        onSwitchView={switchView}
                        rovingId={rovingId}
                        onMoveByDays={onMoveByDays}
                      />
                    ) : view.kind === "agenda" ? (
                      <AgendaView
                        view={view}
                        events={projected.all}
                        selectedId={selectedId}
                        registerNode={registerNode}
                        onSelect={select}
                        onOpenDay={jumpToDay}
                        viewSetting={effectiveView}
                        onSwitchView={switchView}
                        rovingId={rovingId}
                      />
                    ) : view.kind === "timeline" ? (
                      <TimelineApp
                        lanes={lanes ?? EMPTY_LANES}
                        adapter={laneAdapter ?? DEFAULT_LANE_ADAPTER}
                        window={resolvedTimelineWindow}
                        selectedId={selectedId}
                        onSelect={select}
                        registerNode={registerNode}
                        workingHours={workingHours}
                        rovingId={rovingId}
                        onDefaultCalendar={onDefaultCalendar}
                        authoredZone={authoredZone}
                        announce={announce}
                        events={timelinePlaced ?? undefined}
                        keymap={keymap}
                      />
                    ) : (
                      <GutterDateProvider value={gutterDate}>
                        {!ready ? (
                          <div aria-hidden className="h-9 shrink-0 border-b" />
                        ) : (
                          <div
                            className="relative grid shrink-0 border-b pl-(--kloq-gutter-width)"
                            style={{
                              gridTemplateColumns: `repeat(${view.dayCount}, minmax(0, 1fr))`,
                            }}
                          >
                            {/* gutter corner: the ISO week of the first visible day, and the sticky zone labels */}
                            <div className="absolute inset-y-0 left-0 flex w-(--kloq-gutter-width) flex-col items-stretch justify-center gap-0.5">
                              {showWeekNumbers && view.days.length > 0 ? (
                                <abbr
                                  title={`ISO week ${isoWeek(view.days[0])}`}
                                  className={cn(ZONE_CAPTION, "self-center no-underline")}
                                >
                                  W{isoWeek(view.days[0])}
                                </abbr>
                              ) : null}
                              <GutterZoneLabels day={gutterDate} onPress={onTimeZonesClick} />
                            </div>
                            {view.days.map((d, i) => (
                              <C.DayHeader
                                key={d.toDateString()}
                                date={d}
                                index={i}
                                isToday={i === view.todayIndex}
                                nameShort={view.namesShort[i]}
                              />
                            ))}
                          </div>
                        )}

                        {!ready ? (
                          <AllDayLaneFrame />
                        ) : (
                          <AllDayLane
                            events={projected.allDay}
                            dayCount={view.dayCount}
                            dayNamesShort={view.namesShort}
                            laneRef={laneRef}
                            laneDraftRef={laneDraftRef}
                            selectedId={selectedId}
                            registerNode={registerNode}
                            onLanePointerDown={onLanePointerDown}
                            onEventPointerDown={onEventPointerDown}
                            days={view.days}
                            onSelect={select}
                            rovingId={rovingId}
                            cramped={cramped}
                          />
                        )}

                        <div className="relative flex min-h-0 flex-1 flex-col">
                          {/* before the grid in the DOM: its tab stop comes and goes with the time of day,
                    and must never sit between the grid and the event panel */}
                          {ready ? (
                            <JumpToNow
                              scrollRef={scrollRef}
                              todayIndex={view.todayIndex}
                              narrow={responsiveView.narrow}
                            />
                          ) : null}
                          <div
                            ref={scrollRef}
                            data-cal-scroll
                            data-craft="edge-scroll"
                            className="min-h-0 flex-1 overflow-y-auto overscroll-none"
                          >
                            {!ready ? (
                              <WeekGridFrame />
                            ) : (
                              <WeekGrid
                                events={projected.timed}
                                dayCount={view.dayCount}
                                dayNamesShort={view.namesShort}
                                todayIndex={view.todayIndex}
                                canvasRef={canvasRef}
                                scrollRef={scrollRef}
                                draftRef={draftRef}
                                registerNode={registerNode}
                                registry={registry}
                                onCanvasPointerDown={onCanvasPointerDown}
                                onCanvasDoubleClick={onCanvasDoubleClick}
                                onEventPointerDown={onEventPointerDown}
                                selectedId={selectedId}
                                workingHours={workingHours}
                                days={view.days}
                                viewSetting={effectiveView}
                                onSwitchView={switchView}
                                onSelect={select}
                                rovingId={rovingId}
                                cramped={cramped}
                              />
                            )}
                          </div>
                          {ssr || !ready ? (
                            /* pre-paint scroll: the layout effect runs at hydration, after SSR HTML painted at midnight */
                            <script
                              dangerouslySetInnerHTML={{
                                __html: `(function(){var s=document.currentScript;if(!s)return;var el=s.previousElementSibling;if(el&&!el.scrollTop)el.scrollTop=${initialScrollTop};})()`,
                              }}
                            />
                          ) : null}
                        </div>
                      </GutterDateProvider>
                    )}
                  </div>

                  <ExitPresence>
                    {selectedEvent && panelOpen ? (
                      <C.EventPanel
                        event={timelinePanel?.event ?? selectedEvent}
                        onSelectOccurrence={(id, date) => {
                          const day = startOfLocalDay(date).getTime();
                          if (!view.days.some((d) => startOfLocalDay(d).getTime() === day))
                            applyDate(date);
                          selection.setLead(id);
                          setPanelId(id);
                        }}
                        currentUserEmail={currentUserEmail}
                        dayNamesLong={timelinePanel?.namesLong ?? view.namesLong}
                        dayNamesShort={timelinePanel?.namesShort ?? view.namesShort}
                        /* `eventKeyOf`: a new event can already be split, with lead placement `${id}@0` */
                        isNew={newId !== null && eventKeyOf(selectedEvent) === newId}
                        getAnchor={(id) => nodeFor(registry, id) ?? null}
                        onToggleAllDay={(allDay) => toggleAllDay(selectedEvent, allDay)}
                        onEditTime={(startMin, endMin) => {
                          // minutes are in the event's OWN day (endMin past 1440 = next day), anchored off its real start
                          const was = minutesOfDate(
                            displayDate(parseInstant(selectedEvent.start), g.displayZone),
                          );
                          const start = instantPlus(
                            selectedEvent.start,
                            startMin - was,
                            g.displayZone,
                          );
                          void commitPlacement(
                            selectedEvent.id,
                            {
                              start,
                              end: instantPlus(start, endMin - startMin, g.displayZone),
                            },
                            announceResized(selectedEvent.source, {
                              time: g.formatRange(startMin, endMin),
                            }),
                          );
                        }}
                        onClose={closePanel}
                        onCancel={discardPanel}
                      />
                    ) : null}
                  </ExitPresence>

                  {paletteOn ? (
                    <KloqCommandMenu
                      keymap={keymap}
                      commands={paletteCommands}
                      open={commandOpen}
                      onOpenChange={setCommandOpen}
                      selectedEvent={selectedEvent?.source ?? null}
                      selectedOccurrence={selectedEvent?.occurrence ?? null}
                      days={view.days}
                      namesLong={view.namesLong}
                      viewSetting={effectiveView}
                      onSwitchView={switchView}
                      onJumpToDay={jumpToDay}
                      onToday={goToday}
                      onQuickCreate={paletteQuickCreate}
                      onReset={resetAll}
                      onShortcuts={openShortcuts}
                      /* search reads the whole store, not the visible projection */
                      events={events}
                      onStepRange={step}
                      defaultDurationMin={DEFAULT_QUICK_ADD_MIN}
                      onSelectEvent={paletteSelectEvent}
                    />
                  ) : null}
                  <ShortcutsOverlay
                    open={shortcutsOpen}
                    onOpenChange={setShortcutsOpen}
                    keymap={keymap}
                    commandPalette={paletteOn}
                    onCustomize={onCustomizeKeybinds}
                  />

                  {dmEnabled ? <DesignModeOverlay /> : null}
                  {dmHint ? <DesignModeHint /> : null}
                </div>
              </ConstraintsProvider>
            </ChromeProvider>
          </SelectionProvider>
        </StoreProvider>
      </AnnounceProvider>
    </DesignModeProvider>
  );
}

"use client";

/**
 * calendar-field — which calendar an event lives on. Picking commits through
 * `onChange` immediately; renders nothing when no sources are registered.
 */

import { ChevronDown, Lock } from "lucide-react";
import { type RefObject, useState } from "react";
import {
  type CalendarAccount,
  type CalendarAccountGroup,
  type CalendarSource,
  findCalendar,
  groupByAccount,
  useCalendarSources,
} from "../lib/calendar-sources";
import { EVENT_COLORS } from "../lib/event-palette";
import { cn } from "../lib/utils";
import {
  Menu,
  MenuGroup,
  MenuGroupLabel,
  MenuPopup,
  MenuRadioGroup,
  MenuRadioItem,
  MenuTrigger,
} from "../ui/menu";
import { GHOST_TRIGGER, RowValue } from "./panel-rows";

// Read-only calendars are dropped unless the event is already on one (it must stay checked).
export function calendarChoices(
  accounts: readonly CalendarAccount[],
  sources: readonly CalendarSource[],
  current?: string,
): CalendarAccountGroup[] {
  const offerable = sources.filter((s) => !s.readOnly || s.id === current);
  return groupByAccount(accounts, offerable).filter((g) => g.calendars.length > 0);
}

export function calendarSummary(calendar: CalendarSource | undefined): string {
  return calendar?.name ?? "No calendar";
}

export interface CalendarFieldProps {
  /** The event's `calendarId`. Unset, or unregistered, reads as unassigned. */
  value?: string;
  /** Commit. Always a registered, writable calendar — the whole source, since callers need the name. */
  onChange: (calendar: CalendarSource) => void;
  /** Renders the current calendar as static text with no controls. */
  readOnly?: boolean;
  /** Lets the panel focus the trigger after revealing the row. */
  triggerRef?: RefObject<HTMLButtonElement | null>;
  /** Accounts to offer. Omit to read the registry. */
  accounts?: readonly CalendarAccount[];
  /** Calendars to offer. Omit to read the registry. */
  sources?: readonly CalendarSource[];
  className?: string;
}

export function CalendarField({
  value,
  onChange,
  readOnly = false,
  triggerRef,
  accounts,
  sources,
  className,
}: CalendarFieldProps) {
  const [open, setOpen] = useState(false);

  const registry = useCalendarSources();
  const resolvedAccounts = accounts ?? registry.accounts;
  const resolvedSources = sources ?? registry.sources;

  const current = findCalendar(resolvedSources, value);
  const groups = calendarChoices(resolvedAccounts, resolvedSources, value);

  if (groups.length === 0) return null;

  const summary = calendarSummary(current);

  if (readOnly) {
    if (!current) return null;
    return (
      <RowValue className={className}>
        <CalendarDot color={current.color} />
        <span className="min-w-0 flex-1 truncate">{summary}</span>
      </RowValue>
    );
  }

  const pick = (id: string) => {
    const calendar = findCalendar(resolvedSources, id);
    // re-picking the current calendar is a close, not a commit: no-op writes still push undo
    if (calendar && calendar.id !== value) onChange(calendar);
  };

  return (
    <Menu open={open} onOpenChange={setOpen}>
      <MenuTrigger
        ref={triggerRef}
        aria-label={`Calendar — ${summary}`}
        className={cn(GHOST_TRIGGER, className)}
      >
        {current ? (
          <CalendarDot color={current.color} />
        ) : (
          <span
            aria-hidden
            className="size-2.5 shrink-0 rounded-full border border-muted-foreground"
          />
        )}
        <span
          className={cn(
            "min-w-0 flex-1 truncate",
            current ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {summary}
        </span>
        <ChevronDown
          aria-hidden
          className="size-3 shrink-0 text-muted-foreground transition-transform duration-(--overlay-enter) group-data-popup-open:rotate-180 motion-reduce:transition-none"
        />
      </MenuTrigger>

      <MenuPopup align="start" className="w-60">
        <MenuRadioGroup value={value ?? ""} onValueChange={pick}>
          {groups.map((group) => (
            <MenuGroup key={group.account.id}>
              <MenuGroupLabel>{group.account.label}</MenuGroupLabel>
              {group.calendars.map((cal) => (
                <MenuRadioItem
                  key={cal.id}
                  value={cal.id}
                  disabled={cal.readOnly}
                  closeOnClick
                  aria-label={`${cal.name} — ${group.account.label}`}
                >
                  <span className="flex min-w-0 items-center gap-2">
                    <CalendarDot color={cal.color} />
                    <span className="min-w-0 flex-1 truncate">{cal.name}</span>
                    {cal.readOnly ? (
                      <Lock aria-hidden className="size-3 shrink-0 text-muted-foreground" />
                    ) : null}
                  </span>
                </MenuRadioItem>
              ))}
            </MenuGroup>
          ))}
        </MenuRadioGroup>
      </MenuPopup>
    </Menu>
  );
}

function CalendarDot({ color }: { color: CalendarSource["color"] }) {
  return (
    <span
      aria-hidden
      className="size-2.5 shrink-0 rounded-full"
      style={{ backgroundColor: EVENT_COLORS[color].solid }}
    />
  );
}

"use client";

/**
 * The sidebar calendar list — accounts grouped, each calendar a colour dot,
 * a name and a visibility toggle. Reads the registry unless given props.
 */

import { Building2, Calendar as CalendarIcon, Globe, Lock, Mail, Unplug } from "lucide-react";
import * as React from "react";
import {
  accountDefaultCalendar,
  type CalendarAccount,
  type CalendarSource,
  CONFERENCING_PROVIDERS,
  type ConferencingProvider,
  conferencingLabel,
  disconnectAccount,
  groupByAccount,
  isVisible,
  providerLabel,
  setAccountConferencing,
  setAccountDefaultCalendar,
  setCalendarVisible,
  setDefaultAccount,
  setDefaultCalendar,
  useCalendarSources,
} from "../lib/calendar-sources";
import { cn } from "../lib/utils";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import { Checkbox } from "../ui/checkbox";
import { SegmentedControl, SegmentedControlItem } from "../ui/segmented-control";
import { Select, SelectItem, SelectPopup, SelectTrigger, SelectValue } from "../ui/select";
import { Tooltip, TooltipPopup, TooltipTrigger } from "../ui/tooltip";
import { EVENT_COLORS } from "./event-block";

const PROVIDER_ICONS: Record<string, React.ComponentType<{ className?: string }>> = {
  google: Mail,
  gmail: Mail,
  outlook: Building2,
  microsoft: Building2,
  office365: Building2,
  caldav: Globe,
  ical: Globe,
  icloud: Globe,
};

// module-scope so the looked-up icon isn't a new component identity per render
function ProviderIcon({
  provider,
  className,
}: {
  provider: string;
  className?: string;
}): React.ReactElement {
  const Icon = PROVIDER_ICONS[provider.toLowerCase()] ?? CalendarIcon;
  return <Icon className={className} />;
}

export interface CalendarListProps {
  /** Accounts to render. Omit to read the registry. */
  accounts?: CalendarAccount[];
  /** Calendars to render. Omit to read the registry. */
  sources?: CalendarSource[];
  /** A calendar's visibility was toggled. Omit → the registry. */
  onToggleVisible?: (id: string, visible: boolean) => void;
  /** A calendar was made the default. Omit → the registry. */
  onSetDefault?: (id: string) => void;
  /** Show the "make default" affordance on writable calendars. */
  allowSetDefault?: boolean;
  /** Render account-management chrome (conferencing picker, default account, Disconnect). */
  accountActions?: boolean;
  /** Conferencing options offered per account. Defaults to `CONFERENCING_PROVIDERS`. */
  conferencing?: readonly ConferencingProvider[];
  /** An account's default conferencing changed. Omit → the registry. */
  onSetAccountConferencing?: (accountId: string, conferencing: string) => void;
  /** An account was made the default. Omit → the registry. */
  onSetDefaultAccount?: (accountId: string) => void;
  /** Disconnect was pressed. Omit → the registry drops the account; no confirmation step. */
  onDisconnectAccount?: (accountId: string) => void;
  /** Section heading; pass `null` for none. Default "Calendars". */
  heading?: React.ReactNode;
  /** Rendered when nothing is registered. Default: render nothing at all. */
  empty?: React.ReactNode;
  className?: string;
}

export function CalendarList({
  accounts,
  sources,
  onToggleVisible,
  onSetDefault,
  allowSetDefault = true,
  accountActions = false,
  conferencing = CONFERENCING_PROVIDERS,
  onSetAccountConferencing,
  onSetDefaultAccount,
  onDisconnectAccount,
  heading = "Calendars",
  empty = null,
  className,
}: CalendarListProps): React.ReactElement | null {
  const registry = useCalendarSources();
  const resolvedAccounts = accounts ?? registry.accounts;
  const resolvedSources = sources ?? registry.sources;

  const groups = React.useMemo(
    () => groupByAccount(resolvedAccounts, resolvedSources),
    [resolvedAccounts, resolvedSources],
  );

  const toggle = React.useCallback(
    (cal: CalendarSource) => {
      const next = !isVisible(cal);
      if (onToggleVisible) onToggleVisible(cal.id, next);
      else setCalendarVisible(cal.id, next);
    },
    [onToggleVisible],
  );

  const makeDefault = React.useCallback(
    (cal: CalendarSource) => {
      // account-scoped and global defaults move together, or badge and create path disagree
      if (onSetDefault) onSetDefault(cal.id);
      else {
        setDefaultCalendar(cal.id);
        setAccountDefaultCalendar(cal.accountId, cal.id);
      }
    },
    [onSetDefault],
  );

  const setConferencing = React.useCallback(
    (accountId: string, id: string) => {
      if (onSetAccountConferencing) onSetAccountConferencing(accountId, id);
      else setAccountConferencing(accountId, id);
    },
    [onSetAccountConferencing],
  );

  const makeDefaultAccount = React.useCallback(
    (accountId: string) => {
      if (onSetDefaultAccount) onSetDefaultAccount(accountId);
      else setDefaultAccount(accountId);
    },
    [onSetDefaultAccount],
  );

  const disconnect = React.useCallback(
    (accountId: string) => {
      if (onDisconnectAccount) onDisconnectAccount(accountId);
      else disconnectAccount(accountId);
    },
    [onDisconnectAccount],
  );

  if (groups.length === 0) return empty === null ? null : <>{empty}</>;

  return (
    <div
      data-craft="calendar-list"
      data-craft-label="Accounts → calendars"
      className={cn("flex flex-col gap-3 text-sm", className)}
    >
      {heading !== null && (
        <h2 className="font-heading px-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
          {heading}
        </h2>
      )}

      {groups.map((group) => (
        <section
          key={group.account.id}
          aria-label={group.account.label}
          data-craft="calendar-account"
          className="group/account flex flex-col gap-1"
        >
          <AccountHeader
            account={group.account}
            calendars={group.calendars}
            actions={accountActions}
            conferencing={conferencing}
            onSetConferencing={setConferencing}
            onMakeDefault={makeDefaultAccount}
            onDisconnect={disconnect}
          />

          {group.calendars.length === 0 ? (
            <p className="px-1 py-1 text-xs text-muted-foreground">No calendars</p>
          ) : (
            <ul className="flex flex-col">
              {group.calendars.map((cal) => (
                <CalendarRow
                  key={cal.id}
                  calendar={cal}
                  onToggle={toggle}
                  onMakeDefault={allowSetDefault ? makeDefault : undefined}
                />
              ))}
            </ul>
          )}
        </section>
      ))}
    </div>
  );
}

function AccountHeader({
  account,
  calendars,
  actions,
  conferencing,
  onSetConferencing,
  onMakeDefault,
  onDisconnect,
}: {
  account: CalendarAccount;
  calendars: CalendarSource[];
  actions: boolean;
  conferencing: readonly ConferencingProvider[];
  onSetConferencing: (accountId: string, id: string) => void;
  onMakeDefault: (accountId: string) => void;
  onDisconnect: (accountId: string) => void;
}): React.ReactElement {
  const conference = conferencingLabel(account, conferencing);
  const landing = accountDefaultCalendar(account, calendars);

  return (
    <header className="flex flex-col gap-1 px-1">
      <div className="flex items-center gap-2">
        {account.avatarUrl ? (
          /* eslint-disable-next-line @next/next/no-img-element */
          <img
            src={account.avatarUrl}
            alt=""
            className="size-5 shrink-0 rounded-full object-cover"
          />
        ) : (
          <span
            aria-hidden
            className="flex size-5 shrink-0 items-center justify-center rounded-full border text-muted-foreground"
          >
            <ProviderIcon provider={account.provider} className="size-3" />
          </span>
        )}

        <span className="min-w-0 flex-1 truncate text-xs font-medium text-foreground">
          {account.label}
        </span>

        {account.isDefault && (
          <Tooltip>
            <TooltipTrigger
              render={
                <Badge variant="outline" size="sm">
                  Default
                </Badge>
              }
            />
            <TooltipPopup>
              New events land in this account
              {landing ? ` — ${landing.name}` : ""}
            </TooltipPopup>
          </Tooltip>
        )}

        {actions && !account.isDefault && (
          <Button
            variant="ghost"
            size="xs"
            onClick={() => onMakeDefault(account.id)}
            className={cn(
              REVEAL,
              "group-hover/account:opacity-100 group-focus-within/account:opacity-100",
            )}
          >
            Set default
          </Button>
        )}

        {actions && (
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="icon-xs"
                  aria-label={`Disconnect ${account.label}`}
                  onClick={() => onDisconnect(account.id)}
                  className={cn(
                    REVEAL,
                    "hover:text-destructive-foreground group-hover/account:opacity-100 group-focus-within/account:opacity-100",
                  )}
                >
                  <Unplug />
                </Button>
              }
            />
            <TooltipPopup>Disconnect — removes its calendars</TooltipPopup>
          </Tooltip>
        )}

        {!actions && (
          <span className="shrink-0 text-3xs text-muted-foreground uppercase">
            {providerLabel(account)}
          </span>
        )}
      </div>

      {actions ? (
        <div className="flex flex-wrap items-center justify-between gap-1.5 pl-7">
          <span className="text-2xs text-muted-foreground">{providerLabel(account)}</span>
          <Select
            items={conferencing.map((c) => ({ value: c.id, label: c.label }))}
            value={account.defaultConferencing ?? conferencing[0]?.id}
            onValueChange={(id) => id && onSetConferencing(account.id, id as string)}
          >
            <SelectTrigger
              size="xs"
              className="w-auto min-w-28"
              aria-label={`Default conferencing for ${account.label}`}
            >
              <SelectValue />
            </SelectTrigger>
            <SelectPopup size="xs">
              {conferencing.map((c) => (
                <SelectItem key={c.id} value={c.id}>
                  {c.label}
                </SelectItem>
              ))}
            </SelectPopup>
          </Select>
        </div>
      ) : (
        conference && <span className="pl-7 text-2xs text-muted-foreground">{conference}</span>
      )}
    </header>
  );
}

/** One-of-many choice on the `SegmentedControl` primitive, fed from `{ id, label }` options. */
export function SegmentedChoice<T extends { id: string; label: string }>({
  label,
  options,
  value,
  onChange,
  className,
}: {
  label: string;
  options: readonly T[];
  value: string | undefined;
  onChange: (id: string) => void;
  className?: string;
}): React.ReactElement {
  return (
    <SegmentedControl
      size="xs"
      aria-label={label}
      value={value}
      onValueChange={(id) => onChange(id as string)}
      className={className}
    >
      {options.map((o) => (
        <SegmentedControlItem key={o.id} value={o.id}>
          {o.label}
        </SegmentedControlItem>
      ))}
    </SegmentedControl>
  );
}

function CalendarRow({
  calendar,
  onToggle,
  onMakeDefault,
}: {
  calendar: CalendarSource;
  onToggle: (cal: CalendarSource) => void;
  onMakeDefault?: (cal: CalendarSource) => void;
}): React.ReactElement {
  const visible = isVisible(calendar);
  const swatch = EVENT_COLORS[calendar.color];

  return (
    <li className="group/cal flex items-center gap-1">
      <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2 rounded-md px-1 py-1 transition-colors hover:bg-accent">
        <Checkbox
          checked={visible}
          onCheckedChange={() => onToggle(calendar)}
          // the calendar's own colour fills the box
          style={
            {
              "--primary": swatch.solid,
              "--primary-foreground": "var(--color-white)",
              borderColor: visible ? undefined : swatch.solid,
            } as React.CSSProperties
          }
        />

        <span
          className={cn(
            "truncate transition-colors",
            visible ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {calendar.name}
        </span>

        {calendar.readOnly && (
          <Tooltip>
            <TooltipTrigger
              render={
                <span className="shrink-0 text-muted-foreground">
                  <Lock className="size-3" aria-label="Read-only" />
                </span>
              }
            />
            <TooltipPopup>Read-only — events can&rsquo;t be edited here</TooltipPopup>
          </Tooltip>
        )}
      </label>

      {calendar.isDefault ? (
        <Tooltip>
          <TooltipTrigger
            render={
              <Badge variant="outline" size="sm">
                Default
              </Badge>
            }
          />
          <TooltipPopup>New events land here</TooltipPopup>
        </Tooltip>
      ) : (
        onMakeDefault &&
        !calendar.readOnly && (
          <Button
            variant="ghost"
            size="xs"
            onClick={() => onMakeDefault(calendar)}
            className={cn(REVEAL, "group-hover/cal:opacity-100 group-focus-within/cal:opacity-100")}
          >
            Set default
          </Button>
        )
      )}
    </li>
  );
}

// always in the a11y tree; only visible on hover/focus
const REVEAL =
  "shrink-0 text-muted-foreground opacity-0 transition-opacity focus-visible:opacity-100 pointer-coarse:opacity-100";

/** Shared state classes for grid cells that cannot be a `Button` (chips, rows, day cells). */

export const FOCUS_RING =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background";

/** For full-bleed rows, where an offset ring would be clipped by the scroller. */
export const FOCUS_RING_INSET =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset";

export const CELL_HOVER = "transition-colors duration-150 hover:bg-accent";

"use client";

/** Chrome — the app bar as composable parts; must render inside `<Kloq>`. */

import { RotateCcw } from "lucide-react";
import { createContext, type ReactNode, useContext } from "react";
import type { KloqView, ViewDescriptor } from "../lib/calendar-types";
import type { Keymap } from "../lib/keymap";
import type { StepDirection } from "../lib/navigation";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { Tooltip, TooltipPopup, TooltipTrigger } from "../ui/tooltip";
import { CalendarNav } from "./nav";
import { useKloqSettings } from "./settings-context";

export interface KloqChrome {
  /** the resolved EFFECTIVE view (a narrow box may force day view) */
  view: ViewDescriptor;
  /** the effective view SETTING (`"week"`, `3`, `"month"`…), not the shape */
  viewSetting: KloqView;
  /** true when a narrow box is overriding the consumer's view */
  collapsed?: boolean;
  /** true below the narrow breakpoint (phone width); `undefined` until the box has been measured */
  narrow?: boolean;
  /**
   * False on the server and during hydration when the calendar was given no `date`/`defaultDate`
   * plus `locale` to render from: `date` and `view` are placeholders until it turns true.
   */
  ready?: boolean;
  /** true when the host passed `lanes`, so a Timeline view exists to switch to */
  timeline?: boolean;
  /** whether a view fits the box at its current width */
  fits?: (view: KloqView) => boolean;
  /** anchor date the view is resolved around */
  date: Date;
  /** true when today is inside the visible range */
  atToday: boolean;
  /** direction of the last range step, for directional animation */
  lastStep: StepDirection | null;
  /** step the range by one of the current view's units */
  step: (dir: StepDirection) => void;
  /** move the range back onto today */
  goToday: () => void;
  /** request a view change (reports through `onViewChange`) */
  switchView: (view: KloqView) => void;
  /** move the anchor date and switch to the day view */
  jumpToDay: (date: Date) => void;
  /** move the anchor date, leaving the view alone */
  goToDate: (date: Date) => void;
  reset: () => void;
  /** toggle ⌘K; a no-op under `commandPalette: false` */
  openCommand: () => void;
  openShortcuts: () => void;
  /** keymap overrides, so advertised keys show the live binding */
  keymap?: Keymap;
}

const ChromeContext = createContext<KloqChrome | null>(null);

export const ChromeProvider = ChromeContext.Provider;

/** The calendar's live view state and navigation actions. Throws outside `<Kloq>`. */
export function useKloq(): KloqChrome {
  const chrome = useContext(ChromeContext);
  if (!chrome) throw new Error("useKloq must be used inside <Kloq> (as a child of it)");
  return chrome;
}

export interface KloqToolbarProps {
  /** the bar's contents; omit for the default nav-left / Reset-right layout */
  children?: ReactNode;
  className?: string;
}

/** A bordered app-bar row above the calendar surface. Pure layout. */
export function KloqToolbar({ children, className }: KloqToolbarProps) {
  return (
    <header
      className={cn(
        // `flex-wrap` is the toolbar's only responsiveness: nav and controls stack when narrow
        "@container flex shrink-0 flex-wrap items-center justify-between gap-x-4 gap-y-2 border-b px-4 py-2.5",
        className,
      )}
    >
      {children ?? (
        <>
          <KloqNav />
          <KloqReset />
