export function KloqNav({ className }: { className?: string }) {
  const k = useKloq();
  const { locale } = useKloqSettings();
  return (
    <CalendarNav
      className={className}
      view={k.view}
      viewSetting={k.viewSetting}
      onStep={k.step}
      onToday={k.goToday}
      onSwitchView={k.switchView}
      atToday={k.atToday}
      date={k.date}
      onGoToDate={k.goToDate}
      lastStep={k.lastStep}
      collapsed={k.collapsed}
      narrow={k.narrow}
      ready={k.ready}
      locale={locale}
      timeline={k.timeline}
