          </>
        )}
      </div>

      {/* no resize edge at a midnight cut — it isn't the event's edge */}
      {before ? null : (
        <div
          aria-hidden
          data-resize-edge="start"
          // coarse pointers get a 24px hit zone (WCAG 2.2 target minimum)
          className="absolute -top-1 left-0 right-0 h-2 cursor-ns-resize pointer-coarse:-top-3 pointer-coarse:h-6"
        />
      )}
      {after ? null : (
        <div
          aria-hidden
          data-resize-edge="end"
          className="absolute -bottom-1 left-0 right-0 flex h-2 cursor-ns-resize items-center justify-center pointer-coarse:-bottom-3 pointer-coarse:h-6"
        >
          <span
            className={cn(
              "h-0.75 w-6 rounded-full opacity-0 transition-opacity duration-150 group-hover:opacity-60",
              c.bar,
            )}
          />
        </div>
      )}
    </div>
  );
}, sameBlock);

