/** Default length of an event created from ⌘K, matching quick-create. */
export const DEFAULT_QUICK_ADD_MIN = 30;

interface Action {
  id: string;
  /** What the filter matches against — label plus synonyms. */
  search: string;
  label: string;
  /** Muted secondary line: an event's date, a preset's resolved day. */
  meta?: string;
  hint?: string | readonly string[];
  icon?: ReactNode;
  group: string;
  order?: number;
  checked?: boolean;
  disabled?: boolean;
  /** Already derived from the query — never filter it out again. */
  always?: boolean;
  /** Opens a nested picker: renders a chevron and keeps the dialog open. */
  nested?: boolean;
  /** Acts immediately but leaves the dialog open — a live preview toggle. */
  keepOpen?: boolean;
  run: () => void;
}

type MenuMode = "commands" | "quick-add" | "move-to" | "date" | "theme";

interface KloqCommandMenuProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  days: Date[];
  namesLong: string[];
  viewSetting: KloqView;
  onSwitchView: (view: KloqView) => void;
  onJumpToDay: (date: Date) => void;
  onToday: () => void;
  /** Step the visible range by its own unit; omit and the two rows don't appear. */
  onStepRange?: (dir: -1 | 1) => void;
  onQuickCreate: () => void;
  onReset: () => void;
  onShortcuts: () => void;
  /** The whole store, not the visible projection — search spans every event. */
  events?: CalEvent[];
  /** Navigate to and select an event; without it, results are inert. */
  onSelectEvent?: (event: CalEvent) => void;
  /** Length of a quick-added event when the text doesn't say. */
  defaultDurationMin?: number;
  /** The currently selected event; enables "Move to…". */
  selectedEvent?: CalEvent | null;
  /** Selected occurrence of a recurring series; scoped "Move to…" falls back to the first. */
  selectedOccurrence?: Occurrence | null;
  /** Keymap overrides so key hints show the real bindings. */
  keymap?: Keymap;
  /** Built-in allowlist (see `BUILT_IN_COMMANDS`); omit for all. Registered commands always show. */
  commands?: readonly string[];
}

const DAY_LABEL = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  day: "numeric",
  month: "short",
});
const DAY_LABEL_YEAR = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  day: "numeric",
  month: "short",
  year: "numeric",
});
const dayLabel = (date: Date, now: Date): string =>
  (date.getFullYear() === now.getFullYear() ? DAY_LABEL : DAY_LABEL_YEAR).format(date);

const DATE_PRESETS: [string, string][] = [
  ["today", "Today"],
  ["tomorrow", "Tomorrow"],
  ["yesterday", "Yesterday"],
  ["next monday", "Next Monday"],
  ["next week", "Next week"],
];

export function KloqCommandMenu(props: KloqCommandMenuProps) {
  return (
    <CommandDialog open={props.open} onOpenChange={props.onOpenChange}>
      <CommandDialogPopup aria-label="Command menu">
        <CommandMenuBody {...props} />
      </CommandDialogPopup>
    </CommandDialog>
  );
}

/** Mounted only while the popup is: a closed menu builds nothing. */
function CommandMenuBody({
  onOpenChange,
  days,
  namesLong,
  viewSetting,
  onSwitchView,
  onJumpToDay,
  onToday,
  onStepRange,
  onQuickCreate,
  onReset,
  onShortcuts,
  events,
  onSelectEvent,
  defaultDurationMin = DEFAULT_QUICK_ADD_MIN,
  selectedEvent,
  selectedOccurrence,
  keymap,
  commands,
}: KloqCommandMenuProps) {
  const { toggle: toggleDesignMode } = useDesignMode();
  const store = useKloqStore();
  const g = useKloqSettings();
  const askScope = useRecurrenceScope();

  const [mode, setMode] = useState<MenuMode>("commands");
  const [query, setQuery] = useState("");
  const [quickValue, setQuickValue] = useState("");
  const [moveValue, setMoveValue] = useState("");
  const [isDark, setIsDark] = useState(() => resolveScheme() === "dark");
  const [themeId, setThemeId] = useState(getTheme);
  const [now] = useState(() => new Date());

  const [registered, setRegistered] = useState<KloqCommand[]>(getCommands);
  useEffect(() => subscribeCommands(() => setRegistered(getCommands())), []);

  // read through a ref so a host passing inline callbacks never rebuilds the action list
  const cb = useLatest({
    onOpenChange,
    onSwitchView,
    onJumpToDay,
    onToday,
    onStepRange,
    onQuickCreate,
    onReset,
    onShortcuts,
    onSelectEvent,
    toggleDesignMode,
  });
  const close = () => cb.current.onOpenChange(false);
  // first render, before the input autofocuses: the calendar this menu was opened from
  const [root] = useState<ParentNode>(
    () => document.activeElement?.closest("[data-kloq-root]") ?? document,
  );
  // the palette restores focus to where it came from unless focus has moved on; a command that
  // selects an event moves it to that event's block
  const selectEvent = (e: CalEvent) => {
    cb.current.onSelectEvent?.(e);
    requestAnimationFrame(() =>
      requestAnimationFrame(() =>
        root
          .querySelector<HTMLElement>('[data-cal-event][data-selected="true"]')
          ?.focus({ preventScroll: true }),
      ),
    );
  };

  const movable = selectedEvent && canEditEvent(selectedEvent) ? selectedEvent : null;
  const canStep = Boolean(onStepRange);
  const canSelect = Boolean(onSelectEvent);

  const parsed = useMemo(
    () => parseQuickAdd(quickValue, now, { defaultDurationMin }),
    [quickValue, now, defaultDurationMin],
  );

  const commitQuickAdd = () => {
    const r = parsed;
    if (!r.start || !r.end) return;
    const preview = quickAddPreview(r, now);
    const calendarId = newEventCalendarId();
    const base = {
      id: g.makeId(),
      title: preview.title,
      ...(calendarId ? { calendarId } : {}),
      ...(r.location ? { location: r.location } : {}),
      ...(r.attendees.length ? { attendees: r.attendees.map((email) => ({ email })) } : {}),
    };
    // the parser's all-day `end` is inclusive; the store's is exclusive
    const event: CalEvent = r.allDay
      ? {
          ...base,
          allDay: true,
          start: toDateOnlyString(r.start),
          end: toDateOnlyString(addDays(r.end, 1)),
        }
      : {
          ...base,
          start: formatInstant(r.start),
          end: formatInstant(r.end),
        };
    store.add(event);
    close();
    selectEvent(event);
  };

  const openQuickAdd = (seed: string) => {
    setQuickValue(seed);
    setMode("quick-add");
  };

  const run = (a: Action) => {
    if (a.disabled) return;
    // close first so the action never animates behind a closing sheet
    if (!a.nested && !a.keepOpen) close();
    a.run();
  };

  const movableTitle = movable ? eventTitle(movable) : null;

  const staticActions = useMemo<Action[]>(() => {
    const bound = resolveKeymap(keymap).byAction;
    const hintFor = (id: KeyActionId): string | undefined => {
      const key = bound[id];
      return key ? displayKey(key) : undefined;
    };
    const out: Action[] = [
      {
        id: "new-event",
        search: "new event create",
        label: "New event",
        hint: hintFor("create"),
        icon: <CalendarPlus />,
        group: "Calendar",
        order: 0,
        run: () => cb.current.onQuickCreate(),
      },
      {
        id: "quick-add",
        search: "quick add natural language parse",
        label: "Quick add…",
        meta: "Type “lunch tomorrow 1pm”",
        icon: <CalendarClock />,
        group: "Calendar",
        order: 1,
        nested: true,
        run: () => openQuickAdd(""),
      },
      {
        id: "reset",
        search: "reset sample events restore",
        label: "Reset sample events",
        icon: <RotateCcw />,
        group: "Calendar",
        order: 3,
        run: () => cb.current.onReset(),
      },
      {
        id: "today",
        search: "go to today now",
        label: "Go to today",
        hint: hintFor("today"),
        icon: <CalendarDays />,
        group: "Navigation",
        order: 0,
        run: () => cb.current.onToday(),
      },
      {
        id: "go-to-date",
        search: "go to date jump picker calendar",
        label: "Go to date…",
        icon: <CalendarSearch />,
        group: "Navigation",
        order: 1,
        nested: true,
        run: () => {
          setQuery("");
          setMode("date");
        },
      },
    ];
    if (movableTitle !== null)
      out.push({
        id: "move-to",
        search: "move to reschedule shift event",
        label: `Move “${movableTitle}” to…`,
        meta: "“next tuesday”, “3pm”, “+2h”",
        icon: <CalendarClock />,
        group: "Calendar",
        order: 2,
        nested: true,
        run: () => {
          setMoveValue("");
          setMode("move-to");
        },
      });
    if (canStep)
      out.push(
        {
          id: "range:prev",
          search: "previous range back week day month earlier",
          label: "Previous range",
          hint: "←",
          icon: <ChevronLeft />,
          group: "Navigation",
          order: 100,
          run: () => cb.current.onStepRange?.(-1),
        },
        {
          id: "range:next",
          search: "next range forward week day month later",
          label: "Next range",
          hint: "→",
          icon: <ChevronRight />,
          group: "Navigation",
          order: 101,
          run: () => cb.current.onStepRange?.(1),
        },
      );
    dayJumps(days).forEach((d, i) => {
      out.push({
        id: `jump:${d.toDateString()}`,
        search: `jump ${namesLong[i] ?? ""} ${d.getDate()} ${dayLabel(d, now)}`,
        label: `Jump to ${namesLong[i] ?? ""} ${d.getDate()}`,
        icon: <CalendarDays />,
        group: "Navigation",
        order: 2 + i,
        run: () => cb.current.onJumpToDay(d),
      });
    });
    VIEW_META.forEach(({ key, command: label, action, icon: Icon }, order) => {
      out.push({
        id: `view:${String(key)}`,
        search: `view ${label}`,
        label,
        hint: hintFor(action),
        icon: <Icon />,
        group: "View",
        order,
        checked: key === viewSetting,
        run: () => cb.current.onSwitchView(key),
      });
    });
    out.push(
      {
        id: "scheme:toggle",
        search: `appearance ${isDark ? "light" : "dark"} mode theme`,
        label: `Switch to ${isDark ? "light" : "dark"} mode`,
        icon: isDark ? <Sun /> : <Moon />,
        group: "Appearance",
        order: 0,
        run: () => setScheme(isDark ? "light" : "dark"),
      },
      {
        id: "scheme:system",
        search: "appearance system mode follow os",
        label: "Match system appearance",
        icon: <MonitorSmartphone />,
        group: "Appearance",
        order: 1,
        run: () => setScheme("system"),
      },
      {
        id: "theme:picker",
        search: `set theme ${THEMES.map((t) => `${t.name} ${t.credit ?? ""}`).join(" ")}`,
        label: "Set theme…",
        meta: THEMES.find((t) => t.id === themeId)?.name,
        icon: <Palette />,
        group: "Appearance",
        order: 2,
        nested: true,
        run: () => {
          setQuery("");
          setMode("theme");
        },
      },
      {
        id: "design-mode",
        search: "design mode inspect annotate",
        label: "Toggle design mode",
        hint: ["⌥", "D"],
        icon: <PenTool />,
        group: "App",
        order: 0,
        run: () => cb.current.toggleDesignMode(),
      },
      {
        id: "shortcuts",
        search: "keyboard shortcuts help",
        label: "Keyboard shortcuts",
        hint: hintFor("shortcuts"),
        icon: <Keyboard />,
        group: "App",
        order: 1,
        run: () => cb.current.onShortcuts(),
      },
    );

    // a registered command sharing a built-in's id replaces it; the rest pass the allowlist
    const shadowed = new Set(registered.map((c) => c.id));
    const merged = out.filter((a) => !shadowed.has(a.id) && commandAllowed(a.id, commands));
    for (const c of registered)
      merged.push({
        id: c.id,
        search: `${c.label} ${c.keywords ?? ""}`,
        label: c.label,
        hint: c.hint,
        group: c.group ?? DEFAULT_COMMAND_GROUP,
        order: c.order,
        checked: c.checked,
        disabled: c.disabled,
        run: c.run,
      });
    return merged;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    keymap,
    commands,
    registered,
    days,
    namesLong,
    now,
    viewSetting,
    isDark,
    themeId,
    movableTitle,
    canStep,
  ]);

  const queryActions = useMemo<Action[]>(() => {
    const trimmed = query.trim();
    const out: Action[] = [];
    if (trimmed) {
      const r = parseQuickAdd(trimmed, now, { defaultDurationMin });
      const preview = quickAddPreview(r, now);
      out.push({
        id: "quick-add:query",
        search: trimmed,
        always: true,
        label: `Quick add “${preview.title}”`,
        meta: preview.when ?? undefined,
        icon: <CalendarClock />,
        group: "Quick add",
        run: () => openQuickAdd(trimmed),
        nested: true,
      });
      const target = r.start;
      if (target && !r.title.trim() && r.tokens.some((t) => t.kind === "date"))
        out.push({
          id: "jump:typed",
          search: trimmed,
          always: true,
          label: `Go to ${dayLabel(target, now)}`,
          icon: <CalendarSearch />,
          group: "Navigation",
          order: -1,
          run: () => cb.current.onJumpToDay(target),
        });
    }
    for (const hit of searchEvents(events ?? [], trimmed, { now, limit: 6 })) {
      const e = hit.event;
      out.push({
        id: `event:${e.id}`,
        search: `${e.title} ${e.location ?? ""}`,
        always: true,
        label: e.title || "Untitled event",
        meta: formatEventWhen(e, now),
        icon: <Search />,
        group: "Events",
        disabled: !canSelect,
        run: () => selectEvent(e),
      });
    }
    return out.filter((a) => commandAllowed(a.id, commands));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query, now, defaultDurationMin, events, canSelect, commands]);

  const datePresets = useMemo<Action[]>(() => {
    const out: Action[] = [];
    DATE_PRESETS.forEach(([phrase, label], i) => {
      const d = parseQuickAdd(phrase, now).start;
      if (!d) return;
      out.push({
        id: `date:${phrase}`,
        search: `${label} ${phrase} ${dayLabel(d, now)}`,
        label,
        meta: dayLabel(d, now),
        icon: <CalendarDays />,
        group: "Quick jumps",
        order: i,
        run: () => cb.current.onJumpToDay(d),
      });
    });
    dayJumps(days).forEach((d, i) => {
      out.push({
        id: `date:col:${d.toDateString()}`,
        search: `${namesLong[i] ?? ""} ${dayLabel(d, now)}`,
        label: dayLabel(d, now),
        icon: <CalendarDays />,
        group: "In view",
        order: i,
        run: () => cb.current.onJumpToDay(d),
      });
    });
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [now, days, namesLong]);

  const typedDate = useMemo<Action[]>(() => {
    const trimmed = query.trim();
    if (mode !== "date" || !trimmed) return [];
    const r = parseQuickAdd(trimmed, now);
    if (!r.start || r.confidence === "none") return [];
    const target = r.start;
    return [
      {
        id: "date:parsed",
        search: trimmed,
        always: true,
        label: `Go to ${dayLabel(target, now)}`,
        icon: <CalendarSearch />,
        group: "Go to",
        run: () => cb.current.onJumpToDay(target),
      },
    ];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, query, now]);

  const themeActions = useMemo<Action[]>(
    () => [
      ...THEMES.map(
        (t, i): Action => ({
          id: `theme:${t.id}`,
          search: `${t.name} ${t.credit ?? ""} ${t.family} theme`,
          label: t.name,
          meta: t.credit,
          hint: t.family === "coss" ? undefined : t.family,
          icon: <Palette />,
          group: "Theme",
          order: i,
          checked: t.id === themeId,
          run: () => {
            setTheme(t.id);
            setThemeId(t.id);
          },
          keepOpen: true,
        }),
      ),
      {
        id: "theme:light",
        search: "light mode appearance",
        label: "Light",
        icon: <Sun />,
        group: "Appearance",
        order: 0,
        checked: !isDark,
        keepOpen: true,
        run: () => {
          setScheme("light");
          setIsDark(false);
        },
      },
      {
        id: "theme:dark",
        search: "dark mode appearance",
        label: "Dark",
        icon: <Moon />,
        group: "Appearance",
        order: 1,
        checked: isDark,
        keepOpen: true,
        run: () => {
          setScheme("dark");
          setIsDark(true);
        },
      },
      {
        id: "theme:system",
        search: "system appearance follow os",
        label: "Match system",
        icon: <MonitorSmartphone />,
        group: "Appearance",
        order: 2,
        keepOpen: true,
        run: () => {
          setScheme("system");
          setIsDark(resolveScheme() === "dark");
        },
      },
    ],
    [themeId, isDark],
  );

  const surface = useMemo(() => {
    switch (mode) {
      case "date":
        return {
          title: "Go to date",
          placeholder: "Try “next friday”, “12 aug”, “tomorrow”…",
          groups: groupCommands(
            [...typedDate, ...datePresets],
            ["Go to", "Quick jumps", "In view"],
          ),
        };
      case "theme":
        return {
          title: "Set theme",
          placeholder: "Search themes…",
          groups: groupCommands(themeActions, ["Theme", "Appearance"]),
        };
      default:
        return {
          title: null,
          placeholder: "Search or type a command…",
          groups: groupCommands([...queryActions, ...staticActions]),
        };
    }
  }, [mode, typedDate, datePresets, themeActions, queryActions, staticActions]);

  const back = () => {
    setMode("commands");
    setQuery("");
  };

  if (mode === "move-to" && movable)
    return (
      <>
        <SurfaceHeader title={`Move “${eventTitle(movable)}”`} onBack={back} />
        <MoveToInput
          value={moveValue}
          onValueChange={setMoveValue}
          event={movable}
          now={now}
          onCommit={(target) => {
            // the target is display-zone wall time
            const patch = movePatch(movable, target, g.displayZone);
            setMoveValue("");
            close();
            // a recurring event asks the scope question first; that dialog outlives this menu
            const occurrence = movable.rrule
              ? (selectedOccurrence ?? occurrenceAt(movable, movable.start))
              : null;
            if (occurrence && askScope) {
              void askScope({ action: "edit", event: movable, occurrence }).then((scope) => {
                if (!scope) return;
                applyPlan(
                  store,
                  editOccurrence(movable, occurrence, patch, scope, {
                    makeId: g.makeId,
                  }),
                );
              });
              return;
            }
            store.update(masterIdOf(movable.id), patch);
          }}
          onBack={back}
        />
      </>
    );

  if (mode === "quick-add")
    return (
      <>
        <SurfaceHeader title="Quick add" onBack={back} />
        <QuickAddInput
          value={quickValue}
          onValueChange={setQuickValue}
          result={parsed}
          now={now}
          onCommit={commitQuickAdd}
          onBack={back}
        />
      </>
    );

  return (
    <Command
      items={surface.groups}
      value={query}
      onValueChange={setQuery}
      filter={(item, q) => {
        const a = item as unknown as Action;
        return a.always === true || matchesQuery(a.search, q);
      }}
    >
      {surface.title ? <SurfaceHeader title={surface.title} onBack={back} /> : null}
      <CommandInput
        placeholder={surface.placeholder}
        onKeyDown={(e) => {
          // Escape steps out of a nested picker before closing the whole menu
          if (e.key === "Escape" && mode !== "commands") {
            e.preventDefault();
            e.stopPropagation();
            back();
          }
        }}
      />
      <CommandList className="max-h-80">
        <CommandEmpty>Nothing matches.</CommandEmpty>
        <CommandCollection>
          {(group: CommandGroupModel<Action>) => (
            <CommandGroup key={group.value} items={group.items}>
              <CommandGroupLabel>{group.value}</CommandGroupLabel>
              <CommandCollection>
                {(a: Action) => (
                  <CommandItem
                    key={a.id}
                    value={a.search}
                    disabled={a.disabled}
                    onClick={() => run(a)}
                  >
                    <span className="mr-2 flex size-4 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4">
                      {a.icon}
                    </span>
                    <span className="flex-1 truncate">
                      {a.label}
                      {a.meta ? (
                        <span className="ml-2 text-muted-foreground text-xs">{a.meta}</span>
                      ) : null}
                    </span>
                    {a.checked ? (
                      <Check aria-hidden className="ml-2 size-4 shrink-0 text-muted-foreground" />
                    ) : null}
                    {a.nested && !a.checked ? (
                      <ChevronRight
                        aria-hidden
                        className="ml-2 size-4 shrink-0 text-muted-foreground"
                      />
                    ) : null}
                    {a.hint ? (
                      <KbdKeys
                        className="ml-2 in-data-highlighted:*:bg-background"
                        keys={typeof a.hint === "string" ? [a.hint] : a.hint}
                      />
                    ) : null}
                  </CommandItem>
                )}
              </CommandCollection>
            </CommandGroup>
          )}
        </CommandCollection>
      </CommandList>
      <CommandFooter>
        <span className="flex items-center gap-1.5">
          <KbdKeys keys={["↑", "↓"]} />
          navigate
        </span>
        <span className="flex items-center gap-3">
          <span className="flex items-center gap-1.5">
            <KbdKeys keys={["↵"]} />
            run
          </span>
          <span className="flex items-center gap-1.5">
            <KbdKeys keys={["esc"]} />
            {mode === "commands" ? "close" : "back"}
          </span>
        </span>
      </CommandFooter>
    </Command>
  );
}

export function SurfaceHeader({ title, onBack }: { title: string; onBack: () => void }) {
  return (
    <div className="flex items-center gap-2 border-b px-3 py-2">
      <Button
        variant="ghost"
        size="xs"
        className="font-normal text-muted-foreground"
        onClick={onBack}
      >
        <ArrowLeft />
        Back
      </Button>
      <span className="min-w-0 truncate font-medium text-sm">{title}</span>
    </div>
  );
}

"use client";

/**
 * The calendar's two aria-live regions and the `announce()` every commit path uses.
 * Text is written imperatively via refs: no re-render, and a cleared-then-written node re-announces repeats.
 */

import { createContext, type RefObject, useCallback, useContext, useEffect, useRef } from "react";

type Politeness = "polite" | "assertive";

/** Say something. Empty strings are ignored, so a builder may return "". */
export type Announce = (message: string, politeness?: Politeness) => void;

const noop: Announce = () => {};

const AnnounceContext = createContext<Announce>(noop);

export const AnnounceProvider = AnnounceContext.Provider;

/** The calendar's announcer; a `noop` outside a provider. */
export function useAnnounce(): Announce {
  return useContext(AnnounceContext);
}

interface Announcer {
  announce: Announce;
  politeRef: RefObject<HTMLDivElement | null>;
  assertiveRef: RefObject<HTMLDivElement | null>;
}

export function useAnnouncer(): Announcer {
  const politeRef = useRef<HTMLDivElement | null>(null);
  const assertiveRef = useRef<HTMLDivElement | null>(null);
  const frame = useRef(0);

  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const announce = useCallback<Announce>((message, politeness = "polite") => {
    const text = message.trim();
    if (!text) return;
    const node = politeness === "assertive" ? assertiveRef.current : politeRef.current;
    if (!node) return;
    // clear then write next frame: identical text twice is not a change, so it would not re-announce
    node.textContent = "";
    cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(() => {
      node.textContent = text;
    });
  }, []);

  return { announce, politeRef, assertiveRef };
}

// clip-rect idiom inline (display:none/visibility:hidden drop live regions from the a11y tree)
const SR_ONLY = {
  position: "absolute",
  width: "1px",
  height: "1px",
  margin: "-1px",
  padding: 0,
  border: 0,
  overflow: "hidden",
  clip: "rect(0 0 0 0)",
  clipPath: "inset(50%)",
  whiteSpace: "nowrap",
} as const;

/** The regions; mounted once and never unmounted, or screen readers skip the first announcement. */
export function LiveRegions({ politeRef, assertiveRef }: Omit<Announcer, "announce">) {
  return (
    <>
      <div
        ref={politeRef}
        data-kloq-live="polite"
        role="status"
        aria-live="polite"
        aria-atomic="true"
        style={SR_ONLY}
      />
      <div
        ref={assertiveRef}
        data-kloq-live="assertive"
        role="alert"
        aria-live="assertive"
        aria-atomic="true"
        style={SR_ONLY}
      />
    </>
  );
}

"use client";

/** month-view — the 6×7 cell grid; `lib/month-grid` packs placements into per-cell rows. */

import type React from "react";
import { memo, useCallback, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  formatRange,
  type KloqView,
  type PlacedEvent,
  type TimeFormatOptions,
  type ViewDescriptor,
} from "../lib/calendar-types";
import { formatDate } from "../lib/date-format";
import type { CommitResult } from "../lib/drag-engine/types";
import {
  createJiggle,
  JIGGLE_REST,
  type JiggleState,
  jiggleTransform,
  liftOf,
  stepJiggle,
} from "../lib/drag-physics";
import { EVENT_COLORS, EVENT_TEXT_CSS } from "../lib/event-palette";
import { eventTitle, fullDate, plural } from "../lib/event-text";
import { hiddenOn, layoutMonth, type MonthChip, type MonthLayout } from "../lib/month-grid";
import { rovingTab } from "../lib/roving";
import { ms, prefersReducedMotion, SPRING, SPRING_MS } from "../lib/springs";
import { cn } from "../lib/utils";
import { ContextMenu, ContextMenuTrigger } from "../ui/context-menu";
import { CELL_HOVER, FOCUS_RING } from "./cell-classes";
import { type CalendarMenuTarget, EventContextMenu, GridContextMenu } from "./event-context-menu";
import { EventOverflow } from "./event-overflow";
import { useKloqSettings } from "./settings-context";
import { useCoarsePointer } from "./use-responsive";

// chip (18) + 2px gap; on touch the chip is the 24px minimum
const CHIP_H = 20;
const CHIP_H_TOUCH = 26;
const CELL_HEAD = 24;
// rows assumed before measurement, and on the server
const DEFAULT_SLOTS = 3;
const MONTH_NEW_EVENT_MIN = 9 * 60;

interface MonthViewProps {
  view: ViewDescriptor;
  events: PlacedEvent[];
  selectedId: string | null;
  registerNode: (id: string, node: HTMLElement | null) => void;
  onSelect: (id: string | null, opts?: { isNew?: boolean }) => void;
  onOpenDay: (date: Date) => void;
  /** phone width: dots per day instead of titled chips */
  compact?: boolean;
  viewSetting: KloqView;
  onSwitchView: (view: KloqView) => void;
  /** The one event carrying `tabIndex={0}` — see `lib/roving.ts`. */
  rovingId?: string | null;
  /** Drag a chip to another day; `dayDelta` is whole days. Omit and chips stay click-only. */
  onMoveByDays?: (id: string, dayDelta: number) => CommitResult;
}

const MONTH_YEAR: Intl.DateTimeFormatOptions = { month: "long", year: "numeric" };

const DAY_KEYS: Record<string, (day: number) => number> = {
  ArrowLeft: (d) => d - 1,
  ArrowRight: (d) => d + 1,
  ArrowUp: (d) => d - 7,
  ArrowDown: (d) => d + 7,
  Home: (d) => d - (d % 7),
  End: (d) => d - (d % 7) + 6,
};

export function MonthView({
  view,
  events,
  selectedId,
  registerNode,
  onSelect,
  onOpenDay,
  viewSetting,
  onSwitchView,
  rovingId,
  onMoveByDays,
  compact = false,
}: MonthViewProps) {
  const g = useKloqSettings();
  const gridRef = useRef<HTMLDivElement>(null);
  const [slots, setSlots] = useState(DEFAULT_SLOTS);
  const chipH = useCoarsePointer() ? CHIP_H_TOUCH : CHIP_H;

  // measure a real cell: it carries its own padding and border
  useLayoutEffect(() => {
    const grid = gridRef.current;
    if (!grid || typeof ResizeObserver === "undefined") return;
    const measure = () => {
      const cell = grid.querySelector<HTMLElement>("[data-month-day]");
      if (!cell) return;
      const room = cell.clientHeight - CELL_HEAD;
      setSlots(Math.max(1, Math.floor(room / chipH)));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(grid);
    return () => ro.disconnect();
  }, [chipH]);

  const weeks = Math.max(1, Math.ceil(view.dayCount / 7));
  const layout = useMemo(
    () => layoutMonth(events, { dayCount: view.dayCount, slots }),
    [events, view.dayCount, slots],
  );
  const rows = useMemo(() => {
    const out = Array.from({ length: weeks }, () => ({
      chips: [] as MonthChip[],
      ids: new Set<string>(),
    }));
    for (const chip of layout.chips) {
      const row = out[chip.week];
      if (!row) continue;
      row.chips.push(chip);
      row.ids.add(chip.event.id);
    }
    return out;
  }, [layout, weeks]);

  const month = view.month?.getMonth();

  // one day button is in the tab order; arrows move it
  const [leadDay, setLeadDay] = useState<string | null>(null);
  const rovingDay = useMemo(() => {
    const at = leadDay === null ? -1 : view.days.findIndex((d) => d.toDateString() === leadDay);
    if (at >= 0) return at;
    if (view.todayIndex >= 0) return view.todayIndex;
    return Math.max(
      0,
      view.days.findIndex((d) => month === undefined || d.getMonth() === month),
    );
  }, [leadDay, view.days, view.todayIndex, month]);
  const onFocusDay = useCallback(
    (day: number) => setLeadDay(view.days[day]?.toDateString() ?? null),
    [view.days],
  );

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
      const from = (e.target as HTMLElement | null)?.dataset?.monthOpen;
      const move = DAY_KEYS[e.key];
      if (from === undefined || !move) return;
      // `preventDefault()` also tells the document-level keyboard layer to yield
      e.preventDefault();
      const next = move(Number(from));
      if (next < 0 || next >= view.dayCount) return;
      gridRef.current?.querySelector<HTMLElement>(`[data-month-open="${next}"]`)?.focus();
    },
    [view.dayCount],
  );

  const [target, setTarget] = useState<CalendarMenuTarget | null>(null);
  const pending = useRef<CalendarMenuTarget | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);

  const onContextMenuCapture = useCallback(
    (e: React.MouseEvent) => {
      pending.current = null;
      const el = e.target as HTMLElement | null;
      const chip = el?.closest?.("[data-cal-event]") as HTMLElement | null;
      const id = chip?.dataset.calEvent;
      if (id) {
        const event = events.find((ev) => ev.id === id);
        if (event) pending.current = { kind: "event", event };
        return;
      }
      const cell = el?.closest?.("[data-month-day]") as HTMLElement | null;
      const col = Number(cell?.dataset.monthDay);
      if (!Number.isFinite(col)) return;
      pending.current = {
        kind: "slot",
        col,
        startMin: MONTH_NEW_EVENT_MIN,
        allDay: false,
      };
    },
    [events],
  );

  const onOpenChange = (next: boolean) => {
    if (next && !pending.current) return;
    if (next) setTarget(pending.current);
    setMenuOpen(next);
  };

  return (
    <ContextMenu open={menuOpen} onOpenChange={onOpenChange}>
      <ContextMenuTrigger
        onContextMenuCapture={onContextMenuCapture}
        render={
          <div
            ref={gridRef}
            role="table"
            aria-label={`Month of ${view.month ? formatDate(view.month, g.locale, MONTH_YEAR) : ""}`}
            className="flex min-h-0 min-w-0 flex-1 flex-col"
            onKeyDown={onKeyDown}
          />
        }
      >
        <div role="row" className="grid shrink-0 border-b" style={COLS}>
          {view.days.slice(0, 7).map((d, i) => (
            <div
              key={i}
              role="columnheader"
              data-cal-day-header
              className={cn(
                "truncate border-l border-border/70 py-2 text-xs text-muted-foreground first:border-l-0",
                compact ? "text-center" : "px-2.5",
              )}
            >
              <abbr title={view.namesLong[i]} className="no-underline">
                {view.namesShort[i]}
              </abbr>
            </div>
          ))}
        </div>

        <div
          role="rowgroup"
          className="grid min-h-0 flex-1"
          style={{ gridTemplateRows: `repeat(${weeks}, minmax(0, 1fr))` }}
        >
          {rows.map((row, w) => {
            const inRow = (day: number) => day >= w * 7 && day < w * 7 + 7;
            return (
              <MonthWeekRow
                key={w}
                week={w}
                compact={compact}
                view={view}
                layout={layout}
                chips={row.chips}
                slots={slots}
                chipH={chipH}
                month={month}
                selectedId={selectedId !== null && row.ids.has(selectedId) ? selectedId : null}
                rovingId={rovingId == null || row.ids.has(rovingId) ? rovingId : null}
                rovingDay={inRow(rovingDay) ? rovingDay : -1}
                registerNode={registerNode}
                onSelect={onSelect}
                onOpenDay={onOpenDay}
                onFocusDay={onFocusDay}
                onMoveByDays={onMoveByDays}
              />
            );
          })}
        </div>
      </ContextMenuTrigger>

      {target?.kind === "event" ? (
        <EventContextMenu
          event={target.event}
          selected={target.event.id === selectedId}
          host={gridRef}
          days={view.days}
          onSelect={onSelect}
          close={() => setMenuOpen(false)}
        />
      ) : target ? (
        <GridContextMenu
          slot={target}
          host={gridRef}
          days={view.days}
          // no hour axis: "Jump to now" stays disabled
          todayIndex={-1}
          viewSetting={viewSetting}
          onSwitchView={onSwitchView}
          onSelect={onSelect}
          close={() => setMenuOpen(false)}
        />
      ) : null}
    </ContextMenu>
  );
}

const COLS: React.CSSProperties = {
  gridTemplateColumns: "repeat(7, minmax(0, 1fr))",
};

const WEEK_COLS = [0, 1, 2, 3, 4, 5, 6];

const DAY_BUTTON = cn(
  "flex size-6 cursor-pointer items-center justify-center rounded-full text-2xs tabular-nums",
  CELL_HOVER,
  FOCUS_RING,
);

interface WeekRowProps {
  week: number;
  compact: boolean;
  view: ViewDescriptor;
  layout: MonthLayout;
  chips: MonthChip[];
  slots: number;
  chipH: number;
  month: number | undefined;
  selectedId: string | null;
  rovingId?: string | null;
  /** the day button in the tab order, or -1 when it is in another row */
  rovingDay: number;
  registerNode: (id: string, node: HTMLElement | null) => void;
  onSelect: (id: string | null, opts?: { isNew?: boolean }) => void;
  onOpenDay: (date: Date) => void;
  onFocusDay: (day: number) => void;
  onMoveByDays?: (id: string, dayDelta: number) => CommitResult;
}

const MonthWeekRow = memo(function MonthWeekRow({
  week,
  view,
  layout,
  chips,
  slots,
  chipH,
  month,
  selectedId,
  registerNode,
  onSelect,
  onOpenDay,
  onFocusDay,
  rovingId,
  rovingDay,
  onMoveByDays,
  compact,
}: WeekRowProps) {
  const g = useKloqSettings();
  const first = week * 7;

  return (
    <div role="row" className="relative grid border-b" style={COLS}>
      {WEEK_COLS.map((i) => {
        const day = first + i;
        if (day >= view.dayCount) return null;
        const date = view.days[day];
        const isToday = day === view.todayIndex;
        const inMonth = month === undefined || date.getMonth() === month;
        const count = layout.byDay[day]?.length ?? 0;
        const overflow = layout.overflow[day] ?? 0;
        const full = fullDate(date, g.locale);
        return (
          <div
            key={day}
            role="cell"
            data-month-day={day}
            aria-label={cellLabel(date, view.namesLong[day], count, g.locale)}
            className={cn(
              "relative min-w-0 border-l border-border/70 first:border-l-0 data-month-drop:bg-accent",
              !inMonth && "bg-muted/60",
            )}
          >
            <div
              className={cn(
                "flex h-6 items-center px-1",
                compact ? "justify-center" : "justify-end",
              )}
            >
              <button
                type="button"
                data-month-open={day}
                tabIndex={day === rovingDay ? 0 : -1}
                onClick={() => onOpenDay(date)}
                onFocus={() => onFocusDay(day)}
                aria-label={`Open ${full}`}
                aria-current={isToday ? "date" : undefined}
                className={cn(
                  DAY_BUTTON,
                  isToday
                    ? "bg-primary font-medium text-primary-foreground hover:bg-primary"
                    : inMonth
                      ? "text-foreground"
                      : "text-muted-foreground",
                )}
              >
                {date.getDate()}
              </button>
            </div>

            {compact ? (
              <CompactDay
                events={layout.byDay[day] ?? EMPTY_EVENTS}
                date={date}
                onOpenDay={onOpenDay}
              />
            ) : (
              <EventOverflow
                count={overflow}
                events={() => hiddenOn(layout, day)}
                label={`Show ${plural(overflow, "more event")} on ${full}`}
                heading={full}
                onSelect={(event) => onSelect(event.id)}
                rowLabel={(event) => chipLabel(event, date, g.timeFormat)}
                rowMeta={(event) => (event.allDay ? null : g.formatMinutes(event.startMin))}
                tabIndex={day === rovingDay ? 0 : -1}
                className="absolute right-1"
                style={{ top: CELL_HEAD + (slots - 1) * chipH, height: chipH - 2 }}
              />
            )}
          </div>
        );
      })}

      {/* a multi-day event is one element spanning columns; `cell` keeps the ARIA table valid */}
      <div role="cell" aria-label="Events" className="pointer-events-none absolute inset-0">
        {compact
          ? null
          : chips.map((chip) => (
              <MonthChipBar
                key={`${chip.event.id}:${chip.week}`}
                chip={chip}
                chipH={chipH}
                view={view}
                selected={chip.event.id === selectedId}
                tabIndex={rovingTab(rovingId, chip.event.id)}
                registerNode={registerNode}
                onSelect={onSelect}
                onMoveByDays={onMoveByDays}
              />
            ))}
      </div>
    </div>
  );
});

const EMPTY_EVENTS: PlacedEvent[] = [];
const COMPACT_DOTS = 4;

function CompactDay({
  events,
  date,
  onOpenDay,
}: {
  events: PlacedEvent[];
  date: Date;
  onOpenDay: (date: Date) => void;
}) {
  if (events.length === 0) return null;
  const extra = events.length - COMPACT_DOTS;
  return (
    <button
      type="button"
      tabIndex={-1}
      aria-hidden
      onClick={() => onOpenDay(date)}
      className="absolute inset-x-0 top-6 bottom-0 flex cursor-pointer flex-wrap content-start justify-center gap-1 px-1 pt-0.5 outline-none"
    >
      {events.slice(0, COMPACT_DOTS).map((e) => (
        <span key={e.id} className={cn("size-1.5 rounded-full", EVENT_COLORS[e.color].bar)} />
      ))}
      {extra > 0 ? (
        <span className="basis-full text-center text-3xs leading-none text-muted-foreground">
          +{extra}
        </span>
      ) : null}
    </button>
  );
}

function cellLabel(date: Date, nameLong: string, count: number, locale?: string): string {
  const when = fullDate(date, locale) || nameLong;
  if (count === 0) return `${when}, no events`;
  return `${when}, ${plural(count, "event")}`;
}

/** Accessible name for a chip: what, when, and for a bar how long. */
export function chipLabel(event: PlacedEvent, date: Date, opts?: TimeFormatOptions): string {
  const title = eventTitle(event);
  const when = fullDate(date, opts?.locale);
  if (event.allDay) {
    const span = event.endDayIndex - event.dayIndex + 1;
    return span > 1 ? `${title}, all day, ${span} days from ${when}` : `${title}, all day, ${when}`;
  }
  // title then time, in the order a chip renders them — the visible text has to
  // be part of the accessible name (label-content-name-mismatch)
  return `${title}, ${formatRange(event.startMin, event.endMin, opts)}, ${when}`;
}

interface ChipBarProps {
  chip: MonthChip;
  chipH: number;
  view: ViewDescriptor;
  selected: boolean;
  tabIndex?: number;
  registerNode: (id: string, node: HTMLElement | null) => void;
  onSelect: (id: string | null, opts?: { isNew?: boolean }) => void;
  onMoveByDays?: (id: string, dayDelta: number) => CommitResult;
}

// below this a click, past it a drag
const MONTH_DRAG_THRESHOLD = 4;

interface MonthDrag {
  pointerId: number;
  x0: number;
  y0: number;
  x: number;
  y: number;
  t: number;
  fromDay: number | null;
  moved: boolean;
  hover: HTMLElement | null;
  lift: HTMLElement | null;
  origin: DOMRect | null;
  jiggle: JiggleState;
  jiggleT: number;
  vx: number;
  vy: number;
  raf: number;
  reduced: boolean;
}

const LIFT_Z = "60";

function monthCellAt(x: number, y: number): HTMLElement | null {
  for (const el of document.elementsFromPoint(x, y)) {
    if ((el as HTMLElement).dataset?.monthDay !== undefined) return el as HTMLElement;
  }
  return null;
}

function monthDayAt(x: number, y: number): number | null {
  const day = monthCellAt(x, y)?.dataset.monthDay;
  return day === undefined ? null : Number(day);
}

const MonthChipBar = memo(function MonthChipBar({
  chip,
  chipH,
  view,
  selected,
  tabIndex,
  registerNode,
  onSelect,
  onMoveByDays,
}: ChipBarProps) {
  const g = useKloqSettings();
  const { event } = chip;
  const c = EVENT_COLORS[event.color];
  const span = chip.endCol - chip.startCol + 1;
  const banner = event.allDay || span > 1;

  // day-granularity drag, separate from the grid engine (no minute axis here)
  const drag = useRef<MonthDrag | null>(null);
  const suppressClick = useRef(false);

  const washCell = (cell: HTMLElement | null) => {
    const d = drag.current;
    if (!d || d.hover === cell) return;
    d.hover?.removeAttribute("data-month-drop");
    cell?.setAttribute("data-month-drop", "");
    d.hover = cell;
  };

  // the chip is clipped by the month's overflow, so a fixed clone travels and the chip ghosts
  const pickUp = (node: HTMLElement, d: MonthDrag) => {
    const rect = node.getBoundingClientRect();
    const lift = node.cloneNode(true) as HTMLElement;
    lift.removeAttribute("data-cal-event");
    lift.removeAttribute("aria-pressed");
    lift.setAttribute("data-cal-lift", "");
    lift.setAttribute("aria-hidden", "true");
    lift.tabIndex = -1;
    Object.assign(lift.style, {
      position: "fixed",
      left: `${rect.left}px`,
      top: `${rect.top}px`,
      width: `${rect.width}px`,
      height: `${rect.height}px`,
      margin: "0",
      pointerEvents: "none",
      zIndex: LIFT_Z,
      transformOrigin: "50% 50%",
      opacity: "1",
    } satisfies Partial<CSSStyleDeclaration>);
    lift.style.setProperty("--kloq-lift", d.reduced ? "1" : "0");
    // dark mode is a class on an ancestor; the clone has to land inside it
    (node.closest(".dark") ?? document.body).appendChild(lift);
    node.setAttribute("data-cal-lifted", "");
    node.style.opacity = "0.4";
    if (!d.reduced)
      node.animate([{ opacity: 1 }, { opacity: 0.4 }], {
        duration: ms(160),
        easing: "ease-out",
      });
    d.lift = lift;
    d.origin = rect;
    const frame = () => {
      const dd = drag.current;
      if (!dd || dd.lift !== lift) return;
      const now = performance.now();
      const dt = dd.jiggleT ? (now - dd.jiggleT) / 1000 : 1 / 60;
      dd.jiggleT = now;
      dd.vx *= 0.92;
      dd.vy *= 0.92;
      let tf = `translate(${dd.x - dd.x0}px, ${dd.y - dd.y0}px)`;
      if (!dd.reduced) {
        stepJiggle(dd.jiggle, { vx: dd.vx, vy: dd.vy, dt, tilt: true });
        tf += jiggleTransform(dd.jiggle);
        lift.style.setProperty("--kloq-lift", liftOf(dd.jiggle).toFixed(3));
      }
      lift.style.transform = tf;
      washCell(monthCellAt(dd.x, dd.y));
      dd.raf = requestAnimationFrame(frame);
    };
    d.raf = requestAnimationFrame(frame);
  };

  const chipsOf = (node: HTMLElement) =>
    Array.from(
      (node.closest('[role="table"]') ?? document).querySelectorAll<HTMLElement>(
        `[data-cal-event="${CSS.escape(event.id)}"]`,
      ),
    );

  const unghost = (nodes: HTMLElement[], fade: boolean) => {
    for (const n of nodes) {
      n.removeAttribute("data-cal-lifted");
      n.style.opacity = "";
      if (fade)
        n.animate([{ opacity: 0.4 }, { opacity: 1 }], {
          duration: ms(120),
          easing: "ease-out",
        });
    }
  };

  const endDrag = (node: HTMLElement, commit: boolean) => {
    const d = drag.current;
    if (!d) return;
    drag.current = null;
    cancelAnimationFrame(d.raf);
    d.hover?.removeAttribute("data-month-drop");
    if (!d.moved || !d.lift || !d.origin) return;
    suppressClick.current = true;
    const lift = d.lift;
    const origin = d.origin;
    const from = lift.style.transform;
    const lifted = lift.style.getPropertyValue("--kloq-lift") || "1";

    const home = () => {
      const finish = () => {
        lift.remove();
        unghost(chipsOf(node), !d.reduced);
      };
      if (d.reduced) return finish();
      const anim = lift.animate(
        [
          { transform: from, "--kloq-lift": lifted },
          { transform: `translate(0px, 0px)${JIGGLE_REST}`, "--kloq-lift": "0" },
        ],
        { duration: SPRING_MS, easing: SPRING },
      );
      anim.onfinish = finish;
    };

    const toDay = commit ? monthDayAt(d.x, d.y) : null;
    if (toDay === null || d.fromDay === null || toDay === d.fromDay) return home();

    // rAF: the store update has rendered the new chip by then, nothing has painted yet
    const land = () =>
      requestAnimationFrame(() => {
        const next = chipsOf(node);
        const target = next[0];
        if (!target) {
          lift.remove();
          return;
        }
        const to = target.getBoundingClientRect();
        for (const n of next) {
          n.removeAttribute("data-cal-lifted");
          n.style.opacity = "0";
        }
        const finish = () => {
          lift.remove();
          for (const n of next) n.style.opacity = "";
        };
        if (d.reduced) return finish();
        const anim = lift.animate(
          [
            { transform: lift.style.transform, width: `${origin.width}px`, "--kloq-lift": lifted },
            {
              transform: `translate(${to.left - origin.left}px, ${to.top - origin.top}px)${JIGGLE_REST}`,
              width: `${to.width}px`,
              "--kloq-lift": "0",
            },
          ],
          { duration: SPRING_MS * 0.6, easing: SPRING },
        );
        anim.onfinish = finish;
      });

    const result = onMoveByDays?.(event.id, toDay - d.fromDay);
    if (result && typeof result.then === "function") {
      // host is asking which occurrence; stay lifted until it answers
      void result.then(
        (ok) => (ok ? land() : home()),
        () => home(),
      );
      return;
    }
    land();
  };

  const dragHandlers =
    onMoveByDays && !event.readOnly
      ? {
          onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) => {
            if (e.button !== 0 || drag.current) return;
            e.currentTarget.setPointerCapture(e.pointerId);
            drag.current = {
              pointerId: e.pointerId,
              x0: e.clientX,
              y0: e.clientY,
              x: e.clientX,
              y: e.clientY,
              t: e.timeStamp,
              fromDay: monthDayAt(e.clientX, e.clientY),
              moved: false,
              hover: null,
              lift: null,
              origin: null,
              jiggle: createJiggle(),
              jiggleT: 0,
              vx: 0,
              vy: 0,
              raf: 0,
              reduced: prefersReducedMotion(),
            };
          },
          onPointerMove: (e: React.PointerEvent<HTMLButtonElement>) => {
            const d = drag.current;
            if (!d || e.pointerId !== d.pointerId) return;
            if (!d.moved && Math.hypot(e.clientX - d.x0, e.clientY - d.y0) < MONTH_DRAG_THRESHOLD)
              return;
            if (!d.moved) {
              d.moved = true;
              pickUp(e.currentTarget, d);
            }
            const dt = Math.max(1, e.timeStamp - d.t);
            d.vx = d.vx * 0.8 + ((e.clientX - d.x) / dt) * 1000 * 0.2;
            d.vy = d.vy * 0.8 + ((e.clientY - d.y) / dt) * 1000 * 0.2;
            d.x = e.clientX;
            d.y = e.clientY;
            d.t = e.timeStamp;
          },
          onPointerUp: (e: React.PointerEvent<HTMLButtonElement>) => {
            endDrag(e.currentTarget, true);
          },
          onPointerCancel: (e: React.PointerEvent<HTMLButtonElement>) => {
            endDrag(e.currentTarget, false);
          },
          onKeyDownCapture: (e: React.KeyboardEvent<HTMLButtonElement>) => {
            if (e.key === "Escape" && drag.current?.moved) {
              e.stopPropagation();
              endDrag(e.currentTarget, false);
            }
          },
        }
      : {};

  return (
    <button
      type="button"
      data-cal-event={event.id}
      ref={(node) => registerNode(event.id, node)}
      onClick={() => {
        if (suppressClick.current) {
          suppressClick.current = false;
          return;
        }
        onSelect(event.id);
      }}
      {...dragHandlers}
      aria-pressed={selected}
      tabIndex={tabIndex}
      aria-label={chipLabel(event, view.days[chip.startDay], g.timeFormat)}
      className={cn(
        "pointer-events-auto absolute z-10 flex cursor-pointer items-center gap-1 overflow-hidden rounded-xs px-1 text-left text-2xs leading-none transition-[background-color,box-shadow] duration-150 focus-visible:z-20",
        FOCUS_RING,
        banner ? cn(c.tint, c.ink) : "hover:bg-accent",
        selected && cn("z-20 ring-2", c.ring),
        chip.continuesBefore && "rounded-l-none",
        chip.continuesAfter && "rounded-r-none",
      )}
      style={{
        top: CELL_HEAD + chip.slot * chipH,
        height: chipH - 2,
        left: `calc(${(chip.startCol / 7) * 100}% + 3px)`,
        width: `calc(${(span / 7) * 100}% - 6px)`,
        ...(banner ? { color: EVENT_TEXT_CSS } : null),
      }}
    >
      {banner ? null : <span aria-hidden className={cn("size-1.5 shrink-0 rounded-full", c.bar)} />}
      <span className="truncate font-medium">{eventTitle(event)}</span>{" "}
      {banner ? null : (
        <span className="shrink-0 truncate text-muted-foreground">
          {g.formatMinutes(event.startMin)}
        </span>
      )}
    </button>
  );
});

"use client";

/** month-year-picker — the range title as a control; moves the anchor without changing the view. */

import { ChevronLeft, ChevronRight } from "lucide-react";
import { useMemo, useState } from "react";
import { dateFormatter } from "../lib/date-format";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { Popover, PopoverPopup, PopoverTrigger } from "../ui/popover";

interface MonthYearPickerProps {
  /** current anchor — decides which cell reads as selected */
  date: Date;
  /** move the anchor; the view is left alone */
  onPick: (date: Date) => void;
  /** the rendered title, e.g. "August 2026" */
  label: string;
  /** `Intl` locale for the month names; falls back to the runtime default */
  locale?: string;
  className?: string;
}

const MONTH_FORMAT: Intl.DateTimeFormatOptions = { month: "short" };

function monthNames(locale?: string): string[] {
  const fmt = dateFormatter(locale, MONTH_FORMAT);
  return Array.from({ length: 12 }, (_, m) => fmt.format(new Date(2026, m, 1)));
}

export function MonthYearPicker({ date, onPick, label, locale, className }: MonthYearPickerProps) {
  const [open, setOpen] = useState(false);
  // the browsed year is separate from the anchor until a month is picked
  const [year, setYear] = useState(() => date.getFullYear());
  const months = useMemo(() => monthNames(locale), [locale]);
  const today = new Date();

  const openChange = (next: boolean) => {
    if (next) setYear(date.getFullYear());
    setOpen(next);
  };

  const pick = (month: number) => {
    setOpen(false);
    // the 1st: anchoring on the 31st would skip February
    onPick(new Date(year, month, 1));
  };

  return (
    <Popover open={open} onOpenChange={openChange}>
      <PopoverTrigger
        render={
          <Button
            variant="ghost"
            size="xs"
            className={cn("max-w-full data-popup-open:bg-accent", className)}
          />
        }
        aria-label={`${label} — jump to a month`}
      >
        <span className="truncate">{label}</span>
      </PopoverTrigger>

      <PopoverPopup className="w-60" side="bottom" align="start">
        <div className="flex items-center justify-between pb-2">
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label={`Go to ${year - 1}`}
            onClick={() => setYear((y) => y - 1)}
          >
            <ChevronLeft />
          </Button>
          <span className="text-sm font-medium tabular-nums">{year}</span>
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label={`Go to ${year + 1}`}
            onClick={() => setYear((y) => y + 1)}
          >
            <ChevronRight />
          </Button>
        </div>

        <div role="group" aria-label={`Months of ${year}`} className="grid grid-cols-3 gap-1">
          {months.map((name, m) => {
            const selected = year === date.getFullYear() && m === date.getMonth();
            const isThisMonth = year === today.getFullYear() && m === today.getMonth();
            return (
              <Button
                key={name}
                variant={selected ? "default" : isThisMonth ? "secondary" : "ghost"}
                size="xs"
                aria-pressed={selected}
                aria-current={isThisMonth ? "date" : undefined}
                onClick={() => pick(m)}
              >
                {name}
              </Button>
            );
          })}
        </div>

        <div className="mt-2 border-t pt-2">
          <Button
            variant="ghost"
            size="xs"
            className="w-full justify-center text-muted-foreground"
            onClick={() => {
              setOpen(false);
              onPick(new Date());
            }}
          >
            Today
          </Button>
        </div>
      </PopoverPopup>
    </Popover>
  );
}

"use client";

/**
 * move-to-input — natural-language "move this event to…" field, previewing the
 * resolved destination and which half (date/time) was inherited.
 */

import { ArrowRight, CalendarClock } from "lucide-react";
import { useEffect, useMemo, useRef } from "react";
import { type CalEvent, parseInstant } from "../lib/calendar-types";
import { movePatch } from "../lib/command-model";
import { formatEventWhen, formatWhen } from "../lib/event-search";
import { eventTitle } from "../lib/event-text";
import { type MoveTarget, parseMoveTarget } from "../lib/move-to";
import { cn } from "../lib/utils";
import { Badge } from "../ui/badge";
import { CommandFooter } from "../ui/command";
import { Input } from "../ui/input";
import { KbdKeys } from "./kbd-keys";
import { COMMAND_FIELD_ROW, useSpoken } from "./quick-add-input";
import { useKloqSettings } from "./settings-context";

interface MoveToInputProps {
  value: string;
  onValueChange: (value: string) => void;
  event: CalEvent;
  now: Date;
  /** Called with the resolved destination on commit. */
  onCommit: (target: MoveTarget) => void;
  onBack: () => void;
  autoFocus?: boolean;
  /** `false` keeps the preview out of the live region, for a demo that drives `value`. */
  announce?: boolean;
}

export function MoveToInput({
  value,
  onValueChange,
  event,
  now,
  onCommit,
  onBack,
  autoFocus = true,
  announce = true,
}: MoveToInputProps) {
  const g = useKloqSettings();
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (autoFocus) inputRef.current?.focus();
  }, [autoFocus]);

  const allDay = event.allDay === true;
  const { target, refused } = useMemo(() => {
    // an all-day event's dates are calendar days, not moments in the display zone
    const read = (t: string) =>
      allDay ? new Date(parseInstant(t)) : new Date(g.toDisplay?.(t) ?? Date.parse(t));
    const current = { start: read(event.start), end: read(event.end) };
    const target = parseMoveTarget(value, { ...current, allDay }, now);
    // understood, but nowhere an all-day event can go
    const refused = allDay && !target ? parseMoveTarget(value, current, now) : null;
    return { target, refused };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, event.start, event.end, allDay, now]);
  const inherited =
    !target || target.relative || allDay
      ? null
      : !target.changed.date
        ? "same day"
        : !target.changed.time
          ? "same time"
          : null;

  const from = formatEventWhen(event, now);
  const to = !target
    ? null
    : allDay
      ? formatEventWhen({ ...event, ...movePatch(event, target) }, now)
      : formatWhen(target.start, target.end, false, now);
  const spoken = useSpoken(to ? `Moves to ${to}` : "", announce);

  return (
    <div className="flex flex-col">
      <div className={COMMAND_FIELD_ROW}>
        <Input
          ref={inputRef}
          unstyled
          size="lg"
          value={value}
          onChange={(e) => onValueChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && target) {
              e.preventDefault();
              onCommit(target);
            } else if (e.key === "Escape") {
              e.preventDefault();
              e.stopPropagation();
              onBack();
            }
          }}
          placeholder="next tuesday · 3pm · +2h · a day later"
          aria-label={`Move ${eventTitle(event)} to`}
          autoComplete="off"
          spellCheck={false}
          className="flex w-full text-base sm:text-sm"
        />
      </div>

      <div className="flex flex-wrap items-center gap-x-2 gap-y-1 border-t px-5 py-3 text-xs">
        <span className="flex min-w-0 items-center gap-2">
          <CalendarClock aria-hidden className="size-3.5 shrink-0 text-muted-foreground" />
          <span className="text-muted-foreground line-through">{from}</span>
        </span>
        <span className="flex min-w-0 items-center gap-2">
          <ArrowRight aria-hidden className="size-3.5 shrink-0 text-muted-foreground" />
          <span className={cn("font-medium", to ? "text-foreground" : "text-muted-foreground")}>
            {to ??
              (!refused
                ? "—"
                : refused.changed.date
                  ? "already on that day"
                  : "all-day events move by date")}
          </span>
          {inherited ? (
            <Badge variant="secondary" size="sm">
              {inherited}
            </Badge>
          ) : null}
        </span>
        <span className="sr-only" aria-live="polite">
          {spoken}
        </span>
      </div>

      <CommandFooter>
        <span className="flex items-center gap-3">
          <span className="flex items-center gap-1.5">
            <KbdKeys keys={["↵"]} />
            move
          </span>
          <span className="flex items-center gap-1.5">
            <KbdKeys keys={["esc"]} />
            back
          </span>
        </span>
        <span>{allDay ? "moves by date" : "duration is kept"}</span>
      </CommandFooter>
    </div>
  );
}

"use client";

/**
 * multi-tz-gutter — the hour axis in several zones at once.
 * Offsets come from `Intl` via `lib/timezone`; each row is resolved from a real instant.
 */

import {
  hourLabel,
  type TimeZoneColumn,
  wallClockIn,
  zoneAbbr as zoneAbbrOf,
  zoneOffsetMinutes,
} from "../lib/timezone";
import { useIsClient } from "../lib/use-is-client";
import { useKloqSettings } from "./settings-context";
import { type TimeGutterProps, useGutterDate } from "./time-gutter";

export { zoneAbbr } from "../lib/timezone";
export type { TimeZoneColumn };

/** Wall-clock time of an instant in a given IANA zone. */
export function zoneTimeAt(
  instant: Date | number,
  timeZone: string,
): { hour: number; minute: number } {
  const w = wallClockIn(instant, timeZone);
  return { hour: w.hour, minute: w.minute };
}

/** True when `timeZone` is offset from `relativeTo` (default: browser zone) by a non-whole hour. */
export function hasFractionalOffset(
  instant: Date | number,
  timeZone: string,
  relativeTo?: string,
): boolean {
  const base = relativeTo
    ? zoneOffsetMinutes(instant, relativeTo)
    : -new Date(instant).getTimezoneOffset();
  return (zoneOffsetMinutes(instant, timeZone) - base) % 60 !== 0;
}

export const formatZoneTime = hourLabel;

/** The zone caption above a gutter column. */
export const ZONE_CAPTION = "text-3xs font-medium uppercase tracking-wide text-muted-foreground";

/** Width of the single-zone gutter, in px — Tailwind's `w-16`. */
export const GUTTER_WIDTH = 64;

/**
 * Gutter width with these extra columns. `<Kloq>` publishes it as `--kloq-gutter-width`
 * so headers and the all-day lane can indent to match.
 */
export function multiZoneGutterWidth(
  columns: readonly TimeZoneColumn[],
  instant: Date | number,
  relativeTo?: string,
): number {
  let w = GUTTER_WIDTH;
  for (const c of columns) {
    w += hasFractionalOffset(instant, c.timeZone, relativeTo) ? 62 : 46;
  }
  return w;
}

export interface MultiTimeZoneGutterProps extends TimeGutterProps {
  /** extra zones, left of the main column; omit to use the calendar's `timeZones` */
  zones?: (string | TimeZoneColumn)[];
  /** 12- or 24-hour labels for the foreign columns; defaults to the calendar's `hour12` */
  hour12?: boolean;
}

export function MultiTimeZoneGutter({
  minutesToPx,
  startHour,
  endHour,
  height,
  formatHour,
  date,
  zones,
  hour12,
}: MultiTimeZoneGutterProps) {
  const g = useKloqSettings();
  const contextDate = useGutterDate();
  const isClient = useIsClient();
  const columns = zones ? normalizeLocal(zones) : g.timeZones;
  const use12 = hour12 ?? g.hour12 ?? true;

  // without a display zone the axis is the browser's clock; foreign cells wait for hydration
  const zonesReady = g.hasDisplayZone || isClient;

  const day = date ?? contextDate ?? g.displayNow();

  const instantAtHour = (h: number) => {
    const d = new Date(day);
    // wall-clock addition, not ms arithmetic: DST changeover days would slide every row
    d.setHours(h, 0, 0, 0);
    return g.fromDisplay(d);
  };

  const showHeadings = zones !== undefined;

  const hours: number[] = [];
  // hour 0's label would collide with the in-gutter headings
  const firstHour = showHeadings ? Math.max(1, startHour) : startHour;
  for (let h = firstHour; h < endHour; h++) hours.push(h);
  const noonish = instantAtHour(12);

  // fractional widening waits for the client to avoid a hydration mismatch
  const width = zonesReady
    ? multiZoneGutterWidth(columns, noonish, g.timeZone)
    : GUTTER_WIDTH + columns.length * 46;

  // no display zone → no zone label (server and browser would disagree)
  const mainLabel = g.hasDisplayZone ? g.zoneLabel(noonish) : "local";

  return (
    <div aria-hidden className="relative shrink-0 select-none" style={{ height, width }}>
      {showHeadings ? (
        <div className="absolute inset-x-0 top-1 flex items-baseline justify-between px-2">
          {columns.map((c) => (
            <span key={c.timeZone} className={ZONE_CAPTION}>
              {c.label ?? zoneAbbrOf(noonish, c.timeZone)}
            </span>
          ))}
          <span className={ZONE_CAPTION}>{mainLabel}</span>
        </div>
      ) : null}

      {hours.map((hour) => {
        const instant = instantAtHour(hour);
        return (
          <span
            key={hour}
            className="absolute inset-x-0 flex -translate-y-1/2 items-baseline justify-between px-2 text-2xs tabular-nums"
            style={{ top: minutesToPx(hour * 60) }}
          >
            {columns.map((c) => {
              if (!zonesReady) return <span key={c.timeZone} />;
              const { hour: zh, minute: zm } = zoneTimeAt(instant, c.timeZone);
              return (
                <span
                  key={c.timeZone}
                  className={zh === 0 ? "font-medium text-foreground" : "text-muted-foreground"}
                >
                  {hourLabel(zh, zm, use12)}
                </span>
              );
            })}
            <span className="pr-0.5 text-foreground">
              {formatHour ? formatHour(hour) : hourLabel(hour, 0, use12)}
            </span>
          </span>
        );
      })}
    </div>
  );
}

// deliberately not `normalizeZoneColumns`: an unknown zone should show up empty, not vanish
const normalizeLocal = (zones: (string | TimeZoneColumn)[]): TimeZoneColumn[] =>
  zones.map((z) => (typeof z === "string" ? { timeZone: z } : z));

/**
 * Bind zones once and hand the result to `components.TimeGutter`.
 * Prefer `<Kloq timeZones={[...]} />` unless one instance needs a different zone list.
 */
export function createMultiTimeZoneGutter(
  zones: (string | TimeZoneColumn)[],
  opts: { hour12?: boolean } = {},
) {
  return function BoundMultiTimeZoneGutter(props: TimeGutterProps) {
    return <MultiTimeZoneGutter {...props} zones={zones} {...opts} />;
  };
}

"use client";

/** nav — the range control: ‹ › Today, the range title, and the view switcher. */

import { ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";
import { useLayoutEffect, useMemo, useRef, useState } from "react";
import type { KloqView, ViewDescriptor } from "../lib/calendar-types";
import { formatDate } from "../lib/date-format";
import { displayKey, type KeyActionId, type Keymap, resolveKeymap } from "../lib/keymap";
import { formatViewTitle, type StepDirection, stepLabel } from "../lib/navigation";
import { isNarrowSafe } from "../lib/responsive";
import { EASE_OUT, ms, prefersReducedMotion } from "../lib/springs";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { Kbd } from "../ui/kbd";
import { Menu, MenuPopup, MenuRadioGroup, MenuRadioItem, MenuTrigger } from "../ui/menu";
import { Tooltip, TooltipPopup, TooltipTrigger } from "../ui/tooltip";
import { MonthYearPicker } from "./month-year-picker";

interface ViewOption {
  key: KloqView;
  label: string;
  action?: KeyActionId;
}

/** The switcher's presets. Any `number` 2–14 is still a valid `view` prop. */
export const VIEW_OPTIONS: ViewOption[] = [
  { key: "day", label: "Day", action: "view-day" },
  { key: 3, label: "3 days", action: "view-3days" },
  { key: "week", label: "Week", action: "view-week" },
  { key: "month", label: "Month", action: "view-month" },
  { key: "year", label: "Year", action: "view-year" },
  { key: "agenda", label: "Schedule", action: "view-agenda" },
];

const TIMELINE_OPTION: ViewOption = { key: "timeline", label: "Timeline" };

// the box of a `Button size="xs"`, for measuring a title before it is shown
const TITLE_METRICS =
  "whitespace-nowrap border px-[calc(--spacing(2)-1px)] text-sm font-medium sm:text-xs";

const MONTH_DAY: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" };
const MONTH: Intl.DateTimeFormatOptions = { month: "short" };

/** The range title in every length it comes in, longest first: full, short, and month-only. */
function titleForms(view: ViewDescriptor, locale?: string): string[] {
  const long = formatViewTitle(view, locale);
  const short = formatViewTitle(view, locale, { short: true });
  const l = locale ?? "en-US";
  const first = view.days[0];
  const last = view.days[view.days.length - 1];
  let compact = short;
  if (view.kind !== "year" && first && last) {
    if (view.days.length === 1) compact = formatDate(first, l, MONTH_DAY);
    else if (view.kind === "month" && view.month) compact = formatDate(view.month, l, MONTH);
    else {
      const a = formatDate(first, l, MONTH);
      const b = formatDate(last, l, MONTH);
      compact = a === b ? a : `${a}–${b}`;
    }
  }
  return [...new Set([long, short, compact])];
}

interface CalendarNavProps {
  /** the EFFECTIVE view descriptor — what is on screen, not what was asked for */
  view: ViewDescriptor;
  /** the EFFECTIVE view setting — `"day"` when a narrow box forced it */
  viewSetting: KloqView;
  /** the view is forced narrow; multi-column presets show disabled */
  collapsed?: boolean;
  /** which views fit the box right now; falls back to `isNarrowSafe` when absent */
  fits?: (view: KloqView) => boolean;
  /** the box is phone-width: short title, no standalone Today; `undefined` = not measured yet, CSS decides */
  narrow?: boolean;
  /** false while the calendar has no date to print (server + hydration pass of an undated calendar) */
  ready?: boolean;
  /** the calendar's locale, for the title */
  locale?: string;
  /** the host passed `lanes`: offer the Timeline view */
  timeline?: boolean;
  /** step the range by one of the current view's units */
  onStep: (dir: StepDirection) => void;
  /** jump the range back onto today */
  onToday: () => void;
  onSwitchView: (view: KloqView) => void;
  /** true when today is already inside the visible range */
  atToday: boolean;
  /** the anchor date, for the title's month/year picker */
  date: Date;
  /** move the anchor without changing the view */
  onGoToDate: (date: Date) => void;
  /** the direction of the last step, for the title's slide */
  lastStep?: StepDirection | null;
  /** keymap overrides — the switcher hints and Today tooltip resolve here */
  keymap?: Keymap;
  className?: string;
}

export function CalendarNav({
  view,
  viewSetting,
  onStep,
  onToday,
  onSwitchView,
  atToday,
  date,
  onGoToDate,
  lastStep,
  collapsed = false,
  fits,
  narrow,
  ready = true,
  locale,
  timeline = false,
  keymap,
  className,
}: CalendarNavProps) {
  const resolvedKeys = useMemo(() => resolveKeymap(keymap), [keymap]);
  const todayKey = resolvedKeys.byAction["today"];
  // longest first; the slot shows the longest one it has room for
  const forms = useMemo(() => (ready ? titleForms(view, locale) : []), [ready, view, locale]);
  const [fit, setFit] = useState(0);
  const title = forms[Math.min(fit, forms.length - 1)] ?? "";
  // before the box is measured a container query stands in for `narrow`
  const unmeasured = narrow === undefined;
  const options =
    timeline || viewSetting === "timeline" ? [...VIEW_OPTIONS, TIMELINE_OPTION] : VIEW_OPTIONS;
  const viewLabel =
    typeof viewSetting === "number"
      ? `${viewSetting} days`
      : (options.find((o) => o.key === viewSetting)?.label ?? "Week");
  const titleRef = useRef<HTMLSpanElement>(null);
  const lastTitle = useRef(title);

  // a shorter date before an ellipsis: measure every form against the slot, before paint
  useLayoutEffect(() => {
    const slot = titleRef.current;
    if (!slot || typeof ResizeObserver === "undefined") return;
    const choose = () => {
      const room = slot.clientWidth;
      const widths = Array.from(
        slot.querySelectorAll<HTMLElement>("[data-title-form]"),
        (el) => el.offsetWidth,
      );
      if (!widths.length) return;
      const next = widths.findIndex((w) => w <= room);
      setFit(next < 0 ? widths.length - 1 : next);
    };
    choose();
    const ro = new ResizeObserver(choose);
    ro.observe(slot);
    return () => ro.disconnect();
  }, [forms]);

  // slide the title the way the range moved; keyed on text so re-renders don't re-animate
  useLayoutEffect(() => {
    const node = titleRef.current;
    if (!node) return;
    if (lastTitle.current === title) return;
    lastTitle.current = title;
    if (prefersReducedMotion() || !lastStep) return;
    const dx = lastStep * 8;
    node.animate(
      [
        { transform: `translateX(${dx}px)`, opacity: 0 },
        { transform: "none", opacity: 1 },
      ],
      { duration: ms(200), easing: EASE_OUT },
    );
  }, [title, lastStep]);

  return (
    // steppers lead and the title takes the slack, so nothing before the title ever moves.
    // No `min-w-0`: the nav keeps its own minimum, and a host toolbar wraps around it instead
    <div className={cn("flex flex-auto items-center gap-2", className)}>
      <div className="flex shrink-0 items-center">
        <StepButton
          dir={-1}
          view={viewSetting}
          onStep={onStep}
          hint={resolvedKeys.byAction["prev-period"]}
        />
        <StepButton
          dir={1}
          view={viewSetting}
          onStep={onStep}
          hint={resolvedKeys.byAction["next-period"]}
        />
      </div>

      {/* phone width: Today lives in the title's popover */}
      {narrow === true ? null : (
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="xs"
                // not disabled at today: keeps a stable tab order
                className={cn(
                  atToday && "text-muted-foreground",
                  unmeasured && "@max-[40rem]:hidden",
                )}
                onClick={onToday}
              >
                Today
              </Button>
            }
          />
          <TooltipPopup>
            <span className="flex items-center gap-1.5">
              Jump to today {todayKey ? <Kbd>{displayKey(todayKey)}</Kbd> : null}
            </span>
          </TooltipPopup>
        </Tooltip>
      )}

      {/* a size container, so the title's text never props the nav open: the slot's floor is the
          short date in a wide box and the month-only one in a phone-width box */}
      <span
        ref={titleRef}
        className={cn(
          "@container relative flex flex-1",
          narrow === true ? "min-w-20" : "min-w-31",
          unmeasured && "@max-[40rem]:min-w-20",
        )}
      >
        {ready ? (
          <>
            <MonthYearPicker date={date} label={title} onPick={onGoToDate} locale={locale} />
            <span aria-hidden className="pointer-events-none invisible absolute top-0 left-0 flex">
              {forms.map((form) => (
                <span key={form} data-title-form className={TITLE_METRICS}>
                  {form}
                </span>
              ))}
            </span>
          </>
        ) : null}
      </span>

      {/* the label leads with the visible view name — a labelled widget whose
          visible text isn't part of its accessible name breaks speech input */}
      <Menu>
        <MenuTrigger
          aria-label={`${viewLabel}, calendar view`}
          render={
            <Button
              variant="outline"
              size="xs"
              className={cn(
                "shrink-0",
                narrow !== true && "w-24 justify-between",
                unmeasured && "@max-[40rem]:w-auto",
              )}
            />
          }
        >
          {viewLabel}
          <ChevronDown aria-hidden />
        </MenuTrigger>
        <MenuPopup align="end">
          <MenuRadioGroup
            value={typeof viewSetting === "number" ? 3 : viewSetting}
            onValueChange={(value) => onSwitchView(value as KloqView)}
          >
            {options.map((opt) => {
              // `isNarrowSafe` is the same predicate `effectiveView` collapses on
              const unavailable = fits ? !fits(opt.key) : collapsed && !isNarrowSafe(opt.key);
              const hint = opt.action ? resolvedKeys.byAction[opt.action] : null;
              return (
                <MenuRadioItem
                  key={String(opt.key)}
                  value={opt.key}
                  disabled={unavailable}
                  closeOnClick
                >
                  <span className="flex items-center gap-3">
                    <span className="flex-1">
                      {typeof viewSetting === "number" && typeof opt.key === "number"
                        ? `${viewSetting} days`
                        : opt.label}
                    </span>
                    {unavailable ? (
                      <span className="text-xs text-muted-foreground">too narrow</span>
                    ) : hint ? (
                      <Kbd>{displayKey(hint)}</Kbd>
                    ) : null}
                  </span>
                </MenuRadioItem>
              );
            })}
          </MenuRadioGroup>
        </MenuPopup>
      </Menu>
    </div>
  );
}

function StepButton({
  dir,
  view,
  onStep,
  hint,
}: {
  dir: StepDirection;
  view: KloqView;
  onStep: (dir: StepDirection) => void;
  hint?: string | null;
}) {
  const label = stepLabel(view, dir);
  const Icon = dir < 0 ? ChevronLeft : ChevronRight;

  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label={label}
            className="text-muted-foreground"
            onClick={(e) => {
              const icon = (e.currentTarget as HTMLElement).querySelector("svg");
              if (icon && !prefersReducedMotion())
                icon.animate(
                  [
                    { transform: "none" },
                    { transform: `translateX(${dir * 3}px)` },
                    { transform: "none" },
                  ],
                  { duration: ms(220), easing: EASE_OUT },
                );
              onStep(dir);
            }}
          >
            <Icon />
          </Button>
        }
      />
      <TooltipPopup>
        <span className="flex items-center gap-1.5">
          {label} <Kbd>{hint ? displayKey(hint) : dir < 0 ? "←" : "→"}</Kbd>
        </span>
      </TooltipPopup>
    </Tooltip>
  );
}

"use client";

import { memo } from "react";
import { useKloqSettings } from "./settings-context";
import { useNowMinutes } from "./time-shade";

/** Current-time line across today's column. */
export interface NowIndicatorProps {
  /** Column showing today, or -1. */
  todayIndex: number;
  dayCount: number;
}

export const NowIndicator = memo(function NowIndicator({
  todayIndex,
  dayCount,
}: NowIndicatorProps) {
  const g = useKloqSettings();
  const minutes = useNowMinutes();

  // client-only: avoids SSR/client time mismatch
  if (minutes === null || todayIndex < 0) return null;
  if (minutes < g.dayStartMin || minutes > g.dayEndMin) return null;

  const pct = 100 / dayCount;
  return (
    <div
      className="pointer-events-none absolute z-20 flex items-center"
      style={{
        top: g.minutesToPx(minutes),
        left: `${todayIndex * pct}%`,
        width: `${pct}%`,
      }}
    >
      {/* Text alternative for the line; static, not a live region. */}
      <span className="sr-only">Current time, {g.formatMinutes(Math.round(minutes))}</span>
      <span aria-hidden className="-ml-0.75 size-1.5 rounded-full bg-(--kloq-now)" />
      <span aria-hidden className="h-px flex-1 bg-(--kloq-now)" />
    </div>
  );
});

