);

export function revealRow(el: HTMLElement | null) {
  if (!el || prefersReducedMotion() || el.dataset.revealed !== undefined) return;
  el.dataset.revealed = "";
  el.animate(
    [
      { opacity: 0, transform: "translateY(-4px)" },
      { opacity: 1, transform: "none" },
    ],
    { duration: 150, easing: EASE_OUT },
  );
}

export function PropertyRow({
  label,
  rowRef,
  children,
}: {
  label: string;
  rowRef?: Ref<HTMLDivElement>;
  children: ReactNode;
}) {
  return (
    <div ref={rowRef} className="flex items-start gap-1">
      <span
        className={cn(
          ROW_H,
          "flex w-16 shrink-0 items-center ps-2.5 text-2xs text-muted-foreground",
        )}
      >
        {label}
      </span>
      <div className="min-w-0 flex-1">{children}</div>
    </div>
  );
}

/** Static value in a property row, aligned with the editable controls. */
export function RowValue({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <div
      className={cn(
        ROW_H,
        "flex items-center gap-2 px-2 text-sm text-foreground sm:text-xs",
        className,
      )}
    >
      {children}
    </div>
  );
}

export function ReadOnlyRow({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <div className="flex items-start gap-2 px-0.5 text-sm text-foreground">
      <span aria-hidden className="mt-0.5 shrink-0 text-muted-foreground [&_svg]:size-4">
        {icon}
      </span>
      <span className="min-w-0 flex-1 break-words">{children}</span>
    </div>
  );
}

/** The small uppercase heading that splits an overlay into sections. */
export function SectionLabel({
  as: Tag = "div",
  className,
  children,
}: {
  as?: "div" | "h3";
  className?: string;
  children: ReactNode;
}) {
  return (
    <Tag
      className={cn("font-medium text-muted-foreground text-xs uppercase tracking-wide", className)}
    >
      {children}
    </Tag>
  );
}

"use client";

/**
 * quick-add-input — type a sentence, get an event. Parsed phrases are underlined in place
 * via a mirrored, aria-hidden div under a transparent-text `<input>`.
 */

import { CalendarClock } from "lucide-react";
import type React from "react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import type { QuickAddResult } from "../lib/quick-add";
import { QUICK_ADD_KIND_ORDER, QUICK_ADD_KINDS } from "../lib/quick-add-kinds";
import { highlightSegments, type QuickAddSegment, quickAddPreview } from "../lib/quick-add-view";
import { cn } from "../lib/utils";
import { Badge } from "../ui/badge";
import { CommandFooter } from "../ui/command";
import { KbdKeys } from "./kbd-keys";

/** The ⌘K field row: the same box and type as `CommandInput`, ringed only outside the palette. */
export const COMMAND_FIELD_ROW =
  "mx-2.5 my-1.5 rounded-lg ring-ring transition-shadow not-in-data-[slot=command-dialog-popup]:has-[input:focus-visible]:ring-2";
export const COMMAND_FIELD =
  "h-9.5 px-[calc(--spacing(3)-1px)] font-sans text-base leading-9.5 tracking-normal sm:h-8.5 sm:text-sm sm:leading-8.5";

const SPEAK_AFTER_MS = 700;

/** `text` once typing has paused, so a live region reads the result and not every keystroke. */
export function useSpoken(text: string, enabled: boolean): string {
  const [spoken, setSpoken] = useState("");
  useEffect(() => {
    if (!enabled) return;
    const t = setTimeout(() => setSpoken(text), SPEAK_AFTER_MS);
    return () => clearTimeout(t);
  }, [text, enabled]);
  return enabled ? spoken : "";
}

interface QuickAddInputProps {
  value: string;
  onValueChange: (value: string) => void;
  /** Parse of `value` against the caller's clock. */
  result: QuickAddResult;
  /** Clock used for the preview line; the same `now` the parse used. */
  now: Date;
  /** Enter with a non-empty value. */
  onCommit: () => void;
  /** Escape on an already-empty value. */
  onBack?: () => void;
  autoFocus?: boolean;
  /** `false` keeps the preview out of the live region, for a demo that drives `value`. */
  announce?: boolean;
}

export function QuickAddInput({
  value,
  onValueChange,
  result,
  now,
  onCommit,
  onBack,
  autoFocus = true,
  announce = true,
}: QuickAddInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const mirrorRef = useRef<HTMLDivElement>(null);
  const previewId = useId();

  const segments: QuickAddSegment[] = useMemo(
    () =>
      result.confidence === "none"
        ? [{ text: value, kind: null }]
        : highlightSegments(value, result.tokens, result.ignored),
    [value, result],
  );

  const preview = useMemo(() => quickAddPreview(result, now), [result, now]);
  const ready = value.trim().length > 0;
  const ignored = result.ignored.map((t) => t.text).join(", ");
  const spoken = useSpoken(
    ready
      ? [preview.title, preview.when, ...preview.chips, ignored && `ignored: ${ignored}`]
          .filter(Boolean)
          .join(", ")
      : "",
    announce,
  );

  useEffect(() => {
    const input = inputRef.current;
    const mirror = mirrorRef.current;
    if (!input || !mirror) return;
    mirror.scrollLeft = input.scrollLeft;
  }, [value]);

  useEffect(() => {
    if (autoFocus) inputRef.current?.focus();
  }, [autoFocus]);

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && !e.nativeEvent.isComposing) {
      e.preventDefault();
      if (ready) onCommit();
      return;
    }
    if (e.key === "Escape" && onBack) {
      // otherwise the surrounding dialog's Escape closes the whole menu
      e.preventDefault();
      e.stopPropagation();
      if (value) onValueChange("");
      else onBack();
    }
  };

  return (
    <div className="flex flex-col">
      <div className={cn(COMMAND_FIELD_ROW, "relative")}>
        <div
          aria-hidden
          ref={mirrorRef}
          className={cn(
            "pointer-events-none absolute inset-0 select-none overflow-hidden whitespace-pre text-transparent",
            COMMAND_FIELD,
          )}
        >
          {segments.map((s, i) =>
            s.ignored ? (
              // read, then overruled: struck through, in no kind's colour
              <span
                key={i}
                data-ignored
                className="rounded-xs bg-muted line-through decoration-muted-foreground decoration-2"
              >
                {s.text}
              </span>
            ) : s.kind ? (
              <span
                key={i}
                className={cn(
                  "rounded-xs underline decoration-2 underline-offset-4 motion-safe:transition-colors",
                  QUICK_ADD_KINDS[s.kind].mark,
                )}
              >
                {s.text}
              </span>
            ) : (
              <span key={i}>{s.text}</span>
            ),
          )}
        </div>
        <input
          ref={inputRef}
          value={value}
          onChange={(e) => onValueChange(e.target.value)}
          onScroll={() => {
            const mirror = mirrorRef.current;
            if (mirror && inputRef.current) mirror.scrollLeft = inputRef.current.scrollLeft;
          }}
          onKeyDown={onKeyDown}
          placeholder="lunch with sam@acme.com tomorrow 1pm at Padella"
          aria-label="Quick add an event"
          aria-describedby={previewId}
          autoComplete="off"
          spellCheck={false}
          className={cn(
            "relative w-full bg-transparent text-foreground caret-foreground outline-none placeholder:text-muted-foreground",
            COMMAND_FIELD,
          )}
        />
      </div>

      <div
        id={previewId}
        // a fixed height: the preview rewrites itself per keystroke and must not shift what follows
        className="flex h-17 flex-col gap-1 overflow-hidden border-t px-5 py-3"
      >
        {ready ? (
          <>
            <div className="flex items-baseline gap-2">
              <span className="min-w-0 flex-1 truncate font-medium text-sm text-foreground">
                {preview.title}
              </span>
              {ignored ? (
                <span className="min-w-0 shrink truncate text-2xs text-muted-foreground">
                  ignored: <s>{ignored}</s>
                </span>
              ) : preview.confidence !== "full" ? (
                <span className="shrink-0 text-2xs text-muted-foreground">
                  {preview.confidence === "none" ? "no date found" : "partial match"}
                </span>
              ) : null}
            </div>
            <div className="flex items-center gap-x-2 overflow-x-auto text-xs text-muted-foreground [scrollbar-width:none]">
              <span className="inline-flex shrink-0 items-center gap-1.5">
                <CalendarClock aria-hidden className="size-3.5" />
                {preview.when ?? "—"}
              </span>
              {preview.chips.map((chip) => (
                <Badge key={chip} variant="secondary" size="sm">
                  {chip}
                </Badge>
              ))}
            </div>
          </>
        ) : (
          <p className="text-xs text-muted-foreground">
            Type a sentence — a date, a time, “for 45 minutes”, “at Padella”, or an email address
            all get picked up.
          </p>
        )}
      </div>
      <span className="sr-only" aria-live="polite">
        {spoken}
      </span>

      <CommandFooter>
        <span className="flex flex-wrap items-center gap-x-3 gap-y-1">
          {QUICK_ADD_KIND_ORDER.map((kind) => (
            <span
              key={kind}
              className={cn(
                "rounded-xs px-0.5 underline decoration-2 underline-offset-4",
                QUICK_ADD_KINDS[kind].mark,
              )}
            >
              {QUICK_ADD_KINDS[kind].label}
            </span>
          ))}
        </span>
        <span className="flex shrink-0 items-center gap-3">
          <span className="flex items-center gap-1.5">
            <KbdKeys keys={["↵"]} />
            create
          </span>
          {onBack ? (
            <span className="flex items-center gap-1.5">
              <KbdKeys keys={["esc"]} />
              back
            </span>
          ) : null}
        </span>
      </CommandFooter>
    </div>
  );
}

"use client";

/**
 * recurrence-scope-dialog — "this event / this and following / all events".
 * A chooser only; the caller turns the answer into a plan via `lib/recurrence.ts`.
 */

import { Repeat } from "lucide-react";
import { useState } from "react";
import { RECURRENCE_SCOPES, type RecurrenceScope } from "../lib/recurrence";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import {
  Dialog,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPanel,
  DialogPopup,
  DialogTitle,
} from "../ui/dialog";
import { Label } from "../ui/label";
import { Radio, RadioGroup } from "../ui/radio-group";
import { useReturnFocus } from "./use-return-focus";

export type RecurrenceScopeAction = "edit" | "delete";

const LABELS: Record<RecurrenceScope, string> = {
  this: "This event",
  following: "This and following",
  all: "All events",
};

const HINTS: Record<RecurrenceScopeAction, Record<RecurrenceScope, string>> = {
  edit: {
    this: "Detaches from the series",
    following: "Earlier ones stay as they are",
    all: "Past and future, together",
  },
  delete: {
    this: "The rest of the series stays",
    following: "Earlier ones stay as they are",
    all: "Removes the whole series",
  },
};

const CONFIRM: Record<RecurrenceScopeAction, Record<RecurrenceScope, string>> = {
  edit: {
    this: "Change this event",
    following: "Change following",
    all: "Change all",
  },
  delete: {
    this: "Delete this event",
    following: "Delete following",
    all: "Delete all",
  },
};

const DOTS = 7;
const THIS = 3;

function affected(scope: RecurrenceScope, i: number): boolean {
  if (scope === "all") return true;
  if (scope === "following") return i >= THIS;
  return i === THIS;
}

function Strip({
  scope,
  action,
  active,
}: {
  scope: RecurrenceScope;
  action: RecurrenceScopeAction;
  active: boolean;
}) {
  return (
    <span aria-hidden className="flex shrink-0 items-center gap-1">
      {Array.from({ length: DOTS }, (_, i) => {
        const hit = affected(scope, i);
        return (
          <span
            key={i}
            className={cn(
              "rounded-full transition-[background-color,box-shadow,scale] duration-(--overlay-enter)",
              i === THIS ? "size-2.5" : "size-2",
              hit
                ? action === "delete"
                  ? "bg-destructive"
                  : "bg-primary"
                : "bg-muted-foreground/25",
              hit && !active && "opacity-70",
              i === THIS &&
                "ring-2 ring-offset-1 ring-offset-popover " +
                  (hit
                    ? action === "delete"
                      ? "ring-destructive/35"
                      : "ring-primary/35"
                    : "ring-muted-foreground/30"),
            )}
          />
        );
      })}
    </span>
  );
}

export interface RecurrenceScopeDialogProps {
  open: boolean;
  /** Fired for every close, chosen or not. */
  onOpenChange: (open: boolean) => void;
  action: RecurrenceScopeAction;
  title?: string;
  /** `describeRRule` of the series — "Every week on Mon". */
  summary?: string;
  /** The answer. Only fires on confirm. */
  onChoose: (scope: RecurrenceScope) => void;
  /** Dismissed without answering. */
  onCancel?: () => void;
  /** Scopes to offer; the first occurrence has no "and following". */
  scopes?: readonly RecurrenceScope[];
}

export function RecurrenceScopeDialog({
  open,
  onOpenChange,
  action,
  title,
  summary,
  onChoose,
  onCancel,
  scopes = RECURRENCE_SCOPES,
}: RecurrenceScopeDialogProps) {
  const [scope, setScope] = useState<RecurrenceScope>("this");
  // Reset during render so the old choice never paints.
  const [wasOpen, setWasOpen] = useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) setScope("this");
  }

  const confirm = () => {
    onChoose(scope);
    onOpenChange(false);
  };
  const dismiss = () => {
    onCancel?.();
    onOpenChange(false);
  };

  const label = title?.trim() || "Untitled";
  const destructive = action === "delete";

  const finalFocus = useReturnFocus(open);

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) onCancel?.();
        onOpenChange(next);
      }}
    >
      <DialogPopup
        className="max-w-sm"
        showCloseButton={false}
        finalFocus={finalFocus}
        onKeyDown={(e) => {
          // Enter on a radio confirms it; Space still just selects
          if (e.key !== "Enter" || e.defaultPrevented) return;
          if (!(e.target as HTMLElement).closest("[role=radio]")) return;
          e.preventDefault();
          confirm();
        }}
      >
        <DialogHeader>
          <DialogTitle>
            {destructive ? "Delete recurring event" : "Edit recurring event"}
          </DialogTitle>
          <DialogDescription className="flex min-w-0 items-center gap-1.5">
            <Repeat aria-hidden className="size-3.5 shrink-0" />
            <span className="truncate">
              <span className="text-foreground">{label}</span>
              {summary ? ` · ${summary.toLowerCase()}` : ""}
            </span>
          </DialogDescription>
        </DialogHeader>

        <DialogPanel>
          <RadioGroup
            aria-label={destructive ? "Delete scope" : "Edit scope"}
            className="gap-0 overflow-hidden rounded-xl border bg-background"
            value={scope}
            onValueChange={(next) => setScope(next as RecurrenceScope)}
          >
            {scopes.map((value) => (
              <Label
                key={value}
                className="cursor-pointer gap-3 px-3.5 py-3 font-normal transition-colors not-first:border-t hover:bg-accent/40 has-data-checked:bg-accent/70"
              >
                <Radio value={value} />
                <span className="min-w-0 flex-1">
                  <span className="block font-medium text-sm text-foreground">{LABELS[value]}</span>
                  <span className="block text-xs text-muted-foreground">
                    {HINTS[action][value]}
                  </span>
                </span>
                <Strip scope={value} action={action} active={scope === value} />
              </Label>
            ))}
          </RadioGroup>
        </DialogPanel>

        <DialogFooter variant="bare">
          <Button variant="outline" size="sm" onClick={dismiss}>
            Cancel
          </Button>
          <Button size="sm" variant={destructive ? "destructive" : "default"} onClick={confirm}>
            {CONFIRM[action][scope]}
          </Button>
        </DialogFooter>
      </DialogPopup>
    </Dialog>
  );
}

"use client";

/**
 * reminder-field — the panel's alert control, a thin shell over `lib/reminders.ts`.
 * Edits data only; the host owns delivery via `nextReminderAt`.
 */

import { Bell, ChevronDown, Plus } from "lucide-react";
import { type RefObject, useState } from "react";
import type { Reminder } from "../lib/calendar-types";
import {
  addReminder,
  describeReminder,
  describeReminders,
  MAX_REMINDERS,
  normalizeReminders,
  parseReminderAmount,
  REMINDER_PRESETS,
  REMINDER_UNITS,
  type ReminderUnit,
  removeReminder,
} from "../lib/reminders";
import { useEscapeCapture } from "../lib/use-escape-capture";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { Checkbox } from "../ui/checkbox";
import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Popover, PopoverPopup, PopoverTrigger } from "../ui/popover";
import { Select, SelectItem, SelectPopup, SelectTrigger, SelectValue } from "../ui/select";
import { Separator } from "../ui/separator";
import { GHOST_TRIGGER, RowValue } from "./panel-rows";

const UNIT_ITEMS: { value: ReminderUnit; label: string }[] = REMINDER_UNITS.map((u) => ({
  value: u.unit,
  label: { minutes: "min", hours: "hours", days: "days", weeks: "weeks" }[u.unit],
}));

const isPreset = (r: Reminder) =>
  !r.method && REMINDER_PRESETS.some((p) => p.minutesBefore === r.minutesBefore);

export interface ReminderFieldProps {
  /** The event's reminders. Normalised on every commit, never in place. */
  value?: readonly Reminder[];
  /** Commit. Always receives a canonical list; `[]` means "no reminders". */
  onChange: (next: Reminder[]) => void;
  /** Renders the summary as static text with no controls. */
  readOnly?: boolean;
  /** Lets the panel focus the trigger after revealing the row. */
  triggerRef?: RefObject<HTMLButtonElement | null>;
  className?: string;
}

export function ReminderField({
  value,
  onChange,
  readOnly = false,
  triggerRef,
  className,
}: ReminderFieldProps) {
  const [open, setOpen] = useState(false);
  const [unitOpen, setUnitOpen] = useState(false);
  const [amount, setAmount] = useState("");
  const [unit, setUnit] = useState<ReminderUnit>("minutes");

  const reminders = normalizeReminders(value);
  const summary = describeReminders(reminders);
  const full = reminders.length >= MAX_REMINDERS;

  // capture phase, to beat the panel's own Escape; the unit select answers its own
  useEscapeCapture(open && !unitOpen, () => {
    setOpen(false);
    triggerRef?.current?.focus();
  });

  if (readOnly) {
    if (reminders.length === 0) return null;
    return (
      <RowValue className={className}>
        <Bell aria-hidden className="size-3.5 shrink-0 text-muted-foreground" />
        <span className="min-w-0 flex-1 truncate">{summary}</span>
      </RowValue>
    );
  }

  const commitCustom = () => {
    const minutes = parseReminderAmount(amount, unit);
    if (minutes === null) return;
    const next = addReminder(reminders, { minutesBefore: minutes });
    if (next) onChange(next);
    setAmount("");
  };

  const customValid = parseReminderAmount(amount, unit) !== null;

  // custom offsets first: they have no preset row to untick
  const rows: { key: string; label: string; on: boolean; toggle: () => void }[] = [
    ...reminders
      .filter((r) => !isPreset(r))
      .map((r) => ({
        key: `${r.minutesBefore}:${r.method ?? "popup"}`,
        label: describeReminder(r, { withMethod: true }),
        on: true,
        toggle: () => onChange(removeReminder(reminders, r)),
      })),
    ...REMINDER_PRESETS.map((p) => {
      const on = reminders.some((r) => r.minutesBefore === p.minutesBefore && !r.method);
      return {
        key: `preset:${p.minutesBefore}`,
        label: p.label,
        on,
        toggle: () => {
          const next = on
            ? removeReminder(reminders, { minutesBefore: p.minutesBefore })
            : addReminder(reminders, { minutesBefore: p.minutesBefore });
          if (next) onChange(next);
        },
      };
    }),
  ];

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        ref={triggerRef}
        aria-label={`Reminders — ${summary}`}
        className={cn(GHOST_TRIGGER, className)}
      >
        <Bell aria-hidden className="size-3.5 shrink-0 text-muted-foreground" />
        <span
          className={cn(
            "min-w-0 flex-1 truncate",
            reminders.length ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {summary}
        </span>
        <ChevronDown
          aria-hidden
          className="size-3 shrink-0 text-muted-foreground transition-transform duration-(--overlay-enter) group-data-popup-open:rotate-180 motion-reduce:transition-none"
        />
      </PopoverTrigger>

      <PopoverPopup side="bottom" align="start" padding="sm" className="w-64">
        <div role="group" aria-label="Reminders" className="flex flex-col">
          {rows.map((row) => (
            <Label
              key={row.key}
              className="min-h-8 cursor-default rounded-sm px-2 font-normal hover:bg-accent has-data-disabled:pointer-events-none has-data-disabled:opacity-64 sm:min-h-7"
            >
              <Checkbox checked={row.on} disabled={!row.on && full} onCheckedChange={row.toggle} />
              <span className="min-w-0 flex-1 truncate">{row.label}</span>
            </Label>
          ))}
        </div>

        <Separator className="my-1" />

        <div className="flex items-center gap-1.5 px-1 pb-1">
          <Input
            size="xs"
            inputMode="numeric"
            aria-label="Custom reminder amount"
            aria-invalid={amount.trim() !== "" && !customValid ? true : undefined}
            placeholder="15"
            className="w-14 shrink-0"
            value={amount}
            disabled={full}
            onChange={(e) => setAmount(e.target.value)}
            onKeyDown={(e) => {
              if (e.key !== "Enter" || e.metaKey || e.ctrlKey) return;
              e.preventDefault();
              commitCustom();
            }}
          />
          <Select
            items={UNIT_ITEMS}
            value={unit}
            onValueChange={(v) => setUnit(v as ReminderUnit)}
            onOpenChange={setUnitOpen}
            disabled={full}
          >
            <SelectTrigger
              size="xs"
              aria-label="Custom reminder unit"
              className="w-auto min-w-20 shrink-0"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectPopup size="xs">
              {UNIT_ITEMS.map((u) => (
                <SelectItem key={u.value} value={u.value}>
                  {u.label}
                </SelectItem>
              ))}
            </SelectPopup>
          </Select>
          <span className="text-2xs text-muted-foreground">before</span>
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label="Add custom reminder"
            className="ms-auto text-muted-foreground"
            disabled={!customValid || full}
            onClick={commitCustom}
          >
            <Plus />
          </Button>
        </div>

        {full ? (
          <p className="px-2 pb-1.5 text-2xs text-muted-foreground">
            {MAX_REMINDERS} reminders is the limit — remove one to add another.
          </p>
        ) : null}
      </PopoverPopup>
    </Popover>
  );
}

