  /** first working hour, inclusive (e.g. 9) */
  start: number;
  /** end of the working day, exclusive (e.g. 17) */
  end: number;
}

/**
 * "Now" in the display zone as minutes into the day; null until the first client tick.
 * Ticks align to wall-clock 30s boundaries so every consumer moves in the same frame.
 */
export function useNowMinutes(): number | null {
  const g = useKloqSettings();
  const [minutes, setMinutes] = useState<number | null>(null);
  const displayNow = g.displayNow;
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    const update = () => {
      const now = displayNow();
      setMinutes(now.getHours() * 60 + now.getMinutes() + now.getSeconds() / 60);
      timer = setTimeout(update, 30_000 - (Date.now() % 30_000));
    };
    update();
    return () => clearTimeout(timer);
  }, [displayNow]);
  return minutes;
}

interface TimeShadeProps {
  /** column showing today, or -1 (nothing is "past" in a future-only view) */
  todayIndex: number;
  dayCount: number;
  /** false disables the working-hours tint entirely */
  workingHours: WorkingHours | false;
}

// visually hidden but not from AT; inline so it survives a host without the stylesheet
const SR_ONLY = {
  position: "absolute",
  width: "1px",
  height: "1px",
  margin: "-1px",
  padding: 0,
  border: 0,
  overflow: "hidden",
  clip: "rect(0 0 0 0)",
  clipPath: "inset(50%)",
  whiteSpace: "nowrap",
} as const;

const UNAVAILABLE_DAY: Intl.DateTimeFormatOptions = {
  weekday: "long",
  month: "long",
  day: "numeric",
};

const sameHours = (a: WorkingHours | false, b: WorkingHours | false) =>
  a === b || (!!a && !!b && a.start === b.start && a.end === b.end);

export const TimeShade = memo(
  function TimeShade({ todayIndex, dayCount, workingHours }: TimeShadeProps) {
    const g = useKloqSettings();
    const isClient = useIsClient();
    const { constraints, days } = useConstraints();
    const minutes = useNowMinutes();
    const colPct = 100 / dayCount;
    const bottom = g.canvasHeight;

    // sampled at snap resolution so the hatch's edge is exactly where a drag stops
    const bands = useMemo(
      () =>
        disabledBands({ days: days as Date[] }, constraints, {
          dayStartMin: g.dayStartMin,
          dayEndMin: g.dayEndMin,
          stepMinutes: g.snapMinutes,
          toInstant: g.fromDisplay,
        }),
      [days, constraints, g.dayStartMin, g.dayEndMin, g.snapMinutes, g.fromDisplay],
    );
    // clamp into the visible window: a clipped day range would give negative offsets
    const y = (min: number) => g.minutesToPx(g.clampMinutes(min));

    return (
      <>
        {workingHours ? (
          <>
            <div
              aria-hidden
              className="cal-offhours"
              style={{
                top: 0,
                height: y(workingHours.start * 60),
                left: 0,
                width: "100%",
              }}
            />
            <div
              aria-hidden
              className="cal-offhours"
              style={{
                top: y(workingHours.end * 60),
                height: bottom - y(workingHours.end * 60),
                left: 0,
                width: "100%",
              }}
            />
          </>
        ) : null}

        {bands.map((b) => (
          <div
            key={`${b.dayIndex}:${b.startMin}`}
            aria-hidden
            className="cal-blocked"
            data-cal-blocked=""
            style={{
              top: y(b.startMin),
              height: y(b.endMin) - y(b.startMin),
              left: `${b.dayIndex * colPct}%`,
              width: `${colPct}%`,
            }}
          />
        ))}
        {/* the hatch, for AT; client-only because the runtime's default locale differs from the server's */}
        {isClient && bands.length > 0 ? (
          <ul style={SR_ONLY} data-kloq-unavailable="">
            {bands.map((b) => (
              <li key={`${b.dayIndex}:${b.startMin}`}>
                {describeUnavailable({
                  day: days[b.dayIndex] && formatDate(days[b.dayIndex], g.locale, UNAVAILABLE_DAY),
                  time: g.formatRange(b.startMin, b.endMin),
                })}
              </li>
            ))}
          </ul>
        ) : null}

        {/* past wash is client-only */}
        {minutes !== null && todayIndex >= 0 ? (
          <>
            {todayIndex > 0 ? (
              <div
                aria-hidden
                className="cal-past-shade"
                style={{
                  top: 0,
                  height: bottom,
                  left: 0,
                  width: `${todayIndex * colPct}%`,
                }}
              />
            ) : null}
            <div
              aria-hidden
              className="cal-past-shade"
              style={{
                top: 0,
                height: y(minutes),
                left: `${todayIndex * colPct}%`,
                width: `${colPct}%`,
              }}
            />
          </>
        ) : null}
      </>
    );
  },
  (a, b) =>
    a.todayIndex === b.todayIndex &&
    a.dayCount === b.dayCount &&
    sameHours(a.workingHours, b.workingHours),
);

import { type RefObject, useEffect, useLayoutEffect, useRef } from "react";
import { EASE_OUT, prefersReducedMotion } from "../lib/springs";
import { useLatest } from "../lib/use-latest";

export const PANEL_WIDTH = 320;
const GAP = 10;
const MARGIN = 8;
// matches --overlay-enter
const ENTER_MS = 150;
// longest a slow page takes to deliver the opening tap's trailing events
const GHOST_CLICK_MS = 700;
const SHEET_BELOW = 640;
const SIDE_BY_SIDE_FROM = 1024;

interface Pos {
  x: number;
  y: number;
  /** which side of the block the panel sits on */
  side: "right" | "left";
}

/**
 * A bottom sheet on phones, and on tablets whenever the panel could not sit beside a
 * column this wide without covering it.
 */
function wantsSheet(anchor: DOMRect): boolean {
  const w = window.innerWidth;
  if (w < SHEET_BELOW) return true;
  if (w >= SIDE_BY_SIDE_FROM) return false;
  return w < anchor.width + 2 * (PANEL_WIDTH + GAP + MARGIN);
}

/**
 * The tap that opened the sheet is still in flight: its touchend and the mouse events the
 * browser synthesises from it arrive after the sheet has risen under the finger, and would
 * focus whatever is there. Swallow exactly those — the next touch is the user's own.
 */
function swallowGhostClick(wrap: HTMLElement) {
  if (!window.matchMedia("(pointer: coarse)").matches) return;
  const swallow = (e: Event) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "click") stop();
  };
  const types = ["mousedown", "mouseup", "click"] as const;
  const stop = () => {
    window.clearTimeout(timer);
    for (const t of types) wrap.removeEventListener(t, swallow, true);
    document.removeEventListener("touchstart", stop, true);
  };
  for (const t of types) wrap.addEventListener(t, swallow, true);
  document.addEventListener("touchstart", stop, true);
  const timer = window.setTimeout(stop, GHOST_CLICK_MS);
}

/** Scroll the grid so the block being edited sits above the sheet rather than under it. */
function liftAnchorAbove(anchor: HTMLElement, sheet: HTMLElement) {
  let scroller: HTMLElement | null = anchor.parentElement;
  while (scroller && !/(auto|scroll)/.test(getComputedStyle(scroller).overflowY))
    scroller = scroller.parentElement;
  if (!scroller) return;
  const rect = anchor.getBoundingClientRect();
  const top = scroller.getBoundingClientRect().top;
  const sheetTop = window.innerHeight - sheet.offsetHeight;
  // as far as needed to clear the sheet, never so far that the block leaves by the top
  const by = Math.min(rect.bottom - (sheetTop - 12), rect.top - (top + 8));
  if (by <= 0) return;
  scroller.scrollBy({ top: by, behavior: prefersReducedMotion() ? "auto" : "smooth" });
}

/** Fixed-position the panel beside its anchor block: entrance on mount, morph on re-anchor, re-clamp on scroll/resize. */
export function useAnchoredPanel(
  wrapRef: RefObject<HTMLDivElement | null>,
  getAnchor: (id: string) => HTMLElement | null,
  eventId: string,
) {
  const posRef = useRef<Pos>({ x: 0, y: 0, side: "right" });
  const mountedRef = useRef(false);

  const computePos = (anchor: DOMRect): Pos => {
    const wrap = wrapRef.current;
    const h = wrap?.offsetHeight ?? 200;
    let side: Pos["side"] = "right";
    let x = anchor.right + GAP;
    if (x + PANEL_WIDTH > window.innerWidth - MARGIN) {
      side = "left";
      x = anchor.left - GAP - PANEL_WIDTH;
      if (x < MARGIN) x = MARGIN; // a column wider than the room beside it: best effort
    }
    const y = Math.min(
      Math.max(anchor.top, MARGIN),
      Math.max(MARGIN, window.innerHeight - h - MARGIN),
    );
    return { x, y, side };
  };

  /** Returns whether the panel is (now) a sheet, which has no position to apply. */
  const applySheet = (anchor: DOMRect): boolean => {
    const wrap = wrapRef.current;
    if (!wrap) return false;
    const sheet = wantsSheet(anchor);
    if (sheet === (wrap.dataset.sheet !== undefined)) return sheet;
    if (sheet) {
      wrap.dataset.sheet = "";
      wrap.style.transform = "";
      delete wrap.dataset.side;
    } else {
      delete wrap.dataset.sheet;
    }
    return sheet;
  };

  const applyPos = (p: Pos) => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    posRef.current = p;
    wrap.style.transform = `translate(${p.x}px, ${p.y}px)`;
    wrap.dataset.side = p.side;
  };

  const reanchor = (animate: boolean) => {
    const anchor = getAnchor(eventId);
    const wrap = wrapRef.current;
    if (!anchor || !wrap) return;
    const rect = anchor.getBoundingClientRect();
    if (applySheet(rect)) return;
    const prev = posRef.current;
    const next = computePos(rect);
    if (animate && !prefersReducedMotion()) {
      wrap.animate(
        [
          { transform: `translate(${prev.x}px, ${prev.y}px)` },
          { transform: `translate(${next.x}px, ${next.y}px)` },
        ],
        { duration: ENTER_MS, easing: EASE_OUT },
      );
    }
    applyPos(next);
  };

  // entrance on first mount, morph on anchor change
  useLayoutEffect(() => {
    const wrap = wrapRef.current;
    const anchor = getAnchor(eventId);
    if (!wrap || !anchor) return;
    const card = wrap.querySelector<HTMLElement>("[data-slot=card]");

    if (!mountedRef.current) {
      mountedRef.current = true;
      const rect = anchor.getBoundingClientRect();
      const sheet = applySheet(rect);
      let from = "translateY(1rem)";
      if (sheet) {
        swallowGhostClick(wrap);
        liftAnchorAbove(anchor, wrap);
      } else {
        const p = computePos(rect);
        applyPos(p);
        if (card) card.style.transformOrigin = p.side === "right" ? "left top" : "right top";
        from = "scale(0.98)";
      }
      card?.animate(
        prefersReducedMotion()
          ? [{ opacity: 0 }, { opacity: 1 }]
          : [
              { opacity: 0, transform: from },
              { opacity: 1, transform: "none" },
            ],
        { duration: ENTER_MS, easing: EASE_OUT },
      );
    } else {
      reanchor(true);
      card?.animate([{ opacity: 0.5 }, { opacity: 1 }], {
        duration: ENTER_MS,
        easing: EASE_OUT,
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId]);

  useEffect(() => {
    let frame = 0;
    const onShift = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        reanchor(false);
      });
    };
    window.addEventListener("scroll", onShift, { capture: true, passive: true });
    window.addEventListener("resize", onShift, { passive: true });
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", onShift, { capture: true });
      window.removeEventListener("resize", onShift);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId]);

  // re-anchor on resize so the y clamp sees the new height; skipped while a drag drives position.
  // A sheet that grew (a row was added) may have risen over the block again, so lift it once more;
  // never on scroll, which would fight the user.
  const latest = useLatest({ reanchor, getAnchor, eventId });
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap || typeof ResizeObserver === "undefined") return;
    let first = true;
    const ro = new ResizeObserver(() => {
      if (first) {
        first = false;
        return;
      }
      if (wrap.dataset.following !== undefined) return;
      latest.current.reanchor(false);
      const anchor = latest.current.getAnchor(latest.current.eventId);
      if (anchor && wrap.dataset.sheet !== undefined) liftAnchorAbove(anchor, wrap);
    });
    ro.observe(wrap);
    return () => ro.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { reanchor };
}

"use client";

/**
 * use-calendar-keys — the keyboard layer. Fires only when the calendar owns the
 * keyboard (lib/keyboard-scope); ⌘K/⌘Z can go global via `globalShortcuts`.
 */

import type { RefObject } from "react";
import { useEffect } from "react";
import { flushSync } from "react-dom";
import type { EventColor, KloqView, PlacedEvent, ViewDescriptor } from "../lib/calendar-types";
import { MINUTES_PER_DAY } from "../lib/date-math";
import { resetZoom, zoomBy } from "../lib/density";
import { isTypingEvent, watchKeyboardScope } from "../lib/keyboard-scope";
import { actionForEvent, type KeyActionId, type Keymap, resolveKeymap } from "../lib/keymap";
import { compareForDay } from "../lib/month-grid";
import type { NavigationKeys } from "../lib/navigation";
import { nodeFor } from "../lib/recurrence";
import { KEYBOARD_SPRING, KEYBOARD_SPRING_MS, ms, prefersReducedMotion } from "../lib/springs";
import { useLatest } from "../lib/use-latest";
import { EVENT_COLORS } from "./event-block";
import { useKloqSettings } from "./settings-context";
import type { KloqSelectionHandle } from "./use-selection";

const COLOR_ORDER = Object.keys(EVENT_COLORS) as EventColor[];

/** Column-space patch; `updateEvent`'s implementer converts to store space. */
export type PlacedEventPatch = Partial<
  Pick<PlacedEvent, "dayIndex" | "endDayIndex" | "startMin" | "endMin" | "color">
>;

interface CalendarKeysOpts {
  rootRef: RefObject<HTMLElement | null>;
  /** Let ⌘K / ⌘Z / ⇧⌘Z fire without focus. Off by default — embedded calendars must not steal undo. */
  globalShortcuts?: boolean;
  projected: PlacedEvent[];
  view: ViewDescriptor;
  selectedId: string | null;
  registry: Map<string, HTMLElement>;
  /** never opens the panel by itself */
  select: (id: string) => void;
  panelOpen: boolean;
  openPanel: (id: string) => void;
  clearSelection: () => void;
  /** partial patch — `{ endMin }` alone must keep the existing start day */
  updateEvent: (id: string, patch: PlacedEventPatch) => void;
  quickCreate: () => void;
  undo: () => void;
  redo: () => void;
  openCommand: () => void;
  /** `false` leaves ⌘K entirely alone — no preventDefault, so the host's own palette keeps it */
  commandPalette?: boolean;
  openShortcuts: () => void;
  /** PageUp/PageDown always; ←/→ only when nothing is selected */
  stepRange: (dir: -1 | 1) => void;
  /** what ←/→ do under `navigationKeys: "day"` */
  stepDay?: (dir: -1 | 1) => void;
  /** show the gutter time markers for these edges, briefly */
  flashEdges?: (mins: number[]) => void;
  navigationKeys?: NavigationKeys;
  goToday: () => void;
  switchView: (view: KloqView) => void;
  /** omit and ⌘A/⌘C/⌘X/⌘V/⌘D and ⇧arrows don't fire; ⌥arrows / 1–5 act on `selectedId` alone */
  selection?: KloqSelectionHandle | null;
  keymap?: Keymap;
}

const VIEW_ACTIONS: Partial<Record<KeyActionId, KloqView>> = {
  "view-day": "day",
  "view-3days": 3,
  "view-week": "week",
  "view-month": "month",
  "view-agenda": "agenda",
  "view-year": "year",
};

function isTyping(e: KeyboardEvent): boolean {
  return isTypingEvent(e);
}

type ArrowKey = "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight";
/** A "+N more" trigger: a month day index, or the all-day lane. */
type MoreTarget = number | "lane";
type WalkView = Pick<ViewDescriptor, "kind" | "dayCount" | "todayIndex">;
export type WalkStep = { event: PlacedEvent } | { more: MoreTarget } | null;

const byStart = (a: PlacedEvent, b: PlacedEvent) =>
  a.dayIndex - b.dayIndex || a.startMin - b.startMin;
const byLane = (a: PlacedEvent, b: PlacedEvent) =>
  a.dayIndex - b.dayIndex || b.endDayIndex - a.endDayIndex || (a.id < b.id ? -1 : 1);
const byDay = (a: PlacedEvent, b: PlacedEvent) => a.dayIndex - b.dayIndex || compareForDay(a, b);

const isList = (view: WalkView) => view.kind === "month" || view.kind === "agenda";

/** Where a plain arrow starts when nothing is selected: today's first event, else the first drawn. */
export function firstEvent(
  events: readonly PlacedEvent[],
  view: WalkView,
  drawn: (e: PlacedEvent) => boolean = () => true,
): PlacedEvent | null {
  if (isList(view)) {
    const ordered = [...events].sort(byDay).filter(drawn);
    return ordered.find((e) => e.dayIndex === view.todayIndex) ?? ordered[0] ?? null;
  }
  const timed = events.filter((e) => !e.allDay).sort(byStart);
  return (
    timed.find((e) => e.dayIndex === view.todayIndex) ??
    timed[0] ??
    events.filter((e) => e.allDay && drawn(e)).sort(byLane)[0] ??
    null
  );
}

/**
 * One arrow press from `cur`, in the order the view draws events. Every event is reachable:
 * a time grid walks columns and climbs into the all-day lane, month and agenda walk day lists
 * and carry on into the next day. An event hidden behind "+N more" is never selected — the walk
 * stops on that trigger first, and a second press steps over what it hides.
 */
export function walkEvents(
  events: readonly PlacedEvent[],
  view: WalkView,
  cur: PlacedEvent,
  key: ArrowKey,
  drawn: (e: PlacedEvent) => boolean = () => true,
  onMore: MoreTarget | null = null,
): WalkStep {
  const dir = key === "ArrowDown" || key === "ArrowRight" ? 1 : -1;
  const vertical = key === "ArrowUp" || key === "ArrowDown";

  if (isList(view)) {
    const ordered = [...events].sort(byDay);
    const i = ordered.findIndex((e) => e.id === cur.id);
    if (!vertical) {
      for (let day = cur.dayIndex + dir; day >= 0 && day < view.dayCount; day += dir) {
        const first = ordered.find((e) => e.dayIndex === day && drawn(e));
        if (first) return { event: first };
      }
      return null;
    }
    const next = ordered[i + dir];
    if (!next) return null;
    if (drawn(next)) return { event: next };
    if (onMore !== next.dayIndex) return { more: next.dayIndex };
    for (let j = i + dir; ordered[j]; j += dir) if (drawn(ordered[j])) return { event: ordered[j] };
    return null;
  }

  const timed = events.filter((e) => !e.allDay).sort(byStart);
  const lane = events.filter((e) => e.allDay).sort(byLane);

  if (cur.allDay) {
    if (vertical) {
      if (dir < 0) return null;
      for (let day = cur.dayIndex; day <= cur.endDayIndex; day++) {
        const first = timed.find((e) => e.dayIndex === day);
        if (first) return { event: first };
      }
      return null;
    }
    const i = lane.findIndex((e) => e.id === cur.id);
    const next = lane[i + dir];
    if (!next) return null;
    if (drawn(next)) return { event: next };
    if (onMore !== "lane") return { more: "lane" };
    for (let j = i + dir; lane[j]; j += dir) if (drawn(lane[j])) return { event: lane[j] };
    return null;
  }

  if (vertical) {
    const col = timed.filter((e) => e.dayIndex === cur.dayIndex);
    const next = col[col.findIndex((e) => e.id === cur.id) + dir];
    if (next) return { event: next };
    if (dir > 0) return null;
    // off the top of a column: into the all-day lane above it
    const over = lane.filter((e) => e.dayIndex <= cur.dayIndex && cur.dayIndex <= e.endDayIndex);
    const chip = over.filter(drawn).at(-1);
    if (chip) return { event: chip };
    return over.length ? { more: "lane" } : null;
  }
  for (let day = cur.dayIndex + dir; day >= 0 && day < view.dayCount; day += dir) {
    const col = timed.filter((e) => e.dayIndex === day);
    if (!col.length) continue;
    return {
      event: col.reduce((best, e) =>
        Math.abs(e.startMin - cur.startMin) < Math.abs(best.startMin - cur.startMin) ? e : best,
      ),
    };
  }
  return null;
}

export function useCalendarKeys(opts: CalendarKeysOpts) {
  const g = useKloqSettings();
  const o = useLatest({ ...opts, g });

  useEffect(() => {
    const scope = watchKeyboardScope(() => o.current.rootRef.current);

    const applyAnimated = (id: string, patch: PlacedEventPatch) => {
      const { registry, updateEvent } = o.current;
      const node = nodeFor(registry, id);
      const old = node?.getBoundingClientRect();
      flushSync(() => updateEvent(id, patch));
      const after = nodeFor(registry, id);
      if (!old || !after || prefersReducedMotion()) return;
      const now = after.getBoundingClientRect();
      const dx = old.left - now.left;
      const dy = old.top - now.top;
      const sy = now.height > 0 ? old.height / now.height : 1;
      const sx = now.width > 0 ? old.width / now.width : 1;
      if (
        Math.abs(dx) < 1 &&
        Math.abs(dy) < 1 &&
        Math.abs(sy - 1) < 0.01 &&
        Math.abs(sx - 1) < 0.01
      )
        return;
      const tilt = Math.max(-2, Math.min(2, -dx / 60));
      after.animate(
        [
          {
            transform: `translate(${dx}px, ${dy}px) rotate(${tilt}deg) scale(${sx}, ${sy})`,
            transformOrigin: "top left",
          },
          { transform: "none", transformOrigin: "top left" },
        ],
        { duration: KEYBOARD_SPRING_MS, easing: KEYBOARD_SPRING },
      );
    };

    const reveal = (id: string) => {
      o.current.registry.get(id)?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    };

    // an event the view drew: hidden ones sit behind a "+N more" and have no node
    const drawn = (ev: PlacedEvent) =>
      o.current.registry.size === 0 || nodeFor(o.current.registry, ev.id) !== undefined;

    /** The overflow trigger that has focus: a month day index, the all-day lane, or none. */
    const focusedMore = (): MoreTarget | null => {
      const el = document.activeElement as HTMLElement | null;
      if (!el?.matches?.("[data-cal-more]")) return null;
      const day = el.closest<HTMLElement>("[data-month-day]")?.dataset.monthDay;
      return day === undefined ? "lane" : Number(day);
    };

    const focusMore = (target: MoreTarget) => {
      o.current.rootRef.current
        ?.querySelector<HTMLElement>(
          target === "lane"
            ? "[data-cal-lane] [data-cal-more]"
            : `[data-month-day="${target}"] [data-cal-more]`,
        )
        ?.focus();
    };

    const onKey = (e: KeyboardEvent) => {
      if (e.defaultPrevented) return;
      const { selectedId, projected, view, g } = o.current;
      const owned = scope.owns();
      const global = o.current.globalShortcuts ?? false;

      // ⌘K works even while typing
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        if (o.current.commandPalette === false) return;
        if (!owned && !global) return;
        e.preventDefault();
        o.current.openCommand();
        return;
      }
      if (isTyping(e)) return;

      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "z") {
        if (!owned && !global) return;
        e.preventDefault();
        if (e.shiftKey) o.current.redo();
        else o.current.undo();
        return;
      }
      if (
        (e.metaKey || e.ctrlKey) &&
        e.shiftKey &&
        (e.key === "," || e.key === "." || e.key === "0")
      ) {
        if (!owned && !global) return;
        e.preventDefault();
        if (e.key === "0") resetZoom();
        else zoomBy(e.key === "." ? 1 : -1);
        return;
      }
      // everything below is never global: no preventDefault() on arrows for a page not looking at us
      if (!owned) return;

      // with an empty selection ⌘C falls through to the browser's own copy
      const sel = o.current.selection;
      if (sel && (e.metaKey || e.ctrlKey) && !e.altKey) {
        const key = e.key.toLowerCase();
        if (key === "a") {
          e.preventDefault();
          sel.selectAll();
          return;
        }
        if (key === "v") {
          e.preventDefault();
          sel.paste();
          return;
        }
        if (sel.count === 0) return;
        if (key === "c") {
          e.preventDefault();
          sel.copy();
          return;
        }
        if (key === "x") {
          e.preventDefault();
          sel.cut();
          return;
        }
        if (key === "d") {
          e.preventDefault();
          sel.duplicate();
          return;
        }
        return;
      }
      // ⌥⇧⌘↑↓ (start-edge resize) is the one ⌘ chord that belongs to the ⌥ layer below
      if ((e.metaKey || e.ctrlKey) && !e.altKey) return;

      if (sel && sel.count > 0 && (e.key === "Backspace" || e.key === "Delete")) {
        e.preventDefault();
        sel.remove();
        return;
      }

      const selected = selectedId ? (projected.find((ev) => ev.id === selectedId) ?? null) : null;

      // Escape clears only with the panel closed; inside a layered surface it is that surface's
      if (selected && !isTyping(e) && !e.metaKey && !e.ctrlKey && !e.altKey) {
        const layered = (e.target as Element | null)?.closest?.(
          '[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"], [data-popup]',
        );
        // Enter on a focused "+N more" opens that popover, not the selected event
        const onControl = (e.target as Element | null)?.closest?.("[data-cal-more]");
        if (e.key === "Enter" && !layered && !onControl) {
          e.preventDefault();
          o.current.openPanel(selected.id);
          return;
        }
        if (e.key === "Escape" && !layered && !o.current.panelOpen) {
          e.preventDefault();
          o.current.clearSelection();
          return;
        }
      }

      // before the keymap dispatch on purpose: with a selection, digits always recolor
      if (selected && /^[1-5]$/.test(e.key)) {
        e.preventDefault();
        const color = COLOR_ORDER[Number(e.key) - 1];
        if (sel && sel.count > 1) sel.recolor(color);
        else o.current.updateEvent(selected.id, { color });
        requestAnimationFrame(() => {
          document
            .querySelector<HTMLElement>(`[data-color-swatch="${color}"]`)
            ?.animate(
              [{ transform: "scale(1)" }, { transform: "scale(1.35)" }, { transform: "scale(1)" }],
              { duration: ms(220), easing: "ease-out" },
            );
        });
        return;
      }

      // resolved per keydown so a keymap prop change needs no listener re-wiring
      const mnemonic = actionForEvent(e, resolveKeymap(o.current.keymap));
      if (mnemonic) {
        e.preventDefault();
        const nextView = VIEW_ACTIONS[mnemonic];
        if (nextView) {
          o.current.switchView(nextView);
        } else if (mnemonic === "today") {
          o.current.goToday();
        } else if (mnemonic === "create") {
          o.current.quickCreate();
        } else if (mnemonic === "shortcuts") {
          o.current.openShortcuts();
        } else if (mnemonic === "prev-period" || mnemonic === "next-period") {
          // like bare ←/→ with nothing selected, but these fire even with a selection
          const dir = mnemonic === "next-period" ? 1 : -1;
          if (o.current.navigationKeys === "day" && o.current.stepDay) o.current.stepDay(dir);
          else o.current.stepRange(dir);
        }
        return;
      }

      if (e.key === "PageUp" || e.key === "PageDown") {
        e.preventDefault();
        o.current.stepRange(e.key === "PageUp" ? -1 : 1);
        return;
      }

      if (!e.key.startsWith("Arrow")) return;

      if (e.altKey && selected) {
        e.preventDefault();
        const step = g.snapMinutes;
        // bulk move only — no bulk resize: it would turn a 15-minute standup negative
        if (sel && sel.count > 1) {
          if (e.key === "ArrowLeft" || e.key === "ArrowRight")
            sel.nudge({ days: e.key === "ArrowRight" ? 1 : -1 });
          else if (!e.shiftKey) sel.nudge({ minutes: e.key === "ArrowDown" ? step : -step });
          return;
        }
        if (selected.allDay) {
          if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
            const delta = e.key === "ArrowRight" ? 1 : -1;
            const span = selected.endDayIndex - selected.dayIndex;
            const lo = Math.max(0, Math.min(view.dayCount - 1 - span, selected.dayIndex + delta));
            applyAnimated(selected.id, {
              dayIndex: lo,
              endDayIndex: lo + span,
            });
          }
          return;
        }
        const duration = selected.endMin - selected.startMin;
        // midnight is crossable on a full-day grid; a windowed grid has hard edges; a split has none
        const split = selected.segment.n > 1;
        const floorMin = split ? -Infinity : g.dayStartMin > 0 ? g.dayStartMin : -Infinity;
        const ceilMin = split ? Infinity : g.dayEndMin < MINUTES_PER_DAY ? g.dayEndMin : Infinity;
        // ⌥⇧⌘↑/↓ moves the start edge; ⌥⇧↑/↓ the end
        if (
          e.shiftKey &&
          (e.metaKey || e.ctrlKey) &&
          (e.key === "ArrowUp" || e.key === "ArrowDown")
        ) {
          const startMin = Math.min(
            selected.endMin - g.minEventMinutes,
            Math.max(floorMin, selected.startMin + (e.key === "ArrowDown" ? step : -step)),
          );
          applyAnimated(selected.id, { startMin });
          o.current.flashEdges?.([startMin]);
        } else if (e.shiftKey && (e.key === "ArrowUp" || e.key === "ArrowDown")) {
          const endMin = Math.max(
            selected.startMin + g.minEventMinutes,
            Math.min(ceilMin, selected.endMin + (e.key === "ArrowDown" ? step : -step)),
          );
          applyAnimated(selected.id, { endMin });
          o.current.flashEdges?.([endMin]);
        } else if (e.key === "ArrowUp" || e.key === "ArrowDown") {
          const startMin = Math.max(
            floorMin,
            Math.min(
              ceilMin - duration,
              selected.startMin + (e.key === "ArrowDown" ? step : -step),
            ),
          );
          applyAnimated(selected.id, {
            startMin,
            endMin: startMin + duration,
          });
          o.current.flashEdges?.([startMin, startMin + duration]);
        } else {
          const dayIndex = Math.max(
            0,
            Math.min(view.dayCount - 1, selected.dayIndex + (e.key === "ArrowRight" ? 1 : -1)),
          );
          applyAnimated(selected.id, { dayIndex });
          o.current.flashEdges?.([selected.startMin, selected.endMin]);
        }
        reveal(selected.id);
        return;
      }
      if (e.altKey) return;

      e.preventDefault();
      if (!selected) {
        if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
          const dir = e.key === "ArrowLeft" ? -1 : 1;
          if (o.current.navigationKeys === "day" && o.current.stepDay) o.current.stepDay(dir);
          else o.current.stepRange(dir);
          return;
        }
        const first = firstEvent(projected, view, drawn);
        if (first) {
          o.current.select(first.id);
          reveal(first.id);
        }
        return;
      }
      const step = walkEvents(projected, view, selected, e.key as ArrowKey, drawn, focusedMore());
      if (!step) return;
      if ("more" in step) {
        focusMore(step.more);
        return;
      }
      if (e.shiftKey && sel) sel.extendTo(step.event.id);
      else o.current.select(step.event.id);
      reveal(step.event.id);
    };

    // document listener, not root: with nothing focused the event targets <body> and never reaches root
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      scope.dispose();
    };
  }, []);
}

import { useMemo, useSyncExternalStore } from "react";
import type { KloqStore } from "../lib/calendar-store";
import type { CalEvent } from "../lib/calendar-types";
import { parseInstant } from "../lib/calendar-types";
import { type ConflictScope, conflictScopeOf, conflictsFor } from "../lib/conflicts";
import { eventWindow, mayOverlapWindow } from "../lib/event-window";

const NONE: CalEvent[] = [];

// everything but the free text: a conflict never depends on what an event is called
const shape = (e: CalEvent | undefined) =>
  e
    ? JSON.stringify(e, (key, v) =>
        key === "title" || key === "description" || key === "location" || key === "meetingUrl"
          ? undefined
          : v,
      )
    : "";

/** A snapshot reader with its own memory, so the store can be asked on every change for free. */
function conflictSelector(store: KloqStore, id: string, viewer: string | undefined) {
  let seen: readonly CalEvent[] | null = null;
  let own = "";
  let value = NONE;
  let scope: ConflictScope | undefined;
  return () => {
    const events = store.getSnapshot();
    // a resource view on this store narrows a conflict to bookings that share a lane
    const sameResource = conflictScopeOf(store);
    if (events === seen && sameResource === scope) return value;
    const self = events.find((e) => e.id === id);
    const selfShape = shape(self);
    const prev = seen;
    const rescoped = sameResource !== scope;
    seen = events;
    scope = sameResource;
    // the common case while typing: only this event changed, and not in a way that matters
    if (
      !rescoped &&
      prev &&
      prev.length === events.length &&
      selfShape === own &&
      events.every((e, i) => e === prev[i] || e.id === id)
    )
      return value;
    own = selfShape;
    if (!self) return (value = NONE);
    const startMs = parseInstant(self.start);
    const endMs = parseInstant(self.end);
    let nearby = events;
    if (!Number.isNaN(startMs) && !Number.isNaN(endMs)) {
      const w = eventWindow(new Date(startMs), new Date(endMs));
      nearby = events.filter((e) => mayOverlapWindow(e, w));
    }
    const next = conflictsFor(self, nearby, {
      requireSharedAttendee: true,
      viewer,
      sameResource,
    });
    const same = next.length === value.length && next.every((e, i) => e === value[i]);
    if (!same) value = next.length ? next : NONE;
    return value;
  };
}

/**
 * The events that conflict with one event. The scan runs only when something a conflict
 * depends on changed, and the result keeps its identity until its members do — typing a
 * title neither rescans the store nor re-renders through this subscription.
 */
export function useConflicts(store: KloqStore, id: string, viewer: string | undefined): CalEvent[] {
  const getSnapshot = useMemo(() => conflictSelector(store, id, viewer), [store, id, viewer]);
  return useSyncExternalStore(store.subscribe, getSnapshot, () => NONE);
}

import { useState } from "react";

export type Field = "rrule" | "reminders" | "location" | "meetingUrl" | "attendees";

export interface Disclosure {
  id: string;
  fields: Partial<Record<Field, boolean>>;
  draft: string;
  invalid: boolean;
}

const fresh = (id: string): Disclosure => ({ id, fields: {}, draft: "", invalid: false });

/** Which optional rows the panel shows, plus the guest-input draft; keyed by event id so switching events needs no reset. */
export function useDisclosure(
  eventId: string,
  hasValue: Record<Field, boolean>,
  focusField: (f: Field) => void,
) {
  const [disc, setDisc] = useState<Disclosure>(() => fresh(eventId));
  const d = disc.id === eventId ? disc : fresh(eventId);
  const shows = (f: Field) => hasValue[f] || d.fields[f] === true;
  const reveal = (f: Field) => {
    setDisc({ ...d, fields: { ...d.fields, [f]: true } });
    requestAnimationFrame(() => focusField(f));
  };
  return { d, draft: d.draft, invalid: d.invalid, setDisc, shows, reveal };
}

"use client";

/**
 * use-drag-engine — the pointer state machine behind every calendar gesture.
 * One state object, one rAF loop, direct DOM writes; React sees nothing until drop.
 */

import { useEffect, useState } from "react";
import { flushSync } from "react-dom";
import { announceRefused, type RefusedGesture } from "../lib/announce";
import {
  DRAG_THRESHOLD_PX,
  formatDaySpan,
  type PlacedEvent,
  snapMinutes,
} from "../lib/calendar-types";
import {
  allDaySlot,
  allows,
  type ConstraintGesture,
  type DropRequest,
  NO_CONSTRAINTS,
  timedSlot,
} from "../lib/constraints";
import { craftBus, type DragFrame, type DragKind } from "../lib/craft-bus";
import { MINUTES_PER_DAY } from "../lib/date-math";
import {
  ALIGN_PX,
  BASEUI_LONG_PRESS_MOVE_PX,
  EASE,
  EDGE_MAX_V,
  EDGE_ZONE,
  LABEL_FLIP_H,
  LANE_ROW_H,
  RESIZE_PUSH,
  TOUCH_CREATE_MIN,
  TOUCH_THRESHOLD_PX,
} from "../lib/drag-engine/constants";
import {
  animateAll,
  capturePointer,
  LIFT_REST,
  landCommit,
  liftFrom,
  segmentSiblings,
  setTransformAll,
  springHomeFrom,
} from "../lib/drag-engine/dom";
import type {
  CreateDrag,
  Drag,
  DragEngineOpts,
  LaneCreateDrag,
  LaneMoveDrag,
  LaneResizeDrag,
  MoveDrag,
  PressMode,
  ResizeDrag,
  Shared,
} from "../lib/drag-engine/types";
import {
  createJiggle,
  JIGGLE_REST,
  jiggleAtRest,
  jiggleTransform,
  kickJiggle,
  liftOf,
  stepJiggle,
} from "../lib/drag-physics";
import { autoScrollDelta } from "../lib/edge-autoscroll";
import {
  beginLongPress,
  LONG_PRESS_MS,
  longPressMove,
  longPressProgress,
  longPressTick,
  wantsLongPress,
} from "../lib/long-press";
import { ms, prefersReducedMotion, RESIZE_SPRING, SPRING, SPRING_MS } from "../lib/springs";
import { useLatest } from "../lib/use-latest";

export type { CommitResult } from "../lib/drag-engine/types";

function createDragEngine(optsRef: { readonly current: DragEngineOpts }) {
  const s: Shared = {
    drag: null,
    raf: 0,
    pointer: { x: 0, y: 0 },
    lastPointer: { x: 0, y: 0, t: 0 },
    velocity: 0,
    vx: 0,
    vy: 0,
    altHeld: false,
    reduced: false,
    pointerType: "mouse",
    press: null,
    pressMode: null,
    holdSpan: 0,
    scale: 0,
    refused: false,
    refusedSaid: false,
    alignCands: null,
  };

  const vc = () => optsRef.current.view.dayCount;

  const g = () => optsRef.current.settings;

  // -- geometry ------------------------------------------------------------

  const geom = () => {
    const canvas = optsRef.current.canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    const colWidth = rect.width / vc();
    return { canvas, rect, colWidth };
  };

  const laneGeom = () => {
    const lane = optsRef.current.laneRef.current!;
    const rect = lane.getBoundingClientRect();
    const colWidth = rect.width / vc();
    return { lane, rect, colWidth };
  };

  const dayFromX = (x: number, rect: DOMRect, colWidth: number) =>
    Math.max(0, Math.min(vc() - 1, Math.floor((x - rect.left) / colWidth)));

  const spanPx = (startDay: number, endDay: number, colWidth: number) => ({
    left: startDay * colWidth + 2,
    width: (endDay - startDay + 1) * colWidth - 5,
  });

  /** the React-managed calc() styles a chip must be restored to */
  const chipStyles = (startDay: number, endDay: number) => ({
    left: `calc(${(startDay / vc()) * 100}% + 2px)`,
    width: `calc(${((endDay - startDay + 1) / vc()) * 100}% - 5px)`,
  });

  // -- constraints: a refused candidate just isn't written to d.target*; the eased snap holds the block

  const cs = () => optsRef.current.constraints ?? NO_CONSTRAINTS;

  // memoised on the snapped target, so the host's predicate runs on boundary crossings only
  const probe = { key: "", ok: true };

  function askAllowed(
    key: string,
    gesture: ConstraintGesture,
    target: () => { start: Date; end: Date; allDay: boolean },
    origin?: () => { start: Date; end: Date; allDay: boolean },
    event?: PlacedEvent,
  ): boolean {
    if (probe.key === key) return probe.ok;
    probe.key = key;
    probe.ok = allows(cs(), {
      gesture,
      target: target(),
      origin: origin?.(),
      event: event?.source,
    });
    return probe.ok;
  }

  const tSlot = (col: number, startMin: number, endMin: number) =>
    timedSlot(optsRef.current.view, col, startMin, endMin, g().fromDisplay);

  const aSlot = (startCol: number, endCol: number) =>
    allDaySlot(optsRef.current.view, startCol, endCol);

  // the cursor flips every time; the sentence is said once per gesture
  function setRefused(on: boolean, gesture: RefusedGesture, e?: PlacedEvent) {
    if (s.refused === on) return;
    s.refused = on;
    if (!on) {
      document.body.removeAttribute("data-cal-refused");
      return;
    }
    document.body.setAttribute("data-cal-refused", "");
    if (s.refusedSaid) return;
    s.refusedSaid = true;
    optsRef.current.announce?.(announceRefused(gesture, e));
  }

  function refuseRelease(gesture: RefusedGesture, e?: PlacedEvent) {
    optsRef.current.announce?.(announceRefused(gesture, e), "assertive");
  }

  // the release backstop: runs off the memo so a stale probe can never answer it
  function releaseRefused(req: DropRequest): boolean {
    return cs().active && !allows(cs(), req);
  }

  const snapStep = () => (s.altHeld ? g().snapFineMinutes : g().snapMinutes);

  const isTouch = () => wantsLongPress(s.pointerType);

  const threshold = () => (isTouch() ? TOUCH_THRESHOLD_PX : DRAG_THRESHOLD_PX);

  // "create" cancels at the engine's 4px (a scroll); "yield" at base-ui's 10px so both let go together
  function beginPress(e: React.PointerEvent, mode: PressMode) {
    s.pointerType = e.pointerType || "mouse";
    s.holdSpan = 0;
    s.scale = g().hourHeight;
    if (!isTouch()) {
      s.press = null;
      s.pressMode = null;
      return;
    }
    s.pressMode = mode;
    s.press = beginLongPress(e.clientX, e.clientY, performance.now(), {
      delayMs: LONG_PRESS_MS,
      movePx: mode === "yield" ? BASEUI_LONG_PRESS_MOVE_PX : DRAG_THRESHOLD_PX,
    });
  }

  // -- shared frame helpers ------------------------------------------------

  function trackVelocity(x: number, y: number) {
    const now = performance.now();
    const lp = s.lastPointer;
    if (lp.t > 0) {
      const dt = Math.max(1, now - lp.t);
      const dist = Math.hypot(x - lp.x, y - lp.y);
      const inst = (dist / dt) * 1000;
      s.velocity = s.velocity * 0.8 + inst * 0.2;
      s.vx = s.vx * 0.8 + ((x - lp.x) / dt) * 1000 * 0.2;
      s.vy = s.vy * 0.8 + ((y - lp.y) / dt) * 1000 * 0.2;
    }
    s.lastPointer = { x, y, t: now };
    s.pointer = { x, y };
  }

  function publish(type: "drag:start" | "drag:frame", frame: DragFrame) {
    craftBus.emit({ type, frame });
  }

  function endPublish(frame: DragFrame, cancelled: boolean) {
    craftBus.emit({ type: "drag:end", frame, cancelled });
  }

  function autoScroll() {
    const scroll = optsRef.current.scrollRef.current;
    if (!scroll) return;
    const r = scroll.getBoundingClientRect();
    const dv = autoScrollDelta(r, s.pointer, "y", EDGE_ZONE, EDGE_MAX_V);
    if (dv !== 0) scroll.scrollTop += dv;
  }

  // -- create flow ---------------------------------------------------------

  function createFrame(d: CreateDrag): DragFrame {
    if (d.mode === "allday") {
      const lo = Math.min(d.dayIndex, d.curDay);
      const hi = Math.max(d.dayIndex, d.curDay);
      return {
        kind: "create" as DragKind,
        id: "draft",
        velocity: s.velocity,
        rect: { x: d.vLeft, y: 0, width: d.vWidth, height: LANE_ROW_H },
        startMin: 0,
        endMin: 0,
        dayIndex: lo,
        endDayIndex: hi,
        pointer: { ...s.pointer },
      };
    }
    const { colWidth } = geom();
    const startMin = g().pxToMinutes(d.vTop);
    return {
      kind: "create" as DragKind,
      id: "draft",
      velocity: s.velocity,
      rect: { x: d.dayIndex * colWidth, y: d.vTop, width: colWidth, height: d.vHeight },
      startMin: Math.round(startMin),
      endMin: Math.round(startMin + g().pxToDuration(d.vHeight)),
      dayIndex: d.dayIndex,
      pointer: { ...s.pointer },
    };
  }

  function createTargets(d: CreateDrag) {
    const { rect } = geom();
    const rawY = s.pointer.y - rect.top;
    const step = snapStep();
    const anchorMin = g().clampMinutes(snapMinutes(g().pxToMinutes(d.anchorRawY), step));
    // dayDelta carries the growing edge across midnight: 5am in tomorrow's column is minute 1740
    const curMin =
      g().clampMinutes(snapMinutes(g().pxToMinutes(rawY), step)) + d.dayDelta * MINUTES_PER_DAY;
    let startMin = Math.min(anchorMin, curMin);
    let endMin = Math.max(anchorMin, curMin);
    const floor = Math.max(g().minEventMinutes, s.holdSpan);
    if (endMin - startMin < floor) {
      // minimum block, anchored in the drag direction
      if (curMin < anchorMin) startMin = endMin - floor;
      else endMin = startMin + floor;
    }
    const inverted = curMin < anchorMin;
    if (d.dayDelta === 0) {
      startMin = g().clampMinutes(startMin);
      endMin = g().clampMinutes(endMin);
    }

    // whole-body rule: the growing edge stops at the first refused minute
    if (cs().active) {
      const ok = askAllowed(`create|${d.dayIndex}|${startMin}|${endMin}`, "create", () =>
        tSlot(d.dayIndex, startMin, endMin),
      );
      if (ok) {
        d.okStart = startMin;
        d.okEnd = endMin;
        d.everOk = true;
        setRefused(false, "create");
      } else {
        setRefused(true, "create");
        if (d.everOk) return { startMin: d.okStart, endMin: d.okEnd, inverted };
      }
    }
    return { startMin, endMin, inverted };
  }

  function laneCreateAllowed(
    d: CreateDrag | LaneCreateDrag,
    anchor: number,
    cand: number,
  ): boolean {
    if (!cs().active) return true;
    const lo = Math.min(anchor, cand);
    const hi = Math.max(anchor, cand);
    const ok = askAllowed(`lane-create|${lo}|${hi}`, "create", () => aSlot(lo, hi));
    if (ok) d.everOk = true;
    setRefused(!ok, "create");
    return ok;
  }

  function guardLaneCreate(d: CreateDrag | LaneCreateDrag, anchor: number, cand: number): number {
    if (laneCreateAllowed(d, anchor, cand)) return cand;
    return d.everOk ? d.curDay : cand;
  }

  function renderDraft(d: CreateDrag) {
    const draft = optsRef.current.draftRef.current;
    if (!draft) return;

    // into the lane promotes to all-day; crossing columns inside the grid means "on into that day"
    const { rect: canvasRect, colWidth } = geom();
    const overDay = dayFromX(s.pointer.x, canvasRect, colWidth);
    d.curDay = d.mode === "allday" ? guardLaneCreate(d, d.dayIndex, overDay) : overDay;
    const lane = optsRef.current.laneRef.current;
    const inLane = lane ? s.pointer.y < lane.getBoundingClientRect().bottom : false;
    if (d.mode === "timed" && inLane) {
      if (laneCreateAllowed(d, d.dayIndex, d.curDay)) {
        dropCreateOverflow(d, draft);
        d.dayDelta = 0;
        promoteDraft(d);
      }
    } else if (d.mode === "allday" && !inLane) demoteDraft(d);

    if (d.mode === "allday") {
      renderLaneDraft(d);
      return;
    }

    // midnight crossing: full-day grids only, no active constraints, one column at a time
    const crossable = g().dayStartMin === 0 && g().dayEndMin === MINUTES_PER_DAY && !cs().active;
    d.dayDelta = crossable ? Math.max(-1, Math.min(1, d.curDay - d.dayIndex)) : 0;

    const t = createTargets(d);
    const targetTop = g().minutesToPx(t.startMin);
    const targetH = g().durationToPx(t.endMin - t.startMin);
    if (s.reduced) {
      d.vTop = targetTop;
      d.vHeight = targetH;
    } else {
      d.vTop += (targetTop - d.vTop) * EASE;
      d.vHeight += (targetH - d.vHeight) * EASE;
      if (Math.abs(targetTop - d.vTop) < 0.5) d.vTop = targetTop;
      if (Math.abs(targetH - d.vHeight) < 0.5) d.vHeight = targetH;
    }
    draft.style.left = `${d.dayIndex * (100 / vc())}%`;
    draft.style.width = `calc(${100 / vc()}% - 5px)`;
    // past midnight the draft pins to its day's edge; the remainder is a ghost in the next column
    const over =
      t.endMin > MINUTES_PER_DAY ? t.endMin - MINUTES_PER_DAY : t.startMin < 0 ? -t.startMin : 0;
    if (over > 0) {
      const topMin = Math.max(0, t.startMin);
      const botMin = Math.min(MINUTES_PER_DAY, t.endMin);
      const topPx = g().minutesToPx(topMin);
      draft.style.translate = `0 ${topPx}px`;
      draft.style.height = `${Math.max(6, g().minutesToPx(botMin) - topPx)}px`;
      setCutCorners(draft, t.endMin > MINUTES_PER_DAY ? "end" : "start", true);
      if (!d.overflow) {
        const c = draft.cloneNode(true) as HTMLElement;
        c.setAttribute("aria-hidden", "true");
        c.style.pointerEvents = "none";
        c.querySelector<HTMLElement>("[data-slot=draft-label]")?.remove();
        draft.parentElement?.appendChild(c);
        d.overflow = c;
      }
      const c = d.overflow;
      const dir = t.endMin > MINUTES_PER_DAY ? 1 : -1;
      c.style.left = `${(d.dayIndex + dir) * (100 / vc())}%`;
      c.style.width = `calc(${100 / vc()}% - 5px)`;
      c.style.translate = `0 ${dir === 1 ? 0 : g().minutesToPx(MINUTES_PER_DAY - over)}px`;
      c.style.height = `${Math.max(6, g().durationToPx(over))}px`;
      c.removeAttribute("hidden");
      setCutCorners(c, dir === 1 ? "start" : "end", true);
    } else {
      dropCreateOverflow(d, draft);
      // `translate`, not `transform`: WAAPI morphs animate `transform` and the two compose
      draft.style.translate = `0 ${d.vTop}px`;
      draft.style.height = `${Math.max(6, d.vHeight)}px`;
    }
    showGuides([t.startMin, t.endMin]);
    const label = draft.querySelector<HTMLElement>("[data-slot=draft-label]");
    if (label) {
      label.textContent = g().formatRange(t.startMin, t.endMin);
      const outside = targetH < LABEL_FLIP_H ? (t.inverted ? "top" : "bottom") : "";
      if (outside) draft.setAttribute("data-label-outside", outside);
      else draft.removeAttribute("data-label-outside");
    }
  }

  function dropCreateOverflow(d: CreateDrag, draft: HTMLElement | null) {
    if (d.overflow) {
      d.overflow.remove();
      d.overflow = null;
    }
    if (draft) {
      setCutCorners(draft, "start", false);
      setCutCorners(draft, "end", false);
    }
  }

  function renderLaneDraft(d: CreateDrag | LaneCreateDrag) {
    const laneDraft = optsRef.current.laneDraftRef.current;
    if (!laneDraft) return;
    const { colWidth } = laneGeom();
    const anchor = d.kind === "create" ? d.dayIndex : d.anchorDay;
    const lo = Math.min(anchor, d.curDay);
    const hi = Math.max(anchor, d.curDay);
    const t = spanPx(lo, hi, colWidth);
    if (s.reduced) {
      d.vLeft = t.left;
      d.vWidth = t.width;
    } else {
      d.vLeft += (t.left - d.vLeft) * EASE;
      d.vWidth += (t.width - d.vWidth) * EASE;
      if (Math.abs(t.left - d.vLeft) < 0.5) d.vLeft = t.left;
      if (Math.abs(t.width - d.vWidth) < 0.5) d.vWidth = t.width;
    }
    laneDraft.style.left = `${d.vLeft}px`;
    laneDraft.style.width = `${d.vWidth}px`;
    const label = laneDraft.querySelector<HTMLElement>("[data-slot=draft-label]");
    if (label) label.textContent = formatDaySpan(lo, hi, optsRef.current.view.namesShort);
  }

  // grid draft → lane chip: FLIP from the grid draft's rect while the grid draft hides
  function promoteDraft(d: CreateDrag) {
    const draft = optsRef.current.draftRef.current;
    const laneDraft = optsRef.current.laneDraftRef.current;
    if (!draft || !laneDraft) return;
    const fromRect = draft.getBoundingClientRect();
    d.mode = "allday";
    draft.setAttribute("hidden", "");

    const { rect: laneRect, colWidth } = laneGeom();
    const lo = Math.min(d.dayIndex, d.curDay);
    const hi = Math.max(d.dayIndex, d.curDay);
    const t = spanPx(lo, hi, colWidth);
    d.vLeft = t.left;
    d.vWidth = t.width;
    laneDraft.style.left = `${t.left}px`;
    laneDraft.style.width = `${t.width}px`;
    laneDraft.removeAttribute("hidden");

    if (!s.reduced) {
      // the draft chip sits at top: 3px (see [data-cal-lane-draft] css)
      const toRect = {
        x: laneRect.left + t.left,
        y: laneRect.top + 3,
        w: t.width,
        h: LANE_ROW_H,
      };
      laneDraft.style.transformOrigin = "top left";
      laneDraft.animate(
        [
          {
            transform: `translate(${fromRect.left - toRect.x}px, ${fromRect.top - toRect.y}px) scale(${fromRect.width / toRect.w}, ${fromRect.height / toRect.h})`,
          },
          { transform: "none" },
        ],
        { duration: ms(200), easing: "cubic-bezier(0.2, 0.8, 0.2, 1)" },
      );
    }
  }

  function demoteDraft(d: CreateDrag) {
    const draft = optsRef.current.draftRef.current;
    const laneDraft = optsRef.current.laneDraftRef.current;
    if (!draft || !laneDraft) return;
    const fromRect = laneDraft.getBoundingClientRect();
    d.mode = "timed";
    laneDraft.setAttribute("hidden", "");

    // seed at the snapped geometry so the morph lands where per-frame tracking resumes
    const t = createTargets(d);
    d.vTop = g().minutesToPx(t.startMin);
    d.vHeight = g().durationToPx(t.endMin - t.startMin);
    draft.style.left = `${d.dayIndex * (100 / vc())}%`;
    draft.style.width = `calc(${100 / vc()}% - 5px)`;
    draft.style.translate = `0 ${d.vTop}px`;
    draft.style.height = `${Math.max(6, d.vHeight)}px`;
    draft.removeAttribute("hidden");

    if (!s.reduced) {
      const toRect = draft.getBoundingClientRect();
      draft.style.transformOrigin = "top left";
      draft.animate(
        [
          {
            transform: `translate(${fromRect.left - toRect.left}px, ${fromRect.top - toRect.top}px) scale(${fromRect.width / Math.max(1, toRect.width)}, ${fromRect.height / Math.max(1, toRect.height)})`,
          },
          { transform: "none" },
        ],
        { duration: ms(200), easing: "cubic-bezier(0.2, 0.8, 0.2, 1)" },
      );
    }
  }

  // -- long-press affordance: the slot that will be created, outlined and filling in over the hold

  const pressElRef = { current: null as HTMLElement | null };
  const cancelRef = { current: (() => {}) as () => void };

  function pressEl(host: HTMLElement): HTMLElement {
    let el = pressElRef.current;
    if (!el) {
      el = document.createElement("div");
      el.className = "cal-press";
      el.setAttribute("aria-hidden", "true");
      pressElRef.current = el;
    }
    if (el.parentElement !== host) host.appendChild(el);
    return el;
  }

  function hidePress() {
    const el = pressElRef.current;
    if (el) el.setAttribute("hidden", "");
  }

  function renderPress(d: Drag) {
    const p = s.press;
    if (!p || p.phase !== "pending") return;
    const progress = longPressProgress(p, performance.now());

    let el: HTMLElement | null = null;
    if (d.kind === "create") {
      const canvas = optsRef.current.canvasRef.current;
      if (!canvas) return;
      const { colWidth } = geom();
      const step = snapStep();
      const startMin = g().clampMinutes(snapMinutes(g().pxToMinutes(d.anchorRawY), step));
      const span = Math.max(g().minEventMinutes, TOUCH_CREATE_MIN);
      // never outline a slot that will refuse the create; leaves everOk and refusal state untouched
      if (
        cs().active &&
        !askAllowed(`press|${d.dayIndex}|${startMin}|${span}`, "create", () =>
          tSlot(d.dayIndex, startMin, startMin + span),
        )
      ) {
        hidePress();
        return;
      }
      el = pressEl(canvas);
      el.style.left = `${d.dayIndex * colWidth + 1}px`;
      el.style.width = `${colWidth - 5}px`;
      el.style.top = `${g().minutesToPx(startMin)}px`;
      el.style.height = `${g().durationToPx(span)}px`;
    } else if (d.kind === "lane-create") {
      const lane = optsRef.current.laneRef.current;
      if (!lane) return;
      if (
        cs().active &&
        !askAllowed(`press-lane|${d.anchorDay}`, "create", () => aSlot(d.anchorDay, d.anchorDay))
      ) {
        hidePress();
        return;
      }
      el = pressEl(lane);
      const { colWidth } = laneGeom();
      const t = spanPx(d.anchorDay, d.anchorDay, colWidth);
      el.style.left = `${t.left}px`;
      el.style.width = `${t.width}px`;
      el.style.top = "3px";
      el.style.height = `${LANE_ROW_H}px`;
    } else {
      return;
    }

    el.removeAttribute("hidden");
    if (s.reduced) {
      el.style.opacity = progress < 0.35 ? "0" : "1";
      el.style.transform = "none";
    } else {
      el.style.opacity = String(progress);
      el.style.transform = `scale(${0.94 + 0.06 * progress})`;
    }
  }

  function armPress(d: Drag) {
    hidePress();
    if (s.pressMode === "yield") {
      // the context menu owns it; forgetting the drag stops pointerup firing openEditor behind the menu
      cleanup(d);
      return;
    }
    s.holdSpan = TOUCH_CREATE_MIN;
    engage(d);
    if (!s.reduced) {
      try {
        navigator.vibrate?.(8);
      } catch {
        /* unsupported */
      }
    }
  }

  // a scroll must leave nothing behind: no draft, no drag:end, no onCanvasClick
  function abandonPress(d: Drag) {
    hidePress();
    cleanup(d);
    optsRef.current.draftRef.current?.setAttribute("hidden", "");
    optsRef.current.laneDraftRef.current?.setAttribute("hidden", "");
  }

  // hourHeight changed mid-drag (⇧⌘. is live): rebase the values captured at pointerdown
  function rebaseScale(d: Drag, ratio: number) {
    if (d.kind === "create") {
      d.anchorRawY *= ratio;
      d.vTop *= ratio;
      d.vHeight *= ratio;
    } else if (d.kind === "move") {
      d.grabOffsetY *= ratio;
      d.originTop = g().minutesToPx(d.event.startMin);
      d.vDy = g().minutesToPx(d.targetStartMin) - d.originTop;
    } else if (d.kind === "resize") {
      d.vTop = g().minutesToPx(d.targetStartMin);
      d.vHeight = g().durationToPx(d.targetEndMin - d.targetStartMin);
    }
  }

  // -- edge markers: engine-owned pooled carets in the gutter, written in the rAF loop

  const guideEls: HTMLElement[] = [];

  function guideEl(i: number): HTMLElement | null {
    const canvas = optsRef.current.canvasRef.current;
    if (!canvas) return null;
    while (guideEls.length <= i) {
      const el = document.createElement("div");
      el.className = "cal-align-guide";
      el.setAttribute("hidden", "");
      el.setAttribute("aria-hidden", "true");
      canvas.appendChild(el);
      guideEls.push(el);
    }
    // survive canvas remounts (view switches)
    if (guideEls[i].parentElement !== canvas) canvas.appendChild(guideEls[i]);
    return guideEls[i];
  }

  function showGuides(mins: number[], candidates: readonly number[] = []) {
    clearTimeout(flashTimer.current);
    const shown = mins.filter((m) => m >= g().dayStartMin && m <= g().dayEndMin);
    for (let i = 0; i < 2; i++) {
      const el = guideEl(i);
      if (!el) continue;
      if (i < shown.length) {
        const m = shown[i];
        el.style.top = `${g().minutesToPx(m)}px`;
        el.setAttribute("data-time", g().formatMinutes(m));
        if (candidates.includes(m)) el.setAttribute("data-aligned", "");
        else el.removeAttribute("data-aligned");
        el.removeAttribute("hidden");
      } else {
        el.setAttribute("hidden", "");
      }
    }
  }

  const flashTimer = { current: undefined as ReturnType<typeof setTimeout> | undefined };
  /** Keyboard nudges have no release: show the edge markers, then let go. */
  function flashEdges(mins: number[], holdMs = 900) {
    if (s.drag) return;
    showGuides(mins);
    flashTimer.current = setTimeout(() => {
      if (!s.drag) showGuides([]);
    }, holdMs);
  }

  function alignCandidates(excludeId: string): number[] {
    if (s.alignCands) return s.alignCands;
    const out: number[] = [];
    for (const e of optsRef.current.getTimedEvents()) {
      if (e.id === excludeId) continue;
      out.push(e.startMin, e.endMin);
    }
    s.alignCands = out;
    return out;
  }

  function nearestAligned(min: number, candidates: number[]): number | null {
    const win = g().pxToDuration(ALIGN_PX);
    let best: number | null = null;
    let bestD = Infinity;
    for (const c of candidates) {
      const dist = Math.abs(c - min);
      if (dist <= win && dist < bestD) {
        best = c;
        bestD = dist;
      }
    }
    return best;
  }

  // -- move flow -----------------------------------------------------------

  function moveFrame(d: MoveDrag): DragFrame {
    const { colWidth } = geom();
    const duration = d.event.endMin - d.event.startMin;
    return {
      kind: "move",
      id: d.event.id,
      velocity: s.velocity,
      rect: {
        x: d.originLeft + d.vDx,
        y: d.originTop + d.vDy,
        width: colWidth,
        height: g().durationToPx(duration),
      },
      startMin: d.targetStartMin,
      endMin: d.targetStartMin + duration,
      dayIndex: d.targetDayIndex,
      pointer: { ...s.pointer },
    };
  }

  function moveTargets(d: MoveDrag) {
    const { rect, colWidth } = geom();
    const duration = d.event.endMin - d.event.startMin;
    const pointerY = s.pointer.y - rect.top;
    const pointerX = s.pointer.x - rect.left;
    const rawTop = pointerY - d.grabOffsetY;
    // ⌥ on a move means duplicate, not fine snap
    const rawStart = g().pxToMinutes(rawTop);
    let startMin = Math.max(
      g().dayStartMin,
      Math.min(g().dayEndMin - duration, snapMinutes(rawStart, g().snapMinutes)),
    );
    // either edge landing near another event's edge wins over the grid snap
    const candidates = alignCandidates(d.event.id);
    const aStart = nearestAligned(rawStart, candidates);
    const aEnd = nearestAligned(rawStart + duration, candidates);
    if (aStart !== null || aEnd !== null) {
      const dStart = aStart !== null ? Math.abs(aStart - rawStart) : Infinity;
      const dEnd = aEnd !== null ? Math.abs(aEnd - (rawStart + duration)) : Infinity;
      const aligned = dStart <= dEnd ? aStart! : aEnd! - duration;
      startMin = Math.max(g().dayStartMin, Math.min(g().dayEndMin - duration, aligned));
    }
    let dayIndex = Math.max(0, Math.min(vc() - 1, Math.floor(pointerX / colWidth)));

    if (cs().active) {
      const gesture: ConstraintGesture = d.dup ? "duplicate" : "move";
      const ok = askAllowed(
        `${gesture}|${dayIndex}|${startMin}|${duration}|${d.event.id}`,
        gesture,
        () => tSlot(dayIndex, startMin, startMin + duration),
        () => tSlot(d.event.dayIndex, d.event.startMin, d.event.endMin),
        d.event,
      );
      if (ok) {
        setRefused(false, d.dup ? "duplicate" : "move", d.event);
      } else {
        setRefused(true, d.dup ? "duplicate" : "move", d.event);
        startMin = d.targetStartMin;
        dayIndex = d.targetDayIndex;
      }
    }

    showGuides([startMin, startMin + duration], candidates);
    d.targetStartMin = startMin;
    d.targetDayIndex = dayIndex;
    return {
      dx: dayIndex * colWidth - d.originLeft,
      dy: g().minutesToPx(startMin) - d.originTop,
    };
  }

  function stepLift(d: MoveDrag | LaneMoveDrag, tilt: boolean): string {
    const now = performance.now();
    const dt = d.jiggleT ? (now - d.jiggleT) / 1000 : 1 / 60;
    d.jiggleT = now;
    stepJiggle(d.jiggle, { vx: s.vx, vy: s.vy, dt, tilt });
    const lift = liftOf(d.jiggle).toFixed(3);
    d.node.style.setProperty("--kloq-lift", lift);
    if (d.kind === "move") for (const sib of d.siblings) sib.style.setProperty("--kloq-lift", lift);
    return jiggleTransform(d.jiggle);
  }

  function fadeGhostIn(ghost: HTMLElement) {
    if (s.reduced) return;
    ghost.animate([{ opacity: 0 }, { opacity: 0.4 }], { duration: ms(160), easing: "ease-out" });
  }

  function renderMove(d: MoveDrag) {
    const wasDay = d.targetDayIndex;
    const wasMin = d.targetStartMin;
    const t = moveTargets(d);
    // the detent tick on a snap change
    if (!s.reduced && (d.targetDayIndex !== wasDay || d.targetStartMin !== wasMin))
      kickJiggle(d.jiggle);
    if (s.reduced) {
      d.vDx = t.dx;
      d.vDy = t.dy;
    } else {
      d.vDx += (t.dx - d.vDx) * EASE;
      d.vDy += (t.dy - d.vDy) * EASE;
      if (Math.abs(t.dx - d.vDx) < 0.5) d.vDx = t.dx;
      if (Math.abs(t.dy - d.vDy) < 0.5) d.vDy = t.dy;
    }
    let t3 = `translate(${d.vDx}px, ${d.vDy}px)`;
    if (!s.reduced) t3 += stepLift(d, true);
    d.node.style.transform = t3;
    for (const sib of d.siblings) sib.style.transform = t3;
    if (d.timeEl) {
      const duration = d.event.endMin - d.event.startMin;
      d.timeEl.textContent = g().formatRange(d.targetStartMin, d.targetStartMin + duration);
    }
  }

  // -- resize flow ---------------------------------------------------------

  function resizeFrame(d: ResizeDrag): DragFrame {
    const { colWidth } = geom();
    return {
      kind: (d.edge === "start" ? "resize-start" : "resize-end") as DragKind,
      id: d.event.id,
      velocity: s.velocity,
      rect: {
        x: d.event.dayIndex * colWidth,
        y: d.vTop,
        width: colWidth,
        height: d.vHeight,
      },
      startMin: d.targetStartMin,
      endMin: d.targetEndMin,
      dayIndex: d.event.dayIndex,
      pointer: { ...s.pointer },
    };
  }

  function resizeTargets(d: ResizeDrag) {
    const { rect, colWidth } = geom();
    const pointerY = s.pointer.y - rect.top;
    const step = snapStep();
    const raw = g().pxToMinutes(pointerY);
    // midnight crossing: full-day grids only, no active constraints, one column at a time
    const crossable = g().dayStartMin === 0 && g().dayEndMin === MINUTES_PER_DAY && !cs().active;
    const rawDelta = crossable ? dayFromX(s.pointer.x, rect, colWidth) - d.event.dayIndex : 0;
    const dayDelta =
      d.edge === "end" ? Math.max(0, Math.min(1, rawDelta)) : Math.min(0, Math.max(-1, rawDelta));
    let min = dayDelta * MINUTES_PER_DAY + g().clampMinutes(snapMinutes(raw, step));
    const aligned = dayDelta === 0 ? nearestAligned(raw, alignCandidates(d.event.id)) : null;
    if (aligned !== null) min = g().clampMinutes(aligned);
    let nextStart: number;
    let nextEnd: number;
    if (d.edge === "start") {
      nextStart = Math.min(min, d.event.endMin - g().minEventMinutes);
      nextEnd = d.event.endMin;
    } else {
      nextStart = d.event.startMin;
      nextEnd = Math.max(min, d.event.startMin + g().minEventMinutes);
    }

    // judged on the swept delta (`newlyOccupied` in lib/constraints): shrinking is always allowed
    if (cs().active) {
      const ok = askAllowed(
        `resize|${d.event.id}|${nextStart}|${nextEnd}`,
        "resize",
        () => tSlot(d.event.dayIndex, nextStart, nextEnd),
        () => tSlot(d.event.dayIndex, d.event.startMin, d.event.endMin),
        d.event,
      );
      if (ok) {
        setRefused(false, "resize", d.event);
      } else {
        setRefused(true, "resize", d.event);
        nextStart = d.targetStartMin;
        nextEnd = d.targetEndMin;
      }
    }
    d.targetStartMin = nextStart;
    d.targetEndMin = nextEnd;

    showGuides(
      [d.edge === "start" ? d.targetStartMin : d.targetEndMin],
      alignCandidates(d.event.id),
    );
    return {
      top: g().minutesToPx(d.targetStartMin),
      height: g().durationToPx(d.targetEndMin - d.targetStartMin),
    };
  }

  function setCutCorners(el: HTMLElement, edge: "start" | "end", cut: boolean) {
    const v = cut ? "0px" : "";
    if (edge === "end") {
      el.style.borderBottomLeftRadius = v;
      el.style.borderBottomRightRadius = v;
    } else {
      el.style.borderTopLeftRadius = v;
      el.style.borderTopRightRadius = v;
    }
  }

  function dropResizeOverflow(d: ResizeDrag) {
    if (!d.overflow) return;
    d.overflow.remove();
    d.overflow = null;
    setCutCorners(d.node, d.edge, false);
  }

  function renderResize(d: ResizeDrag) {
    const t = resizeTargets(d);
    if (s.reduced) {
      d.vTop = t.top;
      d.vHeight = t.height;
    } else {
      d.vTop += (t.top - d.vTop) * EASE;
      d.vHeight += (t.height - d.vHeight) * EASE;
      if (Math.abs(t.top - d.vTop) < 0.5) d.vTop = t.top;
      if (Math.abs(t.height - d.vHeight) < 0.5) d.vHeight = t.height;
    }
    // past midnight the block pins to its day's edge; the ghost is driven from the snapped target
    const over =
      d.edge === "end"
        ? Math.max(0, d.targetEndMin - MINUTES_PER_DAY)
        : Math.max(0, -d.targetStartMin);
    if (over > 0) {
      const top = d.edge === "end" ? g().minutesToPx(Math.max(0, d.targetStartMin)) : 0;
      const bottom =
        d.edge === "end"
          ? g().minutesToPx(MINUTES_PER_DAY)
          : g().minutesToPx(Math.min(MINUTES_PER_DAY, d.targetEndMin));
      d.node.style.top = `${top}px`;
      d.node.style.height = `${Math.max(bottom - top - 2, 14)}px`;
      setCutCorners(d.node, d.edge, true);
      if (!d.overflow) {
        const c = d.node.cloneNode(true) as HTMLElement;
        c.removeAttribute("data-cal-event");
        c.setAttribute("aria-hidden", "true");
        c.style.pointerEvents = "none";
        d.node.parentElement?.appendChild(c);
        d.overflow = c;
      }
      const { colWidth } = geom();
      const c = d.overflow;
      const dir = d.edge === "end" ? 1 : -1;
      c.style.left = `${d.node.offsetLeft + dir * colWidth}px`;
      c.style.width = `${d.node.offsetWidth}px`;
      c.style.top = `${d.edge === "end" ? 0 : g().minutesToPx(MINUTES_PER_DAY - over)}px`;
      c.style.height = `${Math.max(g().durationToPx(over) - 2, 4)}px`;
      setCutCorners(c, d.edge === "end" ? "start" : "end", true);
      const ghostTime = c.querySelector<HTMLElement>("[data-slot=event-time]");
      if (ghostTime) ghostTime.textContent = g().formatRange(d.targetStartMin, d.targetEndMin);
    } else {
      dropResizeOverflow(d);
      d.node.style.top = `${d.vTop}px`;
      d.node.style.height = `${Math.max(d.vHeight - 2, 14)}px`;
    }
    if (d.timeEl) d.timeEl.textContent = g().formatRange(d.targetStartMin, d.targetEndMin);
  }

  // -- lane flows (all coords in lane px) ----------------------------------

  function laneCreateFrame(d: LaneCreateDrag): DragFrame {
    const lo = Math.min(d.anchorDay, d.curDay);
    const hi = Math.max(d.anchorDay, d.curDay);
    return {
      kind: "create",
      id: "draft",
      velocity: s.velocity,
      rect: { x: d.vLeft, y: 0, width: d.vWidth, height: LANE_ROW_H },
      startMin: 0,
      endMin: 0,
      dayIndex: lo,
      endDayIndex: hi,
      pointer: { ...s.pointer },
    };
  }

  function laneMoveFrame(d: LaneMoveDrag): DragFrame {
    const { colWidth } = laneGeom();
    const span = d.event.endDayIndex - d.event.dayIndex;
    const t = spanPx(d.targetStartDay, d.targetStartDay + span, colWidth);
    return {
      kind: "move",
      id: d.event.id,
      velocity: s.velocity,
      rect: { x: t.left, y: 0, width: t.width, height: LANE_ROW_H },
      startMin: 0,
      endMin: 0,
      dayIndex: d.targetStartDay,
      endDayIndex: d.targetStartDay + span,
      pointer: { ...s.pointer },
    };
  }

  function laneResizeFrame(d: LaneResizeDrag): DragFrame {
    return {
      kind: d.edge === "left" ? "resize-start" : "resize-end",
      id: d.event.id,
      velocity: s.velocity,
      rect: { x: d.vLeft, y: 0, width: d.vWidth, height: LANE_ROW_H },
      startMin: 0,
      endMin: 0,
      dayIndex: d.targetStartDay,
      endDayIndex: d.targetEndDay,
      pointer: { ...s.pointer },
    };
  }

  function renderLaneMove(d: LaneMoveDrag) {
    const { rect, colWidth } = laneGeom();
    const span = d.event.endDayIndex - d.event.dayIndex;
    const pointerDay = dayFromX(s.pointer.x, rect, colWidth);
    let startDay = Math.max(0, Math.min(vc() - 1 - span, pointerDay - d.grabOffsetDays));
    if (cs().active) {
      const ok = askAllowed(
        `lane-move|${d.event.id}|${startDay}`,
        "lane-move",
        () => aSlot(startDay, startDay + span),
        () => aSlot(d.event.dayIndex, d.event.endDayIndex),
        d.event,
      );
      if (ok) {
        setRefused(false, "span", d.event);
      } else {
        setRefused(true, "span", d.event);
        startDay = d.targetStartDay;
      }
    }
    d.targetStartDay = startDay;
    const dx = (d.targetStartDay - d.event.dayIndex) * colWidth;
    if (s.reduced) d.vDx = dx;
    else {
      d.vDx += (dx - d.vDx) * EASE;
      if (Math.abs(dx - d.vDx) < 0.5) d.vDx = dx;
    }
    let t3 = `translateX(${d.vDx}px)`;
    if (!s.reduced) t3 += stepLift(d, false);
    d.node.style.transform = t3;
  }

  function renderLaneResize(d: LaneResizeDrag) {
    const { rect, colWidth } = laneGeom();
    const pointerDay = dayFromX(s.pointer.x, rect, colWidth);
    let nextStart: number;
    let nextEnd: number;
    if (d.edge === "left") {
      nextStart = Math.min(pointerDay, d.event.endDayIndex);
      nextEnd = d.event.endDayIndex;
    } else {
      nextStart = d.event.dayIndex;
      nextEnd = Math.max(pointerDay, d.event.dayIndex);
    }
    if (cs().active) {
      const ok = askAllowed(
        `lane-resize|${d.event.id}|${nextStart}|${nextEnd}`,
        "lane-resize",
        () => aSlot(nextStart, nextEnd),
        () => aSlot(d.event.dayIndex, d.event.endDayIndex),
        d.event,
      );
      if (ok) {
        setRefused(false, "span", d.event);
      } else {
        setRefused(true, "span", d.event);
        nextStart = d.targetStartDay;
        nextEnd = d.targetEndDay;
      }
    }
    d.targetStartDay = nextStart;
    d.targetEndDay = nextEnd;
    const t = spanPx(d.targetStartDay, d.targetEndDay, colWidth);
    if (s.reduced) {
      d.vLeft = t.left;
      d.vWidth = t.width;
    } else {
      d.vLeft += (t.left - d.vLeft) * EASE;
      d.vWidth += (t.width - d.vWidth) * EASE;
      if (Math.abs(t.left - d.vLeft) < 0.5) d.vLeft = t.left;
      if (Math.abs(t.width - d.vWidth) < 0.5) d.vWidth = t.width;
    }
    d.node.style.left = `${d.vLeft}px`;
    d.node.style.width = `${d.vWidth}px`;
  }

  // -- rAF loop ------------------------------------------------------------

  function tick() {
    const d = s.drag;
    if (!d) return;

    // a live zoom is detected here, not in an effect: the loop runs before the next visible frame
    const scale = g().hourHeight;
    if (s.scale !== 0 && scale !== s.scale) {
      rebaseScale(d, scale / s.scale);
      s.scale = scale;
    }

    // the long-press clock rides the rAF loop so the affordance and the arming read the same instant
    if (s.press) {
      const next = longPressTick(s.press, performance.now());
      if (next !== s.press) {
        s.press = next;
        if (next.phase === "armed") {
          armPress(d);
          if (!s.drag) return;
        }
      } else {
        renderPress(d);
      }
    }

    // lane drags (and promoted creates) never scroll the grid
    const inLane =
      d.kind === "lane-create" ||
      d.kind === "lane-move" ||
      d.kind === "lane-resize" ||
      (d.kind === "create" && d.mode === "allday");
    if (d.moved && !inLane) autoScroll();
    s.velocity *= 0.92;
    s.vx *= 0.92;
    s.vy *= 0.92;
    if (d.moved) {
      if (d.kind === "create") {
        renderDraft(d);
        publish("drag:frame", createFrame(d));
      } else if (d.kind === "move") {
        renderMove(d);
        publish("drag:frame", moveFrame(d));
      } else if (d.kind === "resize") {
        renderResize(d);
        publish("drag:frame", resizeFrame(d));
      } else if (d.kind === "lane-create") {
        const { rect, colWidth } = laneGeom();
        d.curDay = guardLaneCreate(d, d.anchorDay, dayFromX(s.pointer.x, rect, colWidth));
        renderLaneDraft(d);
        publish("drag:frame", laneCreateFrame(d));
      } else if (d.kind === "lane-move") {
        renderLaneMove(d);
        publish("drag:frame", laneMoveFrame(d));
      } else {
        renderLaneResize(d);
        publish("drag:frame", laneResizeFrame(d));
      }
    }
    s.raf = requestAnimationFrame(tick);
  }

  function startLoop() {
    cancelAnimationFrame(s.raf);
    s.raf = requestAnimationFrame(tick);
  }

  function stopLoop() {
    cancelAnimationFrame(s.raf);
    s.raf = 0;
  }

  // -- lifecycle: create ---------------------------------------------------

  const onCanvasPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    // ctrlKey: macOS ctrl+click fires contextmenu AND pointerdown with button 0
    if (e.button !== 0 || e.ctrlKey || s.drag) return;
    if ((e.target as HTMLElement).closest("[data-cal-event]")) return;
    const { rect } = geom();
    const el = e.currentTarget;
    // explicit capture on touch too: implicit capture dies when the canvas is rebuilt on a view switch
    capturePointer(el, e.pointerId);
    s.reduced = prefersReducedMotion();
    s.velocity = 0;
    s.vx = 0;
    s.vy = 0;
    s.lastPointer = { x: e.clientX, y: e.clientY, t: 0 };
    s.pointer = { x: e.clientX, y: e.clientY };
    s.altHeld = e.altKey;
    beginPress(e, "create");
    const colWidth = rect.width / vc();
    const day = dayFromX(e.clientX, rect, colWidth);
    const d: CreateDrag = {
      kind: "create",
      pointerId: e.pointerId,
      captureEl: el,
      downX: e.clientX,
      downY: e.clientY,
      dayIndex: day,
      anchorRawY: e.clientY - rect.top,
      moved: false,
      mode: "timed",
      curDay: day,
      dayDelta: 0,
      overflow: null,
      vTop: 0,
      vHeight: 0,
      vLeft: 0,
      vWidth: 0,
      okStart: 0,
      okEnd: 0,
      everOk: false,
    };
    s.drag = d;
    startLoop();
  };

  // -- lifecycle: lane create ----------------------------------------------

  const onLanePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0 || e.ctrlKey || s.drag) return;
    if ((e.target as HTMLElement).closest("[data-cal-event], [data-cal-more]")) return;
    const { rect, colWidth } = laneGeom();
    const el = e.currentTarget;
    capturePointer(el, e.pointerId);
    s.reduced = prefersReducedMotion();
    s.velocity = 0;
    s.vx = 0;
    s.vy = 0;
    s.lastPointer = { x: e.clientX, y: e.clientY, t: 0 };
    s.pointer = { x: e.clientX, y: e.clientY };
    s.altHeld = e.altKey;
    beginPress(e, "create");
    const day = dayFromX(e.clientX, rect, colWidth);
    const d: LaneCreateDrag = {
      kind: "lane-create",
      pointerId: e.pointerId,
      captureEl: el,
      downX: e.clientX,
      downY: e.clientY,
      anchorDay: day,
      curDay: day,
      moved: false,
      everOk: false,
      vLeft: 0,
      vWidth: 0,
    };
    s.drag = d;
    startLoop();
  };

  // -- lifecycle: move -----------------------------------------------------

  const onEventPointerDown = (e: React.PointerEvent<HTMLElement>, event: PlacedEvent) => {
    if (e.button !== 0 || e.ctrlKey || s.drag) return;
    // read-only: run the click half by hand so the event stays selectable, skip the drag half
    if (event.readOnly) {
      e.stopPropagation();
      const el = e.currentTarget as HTMLElement;
      const downX = e.clientX;
      const downY = e.clientY;
      const onUp = (ev: PointerEvent) => {
        el.removeEventListener("pointerup", onUp);
        el.removeEventListener("pointercancel", onUp);
        if (ev.type !== "pointerup") return;
        if (Math.hypot(ev.clientX - downX, ev.clientY - downY) < DRAG_THRESHOLD_PX)
          optsRef.current.openEditor(event.id);
      };
      el.addEventListener("pointerup", onUp);
      el.addEventListener("pointercancel", onUp);
      return;
    }
    e.stopPropagation();
    const node = e.currentTarget as HTMLElement;
    capturePointer(node, e.pointerId);
    const { rect } = geom();
    s.reduced = prefersReducedMotion();
    s.velocity = 0;
    s.vx = 0;
    s.vy = 0;
    s.lastPointer = { x: e.clientX, y: e.clientY, t: 0 };
    s.pointer = { x: e.clientX, y: e.clientY };
    s.altHeld = e.altKey;
    beginPress(e, "yield");

    if (event.allDay) {
      const laneEdge = (e.target as HTMLElement).closest<HTMLElement>("[data-lane-edge]")?.dataset
        .laneEdge as "left" | "right" | undefined;
      const { rect, colWidth } = laneGeom();
      if (laneEdge) {
        const t = spanPx(event.dayIndex, event.endDayIndex, colWidth);
        const d: LaneResizeDrag = {
          kind: "lane-resize",
          edge: laneEdge,
          pointerId: e.pointerId,
          captureEl: node,
          downX: e.clientX,
          downY: e.clientY,
          event,
          node,
          moved: false,
          cancelled: false,
          vLeft: t.left,
          vWidth: t.width,
          targetStartDay: event.dayIndex,
          targetEndDay: event.endDayIndex,
        };
        s.drag = d;
      } else {
        const d: LaneMoveDrag = {
          kind: "lane-move",
          pointerId: e.pointerId,
          captureEl: node,
          downX: e.clientX,
          downY: e.clientY,
          event,
          node,
          ghost: null,
          grabOffsetDays: dayFromX(e.clientX, rect, colWidth) - event.dayIndex,
          moved: false,
          cancelled: false,
          vDx: 0,
          jiggle: createJiggle(),
          jiggleT: 0,
          targetStartDay: event.dayIndex,
        };
        s.drag = d;
      }
      startLoop();
      return;
    }

    const edge = (e.target as HTMLElement).closest<HTMLElement>("[data-resize-edge]")?.dataset
      .resizeEdge as "start" | "end" | undefined;
    if (edge) {
      const d: ResizeDrag = {
        kind: "resize",
        edge,
        pointerId: e.pointerId,
        captureEl: node,
        downX: e.clientX,
        downY: e.clientY,
        event,
        node,
        timeEl: node.querySelector<HTMLElement>("[data-slot=event-time]"),
        moved: false,
        cancelled: false,
        vTop: g().minutesToPx(event.startMin),
        vHeight: g().durationToPx(event.endMin - event.startMin),
        targetStartMin: event.startMin,
        targetEndMin: event.endMin,
        overflow: null,
      };
      s.drag = d;
      startLoop();
      return;
    }
    const colWidth = rect.width / vc();
    const originTop = g().minutesToPx(event.startMin);
    const originLeft = event.dayIndex * colWidth;
    const d: MoveDrag = {
      kind: "move",
      pointerId: e.pointerId,
      captureEl: node,
      downX: e.clientX,
      downY: e.clientY,
      event,
      node,
      siblings: segmentSiblings(event, node),
      ghost: null,
      timeEl: node.querySelector<HTMLElement>("[data-slot=event-time]"),
      originTop,
      originLeft,
      grabOffsetY: e.clientY - rect.top - originTop,
      moved: false,
      cancelled: false,
      dup: false,
      vDx: 0,
      vDy: 0,
      jiggle: createJiggle(),
      jiggleT: 0,
      targetDayIndex: event.dayIndex,
      targetStartMin: event.startMin,
    };
    s.drag = d;
    startLoop();
  };

  // -- engage (threshold crossed) -----------------------------------------

  // a create refused at the threshold: nothing written yet, so no draft, no drag:start, no drag:end
  function standDownCreate(d: CreateDrag | LaneCreateDrag) {
    if (!s.refusedSaid) optsRef.current.announce?.(announceRefused("create"));
    cleanup(d);
    optsRef.current.draftRef.current?.setAttribute("hidden", "");
    optsRef.current.laneDraftRef.current?.setAttribute("hidden", "");
  }

  function engage(d: Drag) {
    d.moved = true;
    if (d.kind === "create") {
      const t = createTargets(d);
      if (cs().active && !d.everOk) {
        standDownCreate(d);
        return;
      }
      const draft = optsRef.current.draftRef.current;
      if (draft) {
        d.vTop = g().minutesToPx(t.startMin);
        d.vHeight = g().durationToPx(t.endMin - t.startMin);
        draft.removeAttribute("hidden");
      }
      publish("drag:start", createFrame(d));
    } else if (d.kind === "lane-create") {
      if (!laneCreateAllowed(d, d.anchorDay, d.anchorDay)) {
        standDownCreate(d);
        return;
      }
      const laneDraft = optsRef.current.laneDraftRef.current;
      if (laneDraft) {
        const { colWidth } = laneGeom();
        const t = spanPx(d.anchorDay, d.anchorDay, colWidth);
        d.vLeft = t.left;
        d.vWidth = t.width;
        laneDraft.style.left = `${t.left}px`;
        laneDraft.style.width = `${t.width}px`;
        laneDraft.removeAttribute("hidden");
      }
      publish("drag:start", laneCreateFrame(d));
    } else if (d.kind === "lane-resize") {
      d.node.setAttribute("data-resizing", "");
      document.body.setAttribute("data-cal-resizing", "");
      publish("drag:start", laneResizeFrame(d));
    } else if (d.kind === "lane-move") {
      const node = d.node;
      const ghost = node.cloneNode(true) as HTMLElement;
      ghost.removeAttribute("data-cal-event");
      ghost.setAttribute("data-cal-ghost", "");
      // the clone carries role="button" and the aria-label — hide it or a reader sees two events
      ghost.setAttribute("aria-hidden", "true");
      ghost.tabIndex = -1;
      ghost.style.pointerEvents = "none";
      ghost.style.opacity = "0.4";
      node.parentElement?.insertBefore(ghost, node);
      fadeGhostIn(ghost);
      d.ghost = ghost;
      node.setAttribute("data-dragging", "");
      if (!s.reduced) node.style.setProperty("--kloq-lift", "0");
      document.body.setAttribute("data-cal-grabbing", "");
      publish("drag:start", laneMoveFrame(d));
    } else if (d.kind === "resize") {
      d.node.setAttribute("data-resizing", "");
      document.body.setAttribute("data-cal-resizing", "");
      publish("drag:start", resizeFrame(d));
    } else {
      const node = d.node;
      const ghost = node.cloneNode(true) as HTMLElement;
      ghost.removeAttribute("data-cal-event");
      ghost.setAttribute("data-cal-ghost", "");
      ghost.setAttribute("aria-hidden", "true");
      ghost.tabIndex = -1;
      ghost.style.pointerEvents = "none";
      ghost.style.opacity = "0.4";
      node.parentElement?.insertBefore(ghost, node);
      fadeGhostIn(ghost);
      d.ghost = ghost;
      node.setAttribute("data-dragging", "");
      if (!s.reduced) node.style.setProperty("--kloq-lift", "0");
      // siblings take the drag treatment too, but get no ghost of their own
      for (const sib of d.siblings) {
        sib.setAttribute("data-dragging", "");
        if (!s.reduced) sib.style.setProperty("--kloq-lift", "0");
      }
      document.body.setAttribute("data-cal-grabbing", "");
      if (s.altHeld) setDup(d, true);
      publish("drag:start", moveFrame(d));
    }
  }

  // ⌥ mid-move toggles duplicate; the ghost solidifying to full opacity is the tell
  function setDup(d: MoveDrag, dup: boolean) {
    if (d.dup === dup) return;
    d.dup = dup;
    if (d.ghost) {
      const to = dup ? "1" : "0.4";
      if (!s.reduced)
        d.ghost.animate([{ opacity: d.ghost.style.opacity || "0.4" }, { opacity: to }], {
          duration: ms(140),
          easing: "ease-out",
        });
      d.ghost.style.opacity = to;
    }
    if (dup) {
      d.node.setAttribute("data-duplicating", "");
      for (const sib of d.siblings) sib.setAttribute("data-duplicating", "");
      document.body.setAttribute("data-cal-duplicating", "");
    } else {
      d.node.removeAttribute("data-duplicating");
      for (const sib of d.siblings) sib.removeAttribute("data-duplicating");
      document.body.removeAttribute("data-cal-duplicating");
    }
  }

  // -- finish --------------------------------------------------------------

  function cleanup(d: Drag) {
    stopLoop();
    s.drag = null;
    s.press = null;
    s.pressMode = null;
    s.holdSpan = 0;
    s.scale = 0;
    s.refused = false;
    s.refusedSaid = false;
    s.alignCands = null;
    probe.key = "";
    hidePress();
    showGuides([]);
    document.body.removeAttribute("data-cal-grabbing");
    document.body.removeAttribute("data-cal-resizing");
    document.body.removeAttribute("data-cal-duplicating");
    document.body.removeAttribute("data-cal-refused");
    try {
      d.captureEl.releasePointerCapture(d.pointerId);
    } catch {
      /* already released */
    }
  }

  function finishCreate(d: CreateDrag, commitIn: boolean) {
    let commit = commitIn;
    const draft = optsRef.current.draftRef.current;
    const laneDraft = optsRef.current.laneDraftRef.current;

    if (d.mode === "allday") {
      const frame = createFrame(d);
      const lo = Math.min(d.dayIndex, d.curDay);
      const hi = Math.max(d.dayIndex, d.curDay);
      cleanup(d);
      if (commit && releaseRefused({ gesture: "create", target: aSlot(lo, hi) })) {
        refuseRelease("create");
        commit = false;
      }
      if (!commit) {
        laneDraft?.setAttribute("hidden", "");
        draft?.setAttribute("hidden", "");
        endPublish(frame, true);
        return;
      }
      const id = optsRef.current.commitCreate({
        dayIndex: lo,
        endDayIndex: hi,
        startMin: 0,
        endMin: 0,
        allDay: true,
      });
      endPublish(frame, false);
      requestAnimationFrame(() =>
        requestAnimationFrame(() => {
          laneDraft?.setAttribute("hidden", "");
          optsRef.current.openEditor(id);
        }),
      );
      return;
    }

    const frame = createFrame(d);
    if (!commit) {
      cleanup(d);
      draft?.setAttribute("hidden", "");
      endPublish(frame, true);
      if (!d.moved)
        optsRef.current.onCanvasClick?.({
          clientX: s.pointer.x,
          clientY: s.pointer.y,
        });
      return;
    }
    const t = createTargets(d);
    cleanup(d);
    if (
      releaseRefused({
        gesture: "create",
        target: tSlot(d.dayIndex, t.startMin, t.endMin),
      })
    ) {
      refuseRelease("create");
      commit = false;
    }
    if (!commit || t.endMin - t.startMin < g().minEventMinutes) {
      draft?.setAttribute("hidden", "");
      dropCreateOverflow(d, draft);
      endPublish(frame, true);
      return;
    }
    const id = optsRef.current.commitCreate({
      dayIndex: d.dayIndex,
      startMin: t.startMin,
      endMin: t.endMin,
    });
    endPublish(frame, false);
    // let the real block paint before the draft disappears
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        draft?.setAttribute("hidden", "");
        dropCreateOverflow(d, draft);
        optsRef.current.openEditor(id);
      }),
    );
  }

  function finishLaneCreate(d: LaneCreateDrag, commitIn: boolean) {
    let commit = commitIn;
    const laneDraft = optsRef.current.laneDraftRef.current;
    const frame = laneCreateFrame(d);
    const lo = Math.min(d.anchorDay, d.curDay);
    const hi = Math.max(d.anchorDay, d.curDay);
    cleanup(d);
    if (commit && releaseRefused({ gesture: "create", target: aSlot(lo, hi) })) {
      refuseRelease("create");
      commit = false;
    }
    if (!commit || !d.moved) {
      laneDraft?.setAttribute("hidden", "");
      endPublish(frame, true);
      if (!d.moved)
        optsRef.current.onCanvasClick?.({
          clientX: s.pointer.x,
          clientY: s.pointer.y,
        });
      return;
    }
    const id = optsRef.current.commitCreate({
      dayIndex: lo,
      endDayIndex: hi,
      startMin: 0,
      endMin: 0,
      allDay: true,
    });
    endPublish(frame, false);
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        laneDraft?.setAttribute("hidden", "");
        optsRef.current.openEditor(id);
      }),
    );
  }

  function finishLaneMove(d: LaneMoveDrag, cancelledIn: boolean) {
    let cancelled = cancelledIn;
    if (
      !cancelled &&
      d.moved &&
      releaseRefused({
        gesture: "lane-move",
        target: aSlot(
          d.targetStartDay,
          d.targetStartDay + (d.event.endDayIndex - d.event.dayIndex),
        ),
        origin: aSlot(d.event.dayIndex, d.event.endDayIndex),
        event: d.event.source,
      })
    ) {
      refuseRelease("span", d.event);
      cancelled = true;
    }
    const node = d.node;
    const frame = laneMoveFrame(d);
    cleanup(d);
    const done = () => {
      node.removeAttribute("data-dragging");
      node.style.removeProperty("--kloq-lift");
      d.ghost?.remove();
    };

    if (cancelled) {
      endPublish(frame, true);
      if (s.reduced) {
        node.style.transform = "";
        done();
        return;
      }
      const anim = node.animate(
        [
          {
            transform: `translateX(${d.vDx}px)${jiggleTransform(d.jiggle)}`,
            ...liftFrom(d.jiggle),
          },
          { transform: `translateX(0px)${JIGGLE_REST}`, ...LIFT_REST },
        ],
        { duration: SPRING_MS, easing: SPRING },
      );
      anim.onfinish = () => {
        node.style.transform = "";
        done();
      };
      return;
    }

    const { colWidth } = laneGeom();
    const span = d.event.endDayIndex - d.event.dayIndex;
    const finalDx = (d.targetStartDay - d.event.dayIndex) * colWidth;
    const commit = () => {
      const result = optsRef.current.commitSpan(d.event.id, {
        dayIndex: d.targetStartDay,
        endDayIndex: d.targetStartDay + span,
      });
      landCommit(
        result,
        () => {
          node.style.transform = "";
          done();
        },
        () => springHomeFrom(node, `translate(${d.vDx}px, 0)${jiggleTransform(d.jiggle)}`, done),
      );
    };
    endPublish(frame, false);
    if (s.reduced || (Math.abs(finalDx - d.vDx) < 1 && jiggleAtRest(d.jiggle))) {
      commit();
      return;
    }
    const anim = node.animate(
      [
        { transform: `translateX(${d.vDx}px)${jiggleTransform(d.jiggle)}`, ...liftFrom(d.jiggle) },
        { transform: `translateX(${finalDx}px)${JIGGLE_REST}`, ...LIFT_REST },
      ],
      { duration: SPRING_MS * 0.6, easing: SPRING },
    );
    anim.onfinish = commit;
  }

  function finishLaneResize(d: LaneResizeDrag, cancelledIn: boolean) {
    let cancelled = cancelledIn;
    if (
      !cancelled &&
      d.moved &&
      releaseRefused({
        gesture: "lane-resize",
        target: aSlot(d.targetStartDay, d.targetEndDay),
        origin: aSlot(d.event.dayIndex, d.event.endDayIndex),
        event: d.event.source,
      })
    ) {
      refuseRelease("span", d.event);
      cancelled = true;
    }
    const node = d.node;
    const frame = laneResizeFrame(d);
    cleanup(d);
    const done = () => node.removeAttribute("data-resizing");

    // left/width are React-managed styles — restore concrete values, never ""
    const restore = (startDay: number, endDay: number) => {
      const cs = chipStyles(startDay, endDay);
      node.style.left = cs.left;
      node.style.width = cs.width;
    };

    if (!d.moved) {
      endPublish(frame, true);
      done();
      return;
    }

    if (cancelled) {
      endPublish(frame, true);
      const { colWidth } = laneGeom();
      const orig = spanPx(d.event.dayIndex, d.event.endDayIndex, colWidth);
      if (s.reduced) {
        restore(d.event.dayIndex, d.event.endDayIndex);
        done();
        return;
      }
      const anim = node.animate(
        [
          { left: `${d.vLeft}px`, width: `${d.vWidth}px` },
          { left: `${orig.left}px`, width: `${orig.width}px` },
        ],
        { duration: SPRING_MS, easing: SPRING },
      );
      anim.onfinish = () => {
        restore(d.event.dayIndex, d.event.endDayIndex);
        done();
      };
      return;
    }

    const { colWidth } = laneGeom();
    const final = spanPx(d.targetStartDay, d.targetEndDay, colWidth);
    const commit = () => {
      const result = optsRef.current.commitSpan(d.event.id, {
        dayIndex: d.targetStartDay,
        endDayIndex: d.targetEndDay,
      });
      landCommit(
        result,
        () => {
          restore(d.targetStartDay, d.targetEndDay);
          done();
        },
        () => {
          restore(d.event.dayIndex, d.event.endDayIndex);
          done();
        },
      );
    };
    endPublish(frame, false);
    if (s.reduced || (Math.abs(final.left - d.vLeft) < 1 && Math.abs(final.width - d.vWidth) < 1)) {
      commit();
      return;
    }
    const anim = node.animate(
      [
        { left: `${d.vLeft}px`, width: `${d.vWidth}px` },
        { left: `${final.left}px`, width: `${final.width}px` },
      ],
      { duration: SPRING_MS * 0.6, easing: SPRING },
    );
    anim.onfinish = commit;
  }

  function finishMove(d: MoveDrag, cancelledIn: boolean) {
    let cancelled = cancelledIn;
    const moveGesture: ConstraintGesture = d.dup ? "duplicate" : "move";
    const moveDuration = d.event.endMin - d.event.startMin;
    if (
      !cancelled &&
      d.moved &&
      releaseRefused({
        gesture: moveGesture,
        target: tSlot(d.targetDayIndex, d.targetStartMin, d.targetStartMin + moveDuration),
        origin: tSlot(d.event.dayIndex, d.event.startMin, d.event.endMin),
        event: d.event.source,
      })
    ) {
      refuseRelease(d.dup ? "duplicate" : "move", d.event);
      cancelled = true;
    }
    const node = d.node;
    const sibs = d.siblings;
    const frame = moveFrame(d);
    cleanup(d);

    const done = () => {
      node.removeAttribute("data-dragging");
      node.removeAttribute("data-duplicating");
      node.style.removeProperty("--kloq-lift");
      for (const sib of sibs) {
        sib.removeAttribute("data-dragging");
        sib.removeAttribute("data-duplicating");
        sib.style.removeProperty("--kloq-lift");
      }
      d.ghost?.remove();
    };

    // ⌥-drop: settle the carried copy into the target, commit a clone, hand the node back to origin
    if (d.dup && !cancelled && d.moved) {
      const { colWidth } = geom();
      const finalDx = d.targetDayIndex * colWidth - d.originLeft;
      const finalDy = g().minutesToPx(d.targetStartMin) - d.originTop;
      const commit = () => {
        flushSync(() =>
          optsRef.current.commitDuplicate(d.event.id, {
            dayIndex: d.targetDayIndex,
            startMin: d.targetStartMin,
          }),
        );
        setTransformAll(node, sibs, "");
        if (d.timeEl) d.timeEl.textContent = g().formatRange(d.event.startMin, d.event.endMin);
        done();
      };
      endPublish(frame, false);
      if (
        s.reduced ||
        (Math.abs(finalDx - d.vDx) < 1 && Math.abs(finalDy - d.vDy) < 1 && jiggleAtRest(d.jiggle))
      ) {
        commit();
        return;
      }
      const anim = animateAll(
        node,
        sibs,
        [
          {
            transform: `translate(${d.vDx}px, ${d.vDy}px)${jiggleTransform(d.jiggle)}`,
            ...liftFrom(d.jiggle),
          },
          { transform: `translate(${finalDx}px, ${finalDy}px)${JIGGLE_REST}`, ...LIFT_REST },
        ],
        { duration: SPRING_MS * 0.6, easing: SPRING },
      );
      anim.onfinish = commit;
      return;
    }

    if (cancelled) {
      // restore the label the engine overwrote — React's vdom didn't change, so it won't
      const from = `translate(${d.vDx}px, ${d.vDy}px)${jiggleTransform(d.jiggle)}`;
      const restoreLabel = () => {
        if (d.timeEl) d.timeEl.textContent = g().formatRange(d.event.startMin, d.event.endMin);
      };
      endPublish(frame, true);
      if (s.reduced) {
        setTransformAll(node, sibs, "");
        restoreLabel();
        done();
        return;
      }
      const anim = animateAll(
        node,
        sibs,
        [
          { transform: from, ...liftFrom(d.jiggle) },
          { transform: `translate(0px, 0px)${JIGGLE_REST}`, ...LIFT_REST },
        ],
        { duration: SPRING_MS, easing: SPRING },
      );
      anim.onfinish = () => {
        setTransformAll(node, sibs, "");
        restoreLabel();
        done();
      };
      return;
    }

    const { colWidth } = geom();
    const finalDx = d.targetDayIndex * colWidth - d.originLeft;
    const finalDy = g().minutesToPx(d.targetStartMin) - d.originTop;
    const commit = () => {
      const result = optsRef.current.commitMove(d.event.id, {
        dayIndex: d.targetDayIndex,
        startMin: d.targetStartMin,
      });
      landCommit(
        result,
        () => {
          setTransformAll(node, sibs, "");
          done();
        },
        () =>
          springHomeFrom(
            node,
            `translate(${d.vDx}px, ${d.vDy}px)${jiggleTransform(d.jiggle)}`,
            done,
            sibs,
          ),
      );
    };
    endPublish(frame, false);
    if (
      s.reduced ||
      (Math.abs(finalDx - d.vDx) < 1 && Math.abs(finalDy - d.vDy) < 1 && jiggleAtRest(d.jiggle))
    ) {
      commit();
      return;
    }
    const anim = animateAll(
      node,
      sibs,
      [
        {
          transform: `translate(${d.vDx}px, ${d.vDy}px)${jiggleTransform(d.jiggle)}`,
          ...liftFrom(d.jiggle),
        },
        { transform: `translate(${finalDx}px, ${finalDy}px)${JIGGLE_REST}`, ...LIFT_REST },
      ],
      { duration: SPRING_MS * 0.6, easing: SPRING },
    );
    anim.onfinish = commit;
  }

  function finishResize(d: ResizeDrag, cancelledIn: boolean) {
    let cancelled = cancelledIn;
    if (
      !cancelled &&
      d.moved &&
      releaseRefused({
        gesture: "resize",
        target: tSlot(d.event.dayIndex, d.targetStartMin, d.targetEndMin),
        origin: tSlot(d.event.dayIndex, d.event.startMin, d.event.endMin),
        event: d.event.source,
      })
    ) {
      refuseRelease("resize", d.event);
      cancelled = true;
    }
    const node = d.node;
    const frame = resizeFrame(d);
    cleanup(d);

    const crossed = d.overflow !== null;
    const done = () => {
      node.removeAttribute("data-resizing");
      dropResizeOverflow(d);
    };

    // top/height are React-managed styles — restore concrete values, never "" (block jumps to y=0)
    const restore = (startMin: number, endMin: number) => {
      node.style.top = `${g().minutesToPx(startMin)}px`;
      node.style.height = `${Math.max(g().durationToPx(endMin - startMin) - 2, 14)}px`;
      if (d.timeEl) d.timeEl.textContent = g().formatRange(startMin, endMin);
    };

    if (!d.moved) {
      endPublish(frame, true);
      done();
      return;
    }

    if (cancelled) {
      endPublish(frame, true);
      dropResizeOverflow(d);
      const origTop = g().minutesToPx(d.event.startMin);
      const origH = Math.max(g().durationToPx(d.event.endMin - d.event.startMin) - 2, 14);
      if (s.reduced) {
        restore(d.event.startMin, d.event.endMin);
        done();
        return;
      }
      const anim = node.animate(
        [
          { top: `${d.vTop}px`, height: `${Math.max(d.vHeight - 2, 14)}px` },
          { top: `${origTop}px`, height: `${origH}px` },
        ],
        { duration: SPRING_MS, easing: SPRING },
      );
      anim.onfinish = () => {
        restore(d.event.startMin, d.event.endMin);
        done();
      };
      return;
    }

    const finalTop = g().minutesToPx(d.targetStartMin);
    const finalH = Math.max(g().durationToPx(d.targetEndMin - d.targetStartMin) - 2, 14);
    const commit = () => {
      const result = optsRef.current.commitResize(d.event.id, {
        startMin: d.targetStartMin,
        endMin: d.targetEndMin,
      });
      landCommit(
        result,
        () => {
          restore(d.targetStartMin, d.targetEndMin);
          done();
        },
        () => {
          restore(d.event.startMin, d.event.endMin);
          done();
        },
      );
    };
    endPublish(frame, false);
    // a cross-midnight result has nothing to tween toward — the re-render replaces it with segments
    if (
      s.reduced ||
      crossed ||
      (Math.abs(finalTop - d.vTop) < 1 &&
        Math.abs(finalH - (d.vHeight - 2)) < 1 &&
        Math.abs(s.vy * RESIZE_PUSH) < 1)
    ) {
      commit();
      return;
    }
    // rubber-band from the release velocity; skipped when there's no room to overshoot
    const push = s.reduced ? 0 : Math.max(-10, Math.min(10, s.vy * RESIZE_PUSH));
    const overTop = d.edge === "start" ? finalTop + push : finalTop;
    const overH = d.edge === "start" ? finalH - push : finalH + push;
    const bounce = Math.abs(push) >= 1 && overH >= 14 && overTop >= 0;
    const anim = node.animate(
      bounce
        ? [
            { top: `${d.vTop}px`, height: `${Math.max(d.vHeight - 2, 14)}px`, easing: "ease-out" },
            { top: `${overTop}px`, height: `${overH}px`, offset: 0.35, easing: RESIZE_SPRING },
            { top: `${finalTop}px`, height: `${finalH}px` },
          ]
        : [
            { top: `${d.vTop}px`, height: `${Math.max(d.vHeight - 2, 14)}px` },
            { top: `${finalTop}px`, height: `${finalH}px` },
          ],
      { duration: SPRING_MS * (bounce ? 0.9 : 0.6), easing: SPRING },
    );
    anim.onfinish = commit;
  }

  // -- global listeners ----------------------------------------------------

  const attach = () => {
    function onMove(e: PointerEvent) {
      const d = s.drag;
      if (!d || e.pointerId !== d.pointerId) return;
      s.altHeld = e.altKey;
      trackVelocity(e.clientX, e.clientY);

      // the press is asked before the threshold: on touch they use different radii
      if (s.press) {
        const next = longPressMove(s.press, e.clientX, e.clientY);
        if (next !== s.press) {
          s.press = next;
          if (s.pressMode === "create" && d.kind === "create") {
            // moved before the hold matured on the scrollable grid — that was a scroll
            abandonPress(d);
            return;
          }
          // the lane has nothing to scroll; "yield" just saw base-ui let go — ours from here
          s.press = null;
          s.pressMode = null;
          hidePress();
        } else if (s.press.phase === "armed" && s.holdSpan > 0) {
          // the finger moved after a long-press create — back to the normal snap floor
          if (Math.hypot(e.clientX - s.press.x, e.clientY - s.press.y) >= DRAG_THRESHOLD_PX)
            s.holdSpan = 0;
        }
      }

      if (!d.moved) {
        const dist = Math.hypot(e.clientX - d.downX, e.clientY - d.downY);
        if (dist >= threshold()) engage(d);
      }
    }

    function onUp(e: PointerEvent) {
      const d = s.drag;
      if (!d || e.pointerId !== d.pointerId) return;
      if (d.kind === "create") {
        finishCreate(d, d.moved);
      } else if (d.kind === "lane-create") {
        finishLaneCreate(d, d.moved);
      } else if (d.kind === "resize") {
        const wasClick = !d.moved;
        finishResize(d, d.cancelled);
        if (wasClick) optsRef.current.openEditor(d.event.id);
      } else if (d.kind === "lane-resize") {
        const wasClick = !d.moved;
        finishLaneResize(d, d.cancelled);
        if (wasClick) optsRef.current.openEditor(d.event.id);
      } else if (d.kind === "lane-move") {
        const wasClick = !d.moved;
        finishLaneMove(d, d.cancelled || !d.moved);
        if (wasClick) optsRef.current.openEditor(d.event.id);
      } else {
        const wasClick = !d.moved;
        finishMove(d, d.cancelled || !d.moved);
        if (wasClick) optsRef.current.openEditor(d.event.id);
      }
    }

    function cancelDrag(d: Drag) {
      if (d.kind === "create") finishCreate(d, false);
      else if (d.kind === "lane-create") finishLaneCreate(d, false);
      else if (d.kind === "resize") finishResize(d, true);
      else if (d.kind === "lane-resize") finishLaneResize(d, true);
      else if (d.kind === "lane-move") finishLaneMove(d, true);
      else finishMove(d, true);
    }

    function onCancel(e: PointerEvent) {
      const d = s.drag;
      if (!d || e.pointerId !== d.pointerId) return;
      // pre-threshold must not run the click half: on touch, pointercancel means "I took this as a scroll"
      if (!d.moved) abandonPress(d);
      else cancelDrag(d);
    }

    function onKey(e: KeyboardEvent) {
      const d = s.drag;
      if (e.key === "Alt") {
        s.altHeld = e.type === "keydown";
        if (d?.kind === "move" && d.moved) setDup(d, s.altHeld);
      }
      if (!d) return;
      if (e.key === "Escape" && e.type === "keydown") {
        e.preventDefault();
        e.stopImmediatePropagation();
        cancelDrag(d);
      }
    }

    // capture-phase stopPropagation keeps base-ui's long-press timer from starting on empty grid/lane
    function onTouchStartCapture(e: TouchEvent) {
      const t = e.target as HTMLElement | null;
      if (!t?.closest) return;
      if (t.closest("[data-cal-event]")) return;
      const canvas = optsRef.current.canvasRef.current;
      const lane = optsRef.current.laneRef.current;
      if (!(canvas?.contains(t) || lane?.contains(t))) return;
      e.stopPropagation();
    }

    // touch-action can't change for a touch in flight; a non-passive touchmove preventDefault can
    function onTouchMove(e: TouchEvent) {
      const d = s.drag;
      if (!d || !isTouch()) return;
      if (s.press?.phase === "pending") return;
      if (d.moved && e.cancelable) e.preventDefault();
    }

    document.addEventListener("touchstart", onTouchStartCapture, {
      capture: true,
    });
    document.addEventListener("touchmove", onTouchMove, { passive: false });
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
    // capture phase: the engine must see Escape before a focused element can swallow it
    window.addEventListener("keydown", onKey, { capture: true });
    window.addEventListener("keyup", onKey, { capture: true });
    cancelRef.current = () => {
      const d = s.drag;
      if (!d) return;
      if (d.moved) cancelDrag(d);
      else abandonPress(d);
    };

    return () => {
      cancelRef.current = () => {};
      document.removeEventListener("touchstart", onTouchStartCapture, {
        capture: true,
      });
      document.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      window.removeEventListener("keydown", onKey, { capture: true });
      window.removeEventListener("keyup", onKey, { capture: true });
      stopLoop();
      pressElRef.current?.remove();
      pressElRef.current = null;
      for (const el of guideEls) el.remove();
      guideEls.length = 0;
    };
  };

  /** An engaged drag springs home as Escape would; a pre-threshold one is forgotten. Idempotent. */
  const cancelActiveDrag = () => cancelRef.current();

  return {
    onCanvasPointerDown,
    onEventPointerDown,
    onLanePointerDown,
    cancelActiveDrag,
    flashEdges,
    attach,
  };
}

export type DragEngine = ReturnType<typeof createDragEngine>;

/** One engine per mount; options are read through a ref, so nothing here re-renders or re-binds. */
export function useDragEngine(opts: DragEngineOpts) {
  const optsRef = useLatest(opts);
  const [engine] = useState(() => createDragEngine(optsRef));
  useEffect(() => engine.attach(), [engine]);
  return engine;
}

/** The event store behind <Kloq>: controlled facade or an InternalStore with persistence, plus the host seam. */
import { useEffect, useLayoutEffect, useMemo, useRef } from "react";
import {
  controlledStore,
  InternalStore,
  localStorageAdapter,
  type OnCommit,
  type PersistenceAdapter,
  SEED_EVENTS,
  useStoreEvents,
} from "../lib/calendar-store";
import type { CalEvent } from "../lib/event-types";
import { validateEventIds } from "../lib/ids";

const warned = new Set<string>();
function warnOnce(message: string) {
  if (warned.has(message)) return;
  warned.add(message);
  console.warn(message);
}

export interface EventStoreOptions {
  events?: CalEvent[];
  onEventsChange?: (events: CalEvent[]) => void;
  defaultEvents?: CalEvent[];
  persistence?: false | PersistenceAdapter;
  onCommit?: OnCommit;
  onReverted?: (ids: string[]) => void;
}

export function useEventStore({
  events,
  onEventsChange,
  defaultEvents,
  persistence,
  onCommit,
  onReverted,
}: EventStoreOptions) {
  const controlled = events !== undefined;

  // seam object is stable; its fields track the latest props
  const seam = useRef<{
    onCommit?: OnCommit;
    onReverted?: (ids: string[]) => void;
  }>({}).current;

  const internalRef = useRef<InternalStore | null>(null);
  if (!controlled && internalRef.current === null) {
    internalRef.current = new InternalStore(
      defaultEvents ?? SEED_EVENTS,
      persistence === false ? false : (persistence ?? localStorageAdapter()),
      seam,
    );
  }
  // memoised: a per-render facade would resubscribe `useSyncExternalStore` every host render
  const store = useMemo(
    () =>
      controlled
        ? controlledStore(events!, onEventsChange ?? (() => {}), seam)
        : internalRef.current!,
    [controlled, events, onEventsChange, seam],
  );
  const live = useStoreEvents(store);
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    for (const m of validateEventIds(live)) warnOnce(m);
  }, [live]);
  // mirrored into the seam post-render, never during it (abandoned concurrent renders)
  useEffect(() => {
    seam.onCommit = onCommit;
    seam.onReverted = onReverted;
  });
  // swap in the persisted copy before first paint (uncontrolled only); on the way out, write
  // anything still queued, in a layout cleanup so it lands before a remount hydrates
  useLayoutEffect(() => {
    store.hydrate();
    return () => internalRef.current?.flush();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return { store, events: live, controlled };
}

/** Focus follows the roving event; selection size is announced. */
import { type RefObject, useCallback, useEffect, useRef } from "react";
import { announceSelection } from "../lib/announce";
import { INTERACTIVE_WIDGET_SELECTOR } from "../lib/keyboard-scope";
import { nodeFor } from "../lib/recurrence";
import { shouldFollowFocus } from "../lib/roving";

export function useFocusFollow({
  rootRef,
  surfaceRef,
  registry,
  rovingId,
  selectedId,
  count,
  announce,
}: {
  rootRef: RefObject<HTMLElement | null>;
  surfaceRef: RefObject<HTMLElement | null>;
  registry: Map<string, HTMLElement>;
  rovingId: string | null;
  selectedId: string | null;
  count: number;
  announce: (message: string) => void;
}) {
  // move focus to an event, or the surface; guarded so it never steals focus from the host or the panel
  const focusEvent = useCallback(
    (id: string | null) => {
      const active = document.activeElement;
      const root = rootRef.current;
      const ownsFocus = active === null || active === document.body || !!root?.contains(active);
      const widgetHasFocus =
        active instanceof Element && active.closest(INTERACTIVE_WIDGET_SELECTOR) !== null;
      const dragging =
        document.body.hasAttribute("data-cal-grabbing") ||
        document.body.hasAttribute("data-cal-resizing");
      if (!shouldFollowFocus({ ownsFocus, widgetHasFocus, dragging })) return;
      const node = id ? nodeFor(registry, id) : null;
      // `preventScroll`: the keyboard layer already scrolls smoothly; focus scroll would jump first
      (node ?? surfaceRef.current)?.focus({ preventScroll: true });
    },
    [registry, rootRef, surfaceRef],
  );

  // focus follows the roving index
  const lastRoving = useRef<string | null>(null);
  useEffect(() => {
    if (rovingId === lastRoving.current) return;
    lastRoving.current = rovingId;
    if (!rovingId || selectedId !== rovingId) return;
    focusEvent(rovingId);
  }, [rovingId, selectedId, focusEvent]);

  // selection size is announced, not identity — the focused block's name already says which
  const lastCount = useRef(count);
  useEffect(() => {
    if (count === lastCount.current) return;
    const previous = lastCount.current;
    lastCount.current = count;
    if (count > 1 || (previous > 1 && count === 0)) announce(announceSelection(count));
  }, [count, announce]);

  return focusEvent;
}

import { type RefObject, useEffect } from "react";
import { craftBus } from "../lib/craft-bus";
import { formatDuration } from "../lib/event-text";
import { useLatest } from "../lib/use-latest";

/** While the anchored block is dragged, ride along per frame and mirror its live time/day labels. */
export function useFollowDrag({
  wrapRef,
  eventId,
  reanchor,
  refs,
  live,
}: {
  wrapRef: RefObject<HTMLDivElement | null>;
  eventId: string;
  reanchor: (animate: boolean) => void;
  refs: {
    timeRef: RefObject<HTMLSpanElement | null>;
    dayRef: RefObject<HTMLSpanElement | null>;
    durRef: RefObject<HTMLSpanElement | null>;
  };
  live: {
    dayNamesLong: string[];
    spanLabel: (a: number, b: number) => string;
    formatRange: (a: number, b: number) => string;
  };
}) {
  const { timeRef, dayRef, durRef } = refs;
  const liveRef = useLatest(live);

  useEffect(() => {
    let settleRaf = 0;
    const wrap = wrapRef.current;

    const follow = () => reanchor(false);

    const unsub = craftBus.subscribe((e) => {
      if (e.type === "design-mode") return;
      if (e.frame.id !== eventId) return;

      if (e.type === "drag:start" || e.type === "drag:frame") {
        if (wrap && !wrap.dataset.following) {
          wrap.dataset.following = "";
          wrap.style.pointerEvents = "none";
          wrap.style.opacity = "0.85";
        }
        follow();
        const live = liveRef.current;
        if (e.frame.endDayIndex !== undefined) {
          if (dayRef.current)
            dayRef.current.textContent = live.spanLabel(e.frame.dayIndex, e.frame.endDayIndex);
          if (timeRef.current) timeRef.current.textContent = "All day";
        } else {
          if (timeRef.current)
            timeRef.current.textContent = live.formatRange(e.frame.startMin, e.frame.endMin);
          if (durRef.current)
            durRef.current.textContent = formatDuration(e.frame.endMin - e.frame.startMin);
          if (dayRef.current)
            dayRef.current.textContent = live.dayNamesLong[e.frame.dayIndex] ?? "";
        }
        return;
      }

      // ride along with the settle spring, then let go
      const start = performance.now();
      const settle = () => {
        follow();
        if (performance.now() - start < 320) {
          settleRaf = requestAnimationFrame(settle);
        } else if (wrap) {
          delete wrap.dataset.following;
          wrap.style.pointerEvents = "";
          wrap.style.opacity = "";
          follow();
        }
      };
      settleRaf = requestAnimationFrame(settle);
    });
    return () => {
      cancelAnimationFrame(settleRaf);
      unsub();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId]);
}

/** First paint: open the grid at 7:30am and stagger the blocks in; re-open at the same spot when a time grid remounts. */
import { type RefObject, useLayoutEffect } from "react";
import { EASE_OUT, ms, prefersReducedMotion } from "../lib/springs";
import { useKloqSettings } from "./settings-context";

export function useGridMount({
  rootRef,
  scrollRef,
  canvasRef,
  laneRef,
  isTimeGrid,
}: {
  rootRef: RefObject<HTMLElement | null>;
  scrollRef: RefObject<HTMLElement | null>;
  canvasRef: RefObject<HTMLElement | null>;
  laneRef: RefObject<HTMLElement | null>;
  isTimeGrid: boolean;
}) {
  const g = useKloqSettings();
  // where the grid opens: 7:30am, or the top of a day range that starts later
  const initialScrollTop = Math.max(0, g.minutesToPx(7.5 * 60));

  useLayoutEffect(() => {
    const scroll = scrollRef.current;
    // `=== 0`: with `ssr` the pre-paint script already scrolled, and hydration must not snap the user back
    if (scroll && scroll.scrollTop === 0) scroll.scrollTop = initialScrollTop;

    if (prefersReducedMotion()) return;
    const blocks = canvasRef.current
      ? [
          ...(laneRef.current?.querySelectorAll<HTMLElement>("[data-cal-event]") ?? []),
          ...canvasRef.current.querySelectorAll<HTMLElement>("[data-cal-event]"),
        ]
      : [...(rootRef.current?.querySelectorAll<HTMLElement>("[data-cal-event]") ?? [])];
    blocks.forEach((el, i) => {
      el.animate(
        [
          { opacity: 0, transform: "translateY(6px)" },
          { opacity: 1, transform: "none" },
        ],
        {
          duration: ms(260),
          delay: i * 20,
          easing: EASE_OUT,
          fill: "backwards",
        },
      );
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // returning to a time grid remounts the scroller at 0 (midnight)
  useLayoutEffect(() => {
    const scroll = scrollRef.current;
    if (scroll && scroll.scrollTop === 0) scroll.scrollTop = initialScrollTop;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isTimeGrid]);
  return { initialScrollTop };
}

"use client";

/**
 * use-history — bounded snapshot undo/redo over the store; replays via
 * `replaceAll` (never re-records) and FLIPs the affected blocks.
 */

import { useCallback, useEffect, useRef } from "react";
import { flushSync } from "react-dom";
import { isHistoryCapable, type KloqChange, type KloqStore } from "../lib/calendar-store";
import type { CalEvent } from "../lib/calendar-types";
import { entriesFor } from "../lib/recurrence";
import { EASE_OUT, ms, prefersReducedMotion, SPRING } from "../lib/springs";

const LIMIT = 100;
/** Keystrokes in one text field closer together than this share an undo step. */
const TYPING_WINDOW_MS = 1000;
const TEXT_FIELDS = new Set(["title", "description", "location", "meetingUrl"]);

interface Entry {
  before: CalEvent[];
  after: CalEvent[];
  ids: string[];
}

function idsOf(change: KloqChange): string[] {
  switch (change.type) {
    case "add":
    case "remove":
      return [change.event.id];
    case "update":
      return [change.id];
    case "reset":
      return [];
    case "batch":
      return change.changes.flatMap(idsOf);
  }
}

interface Typing {
  id: string;
  fields: string;
  at: number;
}

function typingOf(change: KloqChange, at: number): Typing | null {
  if (change.type !== "update") return null;
  const keys = Object.keys(change.patch);
  if (keys.length === 0 || !keys.every((k) => TEXT_FIELDS.has(k))) return null;
  return { id: change.id, fields: keys.sort().join(), at };
}

interface HistoryHandle {
  undo(): void;
  redo(): void;
}

export function useHistory(store: KloqStore, registry: Map<string, HTMLElement>): HistoryHandle {
  const past = useRef<Entry[]>([]).current;
  const future = useRef<Entry[]>([]).current;
  // the open typing run, always describing the newest `past` entry
  const typing = useRef<Typing | null>(null);

  useEffect(() => {
    past.length = 0;
    future.length = 0;
    typing.current = null;
    if (!isHistoryCapable(store)) return;
    store.setChangeListener((change, before, after) => {
      const next = typingOf(change, Date.now());
      const open = typing.current;
      const last = past[past.length - 1];
      if (
        next &&
        open &&
        last?.after === before &&
        open.id === next.id &&
        open.fields === next.fields &&
        next.at - open.at <= TYPING_WINDOW_MS
      ) {
        last.after = after;
      } else {
        past.push({ before, after, ids: idsOf(change) });
        if (past.length > LIMIT) past.shift();
      }
      typing.current = next;
      future.length = 0;
    });
    return () => store.setChangeListener(null);
  }, [store, past, future]);

  const replay = useCallback(
    (entry: Entry, events: CalEvent[]) => {
      if (!isHistoryCapable(store)) return;
      const reduced = prefersReducedMotion();
      // beforeLead (by store id) is the fallback for a placement id that changed across the replay
      const beforeRects = new Map<string, DOMRect>();
      const beforeLead = new Map<string, DOMRect>();
      if (!reduced)
        for (const id of entry.ids) {
          for (const [key, node] of entriesFor(registry, id)) {
            const rect = node.getBoundingClientRect();
            beforeRects.set(key, rect);
            if (!beforeLead.has(id)) beforeLead.set(id, rect);
          }
        }
      flushSync(() => store.replaceAll(events));
      if (reduced) return;
      for (const id of entry.ids)
        for (const [key, node] of entriesFor(registry, id)) {
          const old = beforeRects.get(key) ?? beforeLead.get(id);
          const now = node.getBoundingClientRect();
          if (!old) {
            node.animate(
              [
                { opacity: 0, transform: "scale(0.94)" },
                { opacity: 1, transform: "none" },
              ],
              { duration: ms(180), easing: EASE_OUT },
            );
            continue;
          }
          const dx = old.left - now.left;
          const dy = old.top - now.top;
          const sy = now.height > 0 ? old.height / now.height : 1;
          if (Math.abs(dx) < 1 && Math.abs(dy) < 1 && Math.abs(sy - 1) < 0.01) continue;
          node.animate(
            [
              {
                transform: `translate(${dx}px, ${dy}px) scaleY(${sy})`,
                transformOrigin: "top left",
              },
              { transform: "none", transformOrigin: "top left" },
            ],
            { duration: ms(200), easing: SPRING },
          );
        }
    },
    [store, registry],
  );

  const undo = useCallback(() => {
    const entry = past.pop();
    if (!entry) return;
    typing.current = null;
    future.push(entry);
    replay(entry, entry.before);
  }, [past, future, replay]);

  const redo = useCallback(() => {
    const entry = future.pop();
    if (!entry) return;
    typing.current = null;
    past.push(entry);
    replay(entry, entry.after);
  }, [past, future, replay]);

  return { undo, redo };
}

"use client";

/**
 * use-marquee — ⌘/Ctrl-drag a box to select events (⇧ keeps the existing selection).
 * `week-grid` offers pointerdown here first and only arms the drag engine if declined.
 */

import type React from "react";
import type { RefObject } from "react";
import { useCallback, useEffect, useRef } from "react";
import { DRAG_THRESHOLD_PX, type PlacedEvent } from "../lib/calendar-types";
import { eventsInMarquee, type MarqueeRect } from "../lib/selection";
import { ms, prefersReducedMotion } from "../lib/springs";
import { useLatest } from "../lib/use-latest";
import { useKloqSettings } from "./settings-context";
import { isToggleModifier } from "./use-selection";

const EDGE_ZONE = 56;
const EDGE_MAX_V = 14;

interface MarqueeOptions {
  canvasRef: RefObject<HTMLElement | null>;
  boxRef: RefObject<HTMLElement | null>;
  scrollRef?: RefObject<HTMLElement | null>;
  dayCount: number;
  /** read per frame — must be cheap */
  getEvents: () => readonly PlacedEvent[];
  registry?: Map<string, HTMLElement>;
  onCommit: (ids: string[], additive: boolean) => void;
}

interface MarqueeState {
  pointerId: number;
  captureEl: HTMLElement;
  /** canvas coordinates, so scrolling mid-drag doesn't move it */
  anchorX: number;
  anchorY: number;
  clientX: number;
  clientY: number;
  additive: boolean;
  moved: boolean;
  cancelled: boolean;
  raf: number;
  painted: Map<string, { outline: string; outlineOffset: string }>;
  hits: string[];
}

interface MarqueeHandle {
  /** Returns `true` when it took the gesture — the caller must then not arm the drag engine. */
  tryStart(e: React.PointerEvent<HTMLElement>): boolean;
  isActive(): boolean;
}

const HIT_OUTLINE = "2px solid var(--ring)";

export function useMarquee(opts: MarqueeOptions): MarqueeHandle {
  const g = useKloqSettings();
  const o = useLatest(opts);
  const gRef = useLatest(g);
  const s = useRef<MarqueeState | null>(null);

  const nodeFor = useCallback((id: string): HTMLElement | null => {
    const fromRegistry = o.current.registry?.get(id);
    if (fromRegistry) return fromRegistry;
    const canvas = o.current.canvasRef.current;
    return canvas?.querySelector<HTMLElement>(`[data-cal-event="${CSS.escape(id)}"]`) ?? null;
  }, []);

  const paint = useCallback(
    (ids: string[]) => {
      const st = s.current;
      if (!st) return;
      const next = new Set(ids);
      for (const [id, prev] of st.painted) {
        if (next.has(id)) continue;
        const el = nodeFor(id);
        if (el) {
          el.style.outline = prev.outline;
          el.style.outlineOffset = prev.outlineOffset;
        }
        st.painted.delete(id);
      }
      for (const id of ids) {
        if (st.painted.has(id)) continue;
        const el = nodeFor(id);
        if (!el) continue;
        st.painted.set(id, {
          outline: el.style.outline,
          outlineOffset: el.style.outlineOffset,
        });
        el.style.outline = HIT_OUTLINE;
        el.style.outlineOffset = "1px";
      }
    },
    [nodeFor],
  );

  const unpaint = useCallback(() => {
    const st = s.current;
    if (!st) return;
    for (const [id, prev] of st.painted) {
      const el = nodeFor(id);
      if (el) {
        el.style.outline = prev.outline;
        el.style.outlineOffset = prev.outlineOffset;
      }
    }
    st.painted.clear();
  }, [nodeFor]);

  const teardown = useCallback(() => {
    const st = s.current;
    if (!st) return;
    cancelAnimationFrame(st.raf);
    unpaint();
    const box = o.current.boxRef.current;
    if (box) box.hidden = true;
    try {
      st.captureEl.releasePointerCapture(st.pointerId);
    } catch {}
    s.current = null;
  }, [unpaint]);

  const frame = useCallback(() => {
    const st = s.current;
    const canvas = o.current.canvasRef.current;
    const box = o.current.boxRef.current;
    if (!st || !canvas || !box) return;

    const scroller = o.current.scrollRef?.current;
    if (scroller && st.moved) {
      const r = scroller.getBoundingClientRect();
      const above = st.clientY - r.top;
      const below = r.bottom - st.clientY;
      if (above < EDGE_ZONE) scroller.scrollTop -= ((EDGE_ZONE - above) / EDGE_ZONE) * EDGE_MAX_V;
      else if (below < EDGE_ZONE)
        scroller.scrollTop += ((EDGE_ZONE - below) / EDGE_ZONE) * EDGE_MAX_V;
    }

    const rect = canvas.getBoundingClientRect();
    const x = st.clientX - rect.left;
    const y = st.clientY - rect.top;
    const m: MarqueeRect = { x1: st.anchorX, y1: st.anchorY, x2: x, y2: y };

    const left = Math.min(m.x1, m.x2);
    const top = Math.min(m.y1, m.y2);
    box.style.transform = `translate(${left}px, ${top}px)`;
    box.style.width = `${Math.abs(m.x2 - m.x1)}px`;
    box.style.height = `${Math.abs(m.y2 - m.y1)}px`;

    st.hits = eventsInMarquee(m, o.current.getEvents(), {
      dayCount: o.current.dayCount,
      width: rect.width,
      minutesToPx: gRef.current.minutesToPx,
    });
    paint(st.hits);
    st.raf = requestAnimationFrame(frame);
  }, [paint]);

  const engage = useCallback(() => {
    const st = s.current;
    const box = o.current.boxRef.current;
    if (!st || !box) return;
    st.moved = true;
    box.hidden = false;
    if (!prefersReducedMotion())
      box.animate([{ opacity: 0 }, { opacity: 1 }], {
        duration: ms(90),
        easing: "ease-out",
      });
  }, []);

  const tryStart = useCallback(
    (e: React.PointerEvent<HTMLElement>): boolean => {
      if (e.button !== 0) return false;
      // ⇧ alone does not arm: a bare ⇧-drag on empty grid must keep creating an event
      if (!isToggleModifier(e)) return false;
      if (s.current) return false;
      const canvas = o.current.canvasRef.current;
      if (!canvas) return false;
      const rect = canvas.getBoundingClientRect();
      const el = e.currentTarget;
      el.setPointerCapture(e.pointerId);
      s.current = {
        pointerId: e.pointerId,
        captureEl: el,
        anchorX: e.clientX - rect.left,
        anchorY: e.clientY - rect.top,
        clientX: e.clientX,
        clientY: e.clientY,
        additive: e.shiftKey,
        moved: false,
        cancelled: false,
        raf: 0,
        painted: new Map(),
        hits: [],
      };
      // the loop runs from the start but writes nothing until `moved`
      s.current.raf = requestAnimationFrame(frame);
      return true;
    },
    [frame],
  );

  useEffect(() => {
    function onMove(e: PointerEvent) {
      const st = s.current;
      if (!st || e.pointerId !== st.pointerId) return;
      st.clientX = e.clientX;
      st.clientY = e.clientY;
      if (st.moved) return;
      const canvas = o.current.canvasRef.current;
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const dist = Math.hypot(
        e.clientX - rect.left - st.anchorX,
        e.clientY - rect.top - st.anchorY,
      );
      if (dist >= DRAG_THRESHOLD_PX) engage();
    }

    function onUp(e: PointerEvent) {
      const st = s.current;
      if (!st || e.pointerId !== st.pointerId) return;
      const { moved, cancelled, hits, additive } = st;
      teardown();
      // a ⌘-click that never crossed the threshold is the grid's click, not a clear
      if (moved && !cancelled) o.current.onCommit(hits, additive);
    }

    function onCancel(e: PointerEvent) {
      const st = s.current;
      if (!st || e.pointerId !== st.pointerId) return;
      teardown();
    }

    function onKey(e: KeyboardEvent) {
      const st = s.current;
      if (!st || e.key !== "Escape") return;
      // capture phase: nothing focused may swallow the cancel
      e.preventDefault();
      e.stopImmediatePropagation();
      st.cancelled = true;
      teardown();
    }

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
    window.addEventListener("keydown", onKey, { capture: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      window.removeEventListener("keydown", onKey, { capture: true });
      teardown();
    };
  }, [engage, teardown]);

  return {
    tryStart,
    isActive: () => s.current !== null,
  };
}

import { type RefObject, useEffect, useLayoutEffect } from "react";
import { downloadICS } from "../lib/ics";
import type { PlacedEvent } from "../lib/placement";
import { useLatest } from "../lib/use-latest";
import { useAnnounce } from "./live-region";

// surfaces above the panel that answer Escape first
const OVERLAY_SELECTOR =
  '[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"], [data-popup]';

/** Focus, announcement, focus-restore, Escape and ⌘⇧E for the open panel. */
export function usePanelKeys({
  wrapRef,
  inputRef,
  eventId,
  event,
  isNew,
  readOnly,
  getAnchor,
  onCancel,
}: {
  wrapRef: RefObject<HTMLDivElement | null>;
  inputRef: RefObject<HTMLInputElement | null>;
  eventId: string;
  event: PlacedEvent;
  isNew: boolean;
  readOnly: boolean;
  getAnchor: (id: string) => HTMLElement | null;
  onCancel: () => void;
}) {
  const announce = useAnnounce();
  // only a new event pulls focus; otherwise the grid's roving tabindex keeps it (non-modal)
  useEffect(() => {
    if (!isNew || readOnly) return;
    const t = requestAnimationFrame(() => {
      inputRef.current?.focus();
      inputRef.current?.select();
    });
    return () => cancelAnimationFrame(t);
  }, [isNew, eventId, readOnly, inputRef]);

  useEffect(() => {
    if (isNew) return;
    announce("Event details open, press Tab to edit");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // a layout cleanup runs while the panel is still attached: if it held focus, hand it to
  // the block, or to the grid when the event is gone
  const restoreRef = useLatest({ getAnchor, eventId });
  useLayoutEffect(() => {
    const wrap = wrapRef.current;
    return () => {
      const active = document.activeElement;
      if (!wrap || !active || !wrap.contains(active)) return;
      const { getAnchor: get, eventId: id } = restoreRef.current;
      const root = wrap.closest("[data-kloq-root]");
      const next =
        get(id) ??
        root?.querySelector<HTMLElement>('[data-cal-event][tabindex="0"]') ??
        root?.querySelector<HTMLElement>("[role=region][tabindex]");
      next?.focus({ preventScroll: true });
    };
  }, [wrapRef, restoreRef]);

  // Escape abandons; a drag-created event is discarded rather than left untitled
  const cancelRef = useLatest(onCancel);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape" || e.defaultPrevented) return;
      const wrap = wrapRef.current;
      const target = e.target as Element | null;
      // topmost surface owns Escape; rrule/reminder fields stop it in capture — stay in bubble phase
      if (target?.closest?.(OVERLAY_SELECTOR) && !(wrap && wrap.contains(target))) return;
      // The panel owns this Escape even when focus remains on a timeline bar.
      // Mark it handled before closing so the calendar's document listener does
      // not see the newly closed panel and clear the selection on the same key.
      e.preventDefault();
      cancelRef.current();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [wrapRef, cancelRef]);

  // ⌘⇧E exports the selected event as .ics
  const eventRef = useLatest(event);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === "KeyE" && e.shiftKey && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        downloadICS(eventRef.current);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [eventRef]);
}

/** Every way a placement's time changes — drag, keyboard, panel, month chip — lands in commitPlacement. */
import { type RefObject, useCallback, useMemo } from "react";
import { flushSync } from "react-dom";
import {
  announceAllDay,
  announceColor,
  announceCreated,
  announceDuplicated,
  announceMoved,
  announceRefused,
  announceResized,
  announceSpanned,
  type WhenRef,
} from "../lib/announce";
import type { KloqStore } from "../lib/calendar-store";
import { allDaySlot, allows, type Constraints, type Slot } from "../lib/constraints";
import { MINUTES_PER_DAY } from "../lib/date-math";
import type { CommitResult } from "../lib/drag-engine/types";
import type { CalEvent, CalEventPatch } from "../lib/event-types";
import { dateOnlyAfter, dateOnlyAt, instantAt, instantPlus, parseInstant } from "../lib/instant";
import type { PlacedEvent } from "../lib/placement";
import { landedWhen, movedStart, wallDuration } from "../lib/placement-patch";
import type { Projection } from "../lib/projection";
import {
  applyPlan,
  editOccurrence,
  masterIdOf,
  type Occurrence,
  type RecurrencePlan,
  type RecurrenceScope,
} from "../lib/recurrence";
import { useLatest } from "../lib/use-latest";
import type { ViewDescriptor } from "../lib/view";
import { DEFAULT_QUICK_ADD_MIN } from "./kloq-command";
import { useKloqSettings } from "./settings-context";
import type { PlacedEventPatch } from "./use-calendar-keys";
import type { AskRecurrenceScope } from "./use-recurrence-scope";

/** A block demoted from all-day lands at 9am. */
const DEMOTED_START_MIN = 9 * 60;

export interface WhenInput {
  dayIndex: number;
  endDayIndex?: number;
  startMin?: number;
  endMin?: number;
  allDay?: boolean;
}

export interface PlacementCommitOptions {
  store: KloqStore;
  view: ViewDescriptor;
  projectedRef: RefObject<Projection>;
  askScope: AskRecurrenceScope | null;
  constraints?: Constraints;
  announce: (message: string) => void;
  whenOf: (p: WhenInput) => WhenRef;
  eventOf: (id: string) => { title?: string };
  onDefaultCalendar: { calendarId?: string } | undefined;
  authoredZone: { timeZone: string } | undefined;
  /** snapshot the blocks immediately before a mutation, so a deferred commit morphs from where they are THEN */
  snapshot: (masterId: string) => void;
  /** "this" / "this and following" mint a new event; the selection and panel must follow it */
  onPlanSelected: (from: string, to: string) => void;
  onCreated: (id: string) => void;
}

export function usePlacementCommits({
  store,
  view,
  projectedRef,
  askScope,
  constraints,
  announce,
  whenOf,
  eventOf,
  onDefaultCalendar,
  authoredZone,
  snapshot,
  onPlanSelected,
  onCreated,
}: PlacementCommitOptions) {
  const g = useKloqSettings();
  const zone = g.displayZone;
  const cb = useLatest({ snapshot, onPlanSelected, onCreated });
  const guard = useLatest({ constraints, announce });

  const timedWindow = (start: string, end: string): Slot => ({
    start: new Date(parseInstant(start)),
    end: new Date(parseInstant(end)),
    allDay: false,
  });

  /** Gesture-level refusal for the non-engine paths; the engine runs its own live probe. */
  const refuse = (
    gesture: "move" | "resize" | "duplicate",
    target: Slot,
    origin: Slot | undefined,
    event?: CalEvent,
  ): boolean => {
    const { constraints: c, announce: say } = guard.current;
    if (!c?.active) return false;
    if (allows(c, { gesture, target, origin, event })) return false;
    say(announceRefused(gesture, event));
    return true;
  };

  const commitPlacement = useCallback(
    (placementId: string, patch: CalEventPatch, say?: string): CommitResult => {
      const masterId = masterIdOf(placementId);
      const master = store.get(masterId);
      const occurrence: Occurrence | undefined = projectedRef.current.all.find(
        (e) => e.id === placementId,
      )?.occurrence;
      // a colour-only patch is not ambiguous and never asks
      const movesInTime = patch.start !== undefined || patch.end !== undefined;
      const snap = () => {
        if (movesInTime) cb.current.snapshot(masterId);
      };

      if (!master || !occurrence || !movesInTime) {
        snap();
        store.update(masterId, patch);
        if (say) announce(say);
        return;
      }

      const apply = (scope: RecurrenceScope) => {
        const plan = editOccurrence(master, occurrence, patch, scope, { makeId: g.makeId });
        applyPlan(store, plan);
        return plan;
      };

      // no asker mounted: fall back to the lossless whole-series shift
      if (!askScope) {
        snap();
        apply("all");
        if (say) announce(say);
        return;
      }

      return askScope({ action: "edit", event: master, occurrence }).then((scope) => {
        if (!scope) return false;
        // flush before resolving: the engine clears its transform on `true`
        let plan: RecurrencePlan | undefined;
        snap();
        flushSync(() => {
          plan = apply(scope);
        });
        if (plan?.selectId) cb.current.onPlanSelected(placementId, plan.selectId);
        if (say) announce(say);
        return true;
      });
    },
    [store, projectedRef, askScope, announce, cb, g.makeId],
  );

  const timedAt = (id: string) => projectedRef.current.timed.find((e) => e.id === id);

  const commitCreate = useCallback(
    (draft: {
      dayIndex: number;
      startMin: number;
      endMin: number;
      allDay?: boolean;
      endDayIndex?: number;
    }) => {
      const id = g.makeId();
      store.add(
        draft.allDay
          ? {
              id,
              title: "",
              ...onDefaultCalendar,
              allDay: true,
              start: dateOnlyAt(view, draft.dayIndex),
              end: dateOnlyAfter(view, draft.endDayIndex ?? draft.dayIndex),
            }
          : {
              id,
              title: "",
              ...onDefaultCalendar,
              ...authoredZone,
              start: instantAt(view, draft.dayIndex, draft.startMin, zone),
              end: instantAt(view, draft.dayIndex, draft.endMin, zone),
            },
      );
      cb.current.onCreated(id);
      announce(announceCreated({ title: "" }, whenOf(draft)));
      return id;
    },
    [store, view, zone, g, onDefaultCalendar, authoredZone, cb, announce, whenOf],
  );

  const commitMove = useCallback(
    (id: string, patch: { dayIndex: number; startMin: number }): CommitResult => {
      const ev = store.get(masterIdOf(id));
      if (!ev || ev.allDay) return;
      const placed = timedAt(id);
      const duration = wallDuration(ev, zone);
      const start = movedStart(placed, view, zone, patch);
      // returned: a promise tells the engine to keep the block welded until the scope is answered
      return commitPlacement(
        id,
        { start, end: instantPlus(start, duration, zone) },
        announceMoved(ev, whenOf(landedWhen(placed, zone, patch, duration))),
      );
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [store, view, zone, commitPlacement, whenOf],
  );

  const commitResize = useCallback(
    (id: string, patch: { startMin: number; endMin: number }): CommitResult => {
      const placed = timedAt(id);
      if (!placed) return;
      // on a segment only the edge that is really the event's edge may be written; midnight is a cut
      const first = placed.segment.i === 0;
      const last = placed.segment.i === placed.segment.n - 1;
      return commitPlacement(
        id,
        {
          start: first ? instantAt(view, placed.dayIndex, patch.startMin, zone) : placed.start,
          end: last ? instantAt(view, placed.dayIndex, patch.endMin, zone) : placed.end,
        },
        announceResized(eventOf(id), { time: g.formatRange(patch.startMin, patch.endMin) }),
      );
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [view, zone, commitPlacement, eventOf, g],
  );

  const commitSpan = useCallback(
    (id: string, patch: { dayIndex: number; endDayIndex: number }): CommitResult =>
      commitPlacement(
        id,
        { start: dateOnlyAt(view, patch.dayIndex), end: dateOnlyAfter(view, patch.endDayIndex) },
        announceSpanned(eventOf(id), whenOf({ ...patch, allDay: true })),
      ),
    [view, commitPlacement, eventOf, whenOf],
  );

  const commitDuplicate = useCallback(
    (sourceId: string, patch: { dayIndex: number; startMin: number }): string => {
      const src = store.get(masterIdOf(sourceId));
      const id = g.makeId();
      if (!src || src.allDay) return id;
      const duration = wallDuration(src, zone);
      const placed = timedAt(sourceId);
      const start = movedStart(placed, view, zone, patch);
      const end = instantPlus(start, duration, zone);
      if (refuse("duplicate", timedWindow(start, end), undefined, src)) return id;
      // copy THAT occurrence, not the series: `...src` would carry the master's `rrule`
      const detach = src.rrule
        ? ({ rrule: undefined, exdates: undefined, recurrenceId: undefined } as const)
        : null;
      store.add({ ...src, ...detach, id, start, end });
      announce(announceDuplicated(src, whenOf(landedWhen(placed, zone, patch, duration))));
      return id;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [store, view, zone, g, announce, whenOf],
  );

  const toggleAllDay = useCallback(
    (placed: PlacedEvent, allDay: boolean) => {
      // the placement id, not `source.id`: commitPlacement needs the occurrence
      const id = placed.id;
      if (placed.source.readOnly) return;
      if (allDay) {
        // the origin is discarded on an all-day-ness flip (`newlyOccupied`), so none is built
        if (
          refuse(
            "move",
            allDaySlot(view, placed.dayIndex, placed.endDayIndex),
            undefined,
            placed.source,
          )
        )
          return;
        void commitPlacement(
          id,
          {
            allDay: true,
            start: dateOnlyAt(view, placed.dayIndex),
            end: dateOnlyAfter(view, placed.endDayIndex),
          } as CalEventPatch,
          announceAllDay(placed.source, true, { day: view.namesLong[placed.dayIndex] }),
        );
        return;
      }
      const startMin = g.clampMinutes(DEMOTED_START_MIN);
      const endMin = Math.min(
        g.dayEndMin,
        startMin + Math.max(g.minEventMinutes, DEFAULT_QUICK_ADD_MIN),
      );
      const start = instantAt(view, placed.dayIndex, startMin, zone);
      const end = instantAt(view, placed.dayIndex, endMin, zone);
      if (refuse("move", timedWindow(start, end), undefined, placed.source)) return;
      void commitPlacement(
        id,
        { allDay: false, start, end } as CalEventPatch,
        announceAllDay(placed.source, false, {
          day: view.namesLong[placed.dayIndex],
          time: g.formatRange(startMin, endMin),
        }),
      );
    },
    [commitPlacement, view, zone, g],
  );

  /** Month/agenda chips: shift by whole days, anchored off the placement. */
  const moveByDays = useCallback(
    (id: string, days: number): CommitResult => {
      const placed = projectedRef.current.all.find((e) => e.id === id);
      if (!placed || placed.source.readOnly || days === 0) return;
      if (placed.allDay) {
        // clamp so the whole span stays on the grid
        const lo = Math.max(
          -placed.dayIndex,
          Math.min(view.dayCount - 1 - placed.endDayIndex, days),
        );
        if (lo === 0) return;
        if (
          refuse(
            "move",
            allDaySlot(view, placed.dayIndex + lo, placed.endDayIndex + lo),
            allDaySlot(view, placed.dayIndex, placed.endDayIndex),
            placed.source,
          )
        )
          return;
        return commitPlacement(
          id,
          {
            start: dateOnlyAt(view, placed.dayIndex + lo),
            end: dateOnlyAfter(view, placed.endDayIndex + lo),
          },
          announceMoved(
            placed.source,
            whenOf({
              dayIndex: placed.dayIndex + lo,
              endDayIndex: placed.endDayIndex + lo,
              allDay: true,
            }),
          ),
        );
      }
      const duration = wallDuration(placed, zone);
      const target = { dayIndex: placed.dayIndex + days, startMin: placed.startMin };
      const start = movedStart(placed, view, zone, target, true);
      const end = instantPlus(start, duration, zone);
      if (
        refuse(
          "move",
          timedWindow(start, end),
          timedWindow(placed.start, placed.end),
          placed.source,
        )
      )
        return;
      return commitPlacement(
        id,
        { start, end },
        announceMoved(placed.source, whenOf(landedWhen(placed, zone, target, duration, true))),
      );
    },
    [projectedRef, view, zone, commitPlacement, whenOf],
  );

  /** The keyboard patch is partial column space; reconstitute it against the full placement. */
  const keyboardPatch = useCallback(
    (id: string, patch: PlacedEventPatch) => {
      const placed = projectedRef.current.all.find((e) => e.id === id);
      if (!placed || placed.readOnly) return;
      const next: CalEventPatch = {};
      if (patch.color !== undefined) next.color = patch.color;
      const movesInTime =
        patch.dayIndex !== undefined ||
        patch.endDayIndex !== undefined ||
        patch.startMin !== undefined ||
        patch.endMin !== undefined;
      const col = patch.dayIndex ?? placed.dayIndex;
      if (movesInTime) {
        if (placed.allDay) {
          next.start = dateOnlyAt(view, col);
          next.end = dateOnlyAfter(view, patch.endDayIndex ?? placed.endDayIndex);
        } else if (placed.segment.n > 1) {
          // one day of a cross-midnight event: same delta/edge rules as the drag commits
          const first = placed.segment.i === 0;
          const last = placed.segment.i === placed.segment.n - 1;
          const startEdgeOnly =
            patch.startMin !== undefined &&
            patch.endMin === undefined &&
            patch.dayIndex === undefined;
          const endEdgeOnly =
            patch.endMin !== undefined &&
            patch.startMin === undefined &&
            patch.dayIndex === undefined;
          if (startEdgeOnly || endEdgeOnly) {
            if (startEdgeOnly && !first) return;
            if (endEdgeOnly && !last) return;
            next.start = startEdgeOnly
              ? instantAt(view, placed.dayIndex, patch.startMin!, zone)
              : placed.start;
            next.end = endEdgeOnly
              ? instantAt(view, placed.dayIndex, patch.endMin!, zone)
              : placed.end;
          } else {
            const delta =
              (col - placed.dayIndex) * MINUTES_PER_DAY +
              ((patch.startMin ?? placed.startMin) - placed.startMin);
            if (delta === 0) return;
            next.start = instantPlus(placed.start, delta, zone);
            next.end = instantPlus(next.start, wallDuration(placed, zone), zone);
          }
        } else {
          next.start = instantAt(view, col, patch.startMin ?? placed.startMin, zone);
          next.end = instantAt(view, col, patch.endMin ?? placed.endMin, zone);
        }
      }
      const resizeOnly =
        patch.startMin === undefined && patch.endMin !== undefined && patch.dayIndex === undefined;
      if (movesInTime) {
        const target = placed.allDay
          ? allDaySlot(view, col, patch.endDayIndex ?? placed.endDayIndex)
          : timedWindow(next.start as string, next.end as string);
        const origin = placed.allDay
          ? allDaySlot(view, placed.dayIndex, placed.endDayIndex)
          : timedWindow(placed.start, placed.end);
        if (refuse(resizeOnly ? "resize" : "move", target, origin, placed.source)) return;
      }
      // the announcement is handed to the commit, which may be deferred behind the scope dialog
      const say =
        patch.color !== undefined
          ? announceColor([placed.source], patch.color)
          : !movesInTime
            ? undefined
            : placed.allDay
              ? announceMoved(
                  placed.source,
                  whenOf({
                    dayIndex: col,
                    endDayIndex: patch.endDayIndex ?? placed.endDayIndex,
                    allDay: true,
                  }),
                )
              : resizeOnly
                ? announceResized(placed.source, {
                    time: g.formatRange(placed.startMin, patch.endMin!),
                  })
                : announceMoved(
                    placed.source,
                    whenOf(
                      placed.segment.n > 1
                        ? landedWhen(
                            placed,
                            zone,
                            { dayIndex: col, startMin: patch.startMin ?? placed.startMin },
                            wallDuration(placed, zone),
                          )
                        : {
                            dayIndex: col,
                            startMin: patch.startMin ?? placed.startMin,
                            endMin: patch.endMin ?? placed.endMin,
                          },
                    ),
                  );
      void commitPlacement(id, next, say);
    },
    [projectedRef, view, zone, commitPlacement, whenOf, g],
  );

  return useMemo(
    () => ({
      commitPlacement,
      commitCreate,
      commitMove,
      commitResize,
      commitSpan,
      commitDuplicate,
      toggleAllDay,
      moveByDays,
      keyboardPatch,
    }),
    [
      commitPlacement,
      commitCreate,
      commitMove,
      commitResize,
      commitSpan,
      commitDuplicate,
      toggleAllDay,
      moveByDays,
      keyboardPatch,
    ],
  );
}

export type PlacementCommits = ReturnType<typeof usePlacementCommits>;

/** Quick-create at the next hour, at a pointer, or on a double-click on empty grid. */
import { type RefObject, useCallback } from "react";
import { announceCreated, announceRefused, type WhenRef } from "../lib/announce";
import type { KloqStore } from "../lib/calendar-store";
import { type Constraints, slotAllowed, timedSlot } from "../lib/constraints";
import { snapMinutes } from "../lib/grid-defaults";
import { instantAt, instantPlus, parseInstant } from "../lib/instant";
import { nodeFor } from "../lib/recurrence";
import { KEYBOARD_SPRING, KEYBOARD_SPRING_MS, prefersReducedMotion } from "../lib/springs";
import { useLatest } from "../lib/use-latest";
import type { ViewDescriptor } from "../lib/view";
import { DEFAULT_QUICK_ADD_MIN } from "./kloq-command";
import { useKloqSettings } from "./settings-context";
import type { WhenInput } from "./use-placement-commits";

export function useQuickCreate({
  store,
  view,
  registry,
  canvasRef,
  onDefaultCalendar,
  authoredZone,
  constraints,
  announce,
  whenOf,
  onCreated,
}: {
  store: KloqStore;
  view: ViewDescriptor;
  registry: Map<string, HTMLElement>;
  canvasRef: RefObject<HTMLDivElement | null>;
  onDefaultCalendar: { calendarId?: string } | undefined;
  authoredZone: { timeZone: string } | undefined;
  constraints?: Constraints;
  announce: (message: string) => void;
  whenOf: (p: WhenInput) => WhenRef;
  onCreated: (id: string) => void;
}) {
  const g = useKloqSettings();
  const cb = useLatest({ onCreated });

  // `pxToMinutes` already restores the day-window offset; don't add `dayStartMin` again
  const slotAt = (canvas: HTMLElement, e: { clientX: number; clientY: number }) => {
    const rect = canvas.getBoundingClientRect();
    const col = Math.max(
      0,
      Math.min(
        view.dayCount - 1,
        Math.floor(((e.clientX - rect.left) / rect.width) * view.dayCount),
      ),
    );
    const min = Math.min(
      g.dayEndMin - DEFAULT_QUICK_ADD_MIN,
      Math.max(g.dayStartMin, snapMinutes(g.pxToMinutes(e.clientY - rect.top), g.snapMinutes)),
    );
    return { col, min };
  };

  const quickCreate = useCallback(
    (col?: number, startMin?: number) => {
      const day = col ?? (view.todayIndex >= 0 ? view.todayIndex : 0);
      // the display zone's next whole hour, clamped into the configured day range
      const start =
        startMin ??
        Math.max(
          g.dayStartMin,
          Math.min((g.displayNow().getHours() + 1) * 60, g.dayEndMin - DEFAULT_QUICK_ADD_MIN),
        );
      if (
        constraints?.active &&
        !slotAllowed(
          constraints,
          timedSlot(view, day, start, start + DEFAULT_QUICK_ADD_MIN, g.fromDisplay),
        )
      ) {
        announce(announceRefused("create"));
        return;
      }
      const id = g.makeId();
      store.add({
        id,
        title: "",
        ...onDefaultCalendar,
        ...authoredZone,
        start: instantAt(view, day, start, g.displayZone),
        end: instantAt(view, day, start + DEFAULT_QUICK_ADD_MIN, g.displayZone),
      });
      cb.current.onCreated(id);
      announce(
        announceCreated(
          { title: "" },
          whenOf({
            dayIndex: day,
            startMin: start,
            endMin: start + DEFAULT_QUICK_ADD_MIN,
          }),
        ),
      );
      requestAnimationFrame(() =>
        requestAnimationFrame(() => {
          const node = nodeFor(registry, id);
          if (!node) return;
          node.scrollIntoView({ block: "center", behavior: "smooth" });
          if (!prefersReducedMotion())
            node.animate(
              [
                { opacity: 0, transform: "scale(0.92)" },
                { opacity: 1, transform: "none" },
              ],
              { duration: KEYBOARD_SPRING_MS, easing: KEYBOARD_SPRING },
            );
        }),
      );
    },
    [view, store, registry, g, announce, whenOf, onDefaultCalendar, authoredZone, constraints, cb],
  );

  // promote to / demote from the all-day lane — the keyboard's only route in

  // snap a pointer position on the canvas to a slot, exactly as drag-create does
  const slotAtPointer = useCallback(
    (e: { clientX: number; clientY: number }) => {
      const canvas = canvasRef.current;
      if (!canvas) return null;
      const { col, min } = slotAt(canvas, e);
      const start = instantAt(view, col, min, g.displayZone);
      return {
        start: new Date(parseInstant(start)),
        end: new Date(parseInstant(instantPlus(start, DEFAULT_QUICK_ADD_MIN, g.displayZone))),
        allDay: false,
      };
    },
    [view, g],
  );

  const onCanvasDoubleClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const canvas = canvasRef.current;
      if (!canvas || (e.target as HTMLElement).closest("[data-cal-event]")) return;
      const { col, min } = slotAt(canvas, e);
      quickCreate(col, min);
    },
    [view, quickCreate, g],
  );

  return { quickCreate, slotAtPointer, onCanvasDoubleClick };
}

"use client";

/**
 * Promise-based "this / this and following / all" chooser, mounted once at the calendar root.
 * Dismissal resolves `null` — never treat `null` as "all", that deletes whole series.
 */

import type { ReactNode } from "react";
import { createContext, useCallback, useContext, useRef, useState } from "react";
import type { CalEvent } from "../lib/calendar-types";
import { type Occurrence, RECURRENCE_SCOPES, type RecurrenceScope } from "../lib/recurrence";
import { describeRRule, parseRRule } from "../lib/rrule";
import { type RecurrenceScopeAction, RecurrenceScopeDialog } from "./recurrence-scope-dialog";

interface RecurrenceScopeRequest {
  /** what the answer will be used for — copy and button colour hang off it */
  action: RecurrenceScopeAction;
  /** the MASTER store event, never a placement */
  event: CalEvent;
  /** which instance of the series is being acted on */
  occurrence: Occurrence;
}

/** Ask, and get an answer or `null` for "they dismissed it". */
export type AskRecurrenceScope = (
  request: RecurrenceScopeRequest,
) => Promise<RecurrenceScope | null>;

const ScopeContext = createContext<AskRecurrenceScope | null>(null);

/** The asker, or `null` outside a provider — callers must branch, not assume "all". */
export function useRecurrenceScope(): AskRecurrenceScope | null {
  return useContext(ScopeContext);
}

export function RecurrenceScopeProvider({ children }: { children: ReactNode }) {
  const [request, setRequest] = useState<RecurrenceScopeRequest | null>(null);
  // a ref, not state: settling a promise is not a render input
  const resolver = useRef<((scope: RecurrenceScope | null) => void) | null>(null);

  const settle = useCallback((scope: RecurrenceScope | null) => {
    const resolve = resolver.current;
    resolver.current = null;
    setRequest(null);
    resolve?.(scope);
  }, []);

  const ask = useCallback<AskRecurrenceScope>(
    (next) =>
      new Promise((resolve) => {
        // a new question dismisses the open one so no caller awaits a promise that never settles
        resolver.current?.(null);
        resolver.current = resolve;
        setRequest(next);
      }),
    [],
  );

  // on the first occurrence "this and following" equals "all", so don't offer both
  const scopes = request?.occurrence.isFirst ? (["this", "all"] as const) : RECURRENCE_SCOPES;

  const parts = request?.event.rrule ? parseRRule(request.event.rrule) : null;

  return (
    <ScopeContext.Provider value={ask}>
      {children}
      <RecurrenceScopeDialog
        open={request !== null}
        onOpenChange={(open) => {
          if (!open && resolver.current) settle(null);
          else if (!open) setRequest(null);
        }}
        action={request?.action ?? "edit"}
        title={request?.event.title}
        summary={parts ? describeRRule(parts) : undefined}
        scopes={scopes}
        onChoose={settle}
        onCancel={() => settle(null)}
      />
    </ScopeContext.Provider>
  );
}

"use client";

/**
 * use-responsive — measure the calendar's own box (not the viewport), resolve the effective view.
 * The decision lives in `lib/responsive.ts`; render from `effective`, not the view setting.
 */

import { useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react";
import type { KloqView } from "../lib/calendar-types";
import {
  type EffectiveView,
  effectiveView,
  isNarrow,
  type ResolvedResponsive,
  type ResponsiveSetting,
  reconcileIntent,
  resolveResponsive,
} from "../lib/responsive";

interface UseResponsiveViewOptions {
  hostRef: React.RefObject<HTMLElement | null>;
  view: KloqView;
  /** `<Kloq responsive>`; on by default, `false` opts out entirely */
  responsive?: ResponsiveSetting;
  /** report a view change; MUST be the same function the switcher uses */
  onRequestView: (view: KloqView) => void;
}

export interface ResponsiveState extends EffectiveView {
  /** measured width of the host box, or 0 before the first observation */
  readonly width: number;
  readonly narrow: boolean;
  readonly config: ResolvedResponsive;
}

export function useResponsiveView({
  hostRef,
  view,
  responsive,
  onRequestView,
}: UseResponsiveViewOptions): ResponsiveState {
  const config = resolveResponsive(responsive);
  const [width, setWidth] = useState(0);

  const resolved = effectiveView(width, view, config);

  // held in a ref: the effect must re-run on width only, or the collapse fights the host
  const live = useRef({ view, onRequestView, config });
  useEffect(() => {
    // declared first so the width effect reads a current intent
    live.current = { view, onRequestView, config };
  });

  const collapsed = useRef<{ from: KloqView; to: KloqView } | null>(null);

  // a layout effect: the first frame painted on the client is already the view that fits
  useLayoutEffect(() => {
    const el = hostRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver((entries) => {
      // `contentRect.width`: the root's own padding is not room for columns
      setWidth(entries[0]?.contentRect.width ?? el.clientWidth);
    });
    ro.observe(el);
    setWidth(el.clientWidth);
    return () => ro.disconnect();
  }, [hostRef]);

  useEffect(() => {
    const { view: intent, onRequestView: request, config: cfg } = live.current;
    if (!cfg.enabled || width <= 0) return;

    const memo = collapsed.current;
    if (memo && intent === memo.to) {
      // we're driving: re-resolve from the original intent across the tiers
      const back = reconcileIntent(width, intent, memo.from, memo.to, cfg);
      if (back === null) return;
      if (back === memo.from) collapsed.current = null;
      else memo.to = back;
      request(back);
      return;
    }

    const next = effectiveView(width, intent, cfg);
    if (next.collapsed) {
      collapsed.current = { from: intent, to: next.effective };
      request(next.effective);
    } else {
      collapsed.current = null;
    }
  }, [width]);

  return { ...resolved, width, narrow: isNarrow(width, config), config };
}

const COARSE = "(pointer: coarse)";
const watchCoarse = (onChange: () => void) => {
  const mq = matchMedia(COARSE);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
};
const isCoarse = () => matchMedia(COARSE).matches;
const notCoarse = () => false;

/** True on touch-first devices, where chips sit on a 24px pitch instead of the pointer one. */
export function useCoarsePointer(): boolean {
  return useSyncExternalStore(
    typeof matchMedia === "undefined" ? () => () => {} : watchCoarse,
    typeof matchMedia === "undefined" ? notCoarse : isCoarse,
    notCoarse,
  );
}

import { useEffect, useState } from "react";

const POPUP = "[data-slot$='-popup']";
// an overlay that is open now, or the event panel: focus there was put there on purpose
const TAKEN = "[data-slot$='-popup']:not([data-closed]), [data-event-panel]";
let lastOutside: HTMLElement | null = null;

function track(e: FocusEvent) {
  const el = e.target as HTMLElement | null;
  if (el && !el.closest(POPUP)) lastOutside = el;
}

/**
 * `finalFocus` for a dialog opened without a trigger: whatever held focus before it
 * opened. It stands down when something else has taken focus since.
 */
export function useReturnFocus(open: boolean | undefined): () => HTMLElement | boolean {
  const [wasOpen, setWasOpen] = useState(false);
  const [target, setTarget] = useState<HTMLElement | null>(null);

  useEffect(() => {
    document.addEventListener("focusin", track);
    return () => document.removeEventListener("focusin", track);
  }, []);

  if (Boolean(open) !== wasOpen) {
    setWasOpen(Boolean(open));
    if (open && typeof document !== "undefined") {
      const active = document.activeElement as HTMLElement | null;
      setTarget(
        active && active !== document.body && !active.closest(POPUP) ? active : lastOutside,
      );
    }
  }
  return () => {
    const active = document.activeElement as HTMLElement | null;
    if (active?.closest(TAKEN)) return false;
    return target?.isConnected ? target : true;
  };
}

/** Optimistic revert: FLIP the block back to where it was, then shake it. Called pre-revert. */
import { useCallback } from "react";
import { announceReverted } from "../lib/announce";
import { entriesFor } from "../lib/recurrence";
import { ms, prefersReducedMotion, SPRING, SPRING_MS } from "../lib/springs";
import type { Announce } from "./live-region";

export function useRevertAnimation({
  registry,
  announce,
  eventOf,
}: {
  registry: Map<string, HTMLElement>;
  announce: Announce;
  eventOf: (id: string) => { title?: string };
}) {
  return useCallback(
    (ids: string[]) => {
      // assertive: with reduced motion the shake is gone and this is the only signal
      announce(announceReverted(ids.map((id) => eventOf(id))), "assertive");
      if (prefersReducedMotion()) return;
      // keyed by placement id (one event, many nodes); `preLead` covers ids changed by the revert
      const pre = new Map<string, DOMRect>();
      const preLead = new Map<string, DOMRect>();
      for (const id of ids) {
        for (const [key, node] of entriesFor(registry, id)) {
          const rect = node.getBoundingClientRect();
          pre.set(key, rect);
          if (!preLead.has(id)) preLead.set(id, rect);
        }
      }
      // double rAF: the revert has re-rendered by the second frame
      requestAnimationFrame(() =>
        requestAnimationFrame(() => {
          for (const id of ids)
            for (const [key, node] of entriesFor(registry, id)) {
              const old = pre.get(key) ?? preLead.get(id);
              const shake = () =>
                node.animate(
                  [
                    { transform: "translateX(0)" },
                    { transform: "translateX(-5px)" },
                    { transform: "translateX(4px)" },
                    { transform: "translateX(-2px)" },
                    { transform: "translateX(0)" },
                  ],
                  { duration: ms(260), easing: "ease-out" },
                );
              if (!old) {
                shake();
                continue;
              }
              const now = node.getBoundingClientRect();
              const dx = old.left - now.left;
              const dy = old.top - now.top;
              const sy = now.height > 0 ? old.height / now.height : 1;
              if (Math.abs(dx) < 1 && Math.abs(dy) < 1 && Math.abs(sy - 1) < 0.01) {
                shake();
                continue;
              }
              const anim = node.animate(
                [
                  {
                    transform: `translate(${dx}px, ${dy}px) scaleY(${sy})`,
                    transformOrigin: "left top",
                  },
                  { transform: "none", transformOrigin: "left top" },
                ],
                { duration: SPRING_MS, easing: SPRING },
              );
              anim.onfinish = shake;
            }
        }),
      );
    },
    [registry, announce, eventOf],
  );
}

"use client";

/**
 * use-selection — selection state plus everything that acts on it. Called once by
 * `calendar-app`, published via context; bulk mutations go through `store.batch()`.
 */

import type { RefObject } from "react";
import { createContext, useCallback, useContext, useMemo, useRef, useState } from "react";
import type { KloqSettings } from "../lib/calendar-config";
import type { KloqBatchOp, KloqStore } from "../lib/calendar-store";
import {
  addDays,
  asPlacementId,
  type CalEvent,
  dateOnlyAt,
  type EventColor,
  formatInstant,
  type Instant,
  instantAt,
  minutesOfDate,
  type PlacedEvent,
  parseInstant,
  type ViewDescriptor,
  wallMinutesBetween,
} from "../lib/calendar-types";
import { readEventsFromClipboard, rebaseEvents, writeEventsToClipboard } from "../lib/clipboard";
import type { PlacedOccurrence } from "../lib/projection";
import { masterIdOf, nodesFor, occurrenceStartOf, withoutSegment } from "../lib/recurrence";
import {
  addToSelection,
  applySelectionClick,
  EMPTY_SELECTION,
  eventKeyOf,
  isSelected,
  nearestOfSeries,
  remapSelection,
  removeFromSelection,
  replaceSelection,
  retainSelection,
  type SelectionModifiers,
  type SelectionState,
  selectAll as selectAllIds,
  selectionIndex,
  selectionOrder,
  selectOnly,
} from "../lib/selection";
import { KEYBOARD_SPRING, KEYBOARD_SPRING_MS, prefersReducedMotion } from "../lib/springs";
import { useLatest } from "../lib/use-latest";
import { useKloqSettings } from "./settings-context";

interface PasteAnchor {
  col: number;
  startMin: number;
}

interface NudgeDelta {
  days?: number;
  minutes?: number;
}

export interface KloqSelectionHandle {
  state: SelectionState;
  ids: readonly string[];
  count: number;
  lead: string | null;
  has(id: string): boolean;
  /** 1-based, or 0 */
  indexOf(id: string): number;

  click(id: string, mods: SelectionModifiers): void;
  setLead(id: string | null): void;
  replace(ids: readonly string[]): void;
  selectAll(): void;
  clear(): void;
  applyMarquee(ids: readonly string[], additive: boolean): void;
  extendTo(id: string): void;

  selectedEvents(): CalEvent[];

  /** hovered slot, written per-pointermove — a paste input, not a render input */
  hover: RefObject<PasteAnchor | null>;

  /** explicit `ids` act on something other than the selection (context menu) */
  copy(ids?: readonly string[]): void;
  cut(ids?: readonly string[]): void;
  paste(): void;
  duplicate(): void;
  remove(ids?: readonly string[]): void;
  recolor(color: EventColor): void;
  /** refuses rather than clamping, so the set keeps its shape */
  nudge(delta: NudgeDelta): void;
}

interface SelectionControllerOptions {
  store: KloqStore;
  view: ViewDescriptor;
  projected: readonly PlacedEvent[];
  registry: Map<string, HTMLElement>;
}

// calendar days, not days * 1440: a move across DST must keep the same clock time
function shiftInstant(instant: Instant, delta: NudgeDelta): Instant {
  const ms = parseInstant(instant);
  if (Number.isNaN(ms)) return instant;
  const d = addDays(new Date(ms), delta.days ?? 0);
  d.setMinutes(d.getMinutes() + (delta.minutes ?? 0));
  return formatInstant(d);
}

function outsideWindow(e: CalEvent, delta: NudgeDelta, g: KloqSettings): boolean {
  if (e.allDay) return false;
  const start = parseInstant(e.start);
  if (Number.isNaN(start)) return true;
  const duration = wallMinutesBetween(e.start, e.end);
  const min = minutesOfDate(new Date(start)) + (delta.minutes ?? 0);
  return min < g.dayStartMin || min + duration > g.dayEndMin;
}

export function useSelectionController({
  store,
  view,
  projected,
  registry,
}: SelectionControllerOptions): KloqSelectionHandle {
  const g = useKloqSettings();
  const [state, setState] = useState<SelectionState>(EMPTY_SELECTION);
  const hover = useRef<PasteAnchor | null>(null);

  const order = useMemo(() => selectionOrder(projected), [projected]);
  const visible = useMemo(() => new Set(order), [order]);

  // lead placement per event key — keeps a selection alive when a resize re-keys `base` to `base@0`
  const leadByKey = useMemo(() => {
    const byId = new Map(projected.map((p) => [p.id as string, p]));
    const m = new Map<string, string>();
    for (const id of order) {
      const p = byId.get(id);
      if (p) m.set(eventKeyOf(p), id);
    }
    return m;
  }, [order, projected]);

  // render-phase prune; both helpers return the same object when unchanged, so this doesn't loop.
  // An id that vanished under a rule edit follows its series to the nearest occurrence.
  const live = retainSelection(
    remapSelection(state, (id) =>
      visible.has(asPlacementId(id))
        ? undefined
        : (leadByKey.get(withoutSegment(id)) ??
          nearestOfSeries(
            projected,
            id,
            occurrenceStartOf(id) ?? store.get(masterIdOf(id))?.start ?? null,
          )),
    ),
    visible,
  );
  if (live !== state) setState(live);

  const latest = useLatest({ store, view, projected, order, state: live, g, registry });

  const popIn = useCallback((ids: readonly string[]) => {
    if (prefersReducedMotion()) return;
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        for (const id of ids) {
          for (const node of nodesFor(latest.current.registry, id))
            node.animate(
              [
                { opacity: 0, transform: "scale(0.92)" },
                { opacity: 1, transform: "none" },
              ],
              { duration: KEYBOARD_SPRING_MS, easing: KEYBOARD_SPRING },
            );
        }
      }),
    );
  }, []);

  const resolve = useCallback((ids?: readonly string[]): CalEvent[] => {
    const { state: s, store: st, order: ord } = latest.current;
    const rank = new Map<string, number>(ord.map((id, i) => [id, i]));
    return (
      [...(ids ?? s.ids)]
        .sort((a, b) => (rank.get(a) ?? 0) - (rank.get(b) ?? 0))
        // strip only the segment suffix; recurring instances fall through to `resolveForCopy`
        .map((id) => st.get(id) ?? st.get(withoutSegment(id)))
        .filter((e): e is CalEvent => e !== undefined)
    );
  }, []);

  // a recurring instance materialises as that occurrence, detached
  const resolveForCopy = useCallback((ids?: readonly string[]): CalEvent[] => {
    const { state: s, store: st, order: ord, projected: proj } = latest.current;
    const rank = new Map<string, number>(ord.map((id, i) => [id, i]));
    const out: CalEvent[] = [];
    for (const id of [...(ids ?? s.ids)].sort((a, b) => (rank.get(a) ?? 0) - (rank.get(b) ?? 0))) {
      const direct = st.get(id) ?? st.get(withoutSegment(id));
      if (direct) {
        out.push(direct);
        continue;
      }
      const placed = proj.find((e) => e.id === id) as PlacedOccurrence | undefined;
      const occ = placed?.occurrence;
      const master = occ && st.get(masterIdOf(id));
      if (!occ || !master) continue;
      const { rrule: _r, exdates: _x, recurrenceId: _i, ...rest } = master;
      out.push({ ...rest, start: occ.start, end: occ.end } as CalEvent);
    }
    return out;
  }, []);

  const selectedEvents = useCallback((): CalEvent[] => resolve(), [resolve]);

  const editable = useCallback(
    (ids?: readonly string[]): CalEvent[] => resolve(ids).filter((e) => !e.readOnly),
    [resolve],
  );

  // hovered slot, else the lead's slot, else the anchor day date-only (keeps original time of day)
  const pasteTarget = useCallback((): Instant => {
    const { view: v, projected: p, state: s } = latest.current;
    const h = hover.current;
    const lead = s.lead ? p.find((e) => e.id === s.lead) : undefined;
    // a timeline placement's column is its lane and its minutes run from the window start: use its real instant
    if (v.kind === "timeline") {
      const at = (lead as Partial<PlacedOccurrence> | undefined)?.start;
      return at && !lead?.allDay ? at : dateOnlyAt(v, 0);
    }
    if (h) return instantAt(v, h.col, h.startMin);
    if (lead && !lead.allDay) return instantAt(v, lead.dayIndex, lead.startMin);
    return dateOnlyAt(v, v.todayIndex >= 0 ? v.todayIndex : 0);
  }, []);

  const insert = useCallback(
    (events: CalEvent[]) => {
      if (events.length === 0) return;
      latest.current.store.batch(events.map((event): KloqBatchOp => ({ type: "add", event })));
      setState(replaceSelection(events.map((e) => e.id)));
      popIn(events.map((e) => e.id));
    },
    [popIn],
  );

  const copy = useCallback(
    (ids?: readonly string[]) => {
      const events = resolveForCopy(ids);
      if (events.length === 0) return;
      void writeEventsToClipboard(events, {
        locale: latest.current.g.locale,
        hour12: latest.current.g.hour12,
      });
    },
    [resolveForCopy],
  );

  const removeSelection = useCallback(
    (ids?: readonly string[]) => {
      const events = editable(ids);
      if (events.length === 0) return;
      latest.current.store.batch(events.map((e): KloqBatchOp => ({ type: "remove", id: e.id })));
      setState((cur) => (ids ? removeFromSelection(cur, ids) : EMPTY_SELECTION));
    },
    [editable],
  );

  const cut = useCallback(
    (ids?: readonly string[]) => {
      copy(ids);
      removeSelection(ids);
    },
    [copy, removeSelection],
  );

  const paste = useCallback(() => {
    const target = pasteTarget();
    void readEventsFromClipboard().then(({ events }) => {
      if (events.length === 0) return;
      insert(rebaseEvents(events, { target, newId: g.makeId }));
    });
  }, [pasteTarget, insert, g.makeId]);

  // deliberately never touches the clipboard
  const duplicate = useCallback(() => {
    const events = resolveForCopy();
    if (events.length === 0) return;
    // copies land below the whole selection's span; if that doesn't fit the day, exactly on top
    const anchor = events[0]!;
    const span = anchor.allDay
      ? 0
      : Math.max(0, ...events.map((e) => (e.allDay ? 0 : wallMinutesBetween(anchor.start, e.end))));
    const startMs = parseInstant(anchor.start);
    const fits =
      span > 0 &&
      !Number.isNaN(startMs) &&
      minutesOfDate(new Date(startMs)) + 2 * span <= latest.current.g.dayEndMin;
    const target = fits ? shiftInstant(anchor.start, { minutes: span }) : anchor.start;
    insert(rebaseEvents(events, { target }));
  }, [resolveForCopy, insert]);

  const recolor = useCallback(
    (color: CalEvent["color"]) => {
      const events = editable();
      if (events.length === 0) return;
      latest.current.store.batch(
        events.map(
          (e): KloqBatchOp => ({
            type: "update",
            id: e.id,
            patch: { color },
          }),
        ),
      );
    },
    [editable],
  );

  const nudge = useCallback(
    (delta: NudgeDelta) => {
      const events = editable();
      if (events.length === 0) return;
      const { g: settings, store: st } = latest.current;
      // refuse rather than clamp: per-event clamping would collapse the selection's shape
      if (events.some((e) => outsideWindow(e, delta, settings))) return;
      st.batch(
        events.map(
          (e): KloqBatchOp => ({
            type: "update",
            id: e.id,
            patch: {
              start: shiftInstant(e.start, delta),
              end: shiftInstant(e.end, delta),
            },
          }),
        ),
      );
    },
    [editable],
  );

  return useMemo<KloqSelectionHandle>(() => {
    const s = live;
    return {
      state: s,
      ids: s.ids,
      count: s.ids.length,
      lead: s.lead,
      has: (id) => isSelected(s, id),
      indexOf: (id) => selectionIndex(s, id),
      click: (id, mods) =>
        setState((cur) => applySelectionClick(cur, id, mods, latest.current.order)),
      setLead: (id) => setState(selectOnly(id)),
      replace: (ids) => setState(replaceSelection(ids)),
      selectAll: () => setState(selectAllIds(latest.current.order)),
      clear: () => setState(EMPTY_SELECTION),
      applyMarquee: (ids, additive) =>
        setState((cur) => (additive ? addToSelection(cur, ids) : replaceSelection(ids))),
      extendTo: (id) =>
        setState((cur) => applySelectionClick(cur, id, { range: true }, latest.current.order)),
      selectedEvents,
      hover,
      copy,
      cut,
      paste,
      duplicate,
      remove: removeSelection,
      recolor,
      nudge,
    };
  }, [live, selectedEvents, copy, cut, paste, duplicate, removeSelection, recolor, nudge]);
}

const SelectionContext = createContext<KloqSelectionHandle | null>(null);

export const SelectionProvider = SelectionContext.Provider;

/** `null` outside a provider — callers treat that as single selection. */
export function useKloqSelection(): KloqSelectionHandle | null {
  return useContext(SelectionContext);
}

interface ModifierEvent {
  metaKey: boolean;
  ctrlKey: boolean;
  shiftKey: boolean;
}

function isAppleLike(): boolean {
  if (typeof navigator === "undefined") return false;
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  return /mac|iphone|ipad|ipod/i.test(
    nav.userAgentData?.platform || nav.platform || nav.userAgent || "",
  );
}

/** ⌘ on Apple, Ctrl elsewhere — ctrl+click is `contextmenu` on a Mac. */
export const isToggleModifier = (e: ModifierEvent): boolean =>
  e.metaKey || (e.ctrlKey && !isAppleLike());

export function selectionModifiers(e: ModifierEvent): SelectionModifiers {
  return { toggle: isToggleModifier(e), range: e.shiftKey };
}

export const hasSelectionModifier = (e: ModifierEvent): boolean =>
  isToggleModifier(e) || e.shiftKey;

import { useRef, useState } from "react";
import { MS_PER_MINUTE } from "../lib/date-math";
import { parseQuickAdd } from "../lib/quick-add";
import { useKloqSettings } from "./settings-context";

/** Inline "9:00 – 10:30"-style editing of a timed event's span, parsed by quick-add. */
export function useTimeEdit({
  enabled,
  spanStartMin,
  spanEndMin,
  onEditTime,
}: {
  enabled: boolean;
  spanStartMin: number;
  spanEndMin: number;
  onEditTime?: (startMin: number, endMin: number) => void;
}) {
  const g = useKloqSettings();
  const [timeEditing, setTimeEditing] = useState(false);
  const [timeDraft, setTimeDraft] = useState("");
  const [timeInvalid, setTimeInvalid] = useState(false);
  const timeInputRef = useRef<HTMLInputElement>(null);
  const beginTimeEdit = () => {
    if (!enabled) return;
    setTimeDraft(g.formatRange(spanStartMin, spanEndMin));
    setTimeInvalid(false);
    setTimeEditing(true);
    requestAnimationFrame(() => timeInputRef.current?.select());
  };
  const commitTimeEdit = () => {
    const r = parseQuickAdd(timeDraft, g.displayNow());
    const heardATime = r.start !== null && !r.allDay && r.tokens.some((t) => t.kind === "time");
    if (!heardATime) {
      setTimeInvalid(true);
      return;
    }
    const startMin = r.start!.getHours() * 60 + r.start!.getMinutes();
    const duration = r.end
      ? Math.round((r.end.getTime() - r.start!.getTime()) / MS_PER_MINUTE)
      : spanEndMin - spanStartMin;
    if (duration <= 0) {
      setTimeInvalid(true);
      return;
    }
    onEditTime!(startMin, startMin + duration);
    setTimeEditing(false);
  };
  return {
    editing: timeEditing,
    draft: timeDraft,
    invalid: timeInvalid,
    inputRef: timeInputRef,
    begin: beginTimeEdit,
    commit: commitTimeEdit,
    setDraft: setTimeDraft,
    setEditing: setTimeEditing,
    setInvalid: setTimeInvalid,
  };
}

/** View + anchor date (controlled or not), responsive collapse, navigation, range and the "where am I" announcement. */
import {
  type RefObject,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { announceFolded, announceView, describeRange } from "../lib/announce";
