const MONTH_DAY: Intl.DateTimeFormatOptions = { month: "long", day: "numeric" };

/** What the structure is resolved around while the real date is unknown. Never printed. */
const NEUTRAL_DATE = new Date(2024, 0, 1);

export function viewLabel(view: KloqView): string {
  if (typeof view === "number") return `${view} day view`;
  return `${view[0].toUpperCase()}${view.slice(1)} view`;
}

export interface ViewNavigationOptions {
  viewProp?: KloqView;
  defaultView?: KloqView;
  onViewChange?: (view: KloqView) => void;
  dateProp?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  responsive?: ResponsiveSetting;
  weekStartsOn: number;
  rangePadding: number | { before: number; after: number };
  onRangeChange?: (start: Date, end: Date) => void;
  rootRef: RefObject<HTMLDivElement | null>;
  /** clear selection state before the view or date moves */
  onNavigate: () => void;
  /** after a view switch — selection is gone, so give focus a home */
  onViewSwitched: () => void;
  announce: (message: string) => void;
}

export interface PendingTransitions {
  morph: RefObject<Snapshot | null>;
  slide: RefObject<StepDirection | null>;
}

export function useViewNavigation({
  viewProp,
  defaultView,
  onViewChange,
  dateProp,
  defaultDate,
  onDateChange,
  responsive,
  weekStartsOn,
  rangePadding,
  onRangeChange,
  rootRef,
  onNavigate,
  onViewSwitched,
  announce,
}: ViewNavigationOptions) {
  const g = useKloqSettings();
  const latest = useLatest({ onNavigate, onViewSwitched, announce });

  // view + anchor date: controlled when the prop is present
  const viewControlled = viewProp !== undefined;
  const [viewState, setViewState] = useState<KloqView>(defaultView ?? "week");
  const viewSetting = viewControlled ? viewProp : viewState;

  // responsive collapse: `viewSetting` is the intent, `effectiveView` is what renders
  const switchViewRef = useRef<(v: KloqView) => void>(() => {});
  const responsiveView = useResponsiveView({
    hostRef: rootRef,
    view: viewSetting,
    responsive,
    onRequestView: (v) => switchViewRef.current(v),
  });
  const effectiveView = responsiveView.effective;

  const dateControlled = dateProp !== undefined;
  // "today", the runtime's locale and its time zone are client facts. Without a host-supplied
  // date and locale the server and the hydration pass render a date-neutral frame instead.
  const isClient = useIsClient();
  const ready = isClient || ((dateProp ?? defaultDate) !== undefined && g.locale !== undefined);
  const [dateState, setDateState] = useState<Date | null>(() => defaultDate ?? null);
  // the uncontrolled anchor starts on the display zone's today, not the browser's
  const clientToday = useMemo(
    () => (isClient ? g.displayNow() : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [isClient],
  );
  const anchorDate = dateControlled ? dateProp : (dateState ?? clientToday ?? NEUTRAL_DATE);

  const applyView = useCallback(
    (next: KloqView) => {
      if (!viewControlled) setViewState(next);
      onViewChange?.(next);
    },
    [viewControlled, onViewChange],
  );
  const applyDate = useCallback(
    (next: Date) => {
      if (!dateControlled) setDateState(next);
      onDateChange?.(next);
    },
    [dateControlled, onDateChange],
  );

  const dateKey = anchorDate.toDateString();
  const view = useMemo(
    () => {
      const resolved = resolveView(effectiveView, weekStartsOn, anchorDate, {
        locale: g.locale,
        // decides which column is "today"
        timeZone: g.displayZone,
      });
      // the server's "today" is not the visitor's
      return isClient ? resolved : { ...resolved, todayIndex: -1 };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [effectiveView, weekStartsOn, dateKey, g.locale, g.displayZone, isClient],
  );

  const switchView = useCallback(
    (next: KloqView) => {
      if (next === viewSetting) return;
      pendingMorph.current = captureSnapshot(rootRef.current);
      latest.current.onNavigate();
      applyView(next);
      latest.current.onViewSwitched();
    },
    [viewSetting, applyView],
  );
  switchViewRef.current = switchView;

  /** ⌘K "Jump to day" / a month or agenda date — day view on that date. */
  const jumpToDay = useCallback(
    (d: Date) => {
      pendingMorph.current = captureSnapshot(rootRef.current);
      latest.current.onNavigate();
      applyDate(d);
      applyView("day");
    },
    [applyDate, applyView],
  );

  /** A year view's month heading — the other half of drilling in. */
  const openMonth = useCallback(
    (month: Date) => {
      pendingMorph.current = captureSnapshot(rootRef.current);
      latest.current.onNavigate();
      applyDate(new Date(month.getFullYear(), month.getMonth(), 1));
      applyView("month");
    },
    [applyDate, applyView],
  );

  // `lastStep` is state because the nav reads it during render to pick its title's slide direction
  const [lastStep, setLastStep] = useState<StepDirection | null>(null);
  const pendingSlide = useRef<StepDirection | null>(null);
  const pendingMorph = useRef<Snapshot | null>(null);

  const step = useCallback(
    (dir: StepDirection) => {
      setLastStep(dir);
      pendingSlide.current = dir;
      latest.current.onNavigate();
      applyDate(stepAnchor(effectiveView, anchorDate, dir));
    },
    [effectiveView, anchorDate, applyDate],
  );

  // one day, whatever the view — `navigationKeys: "day"`
  const stepDay = useCallback(
    (dir: StepDirection) => {
      setLastStep(dir);
      pendingSlide.current = dir;
      latest.current.onNavigate();
      applyDate(addDays(startOfLocalDay(anchorDate), dir));
    },
    [anchorDate, applyDate],
  );

  const goToday = useCallback(() => {
    const next = todayAnchor(effectiveView);
    const dir: StepDirection = next.getTime() < startOfLocalDay(anchorDate).getTime() ? -1 : 1;
    setLastStep(dir);
    pendingSlide.current = dir;
    applyDate(next);
  }, [effectiveView, anchorDate, applyDate]);

  const range = useMemo(() => rangeOfView(view), [view]);

  // the surface's accessible name and the live-region sentence, built once so they can't drift
  const rangeLabel = useMemo(
    () =>
      capabilitiesOf(view.kind).projects === "range"
        ? formatViewTitle(view, g.locale)
        : describeRange(view.days, (d: Date) => formatDate(d, g.locale, MONTH_DAY)),
    [view, g.locale],
  );
  const rangeCb = useRef(onRangeChange);
  // declared BEFORE the effect that reads it, so the mount fire sees the real callback
  useEffect(() => {
    rangeCb.current = onRangeChange;
  });
  const rangeKey = `${range.start.getTime()}:${range.end.getTime()}`;
  const padBefore = typeof rangePadding === "number" ? rangePadding : rangePadding.before;
  const padAfter = typeof rangePadding === "number" ? rangePadding : rangePadding.after;
  useEffect(() => {
    if (!ready) return;
    rangeCb.current?.(addDays(range.start, -padBefore), addDays(range.end, padAfter));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rangeKey, padBefore, padAfter, ready]);

  // one "where am I" announcement watching the result, not the six call sites; silent on mount
  const lastWhere = useRef<string | null>(null);
  const lastIntent = useRef(viewSetting);
  useEffect(() => {
    if (!ready) return;
    const key = `${effectiveView}:${rangeKey}`;
    // asked for a view the box cannot fit: say so, since nothing else on screen does
    const folded = lastIntent.current !== viewSetting && responsiveView.collapsed;
    lastIntent.current = viewSetting;
    if (lastWhere.current === null) {
      lastWhere.current = key;
      return;
    }
    if (lastWhere.current === key && !folded) return;
    lastWhere.current = key;
    const where = announceView(viewLabel(effectiveView), rangeLabel);
    latest.current.announce(folded ? announceFolded(viewLabel(viewSetting), where) : where);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveView, rangeKey, viewSetting, ready]);

  return {
    viewSetting,
    effectiveView,
    responsiveView,
    anchorDate,
    view,
    /** false on the server and the hydration pass when the host gave no date + locale to render from */
    ready,
    isTimeGrid: isTimeGridView(view.kind),
    lastStep,
    switchView,
    jumpToDay,
    openMonth,
    step,
    stepDay,
    goToday,
    applyView,
    applyDate,
    range,
    rangeLabel,
    pending: { morph: pendingMorph, slide: pendingSlide } as PendingTransitions,
  };
}

/** Play a queued view morph or range slide once the render that lands it has committed. */
export function useViewTransitions({
  rootRef,
  surfaceRef,
  pending,
  view,
  projected,
}: {
  rootRef: RefObject<HTMLElement | null>;
  surfaceRef: RefObject<HTMLElement | null>;
  pending: PendingTransitions;
  view: ViewDescriptor;
  projected: Projection;
}) {
  useLayoutEffect(() => {
    if (pending.morph.current) {
      const snap = pending.morph.current;
      pending.morph.current = null;
      pending.slide.current = null;
      playViewMorph(rootRef.current, snap);
      return;
    }
    const dir = pending.slide.current;
    pending.slide.current = null;
    if (dir) playRangeSlide(surfaceRef.current, dir);
    // `projected` so a commit morph plays on the render that lands it
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view, projected]);
}

/** DOM snapshots and the FLIP morph / range slide the calendar plays between renders. */

import type { StepDirection } from "../lib/navigation";
import { masterIdOf } from "../lib/recurrence";
import { EASE_OUT, ms, prefersReducedMotion, SPRING } from "../lib/springs";

export interface Snapshot {
  rects: Map<string, DOMRect>;
  headerRects: DOMRect[];
  /** a commit morph: the blocks around a landed drop make room on a spring */
  commit?: boolean;
  /** master id of the event that landed — it animates itself; only its neighbours morph */
  except?: string;
  at: number;
}

// a commit snapshot older than this (scope dialog left open) would glide from stale rects
const SNAPSHOT_TTL_MS = 1500;
const COMMIT_SPRING_MS = 260;
// past this many blocks the morph is noise, and measuring them all is the cost
const MORPH_CAP = 150;
// above everything the surface draws; the surface is its own stacking context
const MORPH_Z = "50";

export function captureSnapshot(
  root: HTMLElement | null,
  commit = false,
  except?: string,
): Snapshot {
  const rects = new Map<string, DOMRect>();
  const blocks = root?.querySelectorAll<HTMLElement>("[data-cal-event]:not([data-cal-lifted])");
  if (blocks) {
    const n = Math.min(blocks.length, MORPH_CAP);
    for (let i = 0; i < n; i++)
      rects.set(blocks[i].dataset.calEvent!, blocks[i].getBoundingClientRect());
  }
  const headerRects: DOMRect[] = [];
  root
    ?.querySelectorAll<HTMLElement>("[data-cal-day-header]")
    .forEach((el) => headerRects.push(el.getBoundingClientRect()));
  return { rects, headerRects, commit, except, at: performance.now() };
}

const touches = (r: DOMRect, box: DOMRect) =>
  r.right > box.left && r.left < box.right && r.bottom > box.top && r.top < box.bottom;

/** A static copy of `el` that flies in its place; inert, and invisible to every event query. */
function ghostOf(el: HTMLElement, now: DOMRect, stage: DOMRect, hatch: string | null): HTMLElement {
  const ghost = el.cloneNode(true) as HTMLElement;
  for (const name of ["data-cal-event", "id", "role", "aria-label", "aria-pressed", "tabindex"])
    ghost.removeAttribute(name);
  ghost.setAttribute("aria-hidden", "true");
  ghost.setAttribute("inert", "");
  Object.assign(ghost.style, {
    position: "absolute",
    left: `${now.left - stage.left}px`,
    top: `${now.top - stage.top}px`,
    width: `${now.width}px`,
    height: `${now.height}px`,
    margin: "0",
    transformOrigin: "left top",
    pointerEvents: "none",
  } satisfies Partial<CSSStyleDeclaration>);
  // the free/busy hatch is keyed on `[data-cal-event]`, which the ghost no longer carries
  if (hatch) ghost.style.backgroundImage = hatch;
  return ghost;
}

/**
 * FLIP between two renders. The real blocks never leave their new layout position — they are
 * only hidden while a ghost flies from the old rect — so a pointer or a test that asks where a
 * block is mid-morph gets the place it actually is.
 */
export function playViewMorph(root: HTMLElement | null, before: Snapshot) {
  if (!root || prefersReducedMotion()) return;
  if (before.commit && performance.now() - before.at > SNAPSHOT_TTL_MS) return;
  const EASE = before.commit ? SPRING : EASE_OUT;
  const MS = ms(before.commit ? COMMIT_SPRING_MS : 220);

  // every read first, then every write: interleaving them re-runs style per block
  const surface = root.querySelector<HTMLElement>(':scope > [role="region"]') ?? root;
  const stage = surface.getBoundingClientRect();
  const blocks = root.querySelectorAll<HTMLElement>("[data-cal-event]");
  const n = Math.min(blocks.length, MORPH_CAP);
  const moves: {
    el: HTMLElement;
    old: DOMRect | undefined;
    now: DOMRect;
    hatch: string | null;
  }[] = [];
  for (let i = 0; i < n; i++) {
    const el = blocks[i];
    // after a commit the landed block has already been animated into place
    if (
      before.commit &&
      (masterIdOf(el.dataset.calEvent!) === before.except ||
        el.hasAttribute("data-dragging") ||
        el.hasAttribute("data-resizing") ||
        el.getAnimations().some((a) => a.playState === "running"))
    )
      continue;
    moves.push({
      el,
      old: before.rects.get(el.dataset.calEvent!),
      now: el.getBoundingClientRect(),
      hatch: el.hasAttribute("data-free") ? getComputedStyle(el).backgroundImage : null,
    });
  }

  let layer: HTMLElement | null = null;
  let flying = 0;
  for (const { el, old, now, hatch } of moves) {
    if (!old) {
      if (before.commit) continue;
      el.animate([{ opacity: 0 }, { opacity: 1 }], {
        duration: ms(200),
        easing: "ease-out",
      });
      continue;
    }
    const dx = old.left - now.left;
    const dy = old.top - now.top;
    const sw = now.width > 0 ? old.width / now.width : 1;
    if (Math.abs(dx) < 1 && Math.abs(dy) < 1 && Math.abs(sw - 1) < 0.01) continue;
    // both ends out of sight: nothing to watch
    if (!touches(old, stage) && !touches(now, stage)) continue;

    if (!layer) {
      layer = document.createElement("div");
      layer.setAttribute("data-cal-morph", "");
      layer.setAttribute("aria-hidden", "true");
      Object.assign(layer.style, {
        position: "absolute",
        inset: "0",
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: MORPH_Z,
      } satisfies Partial<CSSStyleDeclaration>);
      surface.appendChild(layer);
    }
    const stageLayer = layer;
    const ghost = ghostOf(el, now, stage, hatch);
    stageLayer.appendChild(ghost);
    ghost.animate(
      [{ transform: `translate(${dx}px, ${dy}px) scaleX(${sw})` }, { transform: "none" }],
      { duration: MS, easing: EASE, fill: "forwards" },
    );
    flying++;
    const hidden = el.animate([{ opacity: 0 }, { opacity: 0 }], { duration: MS });
    const land = () => {
      ghost.remove();
      if (--flying === 0) stageLayer.remove();
    };
    hidden.onfinish = land;
    hidden.oncancel = land;
  }
}

// Range step: a slide, not the view morph — a step swaps the whole event set, so blocks don't correspond.
export function playRangeSlide(surface: HTMLElement | null, dir: StepDirection) {
  if (!surface || prefersReducedMotion()) return;
  surface.animate(
    [
      { transform: `translateX(${dir * 12}px)`, opacity: 0.4 },
      { transform: "none", opacity: 1 },
    ],
    { duration: ms(220), easing: EASE_OUT },
  );
}

/** Where a demoted all-day event lands, clamped into the drawn day window. */

/**
 * INTERNAL. The dispatch seam: what a view kind needs, in data, so the app
 * shell stops asking `view.kind === ...` in a dozen places.
 *
 * This is deliberately NOT public API. It is not exported from the package
 * index and it is not documented. kloq promises that nothing changes under
 * you, and a view contract designed before a second view family exists is not
 * a promise worth making. Revisit once the timeline has shipped.
 */

import type { KloqViewKind } from "../lib/view";

export interface ViewCapabilities {
  /** does this view own a scrollable time canvas the drag engine drives? */
  timeGrid: boolean;
  /** can it render meaningfully on the server, before the client zone is known? */
  ssr: boolean;
  /** which projection feeds it */
  projects: "day-columns" | "range" | "lanes";
}

const GRID: ViewCapabilities = { timeGrid: true, ssr: true, projects: "day-columns" };
const LIST: ViewCapabilities = { timeGrid: false, ssr: true, projects: "day-columns" };

export const VIEW_CAPABILITIES: Record<KloqViewKind, ViewCapabilities> = {
  day: GRID,
  days: GRID,
  week: GRID,
  month: LIST,
  agenda: LIST,
  year: { timeGrid: false, ssr: true, projects: "range" },
  timeline: { timeGrid: true, ssr: false, projects: "lanes" },
};

/** Capabilities for a kind, with a safe non-grid fallback for anything unknown. */
export function capabilitiesOf(kind: KloqViewKind): ViewCapabilities {
  return VIEW_CAPABILITIES[kind] ?? LIST;
}

"use client";

import type React from "react";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { type KloqView, type PlacedEvent, snapMinutes } from "../lib/calendar-types";
import { fullDate, plural } from "../lib/event-text";
import { bucketByDay, layoutDay } from "../lib/overlap";
import { withoutSegment } from "../lib/recurrence";
import { rovingTab } from "../lib/roving";
import { eventKeyOf } from "../lib/selection";
import { useLatest } from "../lib/use-latest";
import { ContextMenu, ContextMenuTrigger } from "../ui/context-menu";
import type { EventLayout } from "./event-block";
import {
  EventContextMenu,
  fallbackDays,
  GridContextMenu,
  useCalendarContextMenu,
} from "./event-context-menu";
import { useKloqSettings } from "./settings-context";
import { useSlots } from "./slots";
import { TimeShade, type WorkingHours } from "./time-shade";
import { useMarquee } from "./use-marquee";
import { hasSelectionModifier, selectionModifiers, useKloqSelection } from "./use-selection";

interface WeekGridProps {
  events: PlacedEvent[];
  dayCount: number;
  dayNamesShort: string[];
  todayIndex: number;
  canvasRef: React.RefObject<HTMLDivElement | null>;
  draftRef: React.RefObject<HTMLDivElement | null>;
  registerNode: (id: string, node: HTMLElement | null) => void;
  /** placement-id → node map shared with the engine; lets the marquee hit-test without DOM queries */
  registry?: Map<string, HTMLElement>;
  onCanvasPointerDown: (e: React.PointerEvent<HTMLDivElement>) => void;
  onCanvasDoubleClick?: (e: React.MouseEvent<HTMLDivElement>) => void;
  onEventPointerDown: (e: React.PointerEvent<HTMLElement>, event: PlacedEvent) => void;
  selectedId: string | null;
  /** false = no working-hours tint */
  workingHours: WorkingHours | false;
  /** Real date per visible column; without it the menu assumes `fallbackDays`. */
  days?: Date[];
  /** Select an event (opens the panel). `isNew` marks a draft so Escape discards it. */
  onSelect?: (id: string | null, opts?: { isNew?: boolean }) => void;
  viewSetting?: KloqView;
  /** omit and the menu's view-switch items don't render */
  onSwitchView?: (view: KloqView) => void;
  /** Scroll container, used only to auto-scroll a marquee dragged past the edge. */
  scrollRef?: React.RefObject<HTMLDivElement | null>;
  /** The one event carrying `tabIndex={0}` — see `lib/roving.ts`. */
  rovingId?: string | null;
  /** columns under ~64px: blocks show a title only */
  cramped?: boolean;
}

/** Per-column accessible name: "Tuesday 5 August, 3 events". */
function columnLabel(date: Date | undefined, n: number, locale?: string): string {
  const when = date ? fullDate(date, locale) : "";
  const events = n === 0 ? "no events" : plural(n, "event");
  return when ? `${when}, ${events}` : events;
}

const CONTENTS: React.CSSProperties = { display: "contents" };
const SOLO_LAYOUT: EventLayout = { col: 0, cols: 1 };

/** The grid before the calendar knows its date: the hour axis and its rules, no day columns. */
export function WeekGridFrame() {
  const C = useSlots();
  const g = useKloqSettings();
  // hour labels are printed only when they cannot differ between server and browser:
  // foreign-zone hours depend on the day, and `hour12` without a locale formats in the runtime's
  const deterministic =
    g.timeZones.length === 0 && (g.locale !== undefined || g.hour12 === undefined);
  return (
    <div className="flex min-w-0 flex-1">
      {deterministic ? (
        <C.TimeGutter
          minutesToPx={g.minutesToPx}
          startHour={g.dayStartHour + 1}
          endHour={g.dayEndHour}
          height={g.canvasHeight}
          formatHour={(hour) => g.formatMinutes(hour * 60)}
        />
      ) : (
        <div className="w-(--kloq-gutter-width) shrink-0" />
      )}
      <div className="cal-hour-lines min-w-0 flex-1" style={{ height: g.canvasHeight }} />
    </div>
  );
}

export function WeekGrid({
  events,
  dayCount,
  dayNamesShort,
  todayIndex,
  canvasRef,
  draftRef,
  registerNode,
  registry,
  onCanvasPointerDown,
  onCanvasDoubleClick,
  onEventPointerDown,
  selectedId,
  workingHours,
  days,
  onSelect,
  viewSetting,
  onSwitchView,
  scrollRef,
  rovingId,
  cramped = false,
}: WeekGridProps) {
  const C = useSlots();
  const g = useKloqSettings();
  const selection = useKloqSelection();
  const { timed, columnEvents, layouts } = useMemo(() => {
    const timed = events.filter((e) => !e.allDay);
    const columnEvents = bucketByDay(timed, dayCount);
    const layouts = new Map<string, EventLayout>();
    for (let day = 0; day < dayCount; day++) {
      const dayLayout = layoutDay(columnEvents[day]);
      for (const [id, l] of dayLayout) layouts.set(id, l);
    }
    return { timed, columnEvents, layouts };
  }, [events, dayCount]);

  const columns = days ?? fallbackDays(dayCount, todayIndex);
  const menu = useCalendarContextMenu({
    hostRef: canvasRef,
    events: timed,
    dayCount,
  });

  // read per rAF frame, so the hit test goes through a ref and must not allocate
  const timedRef = useLatest(timed);
  const boxRef = useRef<HTMLDivElement>(null);
  const marquee = useMarquee({
    canvasRef,
    boxRef,
    scrollRef,
    registry,
    dayCount,
    getEvents: () => timedRef.current,
    onCommit: (ids, additive) => selection?.applyMarquee(ids, additive),
  });

  // marquee gets first refusal on the pointerdown; create-drag only if it declines
  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (selection && marquee.tryStart(e)) return;
      onCanvasPointerDown(e);
    },
    [selection, marquee, onCanvasPointerDown],
  );

  // where a paste lands; a ref write, never a render input — measured once per frame, not per move
  const hoverPoint = useRef({ x: 0, y: 0 });
  const hoverFrame = useRef(0);
  const onPointerMove = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.buttons !== 0) return;
      const hover = selection?.hover;
      if (!hover) return;
      hoverPoint.current = { x: e.clientX, y: e.clientY };
      if (hoverFrame.current) return;
      hoverFrame.current = requestAnimationFrame(() => {
        hoverFrame.current = 0;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const { x, y } = hoverPoint.current;
        const col = Math.max(
          0,
          Math.min(dayCount - 1, Math.floor(((x - rect.left) / rect.width) * dayCount)),
        );
        const startMin = Math.max(
          g.dayStartMin,
          Math.min(
            g.dayEndMin - g.snapMinutes,
            snapMinutes(g.pxToMinutes(y - rect.top), g.snapMinutes),
          ),
        );
        hover.current = { col, startMin };
      });
    },
    [selection, canvasRef, dayCount, g],
  );

  const onPointerLeave = useCallback(() => {
    cancelAnimationFrame(hoverFrame.current);
    hoverFrame.current = 0;
    if (selection) selection.hover.current = null;
  }, [selection]);
  useEffect(() => () => cancelAnimationFrame(hoverFrame.current), []);

  // modifier-clicks select and must not arm a drag; refs keep the handlers stable
  const latest = useLatest({ selection, onEventPointerDown, onSelect });
  const onBlockPointerDown = useCallback(
    (e: React.PointerEvent<HTMLElement>, event: PlacedEvent) => {
      const { selection, onEventPointerDown } = latest.current;
      if (selection && e.button === 0 && hasSelectionModifier(e)) {
        e.preventDefault();
        e.stopPropagation();
        selection.click(event.id, selectionModifiers(e));
        return;
      }
      onEventPointerDown(e, event);
    },
    [],
  );
  const onBlockActivate = useCallback((ev: PlacedEvent) => latest.current.onSelect?.(ev.id), []);

  // keyed by event key, not placement id: both segments of a cross-midnight event light up
  const selectedIndex = new Map<string, number>();
  if (selection) {
    for (let i = 0; i < selection.ids.length; i++)
      selectedIndex.set(withoutSegment(selection.ids[i]), i + 1);
  }
  const isSelected = (e: PlacedEvent) =>
    selection ? selectedIndex.has(eventKeyOf(e)) : eventKeyOf(e) === selectedId;
  const selectionIndexOf = (e: PlacedEvent) => selectedIndex.get(eventKeyOf(e)) ?? 0;

  return (
    <div className="flex min-w-0 flex-1">
      <C.TimeGutter
        minutesToPx={g.minutesToPx}
        /* the first hour sits at y=0 where a centred label would clip, so labels start one hour in */
        startHour={g.dayStartHour + 1}
        endHour={g.dayEndHour}
        height={g.canvasHeight}
        formatHour={(hour) => g.formatMinutes(hour * 60)}
      />

      {/* `render` keeps the canvas the same element the engine measures against */}
      <ContextMenu open={menu.open} onOpenChange={menu.onOpenChange}>
        <ContextMenuTrigger
          onContextMenuCapture={menu.onContextMenuCapture}
          render={
            <div
              ref={canvasRef}
              data-cal-canvas
              data-cramped={cramped || undefined}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerLeave={onPointerLeave}
              onDoubleClick={onCanvasDoubleClick}
              data-craft="intent-threshold"
              className="relative min-w-0 flex-1 touch-none select-none cal-hour-lines"
              style={{ height: g.canvasHeight }}
            />
          }
        >
          <TimeShade todayIndex={todayIndex} dayCount={dayCount} workingHours={workingHours} />

          {Array.from({ length: dayCount }, (_, i) => (
            <div
              key={i}
              aria-hidden
              className="pointer-events-none absolute inset-y-0 border-l border-border/70"
              style={{ left: `${(i / dayCount) * 100}%` }}
            />
          ))}

          {/* not `role="grid"`: `lib/keyboard-scope` would treat it as owning its own keys */}
          {Array.from({ length: dayCount }, (_, day) => {
            const column = columnEvents[day];
            return (
              <div
                key={day}
                role="list"
                aria-label={columnLabel(columns[day], column.length, g.locale)}
                className="pointer-events-none absolute inset-0"
              >
                {column.map((event) => (
                  <div key={event.id} role="listitem" style={CONTENTS}>
                    <C.EventBlock
                      event={event}
                      dayCount={dayCount}
                      dayNamesShort={dayNamesShort}
                      layout={layouts.get(event.id) ?? SOLO_LAYOUT}
                      selected={isSelected(event)}
                      selection={
                        selection && selection.count > 1 && isSelected(event)
                          ? {
                              index: selectionIndexOf(event),
                              count: selection.count,
                            }
                          : undefined
                      }
                      tabIndex={rovingTab(rovingId, event.id)}
                      registerNode={registerNode}
                      onPointerDown={onBlockPointerDown}
                      onActivate={onBlockActivate}
                    />
                  </div>
                ))}
              </div>
            );
          })}

          <div ref={draftRef} hidden data-cal-draft className="absolute z-30">
            <span aria-hidden data-slot="draft-bar" />
            <span data-slot="draft-label" />
          </div>

          <div
            ref={boxRef}
            hidden
            aria-hidden
            data-cal-marquee
            data-craft="intent-threshold"
            className="pointer-events-none absolute left-0 top-0 z-40 rounded-xs border border-primary/70 bg-primary/10"
          />

          <C.NowIndicator todayIndex={todayIndex} dayCount={dayCount} />
        </ContextMenuTrigger>

        {menu.target?.kind === "event" ? (
          <EventContextMenu
            event={menu.target.event}
            selected={isSelected(menu.target.event)}
            host={canvasRef}
            days={columns}
            onSelect={onSelect}
            close={menu.close}
          />
        ) : menu.target ? (
          <GridContextMenu
            slot={menu.target}
            host={canvasRef}
            days={columns}
            todayIndex={todayIndex}
            viewSetting={viewSetting}
            onSwitchView={onSwitchView}
            onSelect={onSelect}
            close={menu.close}
          />
        ) : null}
      </ContextMenu>
    </div>
  );
}

"use client";

/** year-view — twelve mini-months heat-mapped from per-day loads (`lib/year-grid`). */

import type React from "react";
import { memo, useCallback, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  addDays,
  parseInstant,
  startOfLocalDay,
  toDateOnlyString,
  type ViewDescriptor,
} from "../lib/calendar-types";
import { formatDate } from "../lib/date-format";
import { fullDate } from "../lib/event-text";
import { rovingTarget } from "../lib/roving";
import { EASE_OUT, ms, prefersReducedMotion } from "../lib/springs";
import { cn } from "../lib/utils";
import {
  buildYearGrid,
  type DayLoad,
  DENSITY_LEVELS,
  densityFill,
  describeLoad,
  EMPTY_DAY,
  weekdayColumns,
  type YearMonth,
} from "../lib/year-grid";
import { Button } from "../ui/button";
import { FOCUS_RING } from "./cell-classes";
import { useKloqSettings } from "./settings-context";

const TILE_STAGGER_MS = 26;

const MONTH_LONG: Intl.DateTimeFormatOptions = { month: "long" };
const MONTH_YEAR: Intl.DateTimeFormatOptions = { month: "long", year: "numeric" };
const WEEKDAY_NARROW: Intl.DateTimeFormatOptions = { weekday: "narrow" };
const WEEKDAY_LONG: Intl.DateTimeFormatOptions = { weekday: "long" };

const DAY_BASE = cn(
  "relative flex aspect-square w-full cursor-pointer items-center justify-center rounded-xs text-3xs tabular-nums",
  // the 1px gutters between cells belong to the nearest day on touch
  "pointer-coarse:after:absolute pointer-coarse:after:-inset-px",
  "transition-[background-color,color,box-shadow] duration-150",
  FOCUS_RING,
);
const DAY_CLASS = `${DAY_BASE} text-foreground hover:ring-1 hover:ring-border`;
const TODAY_CLASS = `${DAY_BASE} bg-primary font-medium text-primary-foreground`;

const luminance = (r: number, g: number, b: number) => {
  const lin = (v: number) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
};

const HEAT_INK = (bucket: number) => `--kloq-heat-ink-${bucket}`;

/**
 * A heat cell mixes `--foreground` into its own ground, so foreground text loses contrast as the
 * cell fills — below 4.5:1 in low-contrast themes. This measures each step's painted fill and,
 * where the theme's text no longer clears it, hands the cell black or white instead: one of the
 * two always clears 4.5:1 on any colour.
 */
function useHeatInk(ref: React.RefObject<HTMLElement | null>, enabled: boolean) {
  useLayoutEffect(() => {
    const root = ref.current;
    if (!enabled || !root || typeof OffscreenCanvas === "undefined") return;
    const ctx = new OffscreenCanvas(1, 1).getContext("2d", { willReadFrequently: true });
    if (!ctx) return;
    const painted = (layers: string[]) => {
      ctx.clearRect(0, 0, 1, 1);
      for (const layer of layers) {
        ctx.fillStyle = layer;
        ctx.fillRect(0, 0, 1, 1);
      }
      const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
      return luminance(r, g, b);
    };
    const probe = document.createElement("span");
    probe.hidden = true;
    root.appendChild(probe);

    const measure = () => {
      const ground: string[] = [];
      for (let n: HTMLElement | null = root; n; n = n.parentElement)
        ground.unshift(getComputedStyle(n).backgroundColor);
      const text = painted([...ground, getComputedStyle(root).color]);
      for (let bucket = 1; bucket <= DENSITY_LEVELS; bucket++) {
        probe.style.backgroundColor = densityFill(bucket as 1 | 2 | 3 | 4);
        const fill = painted([...ground, getComputedStyle(probe).backgroundColor]);
        const ratio = (Math.max(text, fill) + 0.05) / (Math.min(text, fill) + 0.05);
        if (ratio >= 4.5) root.style.removeProperty(HEAT_INK(bucket));
        else
          root.style.setProperty(
            HEAT_INK(bucket),
            fill > 0.179 ? "var(--color-black)" : "var(--color-white)",
          );
      }
    };
    measure();

    // a theme or scheme swap repaints the fills
    const mo = new MutationObserver(measure);
    const watch = { attributes: true, attributeFilter: ["class", "data-kloq-theme"] };
    mo.observe(document.documentElement, watch);
    const scope = root.closest("[data-kloq-root]");
    if (scope) mo.observe(scope, watch);
    return () => {
      mo.disconnect();
      probe.remove();
    };
  }, [ref, enabled]);
}

export interface YearViewProps {
  view: ViewDescriptor;
  weekStartsOn: number;
  density: ReadonlyMap<string, DayLoad>;
  onOpenDay: (date: Date) => void;
  onOpenMonth: (month: Date) => void;
}

interface WeekdayName {
  short: string;
  long: string;
}

export function YearView({ view, weekStartsOn, density, onOpenDay, onOpenMonth }: YearViewProps) {
  const g = useKloqSettings();
  const year = view.year?.getFullYear() ?? view.days[0]?.getFullYear();
  const rootRef = useRef<HTMLDivElement>(null);
  const nodes = useRef(new Map<string, HTMLButtonElement>()).current;

  const months = useMemo(
    () => (year === undefined ? [] : buildYearGrid(year, weekStartsOn)),
    [year, weekStartsOn],
  );
  const weekdayNames = useMemo<WeekdayName[]>(
    () =>
      weekdayColumns(weekStartsOn).map((d) => ({
        short: formatDate(d, g.locale, WEEKDAY_NARROW),
        long: formatDate(d, g.locale, WEEKDAY_LONG),
      })),
    [weekStartsOn, g.locale],
  );

  const order = useMemo(() => view.days.map(toDateOnlyString), [view.days]);
  const todayKey = view.todayIndex >= 0 ? order[view.todayIndex] : undefined;
  const todayMonth = view.todayIndex >= 0 ? view.days[view.todayIndex].getMonth() : -1;
  const [lead, setLead] = useState<string | null>(null);
  const roving = rovingTarget(order, lead ?? todayKey ?? null);
  // "YYYY-MM-DD": the month a key belongs to, without parsing a date
  const rovingMonth = roving ? Number(roving.slice(5, 7)) - 1 : -1;

  const focusDay = useCallback(
    (key: string) => {
      setLead(key);
      nodes.get(key)?.focus();
    },
    [nodes],
  );

  const registerNode = useCallback(
    (key: string, node: HTMLButtonElement | null) => {
      if (node) nodes.set(key, node);
      else nodes.delete(key);
    },
    [nodes],
  );

  // `preventDefault()` also tells the document-level keyboard layer to yield
  const onKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
      const from = (e.target as HTMLElement | null)?.dataset?.yearDay;
      if (!from) return;
      // `parseInstant` reads a date-only string as local midnight; `new Date()` would read UTC
      const at = parseInstant(from);
      if (Number.isNaN(at)) return;
      const cur = startOfLocalDay(new Date(at));

      let next: Date | null = null;
      switch (e.key) {
        case "ArrowLeft":
          next = addDays(cur, -1);
          break;
        case "ArrowRight":
          next = addDays(cur, 1);
          break;
        case "ArrowUp":
          next = addDays(cur, -7);
          break;
        case "ArrowDown":
          next = addDays(cur, 7);
          break;
        case "Home":
          next = new Date(cur.getFullYear(), cur.getMonth(), 1);
          break;
        case "End":
          next = new Date(cur.getFullYear(), cur.getMonth() + 1, 0);
          break;
        case "PageUp":
          next = new Date(cur.getFullYear(), cur.getMonth() - 1, 1);
          break;
        case "PageDown":
          next = new Date(cur.getFullYear(), cur.getMonth() + 1, 1);
          break;
        default:
          return;
      }
      // off the end of the year is a dead end, not a year step
      e.preventDefault();
      const key = toDateOnlyString(next);
      if (nodes.has(key)) focusDay(key);
    },
    [focusDay, nodes],
  );

  // the view-morph FLIP needs `[data-cal-event]`, which a year has none of — tiles animate themselves
  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root || prefersReducedMotion()) return;
    const tiles = root.querySelectorAll<HTMLElement>("[data-year-month]");
    tiles.forEach((tile, i) =>
      tile.animate(
        [
          { opacity: 0, transform: "translateY(4px)" },
          { opacity: 1, transform: "none" },
        ],
        {
          duration: ms(220),
          delay: i * TILE_STAGGER_MS,
          easing: EASE_OUT,
          fill: "backwards",
        },
      ),
    );
  }, [year]);

  useHeatInk(rootRef, year !== undefined);

  if (year === undefined) return null;

  return (
    <div
      ref={rootRef}
      className="@container flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto"
      onKeyDown={onKeyDown}
    >
      <div className="mx-auto flex w-full max-w-5xl flex-col gap-3 p-3 @md:gap-4 @md:p-4">
        <div className="grid grid-cols-1 gap-3 @[22rem]:grid-cols-2 @md:gap-4 @xl:grid-cols-3 @4xl:grid-cols-4">
          {months.map((m) => (
            <YearMonthTile
              key={m.index}
              month={m}
              density={density}
              weekdayNames={weekdayNames}
              current={m.index === todayMonth}
              todayKey={m.index === todayMonth ? todayKey : undefined}
              roving={m.index === rovingMonth ? roving : null}
              locale={g.locale}
              registerNode={registerNode}
              onOpenDay={onOpenDay}
              onOpenMonth={onOpenMonth}
              onFocusDay={setLead}
            />
          ))}
        </div>
        <DensityLegend />
      </div>
    </div>
  );
}

interface YearMonthTileProps {
  month: YearMonth;
  density: ReadonlyMap<string, DayLoad>;
  weekdayNames: WeekdayName[];
  current: boolean;
  todayKey: string | undefined;
  roving: string | null;
  locale?: string;
  registerNode: (key: string, node: HTMLButtonElement | null) => void;
  onOpenDay: (date: Date) => void;
  onOpenMonth: (month: Date) => void;
  onFocusDay: (key: string) => void;
}

// memoised so an arrow key re-renders the one or two months it touches
const YearMonthTile = memo(function YearMonthTile({
  month: m,
  density,
  weekdayNames,
  current,
  todayKey,
  roving,
  locale,
  registerNode,
  onOpenDay,
  onOpenMonth,
  onFocusDay,
}: YearMonthTileProps) {
  const label = formatDate(m.first, locale, MONTH_YEAR);
  return (
    <section data-year-month={m.index} aria-label={label} className="flex min-w-0 flex-col gap-1">
      <Button
        variant="ghost"
        size="xs"
        onClick={() => onOpenMonth(m.first)}
        aria-label={`Open ${label}`}
        className={cn("-mx-1 self-start", !current && "text-muted-foreground")}
      >
        {formatDate(m.first, locale, MONTH_LONG)}
      </Button>

      <div role="grid" aria-label={label} className="min-w-0">
        <div role="row" className="grid grid-cols-7">
          {weekdayNames.map((n, i) => (
            <div
              key={i}
              role="columnheader"
              aria-label={n.long}
              className="pb-0.5 text-center text-3xs text-muted-foreground"
            >
              <span aria-hidden>{n.short}</span>
            </div>
          ))}
        </div>

        {m.weeks.map((week, w) => (
          <div key={w} role="row" className="grid grid-cols-7">
            {week.map((date, c) => {
              if (date === null) return <div key={c} role="gridcell" aria-hidden />;
              const key = toDateOnlyString(date);
              return (
                <YearDay
                  key={c}
                  date={date}
                  dayKey={key}
                  load={density.get(key) ?? EMPTY_DAY}
                  isToday={key === todayKey}
                  tabbable={key === roving}
                  locale={locale}
                  registerNode={registerNode}
                  onOpenDay={onOpenDay}
                  onFocusDay={onFocusDay}
                />
              );
            })}
          </div>
        ))}
      </div>
    </section>
  );
});

interface YearDayProps {
  date: Date;
  dayKey: string;
  load: DayLoad;
  isToday: boolean;
  tabbable: boolean;
  locale?: string;
  registerNode: (key: string, node: HTMLButtonElement | null) => void;
  onOpenDay: (date: Date) => void;
  onFocusDay: (key: string) => void;
}

const YearDay = memo(function YearDay({
  date,
  dayKey,
  load,
  isToday,
  tabbable,
  locale,
  registerNode,
  onOpenDay,
  onFocusDay,
}: YearDayProps) {
  return (
    <div role="gridcell" className="min-w-0 p-px">
      <button
        type="button"
        data-year-day={dayKey}
        ref={(node) => registerNode(dayKey, node)}
        tabIndex={tabbable ? 0 : -1}
        aria-current={isToday ? "date" : undefined}
        // the count is read aloud; the colour wash is never the only channel
        aria-label={`${fullDate(date, locale)}, ${describeLoad(load)}`}
        onFocus={() => onFocusDay(dayKey)}
        onClick={() => onOpenDay(date)}
        className={isToday ? TODAY_CLASS : DAY_CLASS}
        style={
          isToday
            ? undefined
            : load.bucket === 0
              ? undefined
              : {
                  backgroundColor: densityFill(load.bucket),
                  color: `var(${HEAT_INK(load.bucket)}, var(--foreground))`,
                }
        }
      >
        {date.getDate()}
      </button>
    </div>
  );
});

// `aria-hidden`: the legend decodes a colour; screen readers get the real count per cell
function DensityLegend() {
  return (
    <div
      aria-hidden
      className="flex items-center justify-end gap-1.5 text-3xs text-muted-foreground"
    >
      <span>Less</span>
      {Array.from({ length: DENSITY_LEVELS + 1 }, (_, i) => (
        <span
          key={i}
          className="size-2.5 rounded-xs ring-1 ring-border"
          style={{
            backgroundColor: densityFill(i as 0 | 1 | 2 | 3 | 4),
          }}
        />
      ))}
      <span>More</span>
    </div>
  );
}

