"use client";

import * as React from "react";
import { useKloqSettings } from "../calendar/settings-context";
import { useOptionalKloqStore } from "../calendar/store-context";
import { useDesignMode } from "./design-mode-provider";
import { InspectLayer, InspectSection } from "./inspect";
import { MotionSection } from "./motion";
import { NetworkSection } from "./network";
import { OverlayLayers, OverlaysSection } from "./overlays";
import { Panel } from "./panel";
import { usePanelState } from "./panel-state";
import { ThemeSection } from "./theme";

/** Keeps the overlay's frame on the visible part of the calendar it belongs to, or the viewport when unscoped. */
function useScopeFrame(scopeRef: React.RefObject<HTMLElement | null> | null) {
  const frameRef = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = frameRef.current;
    if (!el) return;
    const root = scopeRef?.current ?? null;
    let raf = 0;
    const place = () => {
      const r = root?.getBoundingClientRect() ?? new DOMRect(0, 0, innerWidth, innerHeight);
      const top = Math.max(0, r.top);
      const left = Math.max(0, r.left);
      el.style.top = `${top}px`;
      el.style.left = `${left}px`;
      el.style.width = `${Math.max(0, Math.min(innerWidth, r.right) - left)}px`;
      el.style.height = `${Math.max(0, Math.min(innerHeight, r.bottom) - top)}px`;
    };
    const schedule = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(place);
    };
    place();
    window.addEventListener("scroll", schedule, { capture: true, passive: true });
    window.addEventListener("resize", schedule, { passive: true });
    const ro = root && typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null;
    if (root) ro?.observe(root);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      ro?.disconnect();
    };
  }, [scopeRef]);
  return frameRef;
}

export const DesignModeOverlay = React.memo(
  function DesignModeOverlay(): React.ReactElement | null {
    const { enabled } = useDesignMode();
    return enabled ? <Overlay /> : null;
  },
);

function Overlay(): React.ReactElement {
  const { setEnabled, scopeRef } = useDesignMode();
  const [state, patch] = usePanelState();
  const store = useOptionalKloqStore();
  const settings = useKloqSettings();
  const frameRef = useScopeFrame(scopeRef);
  return (
    // not aria-hidden: the panel holds real controls; decorative layers opt out individually
    <div ref={frameRef} data-design-overlay className="pointer-events-none fixed z-50">
      <OverlayLayers overlays={state.overlays} width={state.width} settings={settings} />
      <InspectLayer store={store} settings={settings} />
      <Panel state={state} patch={patch} onClose={() => setEnabled(false)}>
        <InspectSection />
        <MotionSection settings={settings} />
        <OverlaysSection state={state} patch={patch} />
        <ThemeSection />
        <NetworkSection />
      </Panel>
    </div>
  );
}

"use client";

import * as React from "react";
import { craftBus } from "../lib/craft-bus";
import { isTypingEvent, watchKeyboardScope } from "../lib/keyboard-scope";

interface DesignModeContextValue {
  enabled: boolean;
  setEnabled: (on: boolean) => void;
  toggle: () => void;
  /** the calendar this instance belongs to; `null` = the whole page */
  scopeRef: React.RefObject<HTMLElement | null> | null;
}

const DesignModeContext = React.createContext<DesignModeContextValue | null>(null);

export function useDesignMode(): DesignModeContextValue {
  const ctx = React.useContext(DesignModeContext);
  if (!ctx) throw new Error("useDesignMode must be used within <DesignModeProvider>");
  return ctx;
}

interface DesignModeProviderProps {
  children: React.ReactNode;
  /** when given, ⌥D only fires while that subtree owns the keyboard */
  scopeRef?: React.RefObject<HTMLElement | null>;
  /** force ⌥D page-wide; defaults to `true` iff no `scopeRef` */
  globalToggle?: boolean;
}

export function DesignModeProvider({
  children,
  scopeRef,
  globalToggle,
}: DesignModeProviderProps): React.ReactElement {
  const [enabled, setEnabledState] = React.useState(false);

  const setEnabled = React.useCallback((on: boolean) => {
    setEnabledState(on);
  }, []);

  const toggle = React.useCallback(() => {
    setEnabledState((prev) => !prev);
  }, []);

  React.useEffect(() => {
    const root = document.documentElement;
    if (enabled) root.setAttribute("data-design-mode", "true");
    else root.removeAttribute("data-design-mode");
    craftBus.emit({ type: "design-mode", enabled });
  }, [enabled]);

  const isGlobal = globalToggle ?? !scopeRef;
  React.useEffect(() => {
    const scope = watchKeyboardScope(() => scopeRef?.current ?? null);
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.defaultPrevented) return;
      if (!(e.code === "KeyD" && e.altKey && !e.metaKey && !e.ctrlKey)) return;
      // ⌥d types a character on some layouts, so match on `code` and skip while typing
      if (isTypingEvent(e)) return;
      if (!isGlobal && !scope.owns()) return;
      e.preventDefault();
      toggle();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      scope.dispose();
    };
  }, [toggle, scopeRef, isGlobal]);

  const value = React.useMemo(
    () => ({ enabled, setEnabled, toggle, scopeRef: scopeRef ?? null }),
    [enabled, setEnabled, toggle, scopeRef],
  );

  return <DesignModeContext.Provider value={value}>{children}</DesignModeContext.Provider>;
}

