export function Range({
  label,
  value,
  min,
  max,
  step = 1,
  unit = "",
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step?: number;
  unit?: string;
  onChange: (v: number) => void;
}) {
  const id = React.useId();
  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-baseline justify-between gap-2">
        <span id={id} className="text-muted-foreground">
          {label}
        </span>
        <span className="tabular-nums">
          {value}
          {unit}
        </span>
      </div>
      <Slider
        aria-labelledby={id}
        value={value}
        min={min}
        max={max}
        step={step}
        onValueChange={(v) => onChange(Array.isArray(v) ? v[0] : v)}
      />
    </div>
  );
}

import { contrastRatio, formatHex, parseColor, type RGB, type RGBA } from "../lib/color";

let ctx: CanvasRenderingContext2D | null | undefined;

/** Any CSS color the browser can paint (lab(), color-mix(), …) → RGBA, via a 1px readback. */
export function resolveColor(css: string): RGBA | null {
  const direct = parseColor(css);
  if (direct) return direct;
  if (!css) return null;
  if (ctx === undefined) {
    ctx = document.createElement("canvas").getContext("2d", { willReadFrequently: true });
    if (ctx) {
      ctx.canvas.width = 1;
      ctx.canvas.height = 1;
    }
  }
  if (!ctx) return null;
  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = "rgba(1, 2, 3, 0.5)";
  const sentinel = ctx.fillStyle;
  ctx.fillStyle = css;
  if (ctx.fillStyle === sentinel && css.trim() !== "rgba(1, 2, 3, 0.5)") return null;
  ctx.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
  // premultiplied readback: un-premultiply so translucent layers composite correctly
  const alpha = a / 255;
  if (alpha === 0) return { r: 0, g: 0, b: 0, a: 0 };
  // the color lib works in 0–1
  const ch = (v: number) => Math.min(1, v / 255 / alpha);
  return { r: ch(r), g: ch(g), b: ch(b), a: alpha };
}

export function hex(c: RGB | RGBA | null): string {
  return c ? formatHex(c) : "—";
}

/** `layer` composited over an opaque `backdrop`. */
export function composite(layer: RGBA, backdrop: RGB): RGB {
  const a = layer.a ?? 1;
  return {
    r: layer.r * a + backdrop.r * (1 - a),
    g: layer.g * a + backdrop.g * (1 - a),
    b: layer.b * a + backdrop.b * (1 - a),
  };
}

export function contrastLabel(fg: RGB | null, bg: RGB | null): string {
  if (!fg || !bg) return "—";
  const r = contrastRatio(fg, bg);
  const grade = r >= 7 ? "AAA" : r >= 4.5 ? "AA" : r >= 3 ? "AA large" : "fail";
  return `${r.toFixed(2)}:1 ${grade}`;
}

/** The background behind the calendar, opaque. `root` is the calendar's own element when known. */
export function pageBackground(root?: HTMLElement | null): RGB {
  const el = root ?? document.querySelector<HTMLElement>("[data-kloq-root]") ?? document.body;
  const bg = resolveColor(getComputedStyle(el).backgroundColor);
  if (bg && (bg.a ?? 1) > 0.99) return bg;
  const body = resolveColor(getComputedStyle(document.body).backgroundColor);
  const base = body && (body.a ?? 1) > 0.99 ? body : { r: 255, g: 255, b: 255 };
  return bg ? composite(bg, base) : base;
}

"use client";

import * as React from "react";
import { contrastRatio, mixOklab, type RGB } from "../lib/color";
import {
  EVENT_COLOR_KEYS,
  EVENT_COLORS,
  EVENT_INK_MIX,
  parseInk,
  parseTint,
} from "../lib/event-palette";
import {
  getScheme,
  getTheme,
  type KloqScheme,
  resolveScheme,
  setScheme,
  setTheme,
  THEMES,
} from "../lib/themes";
import { cn } from "../lib/utils";
import { ToggleGroup, ToggleGroupItem } from "../ui/toggle-group";
import { useDesignMode } from "./design-mode-provider";
import { Row, Section, Segmented } from "./panel";
import { composite, hex, pageBackground, resolveColor } from "./resolve-color";

const SCHEMES: { value: KloqScheme; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "system", label: "Auto" },
];

const FAMILY_LABELS = {
  coss: "Kloq originals",
  editor: "Editor ports",
  saas: "SaaS looks",
} as const;

const TOKENS = [
  "background",
  "foreground",
  "primary",
  "accent",
  "muted-foreground",
  "border",
] as const;

/** Re-render whenever the theme or scheme attributes on <html> change. */
function useThemeVersion(): number {
  const [v, bump] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    const mo = new MutationObserver(bump);
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-kloq-theme", "data-theme"],
    });
    return () => mo.disconnect();
  }, []);
  return v;
}

type Scope = HTMLElement | null;

function readVar(name: string, scope: Scope): string {
  const root =
    scope ?? document.querySelector<HTMLElement>("[data-kloq-root]") ?? document.documentElement;
  return getComputedStyle(root).getPropertyValue(name).trim();
}

interface EventScore {
  color: string;
  bg: RGB | null;
  text: RGB | null;
  ratio: number;
}

function scoreEvents(scope: Scope): EventScore[] {
  const scheme = resolveScheme();
  const page = pageBackground(scope);
  const fg = resolveColor(readVar("--foreground", scope));
  return EVENT_COLOR_KEYS.map((color) => {
    const tint = parseTint(EVENT_COLORS[color].tint)[scheme].rest;
    const ramp = resolveColor(readVar(`--color-${tint.ramp}`, scope));
    const ink = resolveColor(
      readVar(`--color-${parseInk(EVENT_COLORS[color].ink)[scheme]}`, scope),
    );
    const bg = ramp ? composite({ ...ramp, a: tint.alpha }, page) : null;
    const text = ink && fg ? mixOklab({ ...ink, a: 1 }, { ...fg, a: 1 }, EVENT_INK_MIX) : null;
    return { color, bg, text, ratio: bg && text ? contrastRatio(text, bg) : 0 };
  });
}

export function ThemeSection() {
  const { scopeRef } = useDesignMode();
  const [scope, setScope] = React.useState<Scope>(null);
  React.useEffect(() => setScope(scopeRef?.current ?? null), [scopeRef]);
  useThemeVersion();
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  const active = typeof document === "undefined" ? "coss" : getTheme();
  const scheme = getScheme();
  const theme = THEMES.find((t) => t.id === active);
  const page = typeof document === "undefined" ? null : pageBackground(scope);
  const tokens =
    typeof document === "undefined"
      ? []
      : TOKENS.map((t) => {
          const c = resolveColor(readVar(`--${t}`, scope));
          const a = c?.a ?? 1;
          return [t, c && page && a < 1 ? composite(c, page) : c, a] as const;
        });
  const scores = typeof document === "undefined" ? [] : scoreEvents(scope);
  const worst = scores.reduce((m, s) => Math.min(m, s.ratio), Infinity);

  return (
    <Section
      id="theme"
      title="Theme"
      summary={`${theme?.name ?? active} · ${resolveScheme(scheme)}`}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-sans text-xs">Appearance</span>
        <Segmented
          label="Color scheme"
          value={scheme}
          options={SCHEMES}
          onChange={(s) => {
            setScheme(s);
            force();
          }}
        />
      </div>
      {(["coss", "editor", "saas"] as const).map((family) => (
        <div key={family} className="flex flex-col gap-1">
          <span className="font-sans text-3xs uppercase tracking-wide text-muted-foreground">
            {FAMILY_LABELS[family]}
          </span>
          <ToggleGroup
            size="xs"
            aria-label={FAMILY_LABELS[family]}
            className="w-full flex-wrap"
            value={[active]}
            onValueChange={(v) => {
              const next = v.find((id) => id !== active);
              if (!next) return;
              setTheme(next);
              force();
            }}
          >
            {THEMES.filter((t) => t.family === family).map((t) => (
              <ToggleGroupItem key={t.id} value={t.id} title={t.credit}>
                <span
                  aria-hidden
                  className="relative size-3 shrink-0 overflow-hidden rounded-full border border-border"
                  style={{ background: t.swatch[0] }}
                >
                  <span
                    className="absolute inset-y-0 right-0 w-1/2"
                    style={{ background: t.swatch[1] }}
                  />
                  <span
                    className="absolute bottom-0 right-0 h-1/2 w-1/4"
                    style={{ background: t.swatch[2] }}
                  />
                </span>
                {t.name}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </div>
      ))}
      <div className="flex flex-col gap-1 border-t pt-2">
        {tokens.map(([name, c, a]) => (
          <Row
            key={name}
            label={
              <span className="flex items-center gap-1.5">
                <span
                  className="size-2.5 rounded-sm border border-border"
                  style={{ background: hex(c) }}
                />
                --{name}
              </span>
            }
          >
            {hex(c)}
            {a < 1 ? ` · ${Math.round(a * 100)}%` : ""}
          </Row>
        ))}
      </div>
      <div className="flex flex-col gap-1 border-t pt-2">
        <div className="flex items-baseline justify-between">
          <span className="font-sans text-xs font-medium">Event text contrast</span>
          <span
            className={cn(
              "tabular-nums",
              worst < 4.5 ? "text-destructive-foreground" : "text-muted-foreground",
            )}
          >
            worst {Number.isFinite(worst) ? worst.toFixed(2) : "—"}:1
          </span>
        </div>
        {scores.map((s) => (
          <div key={s.color} className="flex items-center gap-2">
            <span
              className="flex h-5 w-20 items-center rounded-md px-1.5 font-sans text-2xs font-medium"
              style={{ background: hex(s.bg), color: hex(s.text) }}
            >
              {s.color}
            </span>
            <span
              className={cn("ml-auto tabular-nums", s.ratio < 4.5 && "text-destructive-foreground")}
            >
              {s.ratio.toFixed(2)}:1 {s.ratio >= 7 ? "AAA" : s.ratio >= 4.5 ? "AA" : "fail"}
            </span>
          </div>
        ))}
      </div>
    </Section>
  );
}

/** The horizontal axis a timeline canvas publishes on its element, for the inspector and overlays. */
export interface TimelineAxisInfo {
  canvas: HTMLElement;
  startMs: number;
  slotMinutes: number;
  slotPx: number;
}

export function timelineAxisOf(scope: ParentNode | null): TimelineAxisInfo | null {
  const canvas = (scope ?? document).querySelector<HTMLElement>('[data-slot="timeline-canvas"]');
  if (!canvas) return null;
  const startMs = Number(canvas.dataset.windowStart);
  const slotMinutes = Number(canvas.dataset.slotMinutes);
  const slotPx = Number(canvas.dataset.slotPx);
  if (!Number.isFinite(startMs) || !(slotMinutes > 0) || !(slotPx > 0)) return null;
  return { canvas, startMs, slotMinutes, slotPx };
}

/** Agenda: a chronological list grouped by day. Empty days are dropped; multi-day events appear on every day. */

import {
  continuesAfter,
  continuesBefore,
  type PlacedEvent,
  type ViewDescriptor,
} from "./calendar-types";
import { compareForDay } from "./month-grid";

export interface AgendaEntry {
  event: PlacedEvent;
  /** the event began before this row */
  continuesBefore: boolean;
  /** the event runs past this day */
  continuesAfter: boolean;
  /** the same placement id on a later day; must not register a node or take a tab stop */
  repeat: boolean;
}

export interface AgendaDay {
  /** visible column index */
  dayIndex: number;
  date: Date;
  /** `view.namesLong[dayIndex]` */
  nameLong: string;
  isToday: boolean;
  entries: AgendaEntry[];
}

export interface Agenda {
  /** days with at least one event, in order */
  days: AgendaDay[];
  /** how many days in the range had nothing */
  emptyDays: number;
  /** the searched range */
  firstDay?: Date;
  lastDay?: Date;
}

export function groupAgenda(
  events: readonly PlacedEvent[],
  view: Pick<ViewDescriptor, "days" | "dayCount" | "namesLong" | "todayIndex">,
): Agenda {
  const dayCount = Math.min(view.dayCount, view.days.length);
  if (dayCount <= 0) return { days: [], emptyDays: 0 };

  const buckets: PlacedEvent[][] = Array.from({ length: dayCount }, () => []);
  for (const e of events) {
    const lo = Math.max(0, e.dayIndex);
    const hi = Math.min(dayCount - 1, Math.max(e.dayIndex, e.endDayIndex));
    if (hi < lo) continue;
    for (let d = lo; d <= hi; d++) buckets[d].push(e);
  }

  const days: AgendaDay[] = [];
  let emptyDays = 0;
  for (let d = 0; d < dayCount; d++) {
    if (!buckets[d].length) {
      emptyDays++;
      continue;
    }
    buckets[d].sort(compareForDay);
    days.push({
      dayIndex: d,
      date: view.days[d],
      nameLong: view.namesLong[d] ?? "",
      isToday: d === view.todayIndex,
      entries: buckets[d].map((event) => ({
        event,
        continuesBefore: event.dayIndex < d || continuesBefore(event),
        continuesAfter: Math.max(event.dayIndex, event.endDayIndex) > d || continuesAfter(event),
        // segments have distinct ids, so each owns its own node
        repeat: event.dayIndex < d,
      })),
    });
  }

  return {
    days,
    emptyDays,
    firstDay: view.days[0],
    lastDay: view.days[dayCount - 1],
  };
}

/**
 * announce — live-region copy, pure. One sentence, no trailing period (some voices read "dot");
 * spoken by `calendar/live-region.tsx`, on commit, never per frame.
 */

interface EventRef {
  title?: string;
}

export interface WhenRef {
  day?: string;
  time?: string;
  /** when true, `time` is ignored */
  allDay?: boolean;
}

export function eventName(e: EventRef | undefined): string {
  const t = e?.title?.trim();
  return t ? t : "Untitled event";
}

export function count(n: number, singular: string, plural = `${singular}s`): string {
  return `${n} ${n === 1 ? singular : plural}`;
}

export function describeWhen(when: WhenRef | undefined): string {
  if (!when) return "";
  const parts: string[] = [];
  if (when.day) parts.push(when.day);
  if (when.allDay) parts.push("all day");
  else if (when.time) parts.push(when.time);
  return parts.join(", ");
}

const withWhen = (head: string, when: WhenRef | undefined, joiner = "to") => {
  const tail = describeWhen(when);
  if (!tail) return head;
  return joiner ? `${head} ${joiner} ${tail}` : `${head} ${tail}`;
};

export function announceMoved(e: EventRef, when: WhenRef): string {
  return withWhen(`${eventName(e)} moved`, when);
}

export function announceResized(e: EventRef, when: WhenRef): string {
  return withWhen(`${eventName(e)} resized`, when);
}

export function announceSpanned(e: EventRef, when: WhenRef): string {
  return withWhen(`${eventName(e)} now spans`, when, "");
}

export function announceCreated(e: EventRef, when: WhenRef): string {
  const tail = describeWhen(when);
  const name = e.title?.trim();
  const head = name ? `${name} created` : "New event created";
  return tail ? `${head}, ${tail}` : head;
}

export function announceDuplicated(e: EventRef, when: WhenRef): string {
  return withWhen(`${eventName(e)} duplicated`, when);
}

export function announceDeleted(events: readonly EventRef[]): string {
  if (events.length === 0) return "";
  if (events.length === 1) return `${eventName(events[0])} deleted`;
  return `${count(events.length, "event")} deleted`;
}

export function announceColor(events: readonly EventRef[], color: string): string {
  if (events.length === 0) return "";
  if (events.length === 1) return `${eventName(events[0])} is now ${color}`;
  return `${count(events.length, "event")} are now ${color}`;
}

export function announceCalendar(e: EventRef, calendar: string): string {
  return `${eventName(e)} moved to ${calendar}`;
}

export function announceAllDay(e: EventRef, allDay: boolean, when?: WhenRef): string {
  const name = eventName(e);
  if (!allDay) return withWhen(`${name} is no longer all day, moved`, when);
  // the day only — the full `when` clause would read "all day, Tuesday, all day"
  const tail = when?.day ?? "";
  return tail ? `${name} is now all day, ${tail}` : `${name} is now all day`;
}

/** Named for the sentence, not the engine: a lane move and a lane resize are both "span". */
export type RefusedGesture = "create" | "move" | "resize" | "span" | "duplicate" | "paste";

const REFUSED_VERB: Record<Exclude<RefusedGesture, "create">, string> = {
  move: "cannot be moved there",
  resize: "cannot be resized that far",
  span: "cannot span those days",
  duplicate: "cannot be duplicated there",
  paste: "cannot be pasted there",
};

/** A refused drop. Said once per gesture, never per frame. */
export function announceRefused(gesture: RefusedGesture, e?: EventRef): string {
  if (gesture === "create") return "Cannot create an event there";
  return `${eventName(e)} ${REFUSED_VERB[gesture]}`;
}

export function describeUnavailable(when: WhenRef): string {
  const tail = describeWhen(when);
  return tail ? `Unavailable, ${tail}` : "Unavailable";
}

/** Deliberately undescriptive: the store knows that something changed, not what. */
export const announceUndo = () => "Undone";
export const announceRedo = () => "Redone";

export function announceSelection(n: number): string {
  if (n === 0) return "Selection cleared";
  return `${count(n, "event")} selected`;
}

export function announceView(view: string, range?: string): string {
  return range ? `${view}, ${range}` : view;
}

/** A view the box is too narrow for, then where the calendar landed instead. */
export function announceFolded(asked: string, where: string): string {
  return `${asked} needs a wider calendar. ${where}`;
}

/** `formatDay` is injected so the caller owns locale and zone — this module never touches `Intl`. */
export function describeRange(days: readonly Date[], formatDay: (d: Date) => string): string {
  if (days.length === 0) return "";
  const first = formatDay(days[0]);
  if (days.length === 1) return first;
  const last = formatDay(days[days.length - 1]);
  return first === last ? first : `${first} to ${last}`;
}

/**
 * Optimistic commit rejected and rolled back. The one assertive announcement:
 * the visual tell is a shake, which `prefers-reduced-motion` suppresses.
 */
export function announceReverted(events: readonly EventRef[]): string {
  if (events.length === 0) return "Change could not be saved and was undone";
  if (events.length === 1) return `${eventName(events[0])} could not be saved and was put back`;
  return `${count(events.length, "change")} could not be saved and were put back`;
}

/** Attendee helpers: parse, dedupe, initials, RSVP. */

import type { Attendee, AttendeeStatus, CalEvent } from "./calendar-types";
import { plural } from "./event-text";

// permissive on purpose: UI-side sanity checking, not RFC 5322
const EMAIL_RE = /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]{2,}$/;

export function isValidEmail(value: string): boolean {
  return EMAIL_RE.test(value.trim());
}

/** Normalised identity for an address. */
export const emailKey = (email: string) => email.trim().toLowerCase();

/** Parse `sam@acme.com` or `Sam Rivera <sam@acme.com>` into an attendee; `null` if no valid address. */
export function parseAttendee(raw: string): Attendee | null {
  const input = raw.trim();
  if (!input) return null;

  const angled = /^(.*?)<([^<>]+)>$/.exec(input);
  if (angled) {
    const email = angled[2].trim();
    if (!isValidEmail(email)) return null;
    const name = angled[1]
      .trim()
      .replace(/^["']|["']$/g, "")
      .trim();
    return name ? { email, name, status: "pending" } : { email, status: "pending" };
  }

  if (!isValidEmail(input)) return null;
  return { email: input, status: "pending" };
}

/** Split a pasted blob into entries on commas, semicolons (not inside `<...>`) and newlines. */
export function splitAttendeeInput(raw: string): string[] {
  return raw
    .split(/[,;\n]+(?![^<]*>)/)
    .map((s) => s.trim())
    .filter(Boolean);
}

/** Append one entry, deduped by email. `null` when unparseable or already present. */
export function addAttendee(list: readonly Attendee[] | undefined, raw: string): Attendee[] | null {
  const parsed = parseAttendee(raw);
  if (!parsed) return null;
  const current = list ?? [];
  if (current.some((a) => emailKey(a.email) === emailKey(parsed.email))) return null;
  return [...current, parsed];
}

/** Append every parseable, non-duplicate entry in a pasted blob. */
export function addAttendees(
  list: readonly Attendee[] | undefined,
  raw: string,
): Attendee[] | null {
  let next: Attendee[] | null = null;
  for (const entry of splitAttendeeInput(raw)) {
    const grown = addAttendee(next ?? list, entry);
    if (grown) next = grown;
  }
  return next;
}

export function removeAttendee(list: readonly Attendee[] | undefined, email: string): Attendee[] {
  return (list ?? []).filter((a) => emailKey(a.email) !== emailKey(email));
}

/** Display name, else the address. */
export function attendeeLabel(a: Attendee): string {
  return a.name?.trim() || a.email;
}

/** Two-letter initials: "Sam Rivera" → "SR", "sam.rivera@x" → "SR", "sam@x" → "SA". */
export function initialsFor(a: Pick<Attendee, "email" | "name">): string {
  const source = a.name?.trim() || a.email.split("@")[0] || "";
  const words = source.split(/[\s._\-+]+/).filter(Boolean);
  if (words.length === 0) return "?";
  if (words.length === 1) {
    const letters = words[0].replace(/[^\p{L}\p{N}]/gu, "");
    return (letters.slice(0, 2) || "?").toUpperCase();
  }
  return (words[0][0] + words[1][0]).toUpperCase();
}

/** Stable hue for an address (FNV-1a). */
export function avatarHue(email: string): number {
  const key = emailKey(email);
  let h = 0x811c9dc5;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h % 360;
}

export const attendeeStatus = (a: Attendee): AttendeeStatus => a.status ?? "pending";

export interface AttendeeSummary {
  total: number;
  accepted: number;
  declined: number;
  tentative: number;
  pending: number;
}

export function summarize(list: readonly Attendee[] | undefined): AttendeeSummary {
  const s: AttendeeSummary = {
    total: 0,
    accepted: 0,
    declined: 0,
    tentative: 0,
    pending: 0,
  };
  for (const a of list ?? []) {
    s.total++;
    s[attendeeStatus(a)]++;
  }
  return s;
}

/** "3 guests · 2 yes". */
export function summaryLabel(list: readonly Attendee[] | undefined): string {
  const s = summarize(list);
  if (s.total === 0) return "No guests";
  const head = plural(s.total, "guest");
  const parts: string[] = [];
  if (s.accepted) parts.push(`${s.accepted} yes`);
  if (s.declined) parts.push(`${s.declined} no`);
  if (s.tentative) parts.push(`${s.tentative} maybe`);
  return parts.length ? `${head} · ${parts.join(", ")}` : head;
}

const CYCLE: AttendeeStatus[] = ["pending", "accepted", "tentative", "declined"];

export function cycleStatus(status: AttendeeStatus | undefined): AttendeeStatus {
  const i = CYCLE.indexOf(status ?? "pending");
  return CYCLE[(i + 1) % CYCLE.length];
}

export const STATUS_LABEL: Record<AttendeeStatus, string> = {
  accepted: "Accepted",
  declined: "Declined",
  tentative: "Maybe",
  pending: "Awaiting reply",
};

/** Find someone on the list by address, case-insensitively. */
export function findAttendee(
  list: readonly Attendee[] | undefined,
  email: string | undefined,
): Attendee | undefined {
  if (!email) return undefined;
  const key = emailKey(email);
  return (list ?? []).find((a) => emailKey(a.email) === key);
}

/** Set one person's RSVP. `null` when nothing would change. */
export function setAttendeeStatus(
  list: readonly Attendee[] | undefined,
  email: string,
  status: AttendeeStatus,
): Attendee[] | null {
  const key = emailKey(email);
  let changed = false;
  const next = (list ?? []).map((a) => {
    if (emailKey(a.email) !== key || attendeeStatus(a) === status) return a;
    changed = true;
    return { ...a, status };
  });
  return changed ? next : null;
}

/** Flip one person between required and optional. `null` when nothing would change; `false` is written as an absent key. */
export function setAttendeeOptional(
  list: readonly Attendee[] | undefined,
  email: string,
  optional: boolean,
): Attendee[] | null {
  const key = emailKey(email);
  let changed = false;
  const next = (list ?? []).map((a) => {
    if (emailKey(a.email) !== key || Boolean(a.optional) === optional) return a;
    changed = true;
    if (optional) return { ...a, optional: true };
    const { optional: _drop, ...rest } = a;
    return rest;
  });
  return changed ? next : null;
}

export function toggleAttendeeOptional(
  list: readonly Attendee[] | undefined,
  email: string,
): Attendee[] | null {
  const current = findAttendee(list, email);
  if (!current) return null;
  return setAttendeeOptional(list, email, !current.optional);
}

/** The organiser, normalised, or `undefined`. Deliberately not "the first attendee". */
export function organizerOf(event: Pick<CalEvent, "organizer">): string | undefined {
  const email = event.organizer?.trim();
  return email ? emailKey(email) : undefined;
}

/** Is this address the organiser of that event? */
export function isOrganizer(
  event: Pick<CalEvent, "organizer">,
  email: string | undefined,
): boolean {
  if (!email) return false;
  return organizerOf(event) === emailKey(email);
}

/** The RSVP control's three answers. `pending` isn't offered. */
export const RSVP_CHOICES: readonly {
  status: Extract<AttendeeStatus, "accepted" | "tentative" | "declined">;
  label: string;
}[] = [
  { status: "accepted", label: "Yes" },
  { status: "tentative", label: "Maybe" },
  { status: "declined", label: "No" },
];

/** Is this an absolute http(s) link worth a Join button? */
export function isJoinableUrl(url: string | undefined): boolean {
  if (!url) return false;
  try {
    const u = new URL(url.trim());
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

/** "meet.google.com/abc-defg" — host + path, no scheme. */
export function shortUrl(url: string): string {
  try {
    const u = new URL(url.trim());
    const path = u.pathname === "/" ? "" : u.pathname;
    return `${u.host}${path}`.replace(/\/$/, "");
  } catch {
    return url.trim();
  }
}

/**
 * The geometry seam. Both the calendar's time grid and a timeline are
 * (lane, time-span) pairs; they differ only in which screen axis time runs
 * along and what instant minutes are measured from. An axis is that difference,
 * and nothing else.
 *
 * Minutes are always measured FROM THE WINDOW ORIGIN. For the calendar that
 * origin is a column's local midnight, so the numbers are the same
 * minutes-from-midnight the grid has always used.
 */

export interface KloqAxis {
  /** which screen axis time runs along */
  readonly orientation: "x" | "y";
  /** minutes from the window origin, to px along the axis */
  toPx(min: number): number;
  /** px along the axis, back to minutes from the window origin */
  pxToMinutes(px: number): number;
  /** a DURATION in minutes to a px length; no origin offset */
  durationToPx(min: number): number;
  /** a px LENGTH back to a duration in minutes; no origin offset */
  pxToDuration(px: number): number;
  /** hold a minute inside the window */
  clamp(min: number): number;
  /** first minute of the window */
  readonly startMin: number;
  /** last minute of the window */
  readonly endMin: number;
  /** total px the window occupies */
  readonly extentPx: number;
}

export interface VerticalAxisConfig {
  /** px per hour */
  hourHeight: number;
  /** the top of the canvas, in absolute minutes from midnight */
  dayStartMin: number;
  /** the bottom of the canvas, in absolute minutes from midnight */
  dayEndMin: number;
}

/**
 * The calendar's axis: time runs down, the origin is local midnight, and the
 * window is the (possibly clipped) day. Arithmetic here is deliberately
 * identical to what `createSettings` computed inline before the extraction.
 */
export function createVerticalAxis({
  hourHeight,
  dayStartMin,
  dayEndMin,
}: VerticalAxisConfig): KloqAxis {
  const perMin = hourHeight / 60;
  return {
    orientation: "y",
    toPx: (min) => (min - dayStartMin) * perMin,
    pxToMinutes: (px) => px / perMin + dayStartMin,
    durationToPx: (min) => min * perMin,
    pxToDuration: (px) => px / perMin,
    clamp: (min) => Math.max(dayStartMin, Math.min(dayEndMin, min)),
    startMin: dayStartMin,
    endMin: dayEndMin,
    extentPx: (dayEndMin - dayStartMin) * perMin,
  };
}

/**
 * Geometry and formatting config: `KloqConfig` is the host's input,
 * `KloqSettings` the resolved object with px↔time helpers closed over it.
 */

import { createVerticalAxis, type KloqAxis } from "./axis";
import { displayDate, formatMinutes, formatRange, type TimeFormatOptions } from "./calendar-types";
import { MINUTES_PER_DAY } from "./date-math";
import {
  clampZoom,
  DEFAULT_DENSITY,
  type DensityTokens,
  densityTokens,
  isDensity,
  type KloqDensity,
  MAX_HOUR_HEIGHT,
  MIN_HOUR_HEIGHT,
  resolveHourHeight,
  ZOOM_DEFAULT,
} from "./density";
import { randomId } from "./ids";
import {
  coerceTimeZone,
  type InstantLike,
  isValidTimeZone,
  localZone,
  normalizeZoneColumns,
  sameZone,
  type TimeZoneColumn,
  unzonedInstant,
  zoneAbbr,
} from "./timezone";

/** Config as a host passes it — every field optional. */
export interface KloqConfig {
  /**
   * px per hour on the time grid, clamped to 8–480. Omit it and `density` picks
   * the base (64 comfortable, 44 compact); pass it and `zoom` multiplies yours.
   */
  hourHeight?: number;
  /** `"comfortable"` (default) or `"compact"` — hour height, event type size and padding together. */
  density?: KloqDensity;
  /** Live zoom as an index into `ZOOM_STEPS` (0–10, default 4 = 100%). */
  zoom?: number;
  /**
   * Id factory for everything the calendar creates — drag-create, quick-add,
   * duplicate, paste, detached occurrences. Default: a random UUID. Supply
   * yours when ids must match a server scheme.
   */
  makeId?: () => string;
  /** First hour the grid draws, 0–23; with `dayEndHour` this clips the day. */
  dayStartHour?: number;
  dayEndHour?: number;
  snapMinutes?: number;
  snapFineMinutes?: number;
  minEventMinutes?: number;
  /** BCP 47 tag for every date and time label; undefined means `en-US` 12-hour. */
  locale?: string;
  /** Force a 12- or 24-hour clock; omit and the locale decides. */
  hour12?: boolean;
  /** Draw the calendar in this IANA zone instead of the browser's; unknown ids fall back. */
  displayTimeZone?: string;
  /**
   * Extra gutter zone columns, in order, as ids or `{ timeZone, label }`.
   * Unknown zones and duplicates are dropped; `components.TimeGutter` still wins.
   */
  timeZones?: (string | TimeZoneColumn)[];
}

/** Resolved, validated config plus the px↔time and formatting functions. */
export interface KloqSettings {
  /** px per hour, density and zoom applied; nothing else may re-derive it from props. */
  readonly hourHeight: number;
  readonly density: KloqDensity;
  /** index into `ZOOM_STEPS`; 4 is 100% */
  readonly zoom: number;
  /** the type/padding half of the density — the geometry half is `hourHeight` */
  readonly densityTokens: DensityTokens;
  /** id factory for created events */
  readonly makeId: () => string;
  readonly dayStartHour: number;
  readonly dayEndHour: number;
  /** `dayStartHour * 60` — the top of the canvas in absolute minutes */
  readonly dayStartMin: number;
  /** `dayEndHour * 60` — the bottom of the canvas in absolute minutes */
  readonly dayEndMin: number;
  readonly dayMinutes: number;
  readonly canvasHeight: number;
  readonly snapMinutes: number;
  readonly snapFineMinutes: number;
  readonly minEventMinutes: number;
  readonly locale?: string;
  readonly hour12?: boolean;
  readonly timeFormat: TimeFormatOptions;

  /**
   * The zone the grid is drawn in; always a real IANA id.
   * SSR-unstable without `displayTimeZone` — gate rendering on `hasDisplayZone`.
   */
  readonly timeZone: string;
  /**
   * Zone for the trailing `timeZone` arg of the zone-aware helpers.
   * `undefined` whenever the resolved zone is the browser's; SSR-unstable.
   */
  readonly displayZone: string | undefined;
  /** Is the grid drawn in the browser's own zone? A fast-path flag; SSR-unstable. */
  readonly isLocalZone: boolean;
  /** Did the host ask for a display zone? Derived from props alone, so SSR-stable. */
  readonly hasDisplayZone: boolean;
  /** Extra gutter zone columns, normalised: object form, valid, deduped. */
  readonly timeZones: readonly TimeZoneColumn[];

  /** an instant → a `Date` whose local getters read the DISPLAY zone */
  toDisplay(t: InstantLike): Date;
  /** the inverse: a display-zone `Date` → epoch ms */
  fromDisplay(d: Date): number;
  displayNow(): Date;
  /** the display zone's short label at an instant — `"BST"`, `"JST"` */
  zoneLabel(at?: InstantLike): string;

  /**
   * The geometry seam. `minutesToPx` and its siblings below are delegates to
   * this; a view that runs time along x supplies its own axis instead.
   */
  readonly axis: KloqAxis;
  /** absolute minutes-from-midnight → y on the canvas */
  minutesToPx(min: number): number;
  /** a DURATION in minutes → a height in px (no window offset) */
  durationToPx(min: number): number;
  /** y on the canvas → absolute minutes-from-midnight */
  pxToMinutes(px: number): number;
  /** a px LENGTH → a duration in minutes (no window offset) */
  pxToDuration(px: number): number;
  clampMinutes(min: number): number;
  formatMinutes(min: number): string;
  formatRange(startMin: number, endMin: number): string;
}

/** The values `<Kloq>` uses when a host passes nothing. */
export const DEFAULT_CONFIG: Required<
  Omit<KloqConfig, "locale" | "hour12" | "displayTimeZone" | "timeZones" | "makeId">
> = {
  hourHeight: 64,
  density: DEFAULT_DENSITY,
  zoom: ZOOM_DEFAULT,
  dayStartHour: 0,
  dayEndHour: 24,
  snapMinutes: 15,
  snapFineMinutes: 5,
  minEventMinutes: 15,
};

const num = (v: number | undefined, fallback: number, lo: number, hi: number) =>
  v === undefined || !Number.isFinite(v) ? fallback : Math.min(hi, Math.max(lo, v));

/**
 * Resolve a config into the object everything downstream reads. Values are
 * clamped, not thrown on; an inverted day range becomes a one-hour window.
 */
export function createSettings(config: KloqConfig = {}): KloqSettings {
  // hourHeight is clamped before scaling so a host passing 0 lands on the floor, not 0 × zoom.
  const density: KloqDensity = isDensity(config.density) ? config.density : DEFAULT_DENSITY;
  const zoom = clampZoom(config.zoom);
  const hourHeight = resolveHourHeight({
    hourHeight:
      config.hourHeight === undefined
        ? undefined
        : num(config.hourHeight, DEFAULT_CONFIG.hourHeight, MIN_HOUR_HEIGHT, MAX_HOUR_HEIGHT),
    density,
    zoom,
  });
  const dayStartHour = num(config.dayStartHour, DEFAULT_CONFIG.dayStartHour, 0, 23);
  const dayEndHour = Math.max(
    dayStartHour + 1,
    num(config.dayEndHour, DEFAULT_CONFIG.dayEndHour, 1, 24),
  );
  const snap = num(config.snapMinutes, DEFAULT_CONFIG.snapMinutes, 1, MINUTES_PER_DAY);
  const snapFine = num(config.snapFineMinutes, DEFAULT_CONFIG.snapFineMinutes, 1, MINUTES_PER_DAY);
  const minEvent = num(config.minEventMinutes, DEFAULT_CONFIG.minEventMinutes, 1, MINUTES_PER_DAY);

  const dayStartMin = dayStartHour * 60;
  const dayEndMin = dayEndHour * 60;
  const dayMinutes = dayEndMin - dayStartMin;
  const perMin = hourHeight / 60;

  const timeFormat: TimeFormatOptions = {
    locale: config.locale,
    hour12: config.hour12,
  };

  // displayZone's undefined is load-bearing: helpers treat it as the browser's wall clock.
  const browser = localZone();
  const hasDisplayZone =
    config.displayTimeZone !== undefined && isValidTimeZone(config.displayTimeZone);
  const timeZone = coerceTimeZone(config.displayTimeZone, browser);
  const isLocalZone = sameZone(timeZone, browser);
  const displayZone = isLocalZone ? undefined : timeZone;
  const timeZones = normalizeZoneColumns(config.timeZones);

  const axis = createVerticalAxis({ hourHeight, dayStartMin, dayEndMin });

  return {
    hourHeight,
    density,
    zoom,
    densityTokens: densityTokens(density),
    makeId: typeof config.makeId === "function" ? config.makeId : () => randomId("ev"),
    dayStartHour,
    dayEndHour,
    dayStartMin,
    dayEndMin,
    dayMinutes,
    canvasHeight: dayMinutes * perMin,
    snapMinutes: snap,
    snapFineMinutes: snapFine,
    minEventMinutes: minEvent,
    locale: config.locale,
    hour12: config.hour12,
    timeFormat,

    axis,
    minutesToPx: (min) => axis.toPx(min),
    durationToPx: (min) => axis.durationToPx(min),
    pxToMinutes: (px) => axis.pxToMinutes(px),
    pxToDuration: (px) => axis.pxToDuration(px),
    clampMinutes: (min) => axis.clamp(min),
    formatMinutes: (min) => formatMinutes(min, timeFormat),
    formatRange: (a, b) => formatRange(a, b, timeFormat),

    timeZone,
    displayZone,
    isLocalZone,
    hasDisplayZone,
    timeZones,

    toDisplay: (t) => displayDate(t, displayZone),
    fromDisplay: (d) => (displayZone ? unzonedInstant(d, displayZone) : d.getTime()),
    displayNow: () => displayDate(Date.now(), displayZone),
    zoneLabel: (at) => zoneAbbr(at ?? Date.now(), timeZone),
  };
}

/** The settings a component gets with no `<Kloq>` above it. */
export const DEFAULT_SETTINGS: KloqSettings = createSettings();

"use client";

/**
 * Calendar-source registry: accounts and their calendars, plus pure helpers.
 * The component never owns provider auth; hosts register what they connected.
 */

import { useCallback, useSyncExternalStore } from "react";
import { type CalEvent, DEFAULT_EVENT_COLOR, type EventColor } from "./calendar-types";

/** A calendar's colour is a palette key, not a hex string, so it themes like any event. */
export type CalendarColor = EventColor;

/** One connected account — an identity, not a calendar. */
export interface CalendarAccount {
  /** stable identity; re-registering the same id replaces it in place */
  id: string;
  label: string;
  /** Free-text provider tag (`"google"`, `"outlook"`, …); the component never branches on it. */
  provider: string;
  /** Human name for the provider; falls back to {@link provider}. */
  providerLabel?: string;
  /** Avatar URL or `data:` URI — not a React node, this object must stay serialisable. */
  avatarUrl?: string;
  /**
   * Default conferencing for events created on this account, matched against
   * {@link ConferencingProvider.id}. Records intent only; the host mints links.
   */
  defaultConferencing?: string;
  /** Calendar new events land on; an id outside this account is ignored. */
  defaultCalendarId?: string;
  /** The account new events belong to by default; at most one should carry it. */
  isDefault?: boolean;
}

export interface ConferencingProvider {
  id: string;
  label: string;
}

/** Default list for the settings dialog; `"none"` is the absence of conferencing. */
export const CONFERENCING_PROVIDERS: readonly ConferencingProvider[] = [
  { id: "none", label: "No conferencing" },
  { id: "google-meet", label: "Google Meet" },
  { id: "zoom", label: "Zoom" },
  { id: "teams", label: "Microsoft Teams" },
];

export interface CalendarSource {
  /** stable identity — this is what `CalEvent.calendarId` points at */
  id: string;
  name: string;
  color: CalendarColor;
  accountId: string;
  /** shown on the grid; absent means visible */
  visible?: boolean;
  /** the host can't write here (a holiday feed, a shared team calendar) */
  readOnly?: boolean;
  /** new events land here. At most one should carry it; the first wins. */
  isDefault?: boolean;
}

const accounts = new Map<string, CalendarAccount>();
const sources = new Map<string, CalendarSource>();
const listeners = new Set<() => void>();

// Rebuilt on emit, not on read: useSyncExternalStore needs referentially stable snapshots.
let accountSnapshot: CalendarAccount[] = [];
let sourceSnapshot: CalendarSource[] = [];

const emit = () => {
  accountSnapshot = [...accounts.values()];
  sourceSnapshot = [...sources.values()];
  for (const l of listeners) l();
};

/** Register one or more accounts. Returns an unregister covering exactly this call. */
export function registerCalendarAccounts(...items: CalendarAccount[]): () => void {
  for (const a of items) accounts.set(a.id, a);
  emit();
  return () => {
    let changed = false;
    for (const a of items) changed = accounts.delete(a.id) || changed;
    if (changed) emit();
  };
}

/** Register one or more calendars. A re-registered id keeps its original slot. */
export function registerCalendarSources(...items: CalendarSource[]): () => void {
  for (const s of items) sources.set(s.id, s);
  emit();
  return () => {
    let changed = false;
    for (const s of items) changed = sources.delete(s.id) || changed;
    if (changed) emit();
  };
}

/** Register an account with its calendars; `accountId` is filled in from the account. */
export function registerCalendarAccount(
  account: CalendarAccount,
  ...calendars: (Omit<CalendarSource, "accountId"> & Partial<Pick<CalendarSource, "accountId">>)[]
): () => void {
  const offAccount = registerCalendarAccounts(account);
  const offSources = registerCalendarSources(
    ...calendars.map((c) => ({ ...c, accountId: c.accountId ?? account.id })),
  );
  return () => {
    offSources();
    offAccount();
  };
}

/** Current accounts, in registration order. Referentially stable. */
export function getCalendarAccounts(): CalendarAccount[] {
  return accountSnapshot;
}

/** Current calendars, in registration order. Referentially stable. */
export function getCalendarSources(): CalendarSource[] {
  return sourceSnapshot;
}

export function subscribeCalendarSources(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function clearCalendarSources(): void {
  if (accounts.size === 0 && sources.size === 0) return;
  accounts.clear();
  sources.clear();
  emit();
}

export function setCalendarVisible(id: string, visible: boolean): void {
  const s = sources.get(id);
  if (!s || isVisible(s) === visible) return;
  sources.set(id, { ...s, visible });
  emit();
}

export function toggleCalendarVisible(id: string): void {
  const s = sources.get(id);
  if (s) setCalendarVisible(id, !isVisible(s));
}

/** Make `id` the default calendar, clearing the flag elsewhere. No-op for read-only. */
export function setDefaultCalendar(id: string): void {
  const target = sources.get(id);
  if (!target || target.readOnly || target.isDefault) return;
  for (const [key, s] of sources) if (s.isDefault) sources.set(key, { ...s, isDefault: false });
  sources.set(id, { ...target, isDefault: true });
  emit();
}

function patchAccount(id: string, patch: Partial<Omit<CalendarAccount, "id">>): boolean {
  const a = accounts.get(id);
  if (!a) return false;
  const next = { ...a, ...patch };
  if (Object.entries(patch).every(([k, v]) => a[k as keyof CalendarAccount] === v)) return false;
  accounts.set(id, next);
  emit();
  return true;
}

export function setAccountConferencing(accountId: string, conferencing: string | undefined): void {
  patchAccount(accountId, { defaultConferencing: conferencing });
}

/** Set the calendar new events land on within an account; refuses foreign or read-only ones. */
export function setAccountDefaultCalendar(accountId: string, calendarId: string): void {
  const cal = sources.get(calendarId);
  if (!cal || cal.accountId !== accountId || cal.readOnly) return;
  patchAccount(accountId, { defaultCalendarId: calendarId });
}

export function setDefaultAccount(id: string): void {
  const target = accounts.get(id);
  if (!target || target.isDefault) return;
  for (const [key, a] of accounts) if (a.isDefault) accounts.set(key, { ...a, isDefault: false });
  accounts.set(id, { ...target, isDefault: true });
  emit();
}

/** Drop an account and every calendar under it; returns the removed calendar ids. */
export function disconnectAccount(id: string): string[] {
  const removed: string[] = [];
  for (const [key, s] of sources)
    if (s.accountId === id) {
      sources.delete(key);
      removed.push(key);
    }
  const hadAccount = accounts.delete(id);
  if (hadAccount || removed.length > 0) emit();
  return removed;
}

export function useCalendarSources(): {
  accounts: CalendarAccount[];
  sources: CalendarSource[];
} {
  const subscribe = useCallback((l: () => void) => subscribeCalendarSources(l), []);
  const list = useSyncExternalStore(subscribe, getCalendarSources, getCalendarSources);
  const accts = useSyncExternalStore(subscribe, getCalendarAccounts, getCalendarAccounts);
  return { accounts: accts, sources: list };
}

export const isVisible = (s: Pick<CalendarSource, "visible">) => s.visible !== false;

export function findCalendar(
  sources: readonly CalendarSource[],
  id: string | undefined,
): CalendarSource | undefined {
  if (!id) return undefined;
  return sources.find((s) => s.id === id);
}

/** Event colour: its own, else its calendar's, else the default. */
export function resolveEventColor(
  event: Pick<CalEvent, "color" | "calendarId">,
  sources: readonly CalendarSource[],
): CalendarColor {
  return event.color ?? findCalendar(sources, event.calendarId)?.color ?? DEFAULT_EVENT_COLOR;
}

export function visibleCalendarIds(sources: readonly CalendarSource[]): Set<string> {
  return new Set(sources.filter(isVisible).map((s) => s.id));
}

/** Only an event on a registered *and* hidden calendar is filtered out. */
export function isEventVisible(
  event: Pick<CalEvent, "calendarId">,
  sources: readonly CalendarSource[],
): boolean {
  const cal = findCalendar(sources, event.calendarId);
  return !cal || isVisible(cal);
}

/** Events on visible calendars, in input order. Returns the same array when nothing is hidden. */
export function filterVisibleEvents<T extends Pick<CalEvent, "calendarId">>(
  events: readonly T[],
  sources: readonly CalendarSource[],
): readonly T[] {
  const hidden = sources.filter((s) => !isVisible(s));
  if (hidden.length === 0) return events;
  const hiddenIds = new Set(hidden.map((s) => s.id));
  return events.filter((e) => !e.calendarId || !hiddenIds.has(e.calendarId));
}

/**
 * Where a new event lands: the flagged default, then the first writable visible
 * calendar, then the first writable one. `undefined` when nothing is registered.
 */
export function defaultCalendar(sources: readonly CalendarSource[]): CalendarSource | undefined {
  const writable = sources.filter((s) => !s.readOnly);
  return writable.find((s) => s.isDefault) ?? writable.find(isVisible) ?? writable[0];
}

export function defaultCalendarId(sources: readonly CalendarSource[]): string | undefined {
  return defaultCalendar(sources)?.id;
}

export interface CalendarAccountGroup {
  account: CalendarAccount;
  calendars: CalendarSource[];
}

/**
 * Group calendars under their accounts, both in registration order. A calendar
 * with no registered account gets a placeholder account; empty accounts are kept.
 */
export function groupByAccount(
  accounts: readonly CalendarAccount[],
  sources: readonly CalendarSource[],
): CalendarAccountGroup[] {
  const groups = new Map<string, CalendarAccountGroup>();
  for (const account of accounts) groups.set(account.id, { account, calendars: [] });
  for (const s of sources) {
    let g = groups.get(s.accountId);
    if (!g) {
      g = {
        account: { id: s.accountId, label: s.accountId, provider: "unknown" },
        calendars: [],
      };
      groups.set(s.accountId, g);
    }
    g.calendars.push(s);
  }
  return [...groups.values()];
}

export function findAccount(
  accounts: readonly CalendarAccount[],
  id: string | undefined,
): CalendarAccount | undefined {
  if (!id) return undefined;
  return accounts.find((a) => a.id === id);
}

/** The account new events belong to: the flagged default, else the first one. */
export function defaultAccount(accounts: readonly CalendarAccount[]): CalendarAccount | undefined {
  return accounts.find((a) => a.isDefault) ?? accounts[0];
}

/**
 * The calendar new events land on within one account: its `defaultCalendarId`
 * if still writable here, then the `isDefault` one, then the first writable visible one.
 */
export function accountDefaultCalendar(
  account: CalendarAccount,
  sources: readonly CalendarSource[],
): CalendarSource | undefined {
  const mine = sources.filter((s) => s.accountId === account.id && !s.readOnly);
  const named = mine.find((s) => s.id === account.defaultCalendarId);
  return named ?? mine.find((s) => s.isDefault) ?? mine.find(isVisible) ?? mine[0];
}

/** The default account's default calendar, else {@link defaultCalendar}. */
export function resolveDefaultCalendar(
  accounts: readonly CalendarAccount[],
  sources: readonly CalendarSource[],
): CalendarSource | undefined {
  const account = accounts.find((a) => a.isDefault);
  return (account && accountDefaultCalendar(account, sources)) ?? defaultCalendar(sources);
}

/** The `calendarId` a new event should carry, read off the live registry. */
export function newEventCalendarId(): string | undefined {
  return resolveDefaultCalendar(getCalendarAccounts(), getCalendarSources())?.id;
}

export function providerLabel(account: CalendarAccount): string {
  return account.providerLabel || account.provider || "Calendar";
}

/** Label for an account's conferencing choice, or `undefined`. An unknown id renders as itself. */
export function conferencingLabel(
  account: CalendarAccount,
  providers: readonly ConferencingProvider[] = CONFERENCING_PROVIDERS,
): string | undefined {
  const id = account.defaultConferencing;
  if (!id) return undefined;
  return providers.find((p) => p.id === id)?.label ?? id;
}

