/**
 * Clipboard copy/paste: `text/plain` is the readable summary, the iCalendar rides beside it in a
 * calendar flavour and is read back through `parseICS`; an internal buffer is the fallback.
 */

import { newEventId } from "./calendar-store";
import {
  addDays,
  type CalEvent,
  daysBetween,
  formatInstant,
  type Instant,
  instantPlus,
  isDateOnly,
  minutesOfDate,
  parseInstant,
  startOfLocalDay,
  toDateOnlyString,
  wallMinutesBetween,
} from "./calendar-types";
import { eventTitle } from "./event-text";
import { type ToICSOptions, toICS } from "./ics";
import { vcalendar } from "./ics-format";
import { parseICS } from "./ics-import";

const ICS_MIME = "text/calendar";

/** Chromium rejects `text/calendar` in a `ClipboardItem` and takes only `"web "`-prefixed custom types. */
const ICS_WEB_MIME = "web text/calendar";

const VEVENT_OPEN = "BEGIN:VEVENT";
const VEVENT_CLOSE = "END:VEVENT";

/** One `VCALENDAR` carrying every copied event, spliced from per-event `toICS` output. `""` for none. */
export function eventsToICS(events: readonly CalEvent[], opts: ToICSOptions = {}): string {
  if (events.length === 0) return "";
  const blocks: string[] = [];
  for (const e of events) {
    const doc = toICS(e, opts);
    const lines = doc.split("\r\n");
    const from = lines.indexOf(VEVENT_OPEN);
    const to = lines.lastIndexOf(VEVENT_CLOSE);
    if (from < 0 || to < from) continue;
    blocks.push(...lines.slice(from, to + 1));
  }
  if (blocks.length === 0) return "";
  return vcalendar(blocks, opts.prodId);
}

interface ClipboardTextOptions {
  locale?: string;
  hour12?: boolean;
  /** replace the whole per-event block */
  formatEvent?: (event: CalEvent) => string;
}

const dayFmt = (locale?: string) =>
  new Intl.DateTimeFormat(locale, {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  });

const timeFmt = (locale?: string, hour12?: boolean) =>
  new Intl.DateTimeFormat(locale, {
    hour: "numeric",
    minute: "2-digit",
    ...(hour12 === undefined ? {} : { hour12 }),
  });

/** The human-readable flavour: one block per event (title, day + range, location, link). */
export function eventsToText(events: readonly CalEvent[], opts: ClipboardTextOptions = {}): string {
  if (events.length === 0) return "";
  const day = dayFmt(opts.locale);
  const time = timeFmt(opts.locale, opts.hour12);
  const one =
    opts.formatEvent ??
    ((e: CalEvent): string => {
      const lines: string[] = [eventTitle(e)];
      const startMs = parseInstant(e.start);
      const endMs = parseInstant(e.end);
      if (Number.isNaN(startMs)) {
        lines.push(e.start);
      } else if (e.allDay) {
        const start = new Date(startMs);
        // exclusive end → inclusive last day
        const last = Number.isNaN(endMs)
          ? start
          : (() => {
              const d = addDays(new Date(endMs), -1);
              return d.getTime() < start.getTime() ? start : d;
            })();
        lines.push(
          daysBetween(start, last) === 0
            ? `${day.format(start)} · all day`
            : `${day.format(start)} – ${day.format(last)} · all day`,
        );
      } else {
        const start = new Date(startMs);
        const end = Number.isNaN(endMs) ? start : new Date(endMs);
        lines.push(
          daysBetween(start, end) === 0
            ? `${day.format(start)} · ${time.format(start)} – ${time.format(end)}`
            : `${day.format(start)} ${time.format(start)} – ${day.format(end)} ${time.format(end)}`,
        );
      }
      if (e.location) lines.push(e.location);
      if (e.meetingUrl) lines.push(e.meetingUrl);
      return lines.join("\n");
    });
  return events.map(one).join("\n\n");
}

export function looksLikeICS(text: string): boolean {
  return /BEGIN:\s*VCALENDAR/i.test(text) || /BEGIN:\s*VEVENT/i.test(text);
}

/** Parse pasted text into store events. Anything that isn't iCalendar returns `[]`. */
export function parseClipboardEvents(
  text: string,
  opts: { color?: CalEvent["color"] } = {},
): CalEvent[] {
  if (!text || !looksLikeICS(text)) return [];
  try {
    // fresh ids: a pasted UID must not collide with the event already on the grid
    return parseICS(text, {
      color: opts.color,
      uidToId: () => newEventId(),
    }).events;
  } catch {
    return [];
  }
}

interface RebaseOptions {
  /** where the EARLIEST copied event's start lands; a date-only target keeps each event's time of day */
  target: Instant;
  /** fresh id per pasted event; defaults to `newEventId` */
  newId?: (source: CalEvent) => string;
  /** appended to every pasted title */
  titleSuffix?: string;
}

/**
 * Move a copied set onto a new anchor: the earliest start goes to `target`, every other event keeps
 * its wall-clock offset from it. All-day events shift by whole calendar days.
 */
export function rebaseEvents(
  events: readonly CalEvent[],
  { target, newId = () => newEventId(), titleSuffix }: RebaseOptions,
): CalEvent[] {
  if (events.length === 0) return [];
  const parsed = events
    .map((e) => ({ e, ms: parseInstant(e.start) }))
    .filter((x) => !Number.isNaN(x.ms))
    .sort((a, b) => a.ms - b.ms);
  if (parsed.length === 0) return [];

  const baseInstant = parsed[0]!.e.start;
  const baseDate = new Date(parsed[0]!.ms);
  const targetMs = parseInstant(target);
  if (Number.isNaN(targetMs)) return [];
  const targetDate = new Date(targetMs);
  const targetDay = startOfLocalDay(targetDate);
  const dayAnchored = isDateOnly(target);

  return parsed.map(({ e, ms }) => {
    const id = newId(e);
    const title = titleSuffix ? `${e.title}${titleSuffix}` : e.title;
    const startDate = new Date(ms);

    if (e.allDay) {
      const dayOffset = daysBetween(baseDate, startDate);
      const endMs = parseInstant(e.end);
      const span = Number.isNaN(endMs) ? 1 : Math.max(1, daysBetween(startDate, new Date(endMs)));
      const from = addDays(targetDay, dayOffset);
      return {
        ...e,
        id,
        title,
        allDay: true,
        start: toDateOnlyString(from),
        end: toDateOnlyString(addDays(from, span)),
      } as CalEvent;
    }

    const duration = wallMinutesBetween(e.start, e.end);
    if (dayAnchored) {
      // pasted onto a day: keep the clock time, move the date
      const d = addDays(targetDay, daysBetween(baseDate, startDate));
      d.setMinutes(minutesOfDate(startDate));
      const start = formatInstant(d);
      return {
        ...e,
        id,
        title,
        allDay: false,
        start,
        end: instantPlus(start, duration),
      } as CalEvent;
    }

    const offset = wallMinutesBetween(baseInstant, e.start);
    const start = instantPlus(target, offset);
    return { ...e, id, title, allDay: false, start, end: instantPlus(start, duration) } as CalEvent;
  });
}

interface ClipboardPayload {
  events: CalEvent[];
  ics: string;
  text: string;
}

let internal: ClipboardPayload | null = null;

const setInternalClipboard = (p: ClipboardPayload | null): void => {
  internal = p;
};
const getInternalClipboard = (): ClipboardPayload | null => internal;

/** Which route a copy took: summary plus a calendar flavour, summary only, or the internal buffer only. */
type ClipboardWriteResult = "rich" | "text" | "internal";

export function buildClipboardPayload(
  events: readonly CalEvent[],
  opts: ClipboardTextOptions & ToICSOptions = {},
): ClipboardPayload {
  return {
    events: [...events],
    ics: eventsToICS(events, opts),
    text: eventsToText(events, opts),
  };
}

const blob = (type: string, data: string) => new Blob([data], { type });

/** Copy a selection to the system clipboard. The internal buffer is always written first. */
export async function writeEventsToClipboard(
  events: readonly CalEvent[],
  opts: ClipboardTextOptions & ToICSOptions = {},
): Promise<ClipboardWriteResult> {
  const payload = buildClipboardPayload(events, opts);
  setInternalClipboard(payload.events.length ? payload : null);
  if (payload.events.length === 0) return "internal";

  const nav = typeof navigator === "undefined" ? undefined : navigator;
  const CI = (globalThis as { ClipboardItem?: typeof ClipboardItem }).ClipboardItem;
  if (nav?.clipboard?.write && CI) {
    // one unsupported type sinks the whole item, so the calendar goes in exactly one flavour
    const flavours = CI.supports
      ? [ICS_MIME, ICS_WEB_MIME].filter((type) => CI.supports(type)).slice(0, 1)
      : [ICS_MIME, ICS_WEB_MIME];
    for (const type of flavours) {
      try {
        await nav.clipboard.write([
          new CI({
            "text/plain": blob("text/plain", payload.text),
            [type]: blob(type, payload.ics),
          }),
        ]);
        return "rich";
      } catch {
        // no `supports` to ask: the next spelling may be accepted
      }
    }
  }
  try {
    await nav?.clipboard?.writeText(payload.text);
    return "text";
  } catch {
    return "internal";
  }
}

interface ClipboardReadResult {
  events: CalEvent[];
  /** `"internal"` means the system clipboard failed */
  source: "system" | "internal" | "none";
}

/** Read events back: `text/calendar`, then `web text/calendar`, then iCalendar-looking text, then the buffer. */
export async function readEventsFromClipboard(
  opts: { color?: CalEvent["color"] } = {},
): Promise<ClipboardReadResult> {
  const nav = typeof navigator === "undefined" ? undefined : navigator;
  const fromText = (text: string) => parseClipboardEvents(text, opts);

  if (nav?.clipboard?.read) {
    try {
      const items = await nav.clipboard.read();
      for (const item of items) {
        for (const type of [ICS_MIME, ICS_WEB_MIME]) {
          if (!item.types.includes(type)) continue;
          const events = fromText(await (await item.getType(type)).text());
          if (events.length) return { events, source: "system" };
        }
      }
    } catch {}
  }
  try {
    const text = await nav?.clipboard?.readText();
    if (text) {
      const events = fromText(text);
      if (events.length) return { events, source: "system" };
    }
  } catch {}
  const buffered = getInternalClipboard();
  if (buffered && buffered.events.length)
    // fresh ids: pasting the buffer twice must give two events
    return {
      events: buffered.events.map((e) => ({ ...e, id: newEventId() })),
      source: "internal",
    };
  return { events: [], source: "none" };
}

/**
 * Colour science for the contrast tests: CSS `color-mix` in srgb/oklab, source-over, WCAG contrast.
 * Components are gamma-encoded 0–1.
 */

export interface RGB {
  r: number;
  g: number;
  b: number;
}

export interface RGBA extends RGB {
  /** 0–1 */
  a: number;
}

const clamp01 = (n: number) => (n < 0 ? 0 : n > 1 ? 1 : n);

export const rgb = (r: number, g: number, b: number): RGB => ({ r, g, b });

function srgbToLinear(c: number): number {
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

function linearToSrgb(c: number): number {
  return c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055;
}

// Björn Ottosson's Oklab matrices, verbatim.

interface Lab {
  L: number;
  a: number;
  b: number;
}

function srgbToOklab({ r, g, b }: RGB): Lab {
  const lr = srgbToLinear(r);
  const lg = srgbToLinear(g);
  const lb = srgbToLinear(b);
  const l = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb);
  const m = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb);
  const s = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb);
  return {
    L: 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    a: 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    b: 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
  };
}

function oklabToSrgb({ L, a, b }: Lab): RGB {
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.291485548 * b;
  const l = l_ * l_ * l_;
  const m = m_ * m_ * m_;
  const s = s_ * s_ * s_;
  return {
    r: clamp01(linearToSrgb(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s)),
    g: clamp01(linearToSrgb(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s)),
    b: clamp01(linearToSrgb(-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s)),
  };
}

const NAMED: Record<string, RGBA> = {
  white: { r: 1, g: 1, b: 1, a: 1 },
  black: { r: 0, g: 0, b: 0, a: 1 },
  transparent: { r: 0, g: 0, b: 0, a: 0 },
};

// `none` (CSS Color 4) appears in Tailwind's palette, e.g. `oklch(26.9% 0 none)`, and reads as 0
function num(token: string, full = 1): number {
  const t = token.trim();
  if (t === "none") return 0;
  return t.endsWith("%") ? (parseFloat(t) / 100) * full : parseFloat(t);
}

const comp = (token: string): number => (token.trim() === "none" ? 0 : parseFloat(token));

function args(src: string): string[] {
  return src
    .replace(/^[a-z]+\(/i, "")
    .replace(/\)$/, "")
    .split(/[\s,]+/)
    .filter(Boolean);
}

export function parseColor(input: string): RGBA | null {
  const css = input.trim();
  if (NAMED[css.toLowerCase()]) return { ...NAMED[css.toLowerCase()] };

  if (css.startsWith("#")) {
    const hex = css.slice(1);
    const wide = hex.length > 4;
    const size = wide ? 2 : 1;
    const at = (i: number) => {
      const part = hex.substr(i * size, size);
      return parseInt(wide ? part : part + part, 16) / 255;
    };
    if (hex.length !== 3 && hex.length !== 4 && hex.length !== 6 && hex.length !== 8) return null;
    return {
      r: at(0),
      g: at(1),
      b: at(2),
      a: hex.length === 4 || hex.length === 8 ? at(3) : 1,
    };
  }

  const fn = css.slice(0, css.indexOf("(")).toLowerCase();
  const parts = args(css).filter((p) => p !== "/");
  // the slash may be glued to a token
  const flat = args(css.replace(/\//g, " / "));
  const slash = flat.indexOf("/");
  const alpha = slash === -1 ? 1 : num(flat[slash + 1]);
  const c = slash === -1 ? parts : flat.slice(0, slash);

  if (fn === "rgb" || fn === "rgba")
    return {
      r: clamp01(num(c[0], 255) / (c[0].includes("%") ? 1 : 255)),
      g: clamp01(num(c[1], 255) / (c[1].includes("%") ? 1 : 255)),
      b: clamp01(num(c[2], 255) / (c[2].includes("%") ? 1 : 255)),
      a: c.length > 3 ? num(c[3]) : alpha,
    };

  if (fn === "oklch") {
    const L = num(c[0]);
    const C = comp(c[1]);
    const h = (comp(c[2]) * Math.PI) / 180;
    return {
      ...oklabToSrgb({ L, a: C * Math.cos(h), b: C * Math.sin(h) }),
      a: alpha,
    };
  }

  if (fn === "oklab")
    return {
      ...oklabToSrgb({ L: num(c[0]), a: comp(c[1]), b: comp(c[2]) }),
      a: alpha,
    };

  return null;
}

export function formatHex({ r, g, b }: RGB): string {
  const h = (n: number) =>
    Math.round(clamp01(n) * 255)
      .toString(16)
      .padStart(2, "0");
  return `#${h(r)}${h(g)}${h(b)}`;
}

/** `color-mix(in srgb, a <weightA>, b)`; alpha travels with the mix. */
export function mixSrgb(a: RGBA, b: RGBA, weightA: number): RGBA {
  const w = clamp01(weightA);
  const lerp = (x: number, y: number) => x * w + y * (1 - w);
  return {
    r: lerp(a.r, b.r),
    g: lerp(a.g, b.g),
    b: lerp(a.b, b.b),
    a: lerp(a.a, b.a),
  };
}

/** `color-mix(in oklab, a <weightA>, b)`. */
export function mixOklab(a: RGBA, b: RGBA, weightA: number): RGBA {
  const w = clamp01(weightA);
  const A = srgbToOklab(a);
  const B = srgbToOklab(b);
  return {
    ...oklabToSrgb({
      L: A.L * w + B.L * (1 - w),
      a: A.a * w + B.a * (1 - w),
      b: A.b * w + B.b * (1 - w),
    }),
    a: a.a * w + b.a * (1 - w),
  };
}

/** Source-over: a translucent layer painted on an opaque backdrop. */
export function over(layer: RGBA, backdrop: RGB): RGB {
  const a = clamp01(layer.a);
  return {
    r: layer.r * a + backdrop.r * (1 - a),
    g: layer.g * a + backdrop.g * (1 - a),
    b: layer.b * a + backdrop.b * (1 - a),
  };
}

/** WCAG 2.x relative luminance. */
function relativeLuminance({ r, g, b }: RGB): number {
  return 0.2126 * srgbToLinear(r) + 0.7152 * srgbToLinear(g) + 0.0722 * srgbToLinear(b);
}

/** WCAG 2.x contrast ratio, 1–21. Order-independent. */
export function contrastRatio(a: RGB, b: RGB): number {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

/** WCAG 2.2 AA for body text. */
export const AA_NORMAL_TEXT = 4.5;
/** WCAG 2.2 AA for large text and non-text contrast. */
export const AA_LARGE_TEXT = 3;

import {
  addDays,
  formatInstant,
  type Instant,
  isDateOnly,
  parseInstant,
  toDateOnlyString,
} from "./instant";
/** The pure half of the ⌘K menu: grouping, ordering and query matching. */

/** Built-in group order; anything else renders after it in registration order. */
export const COMMAND_GROUPS = [
  "Quick add",
  "Events",
  "Calendar",
  "Navigation",
  "View",
  "Appearance",
  "App",
] as const;

export type BuiltInCommandGroup = (typeof COMMAND_GROUPS)[number];

/** Group for a command that doesn't name one. */
export const DEFAULT_COMMAND_GROUP = "Commands";

/**
 * Every built-in ⌘K command, as ids. A `:*` entry is a family whose members are
 * minted at render time: `event:*` the search results, `jump:*` the visible-day
 * jumps, `view:*` the view switches, `range:*` prev/next, `scheme:*` light/dark/system.
 * Spread and filter this for `commandPalette.commands`; a family can also be
 * narrowed to exact ids (`"view:week"`).
 */
export const BUILT_IN_COMMANDS = [
  "quick-add:query",
  "event:*",
  "new-event",
  "quick-add",
  "move-to",
  "reset",
  "today",
  "go-to-date",
  "range:*",
  "jump:*",
  "view:*",
  "scheme:*",
  "theme:picker",
  "design-mode",
  "shortcuts",
] as const;

export type BuiltInCommand = (typeof BUILT_IN_COMMANDS)[number];

/** Is `id` in the allowlist? Entries match exactly, or a whole family via a `:*` suffix. */
export function commandAllowed(id: string, allowed: readonly string[] | undefined): boolean {
  if (!allowed) return true;
  return allowed.some(
    (entry) => entry === id || (entry.endsWith(":*") && id.startsWith(entry.slice(0, -1))),
  );
}

export interface CommandGroupModel<T> {
  value: string;
  items: T[];
}

interface Groupable {
  group?: string;
  order?: number;
}

/** Lowercase, diacritics stripped, whitespace collapsed. */
export function normalizeQuery(input: string): string {
  return input
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

/** Every token of `query` must appear in `haystack` (AND, substring, any order). Empty matches all. */
export function matchesQuery(haystack: string, query: string): boolean {
  const q = normalizeQuery(query);
  if (!q) return true;
  const hay = normalizeQuery(haystack);
  return q.split(" ").every((token) => hay.includes(token));
}

/** Bucket commands into ordered groups: `groupOrder` first, then first-seen; stable sort on `order` within. */
export function groupCommands<T extends Groupable>(
  commands: readonly T[],
  groupOrder: readonly string[] = COMMAND_GROUPS,
  fallbackGroup: string = DEFAULT_COMMAND_GROUP,
): CommandGroupModel<T>[] {
  const buckets = new Map<string, T[]>();
  for (const c of commands) {
    const name = c.group ?? fallbackGroup;
    const bucket = buckets.get(name);
    if (bucket) bucket.push(c);
    else buckets.set(name, [c]);
  }

  const rank = new Map(groupOrder.map((name, i) => [name, i]));
  const out: CommandGroupModel<T>[] = [];
  for (const [value, items] of buckets) {
    out.push({ value, items: [...items].sort((a, b) => (a.order ?? 0) - (b.order ?? 0)) });
  }

  const seen = [...buckets.keys()];
  out.sort((a, b) => {
    const ra = rank.get(a.value);
    const rb = rank.get(b.value);
    if (ra !== undefined && rb !== undefined) return ra - rb;
    if (ra !== undefined) return -1;
    if (rb !== undefined) return 1;
    return seen.indexOf(a.value) - seen.indexOf(b.value);
  });
  return out;
}

/** Past this many visible days the per-day "Jump to" rows are dropped in favour of the typed-date jump. */
export const MAX_DAY_JUMPS = 14;

export function dayJumps<T>(days: readonly T[]): readonly T[] {
  return days.length > MAX_DAY_JUMPS ? [] : days;
}

/** A read-only event is never offered an edit command. */
export function canEditEvent(event: { readOnly?: boolean } | null | undefined): boolean {
  return event != null && event.readOnly !== true;
}

const DAY_MS = 86_400_000;

/**
 * The start/end a "Move to…" writes. An all-day event stays all-day: the target's
 * date moves it and its day span is kept; a typed time is ignored.
 */
export function movePatch(
  event: { start: Instant; end: Instant; allDay?: boolean },
  target: { start: Date; end: Date },
  timeZone?: string,
): { start: Instant; end: Instant } {
  if (event.allDay === true || isDateOnly(event.start)) {
    const span = Math.max(
      1,
      Math.round((parseInstant(event.end) - parseInstant(event.start)) / DAY_MS),
    );
    return {
      start: toDateOnlyString(target.start),
      end: toDateOnlyString(addDays(target.start, Number.isNaN(span) ? 1 : span)),
    };
  }
  return {
    start: formatInstant(target.start, timeZone),
    end: formatInstant(target.end, timeZone),
  };
}

"use client";

/** Command registration — a module-level registry hosts push ⌘K actions into. */

export interface KloqCommand {
  /** stable identity — re-registering the same id replaces it in place */
  id: string;
  label: string;
  /** extra words to match on that aren't in the label */
  keywords?: string;
  /** cosmetic shortcut hint, e.g. "⌘K" */
  hint?: string;
  /** group heading; unknown groups render after the built-in ones */
  group?: string;
  /** sort key within a group; lower first, default 0 */
  order?: number;
  /** when present the row renders a check; the label should still describe the action */
  checked?: boolean;
  disabled?: boolean;
  run: () => void;
}

const registry = new Map<string, KloqCommand>();
const listeners = new Set<() => void>();

const emit = () => {
  for (const l of listeners) l();
};

/** Register commands; returns an unregister function covering exactly what this call added. */
export function registerCommands(...commands: KloqCommand[]): () => void {
  for (const c of commands) registry.set(c.id, c);
  emit();
  return () => {
    let changed = false;
    for (const c of commands) changed = registry.delete(c.id) || changed;
    if (changed) emit();
  };
}

export function getCommands(): KloqCommand[] {
  return [...registry.values()];
}

export function subscribeCommands(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Test/teardown helper — drops every registration. */
export function clearCommands(): void {
  if (registry.size === 0) return;
  registry.clear();
  emit();
}

/**
 * Conflict detection: which events double-book somebody, in real epoch time, honoring free/busy.
 * Scheduling, not layout — `lib/overlap.ts` is the layout question.
 */

import { attendeeStatus, emailKey } from "./attendees";
import { type CalEvent, isBusy, isDateOnly, parseInstant } from "./calendar-types";
import { eventTitle } from "./event-text";

/** Half-open epoch-ms range: `[start, end)`. */
export interface EventInterval {
  start: number;
  end: number;
}

/** An event's occupied time, or `null` if its instants don't parse or `end <= start`. */
export function eventInterval(event: CalEvent): EventInterval | null {
  const start = parseInstant(event.start);
  const end = parseInstant(event.end);
  if (Number.isNaN(start) || Number.isNaN(end)) return null;
  if (end <= start) return null;
  return { start, end };
}

/** Half-open overlap: touching is not overlapping. */
export function intervalsOverlap(a: EventInterval, b: EventInterval): boolean {
  return a.start < b.end && b.start < a.end;
}

/** Milliseconds two intervals share, or 0. */
export function overlapMs(a: EventInterval, b: EventInterval): number {
  return Math.max(0, Math.min(a.end, b.end) - Math.max(a.start, b.start));
}

/** Stands in for the calendar owner when an event names nobody; `\0`-prefixed so it never collides with an address. */
export const SELF_PARTICIPANT = "\u0000self";

export interface ConflictOptions {
  /** only report a collision when the two events share a person; default `false` */
  requireSharedAttendee?: boolean;
  /** who "you" are: an event you're on and an event with no attendees both count as yours */
  viewer?: string;
  /** whether an all-day event can conflict; default `false` */
  includeAllDay?: boolean;
  /** ignore attendees who declined; default `true` */
  ignoreDeclined?: boolean;
  /** resource views: two events only collide when this says they share a resource (a room, a person) */
  sameResource?: ConflictScope;
}

export type ConflictScope = (a: CalEvent, b: CalEvent) => boolean;

const scopes = new WeakMap<object, ConflictScope[]>();

/**
 * A mounted resource view registers how its store's events share resources.
 * Per store: nothing registered for one calendar is ever consulted for another.
 * Returns the function that takes this registration back out.
 */
export function registerConflictScope(store: object, scope: ConflictScope): () => void {
  const list = scopes.get(store) ?? [];
  scopes.set(store, [...list, scope]);
  return () => {
    const next = (scopes.get(store) ?? []).filter((s) => s !== scope);
    if (next.length) scopes.set(store, next);
    else scopes.delete(store);
  };
}

/** Replace every registration for this store with one scope; `null` clears them. */
export function setConflictScope(store: object, scope: ConflictScope | null): void {
  if (scope) scopes.set(store, [scope]);
  else scopes.delete(store);
}

/** The scope the most recently mounted resource view registered for this store. */
export function conflictScopeOf(store: object): ConflictScope | undefined {
  return scopes.get(store)?.at(-1);
}

function sharesResource(a: CalEvent, b: CalEvent, opts: ConflictOptions): boolean {
  return opts.sameResource ? opts.sameResource(a, b) : true;
}

/** Organiser plus attendees, lowercased; `SELF_PARTICIPANT` (and the viewer) when the event names nobody. */
export function participantsOf(event: CalEvent, opts: ConflictOptions = {}): Set<string> {
  const ignoreDeclined = opts.ignoreDeclined !== false;
  const out = new Set<string>();
  if (event.organizer) out.add(emailKey(event.organizer));
  for (const a of event.attendees ?? []) {
    if (ignoreDeclined && attendeeStatus(a) === "declined") continue;
    out.add(emailKey(a.email));
  }
  if (out.size === 0) {
    out.add(SELF_PARTICIPANT);
    if (opts.viewer) out.add(emailKey(opts.viewer));
  }
  return out;
}

/** Who both events occupy time for, in `a`'s order. */
export function sharedParticipants(a: CalEvent, b: CalEvent, opts: ConflictOptions = {}): string[] {
  const other = participantsOf(b, opts);
  return [...participantsOf(a, opts)].filter((p) => other.has(p));
}

/** Can this event collide with anything at all? */
export function isBlocking(event: CalEvent, opts: ConflictOptions = {}): boolean {
  if (!isBusy(event)) return false;
  if (!opts.includeAllDay && (event.allDay === true || isDateOnly(event.start))) return false;
  return eventInterval(event) !== null;
}

/** Two events, the time they share, and who's double-booked by it. */
export interface ConflictPair {
  a: CalEvent;
  b: CalEvent;
  /** the shared slice, epoch ms, half-open */
  overlap: EventInterval;
  /** who's on both; empty only when `requireSharedAttendee` is off */
  shared: string[];
}

/** Do these two conflict? Same-id pairs never do. */
export function isConflicting(a: CalEvent, b: CalEvent, opts: ConflictOptions = {}): boolean {
  return conflictBetween(a, b, opts) !== null;
}

/** The pair, or `null` if these two don't conflict. */
export function conflictBetween(
  a: CalEvent,
  b: CalEvent,
  opts: ConflictOptions = {},
): ConflictPair | null {
  if (a.id === b.id) return null;
  if (!isBlocking(a, opts) || !isBlocking(b, opts)) return null;
  const ia = eventInterval(a);
  const ib = eventInterval(b);
  if (!ia || !ib || !intervalsOverlap(ia, ib)) return null;
  if (!sharesResource(a, b, opts)) return null;
  const shared = opts.requireSharedAttendee ? sharedParticipants(a, b, opts) : [];
  if (opts.requireSharedAttendee && shared.length === 0) return null;
  return {
    a,
    b,
    overlap: {
      start: Math.max(ia.start, ib.start),
      end: Math.min(ia.end, ib.end),
    },
    shared,
  };
}

/** Every conflicting pair in the list, via a sort-and-sweep; output order is stable. */
export function findConflicts(
  events: readonly CalEvent[],
  opts: ConflictOptions = {},
): ConflictPair[] {
  const blocking = events
    .filter((e) => isBlocking(e, opts))
    .map((e) => ({ event: e, interval: eventInterval(e)! }))
    .sort(
      (x, y) =>
        x.interval.start - y.interval.start ||
        x.interval.end - y.interval.end ||
        x.event.id.localeCompare(y.event.id),
    );

  const out: ConflictPair[] = [];
  const active: typeof blocking = [];
  for (const cur of blocking) {
    for (let i = active.length - 1; i >= 0; i--) {
      if (active[i].interval.end <= cur.interval.start) active.splice(i, 1);
    }
    for (const open of active) {
      const pair = conflictBetween(open.event, cur.event, opts);
      if (pair) out.push(pair);
    }
    active.push(cur);
  }
  return out;
}

/** The events that conflict with `event`, earliest first. `events` may contain `event` itself. */
export function conflictsFor(
  event: CalEvent,
  events: readonly CalEvent[],
  opts: ConflictOptions = {},
): CalEvent[] {
  if (!isBlocking(event, opts)) return [];
  const hits: { e: CalEvent; start: number }[] = [];
  for (const other of events) {
    if (!conflictBetween(event, other, opts)) continue;
    hits.push({ e: other, start: parseInstant(other.start) });
  }
  return hits.sort((x, y) => x.start - y.start || x.e.id.localeCompare(y.e.id)).map((h) => h.e);
}

/** Connected components of the conflict graph, ordered by earliest start; members by start then id. */
export function conflictClusters(
  events: readonly CalEvent[],
  opts: ConflictOptions = {},
): CalEvent[][] {
  const pairs = findConflicts(events, opts);
  if (pairs.length === 0) return [];

  const parent = new Map<string, string>();
  const find = (id: string): string => {
    let root = parent.get(id) ?? id;
    if (root !== id) {
      root = find(root);
      parent.set(id, root);
    }
    return root;
  };
  const union = (x: string, y: string) => {
    const rx = find(x);
    const ry = find(y);
    if (rx !== ry) parent.set(rx, ry);
  };

  const byId = new Map<string, CalEvent>();
  for (const p of pairs) {
    byId.set(p.a.id, p.a);
    byId.set(p.b.id, p.b);
    parent.set(p.a.id, parent.get(p.a.id) ?? p.a.id);
    parent.set(p.b.id, parent.get(p.b.id) ?? p.b.id);
    union(p.a.id, p.b.id);
  }

  const groups = new Map<string, CalEvent[]>();
  for (const [id, event] of byId) {
    const root = find(id);
    const group = groups.get(root);
    if (group) group.push(event);
    else groups.set(root, [event]);
  }

  const startOf = (e: CalEvent) => parseInstant(e.start);
  const clusters = [...groups.values()].map((g) =>
    g.sort((x, y) => startOf(x) - startOf(y) || x.id.localeCompare(y.id)),
  );
  return clusters.sort((x, y) => startOf(x[0]) - startOf(y[0]) || x[0].id.localeCompare(y[0].id));
}

/** "Overlaps Design review" / "Overlaps Design review and 2 others"; `""` for none. */
export function describeConflicts(conflicts: readonly CalEvent[]): string {
  if (conflicts.length === 0) return "";
  const first = eventTitle(conflicts[0]);
  if (conflicts.length === 1) return `Overlaps ${first}`;
  if (conflicts.length === 2) {
    const second = eventTitle(conflicts[1]);
    return `Overlaps ${first} and ${second}`;
  }
  return `Overlaps ${first} and ${conflicts.length - 1} others`;
}

/**
 * Constraints — the pure half of "the grid refuses a drop". Takes slots as
 * `Date` pairs and answers yes/no. A constraint restricts only what a gesture
 * NEWLY occupies; any region the event already covered is exempt.
 */

import { addDays, type CalEvent, type DayColumns, startOfLocalDay } from "./calendar-types";
import { MINUTES_PER_DAY } from "./date-math";

/** A window a gesture wants to occupy; `end` exclusive. All-day slots span local midnights. */
export interface Slot {
  start: Date;
  end: Date;
  allDay: boolean;
}

export type ConstraintGesture =
  | "create"
  | "move"
  | "resize"
  | "lane-move"
  | "lane-resize"
  | "duplicate"
  | "paste";

/** Does this gesture get the "already occupied" exemption? `false` for those making a NEW event. */
export const EXEMPTS_ORIGIN: Record<ConstraintGesture, boolean> = {
  create: false,
  move: true,
  resize: true,
  "lane-move": true,
  "lane-resize": true,
  duplicate: false,
  paste: false,
};

/** Constraints as a host passes them — every field optional. */
export interface KloqConstraints {
  /** Nothing may start before this instant (inclusive); all-day slots compare at day granularity. */
  minDate?: Date;
  /** Nothing may end after this instant; all-day slots may run to the end of its day. */
  maxDate?: Date;
  /** Return `true` to refuse a slot. Called with sub-slices and sampled to paint, so cheap and pure. */
  isSlotDisabled?(slot: Slot): boolean;
  /** Whole-drop veto about the event, not the time. Called once with the full target, never on create. */
  canDrop?(event: CalEvent, target: Slot): boolean;
}

export interface Constraints {
  /** Is there any constraint at all? Every entry point short-circuits on `!active`. */
  readonly active: boolean;
  /** epoch ms; `-Infinity` when the host passed no (valid) `minDate` */
  readonly minTime: number;
  /** epoch ms; `+Infinity` when the host passed no (valid) `maxDate` */
  readonly maxTime: number;
  readonly minDayTime: number;
  readonly maxDayTime: number;
  readonly hasBounds: boolean;
  readonly hasSlotRule: boolean;
  readonly hasDropRule: boolean;
  isSlotDisabled(slot: Slot): boolean;
  canDrop(event: CalEvent, target: Slot): boolean;
}

function timeOf(d: Date | undefined, fallback: number): number {
  if (!(d instanceof Date)) return fallback;
  const t = d.getTime();
  return Number.isFinite(t) ? t : fallback;
}

/** Resolve host constraints; invalid input degrades rather than throwing. */
export function createConstraints(c: KloqConstraints = {}): Constraints {
  const minTime = timeOf(c.minDate, -Infinity);
  const maxTime = timeOf(c.maxDate, Infinity);
  const hasBounds = minTime !== -Infinity || maxTime !== Infinity;
  const hasSlotRule = typeof c.isSlotDisabled === "function";
  const hasDropRule = typeof c.canDrop === "function";

  const slotRule = c.isSlotDisabled;
  const dropRule = c.canDrop;

  return {
    active: hasBounds || hasSlotRule || hasDropRule,
    minTime,
    maxTime,
    minDayTime: minTime === -Infinity ? -Infinity : startOfLocalDay(new Date(minTime)).getTime(),
    maxDayTime:
      maxTime === Infinity ? Infinity : addDays(startOfLocalDay(new Date(maxTime)), 1).getTime(),
    hasBounds,
    hasSlotRule,
    hasDropRule,
    isSlotDisabled: slotRule ? (slot) => slotRule(slot) === true : () => false,
    canDrop: dropRule ? (e, t) => dropRule(e, t) !== false : () => true,
  };
}

export const NO_CONSTRAINTS: Constraints = createConstraints();

/** Is this slot inside `[minDate, maxDate]`? A slot ending exactly at `minDate` is out. */
export function withinBounds(c: Constraints, slot: Slot): boolean {
  if (!c.hasBounds) return true;
  const lo = slot.allDay ? c.minDayTime : c.minTime;
  const hi = slot.allDay ? c.maxDayTime : c.maxTime;
  return slot.start.getTime() >= lo && slot.end.getTime() <= hi;
}

/** Bounds and the host's slot rule together. `canDrop` is NOT part of this. */
export function slotAllowed(c: Constraints, slot: Slot): boolean {
  if (!c.active) return true;
  if (!withinBounds(c, slot)) return false;
  return !c.isSlotDisabled(slot);
}

/** The parts of `target` that `origin` did not already cover — 0, 1 or 2 pieces. */
export function newlyOccupied(target: Slot, origin?: Slot): Slot[] {
  if (!origin || origin.allDay !== target.allDay) return [target];
  const ts = target.start.getTime();
  const te = target.end.getTime();
  const os = origin.start.getTime();
  const oe = origin.end.getTime();
  if (oe <= ts || os >= te) return [target]; // disjoint
  const out: Slot[] = [];
  if (ts < os) out.push({ start: target.start, end: new Date(os), allDay: target.allDay });
  if (te > oe) out.push({ start: new Date(oe), end: target.end, allDay: target.allDay });
  return out;
}

export interface DropRequest {
  gesture: ConstraintGesture;
  target: Slot;
  /** what it occupied before; absent for create and paste */
  origin?: Slot;
  event?: CalEvent;
}

/** Why a drop was refused. `slot` is the offending piece, for the copy. */
interface Refusal {
  gesture: ConstraintGesture;
  reason: "bounds" | "disabled" | "canDrop";
  slot: Slot;
}

/** Evaluate a gesture. `null` means allowed. */
export function refusalOf(c: Constraints, req: DropRequest): Refusal | null {
  if (!c.active) return null;
  const { gesture, target } = req;

  if (c.hasBounds || c.hasSlotRule) {
    const origin = EXEMPTS_ORIGIN[gesture] ? req.origin : undefined;
    for (const piece of newlyOccupied(target, origin)) {
      if (!withinBounds(c, piece)) return { gesture, reason: "bounds", slot: piece };
      if (c.hasSlotRule && c.isSlotDisabled(piece))
        return { gesture, reason: "disabled", slot: piece };
    }
  }

  // Host veto last: most expensive, and never called without an event.
  if (c.hasDropRule && req.event && !c.canDrop(req.event, target))
    return { gesture, reason: "canDrop", slot: target };

  return null;
}

export function allows(c: Constraints, req: DropRequest): boolean {
  return refusalOf(c, req) === null;
}

/** Build a timed slot from column space; `toInstant` (`settings.fromDisplay`) keeps it zone-agnostic. */
export function timedSlot(
  view: DayColumns,
  col: number,
  startMin: number,
  endMin: number,
  toInstant: (d: Date) => number = (d) => d.getTime(),
): Slot {
  const day = view.days[Math.max(0, Math.min(view.days.length - 1, col))];
  const base = startOfLocalDay(day);
  const s = new Date(base);
  s.setMinutes(s.getMinutes() + Math.round(startMin));
  const e = new Date(base);
  e.setMinutes(e.getMinutes() + Math.round(endMin));
  return { start: new Date(toInstant(s)), end: new Date(toInstant(e)), allDay: false };
}

/** Build an all-day slot spanning columns `[startCol, endCol]` inclusive. No zone conversion. */
export function allDaySlot(view: DayColumns, startCol: number, endCol: number): Slot {
  const n = view.days.length - 1;
  const a = Math.max(0, Math.min(n, Math.min(startCol, endCol)));
  const b = Math.max(0, Math.min(n, Math.max(startCol, endCol)));
  return {
    start: startOfLocalDay(view.days[a]),
    end: addDays(startOfLocalDay(view.days[b]), 1),
    allDay: true,
  };
}

interface DisabledBand {
  dayIndex: number;
  startMin: number;
  endMin: number;
}

interface BandOptions {
  dayStartMin?: number;
  dayEndMin?: number;
  /** Sampling resolution; defaults to 15, callers pass `settings.snapMinutes` so bands match the snap. */
  stepMinutes?: number;
  toInstant?: (d: Date) => number;
}

/** Every refused region in the visible range, merged into runs. Sampled; never call from the rAF loop. */
export function disabledBands(
  view: DayColumns,
  c: Constraints,
  opts: BandOptions = {},
): DisabledBand[] {
  if (!c.active || !(c.hasBounds || c.hasSlotRule)) return [];
  const from = opts.dayStartMin ?? 0;
  const to = opts.dayEndMin ?? MINUTES_PER_DAY;
  const step = Math.max(1, Math.round(opts.stepMinutes ?? 15));
  const bands: DisabledBand[] = [];

  for (let col = 0; col < view.days.length; col++) {
    let runStart: number | null = null;
    for (let min = from; min < to; min += step) {
      const end = Math.min(to, min + step);
      const blocked = !slotAllowed(c, timedSlot(view, col, min, end, opts.toInstant));
      if (blocked) {
        if (runStart === null) runStart = min;
      } else if (runStart !== null) {
        bands.push({ dayIndex: col, startMin: runStart, endMin: min });
        runStart = null;
      }
    }
    if (runStart !== null) bands.push({ dayIndex: col, startMin: runStart, endMin: to });
  }
  return bands;
}

export function disabledAllDayColumns(view: DayColumns, c: Constraints): number[] {
  if (!c.active || !(c.hasBounds || c.hasSlotRule)) return [];
  const out: number[] = [];
  for (let col = 0; col < view.days.length; col++)
    if (!slotAllowed(c, allDaySlot(view, col, col))) out.push(col);
  return out;
}

/**
 * craft-bus — rAF-cadence drag frames from the engine to imperative subscribers.
 * Subscribers write to refs/DOM directly; never setState per frame.
 */

export type DragKind = "create" | "move" | "resize-start" | "resize-end";

export interface DragFrame {
  kind: DragKind;
  id: string;
  velocity: number;
  rect: { x: number; y: number; width: number; height: number };
  startMin: number;
  endMin: number;
  dayIndex: number;
  /** inclusive last day — present on all-day lane drags (rect is in lane coords) */
  endDayIndex?: number;
  pointer: { x: number; y: number };
}

export type CraftEvent =
  | { type: "drag:start"; frame: DragFrame }
  | { type: "drag:frame"; frame: DragFrame }
  | { type: "drag:end"; frame: DragFrame; cancelled: boolean }
  | { type: "design-mode"; enabled: boolean };

type Listener = (e: CraftEvent) => void;

const listeners = new Set<Listener>();

let lastFrame: DragFrame | null = null;
let designMode = false;

export const craftBus = {
  emit(e: CraftEvent) {
    if (e.type === "drag:frame" || e.type === "drag:start") lastFrame = e.frame;
    if (e.type === "drag:end") lastFrame = null;
    if (e.type === "design-mode") designMode = e.enabled;
    for (const l of listeners) l(e);
  },
  subscribe(l: Listener): () => void {
    listeners.add(l);
    return () => listeners.delete(l);
  },
  get frame() {
    return lastFrame;
  },
  get designMode() {
    return designMode;
  },
};

/**
 * A memoised `Intl.DateTimeFormat` cache.
 *
 * ## Why
 *
 * `d.toLocaleDateString(locale, opts)` constructs a fresh `Intl.DateTimeFormat`
 * on every call. Constructing one is *expensive* — locale data lookup, pattern
 * resolution — and formatting with an existing one is nearly free. The ratio is
 * roughly two orders of magnitude.
 *
 * That does not matter for a header. It matters a great deal for an accessible
 * name, because every event in every view has one: the agenda builds a full
 * date string per row, the month view builds one per cell and one per hidden
 * event. Measured on a 30-day agenda over a dense store, the uncached calls
 * were the single largest cost in the whole render path — larger than the
 * projection, larger than the layout, larger than anything.
 *
 * ## The cache
 *
 * Keyed by locale + the option bag. Unbounded on purpose: the key space is the
 * set of *literal option objects the source contains*, which is a handful, not
 * a function of the data. Nothing here holds a `Date`.
 *
 * `undefined` locale is a real, distinct key — it means "the runtime's own",
 * which is what every call site passes when the host hasn't set `locale`.
 */

type DateOptions = Intl.DateTimeFormatOptions;

const cache = new Map<string, Intl.DateTimeFormat>();

/**
 * A stable key for a locale + options pair.
 *
 * `JSON.stringify` on the options is safe here and only here: the option bags
 * in this package are module-level literals with a fixed key order, so the
 * serialisation is stable, and this runs once per *distinct* bag rather than
 * once per call.
 */
const keyOf = (locale: string | undefined, options: DateOptions) =>
  `${locale ?? ""}�${JSON.stringify(options)}`;

/** A shared, memoised formatter. Never construct one at a call site. */
export function dateFormatter(
  locale: string | undefined,
  options: DateOptions,
): Intl.DateTimeFormat {
  const key = keyOf(locale, options);
  let fmt = cache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    cache.set(key, fmt);
  }
  return fmt;
}

/** Drop-in for `d.toLocaleDateString(locale, options)`, without the construction. */
export function formatDate(d: Date, locale: string | undefined, options: DateOptions): string {
  return dateFormatter(locale, options).format(d);
}

/** Test seam. Nothing in the calendar calls this. */
export function clearDateFormatterCache(): void {
  cache.clear();
}

export const MS_PER_MINUTE = 60_000;
export const MS_PER_DAY = 86_400_000;
export const MINUTES_PER_DAY = 1440;

export const pad = (n: number, width = 2) => String(n).padStart(width, "0");
export const pad2 = (n: number) => pad(n);

export const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export const sameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

/** `month` is 1-based. */
export const daysInMonth = (year: number, month: number) =>
  new Date(Date.UTC(year, month, 0)).getUTCDate();

import { storageEnabled, storageKey } from "./storage";

/**
 * The two axes deciding how tall an hour is: density (base height + type +
 * padding) and zoom (a ladder multiplier that leaves type alone).
 */

/* ── density ── */

export type KloqDensity = "compact" | "comfortable";

export const DENSITIES: readonly KloqDensity[] = ["compact", "comfortable"];

export const DEFAULT_DENSITY: KloqDensity = "comfortable";

export function isDensity(v: unknown): v is KloqDensity {
  return v === "compact" || v === "comfortable";
}

/** `hourHeight` feeds `createSettings`; the rest become custom properties read by `styles/kloq.css`. */
export interface DensityTokens {
  /** px per hour before zoom */
  readonly hourHeight: number;
  /** event/chip label size in px */
  readonly fontSize: number;
  /** event/chip label leading, unitless */
  readonly lineHeight: number;
  /** vertical padding inside an event block, px */
  readonly paddingBlock: number;
  /** horizontal padding inside an event block, px (start/end) */
  readonly paddingInline: number;
  /** all-day chip row height, px */
  readonly chipHeight: number;
}

export const DENSITY_TOKENS: Record<KloqDensity, DensityTokens> = {
  comfortable: {
    hourHeight: 64,
    fontSize: 12,
    lineHeight: 1.25,
    paddingBlock: 3,
    paddingInline: 10,
    chipHeight: 22,
  },
  compact: {
    // 44px is the smallest hour that fits a two-line chip at 11px
    hourHeight: 44,
    fontSize: 11,
    lineHeight: 1.15,
    paddingBlock: 1,
    paddingInline: 7,
    chipHeight: 18,
  },
};

export function densityTokens(density: KloqDensity = DEFAULT_DENSITY): DensityTokens {
  return DENSITY_TOKENS[isDensity(density) ? density : DEFAULT_DENSITY];
}

/* ── zoom ── */

/**
 * The zoom ladder, as multipliers of the base hour height. A fixed table so
 * steps are exactly reversible; chosen so base 64 gives whole pixels at every rung.
 */
export const ZOOM_STEPS: readonly number[] = [
  0.5, 0.625, 0.75, 0.875, 1, 1.25, 1.5, 1.75, 2, 2.5, 3,
];

/** The rung that means "no zoom". */
export const ZOOM_DEFAULT = 4;

export const ZOOM_MIN = 0;
export const ZOOM_MAX = ZOOM_STEPS.length - 1;

/** A zoom level, coerced into the ladder. Junk (NaN, undefined) → default. */
export function clampZoom(level: number | undefined): number {
  if (level === undefined || !Number.isFinite(level)) return ZOOM_DEFAULT;
  return Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, Math.round(level)));
}

/** One rung in a direction. Saturates at the ends rather than wrapping. */
export function stepZoom(level: number, dir: 1 | -1): number {
  return clampZoom(clampZoom(level) + dir);
}

/** The multiplier at a rung. */
export function zoomFactor(level: number): number {
  return ZOOM_STEPS[clampZoom(level)];
}

export function isDefaultZoom(level: number): boolean {
  return clampZoom(level) === ZOOM_DEFAULT;
}

export function zoomLabel(level: number): string {
  return `${Math.round(zoomFactor(level) * 100)}%`;
}

/* ── resolved ── */

export interface DensityState {
  readonly density: KloqDensity;
  /** index into `ZOOM_STEPS` */
  readonly zoom: number;
}

export const DEFAULT_DENSITY_STATE: DensityState = {
  density: DEFAULT_DENSITY,
  zoom: ZOOM_DEFAULT,
};

/** Bounds shared with `createSettings` so the two can never disagree. */
export const MIN_HOUR_HEIGHT = 8;
export const MAX_HOUR_HEIGHT = 480;

/**
 * Turns the picked state into px per hour. An explicit `hourHeight` wins as the
 * base over density; zoom multiplies whichever won.
 */
export function resolveHourHeight(opts: {
  hourHeight?: number;
  density?: KloqDensity;
  zoom?: number;
}): number {
  const base =
    opts.hourHeight !== undefined && Number.isFinite(opts.hourHeight)
      ? opts.hourHeight
      : densityTokens(opts.density).hourHeight;
  const scaled = Math.round(base * zoomFactor(clampZoom(opts.zoom)));
  return Math.min(MAX_HOUR_HEIGHT, Math.max(MIN_HOUR_HEIGHT, scaled));
}

/** The custom properties a calendar root carries for a given state, ready for `style`. */
export function densityVars(state: DensityState = DEFAULT_DENSITY_STATE): Record<string, string> {
  const t = densityTokens(state.density);
  return {
    "--kloq-event-font-size": `${t.fontSize}px`,
    "--kloq-event-line-height": `${t.lineHeight}`,
    "--kloq-event-padding-block": `${t.paddingBlock}px`,
    "--kloq-event-padding-inline": `${t.paddingInline}px`,
    "--kloq-chip-height": `${t.chipHeight}px`,
  };
}

/* ── zoom-anchored scrolling ── */

interface AnchoredScrollInput {
  /** minutes-from-midnight that must stay put */
  anchorMin: number;
  /** px from the viewport's top edge */
  anchorOffset: number;
  /** the NEW scale, after the change */
  minutesToPx: (min: number) => number;
  scrollHeight: number;
  clientHeight: number;
}

/**
 * The scroll position that keeps `anchorMin` under `anchorOffset`. Clamped:
 * a scrollTop past the new maximum is silently rejected by the scroller.
 */
export function anchoredScrollTop(o: AnchoredScrollInput): number {
  const target = o.minutesToPx(o.anchorMin) - o.anchorOffset;
  const max = Math.max(0, o.scrollHeight - o.clientHeight);
  return Math.min(max, Math.max(0, target));
}

/** The minute under `anchorOffset` before the change, read on the OLD scale. */
export function minuteUnderAnchor(o: {
  scrollTop: number;
  anchorOffset: number;
  hourHeight: number;
  dayStartMin: number;
}): number {
  return (o.scrollTop + o.anchorOffset) / (o.hourHeight / 60) + o.dayStartMin;
}

/* ── persistence ── */

const DENSITY_STORAGE_KEY = "kloq-density";
const ZOOM_STORAGE_KEY = "kloq-zoom";
/** Stamped on `<html>` so `styles/kloq.css` can key off it pre-hydration. */
const DENSITY_ATTRIBUTE = "data-kloq-density";

export function readStoredDensity(): DensityState {
  if (!storageEnabled()) return DEFAULT_DENSITY_STATE;
  try {
    const d = localStorage.getItem(storageKey("density"));
    const z = localStorage.getItem(storageKey("zoom"));
    return {
      density: isDensity(d) ? d : DEFAULT_DENSITY,
      zoom: clampZoom(z === null ? undefined : Number(z)),
    };
  } catch {
    return DEFAULT_DENSITY_STATE;
  }
}

/** Persist both axes; a default value is removed, so a future default change reaches everyone. */
export function writeStoredDensity(state: DensityState): void {
  if (!storageEnabled()) return;
  try {
    if (state.density === DEFAULT_DENSITY) localStorage.removeItem(storageKey("density"));
    else localStorage.setItem(storageKey("density"), state.density);

    if (isDefaultZoom(state.zoom)) localStorage.removeItem(storageKey("zoom"));
    else localStorage.setItem(storageKey("zoom"), String(clampZoom(state.zoom)));
  } catch {
    /* storage unavailable */
  }
}

/** Pre-paint restore of the `<html>` attribute only; the px-per-hour half is React state. */
export function densityRestoreScript(prefix = "kloq"): string {
  return `try{var d=localStorage.getItem(${JSON.stringify(
    `${prefix}-density`,
  )});if(d==="compact"||d==="comfortable")document.documentElement.setAttribute(${JSON.stringify(
    DENSITY_ATTRIBUTE,
  )},d)}catch(e){}`;
}

/** `densityRestoreScript()` for the default prefix. */
export const DENSITY_RESTORE_SCRIPT = densityRestoreScript();

/* ── store ── */

let current: DensityState = DEFAULT_DENSITY_STATE;
let hydrated = false;
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

/** Stable identity — safe as a `useSyncExternalStore` snapshot. */
export function getDensityState(): DensityState {
  return current;
}

/** Always the defaults, never storage; `hydrateDensity()` closes the gap before paint. */
export function getServerDensityState(): DensityState {
  return DEFAULT_DENSITY_STATE;
}

export function subscribeDensity(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function setDensityState(next: Partial<DensityState>): DensityState {
  const merged: DensityState = {
    density: isDensity(next.density) ? next.density : current.density,
    zoom: next.zoom === undefined ? current.zoom : clampZoom(next.zoom),
  };
  if (merged.density === current.density && merged.zoom === current.zoom) return current;
  current = merged;
  writeStoredDensity(current);
  applyDensityAttribute(current.density);
  emit();
  return current;
}

export function setDensity(density: KloqDensity): DensityState {
  return setDensityState({ density });
}

export function setZoom(zoom: number): DensityState {
  return setDensityState({ zoom });
}

export function zoomBy(dir: 1 | -1): DensityState {
  return setDensityState({ zoom: stepZoom(current.zoom, dir) });
}

export function resetZoom(): DensityState {
  return setDensityState({ zoom: ZOOM_DEFAULT });
}

export function applyDensityAttribute(density: KloqDensity): void {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  if (density === DEFAULT_DENSITY) root.removeAttribute(DENSITY_ATTRIBUTE);
  else root.setAttribute(DENSITY_ATTRIBUTE, density);
}

/** Adopt the persisted state. Idempotent; only the first `<Kloq>` does any work. */
export function hydrateDensity(): DensityState {
  if (hydrated) return current;
  hydrated = true;
  const stored = readStoredDensity();
  if (stored.density !== current.density || stored.zoom !== current.zoom) {
    current = stored;
    applyDensityAttribute(current.density);
    emit();
  }
  return current;
}

/** Test seam. */
export function resetDensityStore(): void {
  current = DEFAULT_DENSITY_STATE;
  hydrated = false;
  listeners.clear();
}

/** Tuning constants for the drag engine. */

export const EDGE_ZONE = 56; // px from scroll edge where auto-scroll engages
export const EDGE_MAX_V = 14; // px per frame at full ramp
export const EASE = 0.38; // per-frame lerp toward the snapped target
export const LABEL_FLIP_H = 28; // below this height the draft label moves outside
export const LANE_ROW_H = 22;

/** px of overshoot per px/s of release velocity, capped at ±10px */
export const RESIZE_PUSH = 0.012;

export const ALIGN_PX = 4;

// touch threshold sits above base-ui's 10px long-press cancel radius, so a drag and its menu are exclusive
export const TOUCH_THRESHOLD_PX = 12;
export const BASEUI_LONG_PRESS_MOVE_PX = 10;
// what a long-press create makes when you lift without dragging; same as ⌘K quick-add
export const TOUCH_CREATE_MIN = 30;

/** DOM helpers the drag engine writes through: transforms, springs, commits. */
import { type JiggleState, liftOf } from "../drag-physics";
import type { PlacedEvent } from "../placement";
import { withoutSegment } from "../recurrence";
import { SPRING, SPRING_MS } from "../springs";
import type { CommitResult } from "./types";

export const capturePointer = (el: Element, pointerId: number) => {
  try {
    el.setPointerCapture(pointerId);
  } catch {
    /* uncapturable pointer */
  }
};

export function landCommit(result: CommitResult, settled: () => void, declined: () => void): void {
  if (result && typeof (result as Promise<boolean>).then === "function") {
    void (result as Promise<boolean>).then(
      (ok) => (ok ? settled() : declined()),
      () => declined(),
    );
    return;
  }
  settled();
}

// DOM-level lookup of a split event's other segments — no registry, usable from pointerdown
export function segmentSiblings(event: PlacedEvent, node: HTMLElement): HTMLElement[] {
  if (event.segment.n <= 1) return [];
  const base = withoutSegment(event.id);
  const root = node.closest("[data-craft='intent-threshold']") ?? node.ownerDocument;
  const out: HTMLElement[] = [];
  root.querySelectorAll<HTMLElement>("[data-cal-event]").forEach((el) => {
    const id = el.dataset.calEvent;
    if (el !== node && id && withoutSegment(id) === base) out.push(el);
  });
  return out;
}

export function setTransformAll(
  node: HTMLElement,
  siblings: readonly HTMLElement[],
  value: string,
): void {
  node.style.transform = value;
  for (const sib of siblings) sib.style.transform = value;
}

// returns the node's own animation — the one whose `onfinish` drives the commit
export function animateAll(
  node: HTMLElement,
  siblings: readonly HTMLElement[],
  keyframes: Keyframe[],
  options: KeyframeAnimationOptions,
): Animation {
  for (const sib of siblings) sib.animate(keyframes, options);
  return node.animate(keyframes, options);
}

export function springHomeFrom(
  node: HTMLElement,
  from: string,
  done: () => void,
  siblings: readonly HTMLElement[] = [],
): void {
  const anim = animateAll(
    node,
    siblings,
    [
      { transform: from, "--kloq-lift": node.style.getPropertyValue("--kloq-lift") || "1" },
      { transform: "none", "--kloq-lift": "0" },
    ],
    { duration: SPRING_MS, easing: SPRING },
  );
  anim.onfinish = () => {
    setTransformAll(node, siblings, "");
    done();
  };
}

export const liftFrom = (j: JiggleState) => ({ "--kloq-lift": liftOf(j).toFixed(3) });
export const LIFT_REST = { "--kloq-lift": "0" };

