// What the last setter asked for and <html> does not show yet: a view transition
// writes the DOM a frame later, the getters answer from here in the meantime.
let pendingTheme: string | null = null;
let pendingDark: boolean | null = null;

function flushPending(): void {
  const root = document.documentElement;
  if (pendingTheme !== null) {
    if (pendingTheme === "coss") root.removeAttribute("data-kloq-theme");
    else root.setAttribute("data-kloq-theme", pendingTheme);
    pendingTheme = null;
  }
  if (pendingDark !== null) {
    root.classList.toggle("dark", pendingDark);
    pendingDark = null;
  }
}

export function getTheme(): string {
  if (typeof document === "undefined") return "coss";
  return pendingTheme ?? document.documentElement.getAttribute("data-kloq-theme") ?? "coss";
}

type ViewTransitionDocument = Document & {
  startViewTransition?: (update: () => void) => { finished: Promise<void> };
};

/**
 * Runs `apply` inside one root view transition, so a theme or scheme swap is a single crossfade.
 * Where the API is missing or motion is reduced, `apply` runs synchronously.
 */
export function themeTransition(apply: () => void): void {
  const doc = document as ViewTransitionDocument;
  if (typeof doc.startViewTransition !== "function" || prefersReducedMotion()) {
    apply();
    return;
  }
  const root = document.documentElement;
  root.setAttribute("data-kloq-swapping", "");
  const done = () => root.removeAttribute("data-kloq-swapping");
  try {
    doc.startViewTransition(apply).finished.then(done, done);
  } catch {
    done();
    apply();
  }
}

/**
 * Applies a theme: stamps <html data-kloq-theme>, persists, and crossfades unless motion is reduced.
 * `getTheme()` and storage reflect it as soon as this returns; under a crossfade the attribute
 * itself lands a frame later.
 */
export function setTheme(id: string): void {
  pendingTheme = id;
  themeTransition(flushPending);

  if (!storageEnabled()) return;
  try {
    if (id === "coss") localStorage.removeItem(storageKey("theme"));
    else localStorage.setItem(storageKey("theme"), id);
  } catch {
    /* storage unavailable */
  }
}

// colour scheme: `.dark` on <html> is the coss convention; only touched once `setScheme` is called

export type KloqScheme = "light" | "dark" | "system";

const systemPrefersDark = () =>
  typeof matchMedia !== "undefined" && matchMedia("(prefers-color-scheme: dark)").matches;

export function getScheme(): KloqScheme {
  if (!storageEnabled()) return "system";
  try {
    const s = localStorage.getItem(storageKey("scheme"));
    return s === "light" || s === "dark" ? s : "system";
  } catch {
    return "system";
  }
}

/** What's actually on screen — "system" collapsed to light or dark. */
export function resolveScheme(pref: KloqScheme = getScheme()): "light" | "dark" {
  return pref === "system" ? (systemPrefersDark() ? "dark" : "light") : pref;
}

/** Applies a scheme; "system" clears the stored preference and follows the OS. Synchronous like `setTheme`. */
export function setScheme(pref: KloqScheme): void {
  pendingDark = resolveScheme(pref) === "dark";
  themeTransition(flushPending);

  if (!storageEnabled()) return;
  try {
    if (pref === "system") localStorage.removeItem(storageKey("scheme"));
    else localStorage.setItem(storageKey("scheme"), pref);
  } catch {
    /* storage unavailable */
  }
}

export function toggleScheme(): "light" | "dark" {
  const next = resolveScheme() === "dark" ? "light" : "dark";
  setScheme(next);
  return next;
}

/** Re-applies on OS scheme changes while the preference is "system". Returns an unsubscribe. */
export function watchSystemScheme(): () => void {
  const mq = matchMedia("(prefers-color-scheme: dark)");
  const onChange = () => {
    if (getScheme() === "system") document.documentElement.classList.toggle("dark", mq.matches);
  };
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
}

/** Pre-paint restore of both theme and scheme for a storage prefix, to inline in `<head>`. */
export function themeRestoreScript(prefix = "kloq"): string {
  const theme = JSON.stringify(`${prefix}-theme`);
  const scheme = JSON.stringify(`${prefix}-scheme`);
  return `try{var d=document.documentElement;var t=localStorage.getItem(${theme});if(t)d.setAttribute("data-kloq-theme",t);var s=localStorage.getItem(${scheme});var m=window.matchMedia("(prefers-color-scheme: dark)").matches;if(s==="dark"||(s!=="light"&&m))d.classList.add("dark")}catch(e){}`;
}

/** `themeRestoreScript()` for the default prefix. */
export const THEME_RESTORE_SCRIPT = themeRestoreScript();

/** Minute-of-day → clock label. */

export interface TimeFormatOptions {
  /** BCP 47 tag; omit for en-US */
  locale?: string;
  /** force a 12- or 24-hour clock; omit and the locale decides */
  hour12?: boolean;
}

const hour12Cache = new Map<string, boolean>();
function localeIsHour12(locale: string | undefined): boolean {
  const key = locale ?? "";
  const hit = hour12Cache.get(key);
  if (hit !== undefined) return hit;
  let is12 = true;
  try {
    is12 = new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions().hour12 ?? false;
  } catch {
    is12 = true;
  }
  hour12Cache.set(key, is12);
  return is12;
}

/** A throwaway Date carrying `min` as a local wall-clock time. */
const atMinutes = (min: number) => {
  const d = new Date(2000, 0, 1);
  d.setMinutes(Math.round(min));
  return d;
};

/**
 * A minute-of-day as a clock label — `"9 AM"`, `"9:30 AM"`, or `"13:30"` on a 24-hour clock.
 * On a 12-hour clock `:00` is dropped; on 24-hour it never is. Minutes past 1440 wrap.
 */
export function formatMinutes(min: number, opts?: TimeFormatOptions): string {
  const h = Math.floor(min / 60) % 24;
  const m = Math.round(min % 60);
  if (!opts || (opts.locale === undefined && opts.hour12 === undefined)) {
    const period = h < 12 ? "AM" : "PM";
    const h12 = h % 12 === 0 ? 12 : h % 12;
    return m === 0 ? `${h12} ${period}` : `${h12}:${String(m).padStart(2, "0")} ${period}`;
  }
  const use12 = opts.hour12 ?? localeIsHour12(opts.locale);
  const d = atMinutes(h * 60 + m);
  try {
    return d.toLocaleTimeString(
      opts.locale,
      use12
        ? m === 0
          ? { hour: "numeric", hour12: true }
          : { hour: "numeric", minute: "2-digit", hour12: true }
        : { hour: "2-digit", minute: "2-digit", hourCycle: "h23" },
    );
  } catch {
    return formatMinutes(min);
  }
}

/** `"9 AM – 10 AM"`. Same options, same defaults, as `formatMinutes`. */
export function formatRange(startMin: number, endMin: number, opts?: TimeFormatOptions): string {
  return `${formatMinutes(startMin, opts)} – ${formatMinutes(endMin, opts)}`;
}

/**
 * Sub-row stacking inside one lane.
 *
 * A declared row height and unbounded stacking pull against each other: a fixed
 * height cannot grow to fit however many bookings happen to overlap. This
 * resolves it the way the all-day lane already does — the height fixes a cap,
 * and anything past the cap collapses into a "+N more" affordance instead of
 * expanding the row. Heights therefore stay known before layout runs, which is
 * what keeps a windowing layer an addition rather than a rewrite.
 */

import type { Lane } from "./lane";
import { layoutDay, type OverlapInput } from "./overlap";

export interface SubRowLayout {
  /** sub-row index within the lane */
  row: number;
  /** how many sub-rows the lane actually draws, never above the cap */
  rows: number;
  /** past the cap: not drawn, counted into the overflow affordance instead */
  hidden: boolean;
}

/**
 * Greedy first-fit packing, reusing the calendar's cluster layout unchanged —
 * a bar's sub-row within a lane is the same problem as an event's column
 * within a day.
 */
export function layoutLane(
  events: readonly OverlapInput[],
  maxRows: number,
): Map<string, SubRowLayout> {
  const cap = Math.max(1, Math.floor(maxRows));
  const packed = layoutDay(events);
  const out = new Map<string, SubRowLayout>();
  let drawn = 0;
  for (const { col } of packed.values()) {
    if (col < cap) drawn = Math.max(drawn, col + 1);
  }
  for (const [id, { col }] of packed) {
    out.set(id, { row: col, rows: Math.max(1, drawn), hidden: col >= cap });
  }
  return out;
}

/** How many bars fit in a lane, from its declared height. Always at least one. */
export function maxSubRows(lane: Lane, defaultHeight: number, barHeight: number): number {
  const height = lane.height ?? defaultHeight;
  return Math.max(1, Math.floor(height / Math.max(1, barHeight)));
}

/**
 * The instant → (lane, span) projection for a timeline. A sibling of
 * `projectEvents`, sharing its prefilters and recurrence expansion.
 *
 * Two deliberate differences from the calendar's projection:
 *  - lanes resolve through the host's adapter, not from the column's date;
 *  - there is NO midnight segmentation. A booking that crosses midnight is one
 *    continuous bar, so `segment` is always `{ i: 0, n: 1 }`.
 */

import { asPlacementId, type CalEvent, DEFAULT_EVENT_COLOR, parseInstant } from "./calendar-types";
import { eventWindow, mayOverlapWindow, seriesMayOverlapWindow } from "./event-window";
import { type Lane, type LaneAdapter, laneIndexOf } from "./lane";
import type { PlacedOccurrence } from "./projection";
import {
  type ExpandRecurrenceFn,
  getRecurrenceEngine,
  type Occurrence,
  occurrenceKey,
} from "./recurrence";
import { minutesFromStart, type TimelineWindow } from "./timeline-window";

export interface TimelineProjection {
  /** a STABLE array; the engine reads it every rAF */
  all: PlacedOccurrence[];
}

export interface TimelineBounds {
  /** Recurrence expansion: omit for the registered engine, `false` to place every master once. */
  expand?: ExpandRecurrenceFn | false;
}

export function projectTimeline(
  events: readonly CalEvent[],
  lanes: readonly Lane[],
  window: TimelineWindow,
  adapter: LaneAdapter,
  bounds: TimelineBounds = {},
): TimelineProjection {
  const all: PlacedOccurrence[] = [];
  if (!lanes.length) return { all };

  const totalMin = minutesFromStart(window, window.end);
  const expand = bounds.expand ?? getRecurrenceEngine();
  const range = { start: window.start, end: window.end };

  const place = (
    e: CalEvent,
    start: string,
    end: string,
    occurrence?: Occurrence,
    truncated?: boolean,
  ) => {
    const laneIndex = laneIndexOf(adapter, lanes, e);
    if (laneIndex === -1) return;

    const startMs = parseInstant(start);
    const endMs = parseInstant(end);
    if (Number.isNaN(startMs) || Number.isNaN(endMs)) return;

    const rawStart = minutesFromStart(window, startMs);
    const rawEnd = Math.max(rawStart, minutesFromStart(window, endMs));
    // half-open: an event ending exactly at the left edge is outside
    if (rawEnd <= 0 || rawStart >= totalMin) return;

    const startMin = Math.max(0, rawStart);
    const endMin = Math.min(totalMin, rawEnd);

    all.push({
      ...e,
      id: occurrence ? occurrenceKey(e.id, occurrence.start) : asPlacementId(e.id),
      color: e.color ?? DEFAULT_EVENT_COLOR,
      start,
      end,
      allDay: e.allDay ?? false,
      laneIndex,
      endLaneIndex: laneIndex,
      dayIndex: laneIndex,
      endDayIndex: laneIndex,
      startMin,
      endMin,
      segment: { i: 0, n: 1 },
      source: e,
      occurrence,
      truncated,
    });
  };

  const visible = eventWindow(window.start, window.end);

  for (const e of events) {
    if (!e.rrule || expand === false) {
      if (!mayOverlapWindow(e, visible)) continue;
      place(e, e.start, e.end);
      continue;
    }
    if (!seriesMayOverlapWindow(e.rrule, e.start, visible)) continue;
    const { occurrences, truncated } = expand(e, range);
    for (const occ of occurrences) place(e, occ.start, occ.end, occ, truncated);
  }
  return { all };
}

/**
 * The timeline's visible span. One continuous window rather than a day: 30-min
 * slots across a working day for room booking, day slots across a fortnight for
 * a roster, and later week slots across a quarter for a Gantt. The only thing
 * that changes between them is the divisor.
 */

import { createVerticalAxis, type KloqAxis } from "./axis";
import { clampZoom, ZOOM_STEPS } from "./density";
import { startOfLocalDay } from "./instant";

export interface TimelineWindow {
  start: Date;
  end: Date;
  /** the snap and tick unit, in minutes */
  slotMinutes: number;
  /** px per slot, before zoom */
  pxPerSlot: number;
}

/**
 * What a host passes for `timelineWindow`. Two modes, same as the calendar's
 * `date` vs. its uncontrolled anchor:
 *
 *  - CONTROLLED — pass both `start` and `end`: honoured exactly, and
 *    `resolveWindow` never recomputes them. Navigation (`stepAnchor` on a
 *    `"timeline"` view) still moves the calendar's own anchor date, but
 *    nothing rebinds this window to it — moving the visible span is then the
 *    host's job, typically by deriving a new `start`/`end` from its own
 *    `onDateChange` and passing it back in.
 *  - DERIVED (the default — omit `start`/`end`) — the window is computed off
 *    the view's anchor date: `start` = the anchor's local midnight plus
 *    `startOffsetMinutes`, `end` = `start` plus `spanMinutes`. This is what
 *    makes `stepAnchor`/next-prev move the window with no extra wiring.
 *
 * `start`/`end` are all-or-nothing: passing only one of them still derives
 * off the anchor (as if neither were passed), same as `slotMinutes`/`pxPerSlot`
 * falling back independently.
 */
export interface TimelineWindowConfig {
  start?: Date;
  end?: Date;
  /** the snap and tick unit, in minutes */
  slotMinutes?: number;
  /** px per slot, before zoom */
  pxPerSlot?: number;
  /** derived mode only: minutes after the anchor's local midnight the window starts. Default 480 (8:00 AM). */
  startOffsetMinutes?: number;
  /** derived mode only: the window's length, in minutes. Default 600 (a 10-hour day, 8:00 AM – 6:00 PM). */
  spanMinutes?: number;
}

const MS_PER_MIN = 60_000;

const DEFAULT_SLOT_MINUTES = 30;
const DEFAULT_PX_PER_SLOT = 40;
/** 8:00 AM */
const DEFAULT_START_OFFSET_MINUTES = 8 * 60;
/** 8:00 AM – 6:00 PM */
const DEFAULT_SPAN_MINUTES = 10 * 60;

const num = (v: number | undefined, fallback: number, lo: number, hi: number) =>
  v === undefined || !Number.isFinite(v) ? fallback : Math.min(hi, Math.max(lo, v));

/**
 * Validate and normalise. Junk is clamped, never thrown on, matching how
 * `createSettings` treats a bad config: a backwards range becomes one slot
 * wide rather than an error.
 *
 * `anchor` is read only in derived mode (no explicit `start`/`end`) — it is
 * the calendar's own view anchor, so a `"timeline"` view's window tracks
 * `stepAnchor`/next-prev the same way every other view's visible range does.
 * Defaults to "now", matching every other uncontrolled default in this
 * package, so it is read fresh on every call rather than frozen at import time.
 */
export function resolveWindow(
  w: TimelineWindowConfig = {},
  anchor: Date = new Date(),
): TimelineWindow {
  const slotMinutes = num(w.slotMinutes, DEFAULT_SLOT_MINUTES, 1, 43_200);
  const pxPerSlot = num(w.pxPerSlot, DEFAULT_PX_PER_SLOT, 1, 2_000);

  let start: Date;
  let proposed: Date;
  if (w.start !== undefined && w.end !== undefined) {
    // controlled mode: both given, honoured exactly
    start = w.start;
    proposed = w.end;
  } else {
    // derived mode: a lone `start` or `end` is not enough to control the
    // window (there is nothing to pair it with), so it derives off the
    // anchor too, same as if neither were passed
    const offset = num(w.startOffsetMinutes, DEFAULT_START_OFFSET_MINUTES, 0, 1440);
    start = new Date(startOfLocalDay(anchor).getTime() + offset * MS_PER_MIN);
    const span = num(w.spanMinutes, DEFAULT_SPAN_MINUTES, slotMinutes, 1440 * 366);
    proposed = new Date(start.getTime() + span * MS_PER_MIN);
  }
  const end =
    proposed.getTime() > start.getTime()
      ? proposed
      : new Date(start.getTime() + slotMinutes * MS_PER_MIN);
  return { start, end, slotMinutes, pxPerSlot };
}

/**
 * Apply a zoom rung. The same ladder the calendar's hour height uses, applied
 * to px per slot: zoom changes how wide time is drawn, never how much of it is
 * shown. `w` is already a resolved window with concrete `start`/`end` (the
 * caller derives those off the anchor before zooming), so routing the scaled
 * result back through `resolveWindow` lands in its controlled branch — a
 * pure passthrough for `start`/`end` here, not a mode change — while still
 * getting `pxPerSlot`'s own clamping rules applied.
 */
export function zoomWindow(w: TimelineWindow, zoom: number): TimelineWindow {
  // INVARIANT this leans on: `w.start`/`w.end` are already consistent with
  // whatever anchor produced `w` (the caller re-derives on every anchor
  // change before this runs), so handing both to `resolveWindow` lands in
  // its controlled branch as a no-op passthrough, not a mode change — it
  // only re-clamps `pxPerSlot`/`slotMinutes` here. If `w` could ever be
  // stale relative to the anchor, this call would freeze it in place.
  return resolveWindow({ ...w, pxPerSlot: w.pxPerSlot * ZOOM_STEPS[clampZoom(zoom)] });
}

/** Minutes from the window's start to an instant. Negative before it. */
export const minutesFromStart = (w: TimelineWindow, at: Date | number): number =>
  ((typeof at === "number" ? at : at.getTime()) - w.start.getTime()) / MS_PER_MIN;

/** The instant a minute offset names. */
export const instantAtMinute = (w: TimelineWindow, min: number): Date =>
  new Date(w.start.getTime() + min * MS_PER_MIN);

/**
 * The timeline's axis: time runs across, and the origin is the window start —
 * so minute 0 is the left edge, not midnight.
 *
 * The arithmetic is identical to the vertical axis with a zero origin, so it
 * reuses that implementation rather than restating it, and overrides only the
 * orientation.
 */
export function createHorizontalAxis(w: TimelineWindow): KloqAxis {
  const totalMin = minutesFromStart(w, w.end);
  const perHour = (w.pxPerSlot / w.slotMinutes) * 60;
  const base = createVerticalAxis({
    hourHeight: perHour,
    dayStartMin: 0,
    dayEndMin: totalMin,
  });
  return { ...base, orientation: "x" };
}

export interface Tick {
  /** minutes from the window start */
  min: number;
  label: string;
  /** does this tick get the heavier rule and the upper-tier label? */
  major: boolean;
}

/**
 * One tick per slot. "Major" is the next unit up: hour boundaries on a
 * sub-hour window, day boundaries on a sub-day one, and every tick on a window
 * whose slot is already a day or larger.
 */
export function ticksOf(w: TimelineWindow, locale?: string): Tick[] {
  const total = minutesFromStart(w, w.end);
  const count = Math.ceil(total / w.slotMinutes);
  const majorEvery = w.slotMinutes < 60 ? 60 : w.slotMinutes < 1440 ? 1440 : w.slotMinutes;
  const l = locale ?? "en-US";
  const ticks: Tick[] = [];
  for (let i = 0; i < count; i += 1) {
    const min = i * w.slotMinutes;
    const at = instantAtMinute(w, min);
    const absolute = at.getHours() * 60 + at.getMinutes();
    const major =
      majorEvery >= 1440 ? absolute === 0 || w.slotMinutes >= 1440 : absolute % majorEvery === 0;
    ticks.push({
      min,
      major,
      label:
        w.slotMinutes >= 1440
          ? at.toLocaleDateString(l, { weekday: "short", day: "numeric" })
          : at.toLocaleTimeString(l, { hour: "numeric", minute: "2-digit" }),
    });
  }
  return ticks;
}

/** Minutes of the heavier rules: the same "major" `ticksOf` marks, without formatting a label per slot. */
export function majorRules(w: TimelineWindow): number[] {
  if (w.slotMinutes >= 1440) return [];
  const total = minutesFromStart(w, w.end);
  const count = Math.ceil(total / w.slotMinutes);
  const every = w.slotMinutes < 60 ? 60 : 1440;
  const out: number[] = [];
  for (let i = 0; i < count; i += 1) {
    const at = instantAtMinute(w, i * w.slotMinutes);
    if ((at.getHours() * 60 + at.getMinutes()) % every === 0) out.push(i * w.slotMinutes);
  }
  return out;
}

export interface AxisLabels {
  /** labelled ticks; `minuteOfDay` is the wall-clock minute, `at` the instant */
  ticks: { min: number; minuteOfDay: number; at: Date }[];
  /** one span per calendar day the window touches; empty when it stays inside one day */
  days: { startMin: number; endMin: number; at: Date }[];
  /** the slot is a day or longer, so `ticks` name dates rather than times */
  dated: boolean;
}

const LABEL_STRIDES = [15, 30, 60, 120, 180, 240, 360, 720, 1440];

/**
 * What the header prints. Ticks are labelled at the first stride that keeps
 * `minGapPx` between them; a window touching several days also gets a day tier.
 * `wallClock` maps an instant onto the display zone's clock (defaults to local).
 */
export function axisLabels(
  w: TimelineWindow,
  opts: { minGapPx?: number; wallClock?: (at: Date) => Date } = {},
): AxisLabels {
  const total = minutesFromStart(w, w.end);
  const count = Math.ceil(total / w.slotMinutes);
  const minGap = opts.minGapPx ?? 56;
  const wall = opts.wallClock ?? ((at: Date) => at);
  const pxPerMin = w.pxPerSlot / w.slotMinutes;
  const ticks: AxisLabels["ticks"] = [];

  if (w.slotMinutes >= 1440) {
    const every = Math.max(1, Math.ceil(minGap / w.pxPerSlot));
    for (let i = 0; i < count; i += every) {
      const at = instantAtMinute(w, i * w.slotMinutes);
      ticks.push({ min: i * w.slotMinutes, minuteOfDay: 0, at });
    }
    return { ticks, days: [], dated: true };
  }

  const stride =
    LABEL_STRIDES.find(
      (s) => s >= w.slotMinutes && s % w.slotMinutes === 0 && s * pxPerMin >= minGap,
    ) ?? 1440;
  const days: AxisLabels["days"] = [];
  let dayKey = "";
  for (let i = 0; i < count; i += 1) {
    const min = i * w.slotMinutes;
    const at = instantAtMinute(w, min);
    const clock = wall(at);
    const minuteOfDay = clock.getHours() * 60 + clock.getMinutes();
    const key = `${clock.getFullYear()}-${clock.getMonth()}-${clock.getDate()}`;
    if (key !== dayKey) {
      dayKey = key;
      // the day began `minuteOfDay` minutes before this slot, clipped to the window
      const startMin = Math.max(0, min - (i === 0 ? 0 : minuteOfDay));
      const prev = days[days.length - 1];
      if (prev) prev.endMin = startMin;
      days.push({ startMin, endMin: total, at });
    }
    if (minuteOfDay % stride === 0) ticks.push({ min, minuteOfDay, at });
  }
  return { ticks, days: days.length > 1 ? days : [], dated: false };
}

/**
 * The default-duration span a fresh booking gets, snapped to the window's
 * slot unit and clamped inside it. Pure window/minute math — `durationMin`
 * is the caller's own default-duration constant (the calendar's
 * `DEFAULT_QUICK_ADD_MIN`, typically), passed in rather than imported, so
 * this stays a `lib` module with no dependency on `calendar/`.
 */
export function defaultBookingSpan(
  window: TimelineWindow,
  rawStartMin: number,
  durationMin: number,
): { startMin: number; endMin: number } {
  const total = minutesFromStart(window, window.end);
  const snapped = Math.round(rawStartMin / window.slotMinutes) * window.slotMinutes;
  const startMin = Math.max(0, Math.min(total - durationMin, snapped));
  return { startMin, endMin: startMin + durationMin };
}

/**
 * Timezone helpers, all via `Intl` (no tz database). Wall clock <-> instant conversion,
 * the zoned proxy `Date` (local getters read another zone's clock), and cached formatters.
 */

import { MS_PER_DAY, MS_PER_MINUTE, pad2 } from "./date-math";
import type { Instant } from "./instant";

/** Anything that names a moment: epoch ms, a `Date`, or a parseable string. */
export type InstantLike = number | Date | string;

/** Epoch milliseconds for an `InstantLike`. `NaN` if it can't be read. */
export function toMs(t: InstantLike): number {
  if (typeof t === "number") return t;
  if (t instanceof Date) return t.getTime();
  return Date.parse(t);
}

/** A wall clock reading. `month` is 1-12, not `Date`'s zero-based month. */
export interface ZoneWallClock {
  year: number;
  /** 1-12 */
  month: number;
  /** 1-31 */
  day: number;
  /** 0-23 */
  hour: number;
  minute: number;
  second: number;
}

const fmtCache = new Map<string, Intl.DateTimeFormat>();

function formatter(key: string, build: () => Intl.DateTimeFormat): Intl.DateTimeFormat {
  const hit = fmtCache.get(key);
  if (hit) return hit;
  const made = build();
  fmtCache.set(key, made);
  return made;
}

// Unknown ids fall back to UTC rather than throwing mid-render.
function partsFormatter(timeZone: string): Intl.DateTimeFormat {
  return formatter(`parts:${timeZone}`, () => {
    const opts: Intl.DateTimeFormatOptions = {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
      era: "short",
    };
    try {
      return new Intl.DateTimeFormat("en-US", opts);
    } catch {
      return new Intl.DateTimeFormat("en-US", { ...opts, timeZone: "UTC" });
    }
  });
}

let localZoneCache: string | null = null;

/** The browser's own zone. On a server this is the server's zone, so treat it as client-only. */
export function localZone(): string {
  if (localZoneCache !== null) return localZoneCache;
  try {
    localZoneCache = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    localZoneCache = "UTC";
  }
  return localZoneCache;
}

/** Forget the memoised browser zone; for tests that change `process.env.TZ`. */
export function resetLocalZoneCache(): void {
  localZoneCache = null;
}

const validCache = new Map<string, boolean>();

/** Does the runtime know this IANA id? */
export function isValidTimeZone(timeZone: string): boolean {
  if (!timeZone) return false;
  const hit = validCache.get(timeZone);
  if (hit !== undefined) return hit;
  let ok = true;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
  } catch {
    ok = false;
  }
  validCache.set(timeZone, ok);
  return ok;
}

/** `timeZone` if the runtime knows it, otherwise `fallback`. */
export function coerceTimeZone(
  timeZone: string | undefined,
  fallback: string = localZone(),
): string {
  return timeZone && isValidTimeZone(timeZone) ? timeZone : fallback;
}

const canonCache = new Map<string, string>();

/** The runtime's own spelling of a zone id (IANA aliases: `Asia/Calcutta` vs `Asia/Kolkata`). */
export function canonicalZone(timeZone: string): string {
  const hit = canonCache.get(timeZone);
  if (hit !== undefined) return hit;
  let out = timeZone;
  try {
    out = new Intl.DateTimeFormat("en-US", { timeZone }).resolvedOptions().timeZone || timeZone;
  } catch {}
  canonCache.set(timeZone, out);
  return out;
}

/** Do these two ids name the same zone? Alias-aware; zones that merely share an offset are not equal. */
export function sameZone(a: string | undefined, b: string | undefined): boolean {
  if ((a ?? "") === (b ?? "")) return true;
  if (!a || !b) return false;
  return canonicalZone(a) === canonicalZone(b);
}

/** What a clock in `timeZone` reads at `instant`. Sub-second precision is dropped. */
export function wallClockIn(instant: InstantLike, timeZone: string): ZoneWallClock {
  const ms = toMs(instant);
  const parts = partsFormatter(timeZone).formatToParts(new Date(ms));
  let year = 0;
  let month = 1;
  let day = 1;
  let hour = 0;
  let minute = 0;
  let second = 0;
  let bc = false;
  for (const p of parts) {
    switch (p.type) {
      case "year":
        year = Number(p.value);
        break;
      case "month":
        month = Number(p.value);
        break;
      case "day":
        day = Number(p.value);
        break;
      case "hour":
        // some older ICU builds emit "24" for midnight despite `hourCycle: "h23"`
        hour = Number(p.value) % 24;
        break;
      case "minute":
        minute = Number(p.value);
        break;
      case "second":
        second = Number(p.value);
        break;
      case "era":
        bc = p.value !== "AD";
        break;
    }
  }
  // `Intl` counts BC years from 1; `Date`'s proleptic numbering has a year 0
  return { year: bc ? 1 - year : year, month, day, hour, minute, second };
}

/**
 * Offset from UTC at `instant`, in minutes EAST (`+330` for Asia/Kolkata) — the RFC 3339 sign,
 * i.e. the OPPOSITE of `Date.prototype.getTimezoneOffset`. Rounded to whole minutes.
 */
export function zoneOffsetMinutes(instant: InstantLike, timeZone: string): number {
  const ms = toMs(instant);
  if (Number.isNaN(ms)) return 0;
  const w = wallClockIn(ms, timeZone);
  const asUTC = Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute, w.second);
  // Date.UTC maps years 0-99 to 1900+n
  const utc = w.year >= 0 && w.year < 100 ? new Date(asUTC).setUTCFullYear(w.year) : asUTC;
  return Math.round((utc - Math.floor(ms / 1000) * 1000) / MS_PER_MINUTE);
}

/** `"+05:45"`, `"-08:00"`, `"+00:00"` — the offset as RFC 3339 spells it. */
export function zoneOffsetLabel(instant: InstantLike, timeZone: string): string {
  const off = zoneOffsetMinutes(instant, timeZone);
  const sign = off < 0 ? "-" : "+";
  const abs = Math.abs(off);
  return `${sign}${pad2(Math.floor(abs / 60))}:${pad2(abs % 60)}`;
}

/** `"unique"`: one instant; `"gap"`: none (spring forward); `"overlap"`: two (fall back). */
export type WallClockKind = "unique" | "gap" | "overlap";

export interface WallClockResolution {
  /** the chosen instant in epoch ms */
  instant: number;
  kind: WallClockKind;
  /** the earlier candidate */
  earlier: number;
  /** the later candidate; equals `earlier` when unique */
  later: number;
}

/**
 * Policy for a gap or overlap. `"compatible"` (Temporal's rule): gap shifts forward, overlap takes the
 * earlier instant. `"earlier"`/`"later"` force a side of an overlap. `"reject"` returns `NaN` for either.
 */
export type Disambiguation = "compatible" | "earlier" | "later" | "reject";

/**
 * Resolve a wall clock in a zone to an instant, reporting whether it was unique, a gap or an overlap.
 * Probes the offset ±1 day around the naive UTC reading (probing at the naive moment itself misses
 * the fall-back overlap) and round-trips each candidate, which stays correct for 30-minute transitions.
 */
export function resolveWallClock(
  parts: ZoneWallClock,
  timeZone: string,
  disambiguation: Disambiguation = "compatible",
): WallClockResolution {
  const naive = utcFromParts(parts);
  const offA = zoneOffsetMinutes(naive - MS_PER_DAY, timeZone);
  const offB = zoneOffsetMinutes(naive + MS_PER_DAY, timeZone);

  const candA = naive - offA * MS_PER_MINUTE;
  const candB = naive - offB * MS_PER_MINUTE;
  const lo = Math.min(candA, candB);
  const hi = Math.max(candA, candB);

  if (candA === candB) {
    return { instant: candA, kind: "unique", earlier: candA, later: candA };
  }

  const loOk = readsAs(lo, timeZone, parts);
  const hiOk = readsAs(hi, timeZone, parts);

  if (loOk && hiOk) {
    const instant = disambiguation === "reject" ? NaN : disambiguation === "later" ? hi : lo;
    return { instant, kind: "overlap", earlier: lo, later: hi };
  }
  if (loOk || hiOk) {
    const instant = loOk ? lo : hi;
    return { instant, kind: "unique", earlier: instant, later: instant };
  }
  // gap: `hi` is built from the pre-transition offset, i.e. the wall time shifted forward past the gap
  return {
    instant: disambiguation === "reject" ? NaN : hi,
    kind: "gap",
    earlier: lo,
    later: hi,
  };
}

/** Parts read as UTC. */
function utcFromParts(p: ZoneWallClock): number {
  const ms = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second ?? 0);
  return p.year >= 0 && p.year < 100 ? new Date(ms).setUTCFullYear(p.year) : ms;
}

/** Does `instant` read as exactly these parts in this zone? */
function readsAs(instant: number, timeZone: string, parts: ZoneWallClock): boolean {
  const w = wallClockIn(instant, timeZone);
  return (
    w.year === parts.year &&
    w.month === parts.month &&
    w.day === parts.day &&
    w.hour === parts.hour &&
    w.minute === parts.minute &&
    w.second === (parts.second ?? 0)
  );
}

/**
 * Inverse of `wallClockIn`; gap/overlap resolved per {@link Disambiguation}. `NaN` for `"reject"` or
 * an unknown zone. `parts` normalise the way `Date.UTC` does (month 13, day 0, minute 90 all roll).
 */
export function instantFromWallClock(
  parts: ZoneWallClock,
  timeZone: string,
  disambiguation: Disambiguation = "compatible",
): number {
  if (!isValidTimeZone(timeZone)) return NaN;
  return resolveWallClock(parts, timeZone, disambiguation).instant;
}

/**
 * A proxy `Date` whose LOCAL getters read `timeZone`'s wall clock at `instant`. Not a moment:
 * `getTime()` is a fiction, convert back with `unzonedInstant`. Identity when `timeZone` is the browser's.
 */
export function zonedDate(instant: InstantLike, timeZone: string): Date {
  const ms = toMs(instant);
  if (Number.isNaN(ms)) return new Date(NaN);
  if (sameZone(timeZone, localZone())) return new Date(ms);
  const w = wallClockIn(ms, timeZone);
  const d = new Date(w.year, w.month - 1, w.day, w.hour, w.minute, w.second, 0);
  // the `Date(y, …)` constructor maps 0-99 to 1900+n
  if (w.year >= 0 && w.year < 100) d.setFullYear(w.year);
  return d;
}

/** Inverse of `zonedDate`: epoch ms at which `timeZone` reads the proxy's wall clock, or `NaN`. */
export function unzonedInstant(
  proxy: Date,
  timeZone: string,
  disambiguation: Disambiguation = "compatible",
): number {
  const t = proxy.getTime();
  if (Number.isNaN(t)) return NaN;
  if (sameZone(timeZone, localZone())) return t;
  return instantFromWallClock(
    {
      year: proxy.getFullYear(),
      month: proxy.getMonth() + 1,
      day: proxy.getDate(),
      hour: proxy.getHours(),
      minute: proxy.getMinutes(),
      second: proxy.getSeconds(),
    },
    timeZone,
    disambiguation,
  );
}

/** An offset-qualified `Instant` written with `timeZone`'s offset — `"2026-08-07T09:00:00+01:00"`. */
export function formatInstantInZone(instant: InstantLike, timeZone: string): Instant {
  const ms = toMs(instant);
  if (Number.isNaN(ms)) return "";
  const w = wallClockIn(ms, timeZone);
  const y =
    w.year < 0
      ? `-${String(-w.year).padStart(6, "0")}`
      : w.year > 9999
        ? `+${String(w.year).padStart(6, "0")}`
        : String(w.year).padStart(4, "0");
  const off = zoneOffsetMinutes(ms, timeZone);
  const zone =
    off === 0
      ? "Z"
      : `${off < 0 ? "-" : "+"}${pad2(Math.floor(Math.abs(off) / 60))}:${pad2(Math.abs(off) % 60)}`;
  return (
    `${y}-${pad2(w.month)}-${pad2(w.day)}` +
    `T${pad2(w.hour)}:${pad2(w.minute)}:${pad2(w.second)}${zone}`
  );
}

/** Short zone label — `"BST"`, `"PDT"`, `"GMT+5:30"`. ICU-build dependent; a label, never an identifier. */
export function zoneAbbr(instant: InstantLike, timeZone: string): string {
  const ms = toMs(instant);
  try {
    const part = formatter(
      `abbr:${timeZone}`,
      () => new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: "short" }),
    )
      .formatToParts(new Date(ms))
      .find((p) => p.type === "timeZoneName");
    if (part) return part.value;
  } catch {}
  return zoneCityLabel(timeZone);
}

/** The long name — `"British Summer Time"`; falls back to the city label. */
export function zoneLongName(instant: InstantLike, timeZone: string, locale?: string): string {
  try {
    const part = formatter(
      `long:${locale ?? ""}:${timeZone}`,
      () => new Intl.DateTimeFormat(locale, { timeZone, timeZoneName: "long" }),
    )
      .formatToParts(new Date(toMs(instant)))
      .find((p) => p.type === "timeZoneName");
    if (part) return part.value;
  } catch {}
  return zoneCityLabel(timeZone);
}

/** A gutter row's label — `"9 AM"`, `"12:45 AM"`, `"09"`, `"17:45"`. Minutes are dropped on the hour. */
export function hourLabel(hour: number, minute: number, hour12: boolean): string {
  if (!hour12) {
    return minute === 0 ? pad2(hour) : `${pad2(hour)}:${pad2(minute)}`;
  }
  const period = hour < 12 ? "AM" : "PM";
  const h = hour % 12 === 0 ? 12 : hour % 12;
  return minute === 0 ? `${h} ${period}` : `${h}:${pad2(minute)} ${period}`;
}

/** `"Europe/London"` → `"London"`, `"America/New_York"` → `"New York"`. */
/** City names for ids whose last segment is an old or clipped spelling. */
const CITY_NAMES: Readonly<Record<string, string>> = {
  Calcutta: "Kolkata",
  Katmandu: "Kathmandu",
  Saigon: "Ho Chi Minh City",
  Ho_Chi_Minh: "Ho Chi Minh City",
  Kiev: "Kyiv",
  Rangoon: "Yangon",
  Thimbu: "Thimphu",
  Dacca: "Dhaka",
  Macao: "Macau",
  Godthab: "Nuuk",
  Faeroe: "Faroe",
  Truk: "Chuuk",
  Ponape: "Pohnpei",
};

export function zoneCityLabel(timeZone: string): string {
  const tail = timeZone.split("/").pop() ?? timeZone;
  return CITY_NAMES[tail] ?? tail.replace(/_/g, " ");
}

/** Format a moment as it reads in a zone; a cached `Intl.DateTimeFormat` wrapper. */
export function formatInZone(
  instant: InstantLike,
  timeZone: string,
  options: Intl.DateTimeFormatOptions = { hour: "numeric", minute: "2-digit" },
  locale?: string,
): string {
  const ms = toMs(instant);
  if (Number.isNaN(ms)) return "";
  try {
    return formatter(
      `f:${locale ?? ""}:${timeZone}:${JSON.stringify(options)}`,
      () => new Intl.DateTimeFormat(locale, { ...options, timeZone }),
    ).format(new Date(ms));
  } catch {
    return "";
  }
}

/** One row of a zone picker. */
export interface ZoneOption {
  /** IANA id */
  id: string;
  /** the city, de-underscored */
  label: string;
  /** the part before the slash */
  region: string;
}

/** Curated shortlist for a picker's default state, including the fractional-offset and odd-DST zones. */
export const COMMON_ZONES: readonly string[] = [
