/* the calendar paints its own ground; page-level resets are in tokens.css (opt-in).
   `@layer base` so utilities like `border-transparent` still win, as with Tailwind's preflight. */
@layer base {
  [data-kloq-root] {
    /* native UA surfaces (scrollbars, form controls) follow the calendar's own
       scheme — without this a dark calendar renders a light scrollbar track */
    color-scheme: light;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji");
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 50%, transparent);
  }
  [data-kloq-root] *,
  [data-kloq-root] *::before,
  [data-kloq-root] *::after {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 50%, transparent);
  }
  [data-kloq-root] :where(code, kbd, samp, pre) {
    font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  }
  /* anchored popups share one enter/exit; a primitive's own transition utilities still win */
  [data-kloq-root] :where(
      [data-slot="menu-popup"],
      [data-slot="menu-sub-content"],
      [data-slot="context-menu-popup"],
      [data-slot="context-menu-sub-content"],
      [data-slot="select-popup"],
      [data-slot="autocomplete-popup"],
      [data-slot="combobox-popup"],
      [data-slot="popover-popup"],
      [data-slot="tooltip-popup"],
      [data-slot="preview-card-content"]
    ) {
    transition:
      scale var(--overlay-enter) var(--overlay-ease),
      opacity var(--overlay-enter) var(--overlay-ease);
    &:where([data-starting-style], [data-ending-style]) {
      scale: 0.98;
      opacity: 0;
    }
    &:where([data-ending-style]) {
      transition-duration: var(--overlay-exit);
    }
    &:where([data-instant]) {
      transition: none;
    }
  }
  /* any focusable thing without its own ring; `:where` keeps it below every utility */
  [data-kloq-root] :where(a, button, input, select, textarea, summary, [tabindex], [contenteditable]):focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}
/* unlayered so it outranks the primitives' duration utilities */
@media (prefers-reduced-motion: reduce) {
  [data-kloq-root] :where([data-slot$="-popup"], [data-slot$="-backdrop"], [data-slot$="-positioner"], [data-slot$="-viewport"]) {
    transition-duration: 1ms;
    animation-duration: 1ms;
  }
}

