/* free/busy — a "free" block is an outline + hatch over the existing tint */
[data-cal-event][data-free] {
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 5px,
    --alpha(var(--color-black) / 6%) 5px 10px
  );
  @variant dark {
    background-image: repeating-linear-gradient(
      -45deg,
      transparent 0 5px,
      --alpha(var(--color-white) / 7%) 5px 10px
    );
  }
}
/* the colour bar still identifies the event */
[data-cal-event][data-free] [data-slot="event-bar"] {
  opacity: 0.6;
}

/* all-day lane draft chip */
[data-cal-lane-draft] {
  pointer-events: none;
  top: 3px;
  height: 22px;
  border-radius: var(--radius-md);
  background: color-mix(in oklab, var(--kloq-draft) 16%, transparent);
  will-change: left, width;
}
[data-cal-lane-draft][hidden] {
  display: none;
}
[data-cal-lane-draft] [data-slot="draft-label"] {
  position: absolute;
  top: 50%;
  left: 8px;
  translate: 0 -50%;
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
  color: var(--kloq-draft-ink);
}

/* timeline slot rules: one gradient per canvas, sized by the slot width */
.tl-slot-lines {
  background-image: repeating-linear-gradient(
    to right,
    color-mix(in oklab, var(--border) 40%, transparent) 0 1px,
    transparent 1px var(--kloq-slot-width, 40px)
  );
}
.tl-slot-lines[data-dated] {
  background-image: repeating-linear-gradient(
    to right,
    var(--border) 0 1px,
    transparent 1px var(--kloq-slot-width, 40px)
  );
}

/* Design mode — scoped to [data-design-mode] on <html> or .dm-* classes */

/* blueprint: a backdrop layer over the calendar, never a filter on <body> (that would break every fixed element) */
.dm-backdrop {
  position: absolute;
  inset: 0;
  pointer-events: none;
  backdrop-filter: saturate(0.72) brightness(0.96);
  background:
    linear-gradient(
      color-mix(in oklab, var(--kloq-draft) 4%, transparent),
      color-mix(in oklab, var(--kloq-draft) 4%, transparent)
    );
}

.dm-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(
    circle at 0.5px 0.5px,
    color-mix(in oklab, currentColor 22%, transparent) 0.75px,
    transparent 0.75px
  );
  background-size: 8px 8px;
  color: var(--foreground);
  opacity: 0.5;
}

/* the hint bar keeps its place in the layout but steps out from behind an event sheet */
:root:has([data-event-panel][data-sheet]) [data-dm-hint] {
  visibility: hidden;
}

.dm-snap-lines {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 1;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    color-mix(in oklab, var(--brand) 45%, transparent) 0 1px,
    transparent 1px 100%
  );
  background-repeat: repeat;
}
.dm-snap-lines[data-axis="x"] {
  background-image: repeating-linear-gradient(
    to right,
    color-mix(in oklab, var(--brand) 45%, transparent) 0 1px,
    transparent 1px 100%
  );
}

html[data-dm-hit] [data-resize-edge],
html[data-dm-hit] [data-lane-edge] {
  background: color-mix(in oklab, var(--brand) 28%, transparent) !important;
  outline: 1px dashed var(--brand);
  outline-offset: -1px;
}
html[data-dm-hit] [data-resize-edge] > *,
html[data-dm-hit] [data-lane-edge] > * {
  opacity: 1 !important;
}

/* ── the anchored panel as a bottom sheet (`use-anchored-panel.ts` decides when) ── */
[data-event-panel][data-sheet] {
  inset: auto 0 0 0;
  width: auto !important;
  max-width: 28rem;
  max-height: 85dvh;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
}
[data-event-panel][data-sheet] > [data-slot="card"] {
  max-height: 85dvh;
  overflow-y: auto;
  border-radius: var(--radius-2xl) var(--radius-2xl) 0 0;
  border-bottom: 0;
}

.dm-inspect-outline {
  position: fixed;
  z-index: 1;
  pointer-events: none;
  border: 1px solid var(--brand);
  visibility: hidden;
}
.dm-inspect-outline[data-kind="slot"] {
  border-style: dashed;
  background: color-mix(in oklab, var(--brand) 8%, transparent);
}
.dm-inspect-outline[data-kind="event"] {
  border-width: 2px;
  border-radius: var(--radius-md);
}

.dm-inspect-badge {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translate(-50%, 4px);
  padding: 2px 6px;
  border-radius: var(--radius-xs);
  background: var(--brand);
  color: var(--color-white);
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: left;
  font-variant-numeric: tabular-nums;
  width: max-content;
  max-width: 16rem;
  white-space: nowrap;
}

/* time-awareness washes — past dim + off-hours tint (see time-shade.tsx) */

.cal-past-shade,
.cal-offhours {
  position: absolute;
  pointer-events: none;
  z-index: 1; /* above hour lines, below every event block */
}

.cal-past-shade {
  background: color-mix(in oklab, var(--background) 42%, transparent);
}

.cal-offhours {
  background: color-mix(in oklab, var(--foreground) 2.5%, transparent);
}

/* agenda days off-screen skip layout and paint */
[data-agenda-day] {
  content-visibility: auto;
  contain-intrinsic-size: auto 6rem;
}

/* unavailable (minDate/maxDate, isSlotDisabled): the hatch carries the meaning without colour */
.cal-blocked {
  position: absolute;
  pointer-events: none;
  z-index: 2; /* above the off-hours tint, below every event block */
  background-image: repeating-linear-gradient(
    135deg,
    color-mix(in oklab, var(--muted-foreground) 20%, transparent) 0 1.5px,
    transparent 1.5px 7px
  );
  background-color: color-mix(in oklab, var(--muted) 45%, transparent);
  border-block: 1px solid color-mix(in oklab, var(--muted-foreground) 26%, transparent);
}

/* forced colours strips color-mix; keep the boundary */
@media (forced-colors: active) {
  .cal-blocked {
    border-block: 1px solid GrayText;
    background-image: repeating-linear-gradient(
      135deg,
      GrayText 0 1px,
      transparent 1px 7px
    );
  }
}

/* refused drag; declared after the grab/copy cursors so it wins */
body[data-cal-refused],
body[data-cal-refused] [data-cal-event] {
  cursor: not-allowed;
}

/* in-flight sync pulse — data-syncing while a commit is on the wire */

[data-cal-event][data-syncing]::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  opacity: 0.4;
  animation: cal-sync-pulse 1.1s ease-in-out infinite;
}

@keyframes cal-sync-pulse {
  0%, 100% { opacity: 0.15; }
  50% { opacity: 0.5; }
}

@media (prefers-reduced-motion: reduce) {
  [data-cal-event][data-syncing]::after {
    animation: none;
    opacity: 0.3;
  }
}

/* touch & density. The geometry half of density (px per hour) lives in `KloqSettings`, not here. */

/* coarse pointers get vertical panning; a matured long press cancels it (see `use-drag-engine.ts`) */
@media (pointer: coarse) {
  .cal-hour-lines {
    touch-action: pan-y;
  }
}

/* long-press create preview; the engine writes opacity/transform/rect from its rAF loop */
.cal-press {
  position: absolute;
  z-index: 24;
  pointer-events: none;
  border-radius: var(--radius-md);
  border: 1.5px dashed color-mix(in oklab, var(--primary) 55%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  transform-origin: center;
  will-change: opacity, transform;
}
.cal-press[hidden] {
  display: none;
}

/* touch targets (WCAG 2.2 §2.5.8): grow the box where there is slack, else a `::before` hit area
   (`::before`, not `::after`: the duplicate-drag tell owns `[data-cal-event]::after`) */
@media (pointer: coarse) {
  /* a 15-minute event is 16px at default zoom; the taller minimum overlaps like any overlapping event.
     Month chips are not here: their pitch grows instead (`useCoarsePointer` in month-view.tsx) */
  [data-cal-canvas] [data-cal-event],
  [data-cal-lane] [data-cal-event] {
    min-height: 24px;
  }

  /* `> div > button` is the header row only; chips and `+N more` are direct children of the cell */
  [data-month-day] > div > button {
    min-width: 24px;
    min-height: 24px;
  }

  /* `+N more` cannot grow without pushing a chip out, so it gets hit area instead */
  [data-cal-more]::before {
    content: "";
    position: absolute;
    inset-block: -7px;
    inset-inline: -8px;
    min-height: 24px;
  }

  /* menu rows go to the 44px comfort size */
  [data-kloq-root] [data-slot="context-menu-item"],
  [data-kloq-root] [data-slot="context-menu-link-item"],
  [data-kloq-root] [data-slot="context-menu-checkbox-item"],
  [data-kloq-root] [data-slot="context-menu-radio-item"],
  [data-kloq-root] [data-slot="context-menu-sub-trigger"],
  [data-kloq-root] [data-slot="command-item"] {
    min-height: 44px;
  }

  /* the chrome buttons are coss `Button`s and already carry a coarse-pointer pseudo-target */
}

/* density: keyed on `<html data-kloq-density>` (stamped by `lib/density.ts`).
   Vertical padding is deliberately not set here: it would clip `event-block.tsx`'s `py-0` on short blocks. */
[data-kloq-root] {
  --kloq-event-font-size: 13px;
  --kloq-event-time-font-size: 11px;
  --kloq-event-padding-start: 10px;
  --kloq-event-padding-end: 8px;
  --kloq-chip-font-size: 12px;
}

[data-kloq-density="compact"] [data-kloq-root],
[data-kloq-root][data-kloq-density="compact"] {
  --kloq-event-font-size: 12px;
  --kloq-event-time-font-size: 10px;
  --kloq-event-padding-start: 7px;
  --kloq-event-padding-end: 5px;
  --kloq-chip-font-size: 11px;
}

[data-kloq-density] [data-cal-event] {
  padding-inline: var(--kloq-event-padding-start) var(--kloq-event-padding-end);
}
[data-kloq-density] [data-cal-event] > div > span {
  font-size: var(--kloq-event-font-size);
}
[data-kloq-density] [data-cal-event] [data-slot="event-time"] {
  font-size: var(--kloq-event-time-font-size);
}

/* the all-day chip's label is a direct child */
[data-kloq-density] [data-cal-event] > span:not([aria-hidden]) {
  font-size: var(--kloq-chip-font-size);
}

/* columns too narrow for the full block (a week forced into a phone-width box): the title alone,
   edge to edge, clipped rather than ellipsised */
[data-cramped] [data-cal-event] {
  padding-inline: 4px 1px;
}
[data-cramped] [data-cal-event] [data-slot="event-bar"],
[data-cramped] [data-cal-event] [data-slot="event-time"],
[data-cramped] [data-cal-event] > span[aria-hidden] {
  display: none;
}
[data-cramped] [data-cal-event] > div > span,
[data-cramped] [data-cal-event] > span:not([aria-hidden]) {
  font-size: var(--text-2xs);
  text-overflow: clip;
}

/*
 * Opt-in page-level styling. kloq.css scopes every token to `[data-kloq-root]`
 * and never touches :root, html, body or `*`. A host that wants kloq's look
 * for the whole page puts `data-kloq-root` on <body> (so the tokens and the
 * `data-kloq-theme` / `.dark` blocks apply everywhere) and imports this file
 * for the resets a page expects. Tailwind v4 only, like kloq.css.
 */
@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  code,
  kbd,
  samp,
  pre {
    font-family: var(--font-mono);
  }
  html {
    @apply font-sans;
  }
}

/**
 * A timeline placement measures minutes from the window start and uses the
 * lane as its column. The event panel reads day-column placements, so this
 * re-expresses one bar in that shape, with the day names it needs.
 */

import { displayDate, minutesOfDate, parseInstant, wallMinutesBetween } from "../lib/instant";
import type { PlacedOccurrence } from "../lib/projection";

const MS_PER_DAY = 86_400_000;

export interface PanelPlacement {
  event: PlacedOccurrence;
  namesLong: string[];
  namesShort: string[];
}

export function panelPlacement(
  placed: PlacedOccurrence,
  zone: string | undefined,
  locale: string | undefined,
): PanelPlacement {
  const startMs = parseInstant(placed.start);
  const endMs = parseInstant(placed.end);
  const first = displayDate(startMs, zone);
  const days = placed.allDay ? Math.max(1, Math.round((endMs - startMs) / MS_PER_DAY)) : 1;
  const dates = Array.from({ length: days }, (_, i) => {
    const d = new Date(first);
    d.setDate(first.getDate() + i);
    return d;
  });
  const startMin = minutesOfDate(first);
  return {
    event: {
      ...placed,
      dayIndex: 0,
      endDayIndex: days - 1,
      startMin: placed.allDay ? 0 : startMin,
      endMin: placed.allDay ? 0 : startMin + wallMinutesBetween(placed.start, placed.end, zone),
      segment: { i: 0, n: 1 },
    },
    namesLong: dates.map((d) => d.toLocaleDateString(locale, { weekday: "long" })),
    namesShort: dates.map((d) => d.toLocaleDateString(locale, { weekday: "short" })),
  };
}

