export interface ResourceGutterProps {
  lane: Lane;
  height: number;
  width: number;
  /** a squeezed gutter: the name wraps to two lines and the sublabel moves to the tooltip */
  narrow?: boolean;
}

export const ResourceGutter = memo(function ResourceGutter({
  lane,
  height,
  width,
  narrow = false,
}: ResourceGutterProps) {
  return (
    <div
      className={cn(
        "sticky left-0 z-50 flex shrink-0 flex-col justify-center gap-0.5 border-r border-b border-border bg-background",
        narrow ? "px-2" : "px-3",
      )}
      style={{ width, height }}
      title={lane.sublabel ? `${lane.label} · ${lane.sublabel}` : lane.label}
      data-slot="resource-gutter"
      data-narrow={narrow || undefined}
